DECLARE
  v_member_id uuid;
  v_need_id uuid;

  v_offer_record
    public.movement_offers%ROWTYPE;

  v_need_record
    public.movement_needs%ROWTYPE;

  v_vehicle_record
    public.vehicles%ROWTYPE;

  v_binding
    private.movement_offer_route_match_bindings%ROWTYPE;

  v_availability_id uuid;
  v_alignment_id uuid;
  v_created_at timestamptz;

  v_confirmed_count integer;
  v_pending_count integer;
BEGIN
  IF current_setting('transaction_isolation')
       <> 'read committed' THEN
    RAISE EXCEPTION USING
      ERRCODE = '25000',
      MESSAGE =
        'Movement offer acceptance requires READ COMMITTED';
  END IF;


  v_member_id := auth.uid();

  IF v_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;


  SELECT mo.movement_need_id
  INTO v_need_id
  FROM public.movement_offers AS mo
  WHERE mo.id = p_movement_offer_id;


  IF v_need_id IS NULL THEN
    RAISE EXCEPTION 'Movement offer not found';
  END IF;


  -- Preserve the existing need -> offer lock order.

  SELECT *
  INTO v_need_record
  FROM public.movement_needs AS mn
  WHERE mn.id = v_need_id
  FOR UPDATE;


  IF NOT FOUND THEN
    RAISE EXCEPTION 'Movement need not found';
  END IF;


  SELECT *
  INTO v_offer_record
  FROM public.movement_offers AS mo
  WHERE mo.id = p_movement_offer_id
    AND mo.movement_need_id = v_need_record.id
  FOR UPDATE;


  IF NOT FOUND THEN
    RAISE EXCEPTION 'Movement offer not found';
  END IF;


  IF v_offer_record.status <> 'pending' THEN
    RAISE EXCEPTION 'Movement offer is not pending';
  END IF;


  IF v_need_record.status <> 'discoverable' THEN
    RAISE EXCEPTION 'Movement need is not discoverable';
  END IF;


  IF v_need_record.member_id <> v_member_id THEN
    RAISE EXCEPTION
      'Only the movement need owner may accept an offer';
  END IF;


  IF v_need_record.member_id =
       v_offer_record.offering_member_id THEN
    RAISE EXCEPTION
      'The offering member cannot accept their own offer';
  END IF;


  -- =======================================================
  -- Trusted offer authorization must exist and still validate
  -- =======================================================

  SELECT b.*
  INTO v_binding
  FROM private.movement_offer_route_match_bindings b
  WHERE b.movement_offer_id = v_offer_record.id;


  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE =
        'Movement offer does not have trusted route-match authorization';
  END IF;


  IF v_binding.movement_need_id
       IS DISTINCT FROM v_need_record.id
     OR v_binding.offering_member_id
       IS DISTINCT FROM v_offer_record.offering_member_id THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE =
        'Movement offer trusted route-match authorization does not match';
  END IF;


  PERFORM
    private.assert_movement_offer_availability_binding(
      v_offer_record.id
    );


  -- =======================================================
  -- Existing vehicle/access/capacity behavior
  -- =======================================================

  IF NOT EXISTS (
    SELECT 1
    FROM public.member_vehicle_access AS mva
    WHERE mva.member_id =
            v_offer_record.offering_member_id
      AND mva.vehicle_id =
            v_offer_record.vehicle_id
      AND mva.active = TRUE
  ) THEN
    RAISE EXCEPTION
      'The offering member no longer has active access to this vehicle';
  END IF;


  SELECT *
  INTO v_vehicle_record
  FROM public.vehicles AS v
  WHERE v.id = v_offer_record.vehicle_id;


  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vehicle not found';
  END IF;


  IF v_offer_record.seats_offered >
       v_vehicle_record.seat_capacity THEN
    RAISE EXCEPTION
      'This offer now exceeds the vehicle seat capacity';
  END IF;


  IF EXISTS (
    SELECT 1
    FROM public.alignments AS a
    WHERE a.movement_need_id = v_need_record.id
      AND a.status IN (
        'awaiting_activation_payment',
        'activated',
        'in_progress',
        'completed'
      )
  ) THEN
    RAISE EXCEPTION
      'This movement need already has an active or completed alignment';
  END IF;


  -- =======================================================
  -- Existing group-completeness behavior
  -- =======================================================

  SELECT COUNT(*)
  INTO v_confirmed_count
  FROM public.movement_participants mp
  WHERE mp.movement_need_id = v_need_record.id
    AND mp.status = 'confirmed';


  SELECT COUNT(*)
  INTO v_pending_count
  FROM public.movement_participants mp
  WHERE mp.movement_need_id = v_need_record.id
    AND mp.status = 'invited';


  IF v_confirmed_count <>
       v_need_record.people_count THEN
    RAISE EXCEPTION
      'All declared travellers must be confirmed before accepting an offer';
  END IF;


  IF v_pending_count > 0 THEN
    RAISE EXCEPTION
      'Pending traveller invitations must be resolved before accepting an offer';
  END IF;


  IF v_offer_record.seats_offered <
       v_need_record.people_count THEN
    RAISE EXCEPTION
      'This offer does not provide enough seats for the confirmed movement group';
  END IF;


  -- Revalidate immediately before the operational alignment
  -- write. The movement-need lock prevents concurrent trusted
  -- route-match replacement while this transaction proceeds.

  PERFORM
    private.assert_movement_offer_availability_binding(
      v_offer_record.id
    );


  -- Need lock serializes all roster mutations (0016 freeze_aligned_face_roster).
  -- In addition to 0042 count/invitation checks, require the primary requester
  -- and exclude the offerer from the confirmed traveller roster.
  IF NOT EXISTS(SELECT 1 FROM public.movement_participants mp
      WHERE mp.movement_need_id=v_need_record.id AND mp.member_id=v_member_id
        AND mp.role='primary_requester' AND mp.status='confirmed')
    OR EXISTS(SELECT 1 FROM public.movement_participants mp
      WHERE mp.movement_need_id=v_need_record.id AND mp.status='confirmed'
        AND (mp.member_id=v_offer_record.offering_member_id
          OR (mp.role='primary_requester') IS DISTINCT FROM (mp.member_id=v_member_id))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Exact confirmed requester roster required';
  END IF;

  SELECT b.availability_id INTO STRICT v_availability_id
  FROM private.movement_offer_availability_bindings b WHERE b.movement_offer_id=v_offer_record.id;
  -- The assertion holds the authoritative availability FOR UPDATE lock.
  -- Consume the whole people_count, never seats_offered. This write and every
  -- following operational transition roll back together on any error.
  UPDATE private.offering_movement_availability a
  SET remaining_places=a.remaining_places-v_need_record.people_count,
      status=CASE WHEN a.remaining_places=v_need_record.people_count THEN 'full' ELSE 'open' END
  WHERE a.id=v_availability_id AND a.status='open'
    AND a.remaining_places>=v_need_record.people_count;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Insufficient remaining places for the complete requester group';
  END IF;

  INSERT INTO public.alignments (
    movement_need_id,
    movement_offer_id,
    member_needing_movement_id,
    offering_member_id,
    activation_fee_minor,
    activation_currency,
    status,
    activated_at,
    created_at,
    updated_at
  )
  VALUES (
    v_need_record.id,
    v_offer_record.id,
    v_member_id,
    v_offer_record.offering_member_id,
    NULL,
    'NGN',
    'awaiting_activation_payment',
    NULL,
    NOW(),
    NOW()
  )
  RETURNING
    public.alignments.id,
    public.alignments.created_at
  INTO
    v_alignment_id,
    v_created_at;


  UPDATE public.movement_offers AS mo
  SET
    status = 'accepted',
    updated_at = NOW()
  WHERE mo.id = v_offer_record.id;


  UPDATE public.movement_needs AS mn
  SET
    status = 'closed',
    updated_at = NOW()
  WHERE mn.id = v_need_record.id;


  UPDATE public.movement_offers AS mo
  SET
    status = 'rejected',
    updated_at = NOW()
  WHERE mo.movement_need_id = v_need_record.id
    AND mo.id <> v_offer_record.id
    AND mo.status = 'pending';


  RETURN QUERY
  SELECT
    v_alignment_id,
    'awaiting_activation_payment'::text,
    v_need_record.id,
    v_offer_record.id,
    v_created_at;
END;

DECLARE f private.funded_activation_fee_finalizations%ROWTYPE; g private.financial_agreements%ROWTYPE;
 a private.funded_movement_activations%ROWTYPE; c private.financial_components%ROWTYPE;
 t private.wallet_transactions%ROWTYPE; debit_id uuid; credit_id uuid; n bigint; matches bigint;
BEGIN
 SELECT * INTO STRICT g FROM private.financial_agreements WHERE id=p_agreement;
 SELECT * INTO STRICT a FROM private.funded_movement_activations WHERE financial_agreement_id=g.id;
 SELECT * INTO f FROM private.funded_activation_fee_finalizations WHERE financial_agreement_id=g.id;
 IF EXISTS(SELECT 1 FROM private.funded_activation_fee_legacy WHERE financial_agreement_id=g.id AND alignment_id=a.alignment_id AND activated_at=a.activated_at) THEN
  IF f.financial_agreement_id IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Conflicting activation fee policy'; END IF;
  RETURN;
 END IF;
 SELECT * INTO STRICT c FROM private.financial_components WHERE agreement_id=g.id AND component_key='requester_platform_share';
 IF f.financial_agreement_id IS NULL OR f.alignment_id IS DISTINCT FROM g.alignment_id OR a.alignment_id IS DISTINCT FROM g.alignment_id
  OR f.financial_component_id IS DISTINCT FROM c.id OR f.requester_member_id IS DISTINCT FROM g.member_needing_movement_id
  OR f.amount_minor IS DISTINCT FROM c.amount_minor OR f.currency IS DISTINCT FROM g.currency
  OR f.finalized_at IS DISTINCT FROM a.activated_at OR NOT isfinite(f.finalized_at) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact activation fee finalization required'; END IF;
 SELECT * INTO t FROM private.wallet_transactions WHERE idempotency_key='requester_platform_charge:'||c.id::text;
 SELECT count(*) INTO n FROM private.wallet_transactions WHERE financial_component_id=c.id AND transaction_kind='requester_platform_charge';
 IF EXISTS(SELECT 1 FROM private.wallet_transactions WHERE financial_component_id=c.id AND transaction_kind IN('movement_hold_release','movement_contribution_settlement','offering_platform_charge')) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Activation platform share is non-refundable'; END IF;
 IF c.amount_minor=0 THEN
  IF t.id IS NOT NULL OR n<>0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Zero activation fee has no transaction'; END IF;
  RETURN;
 END IF;
 SELECT id INTO debit_id FROM private.wallet_accounts WHERE member_id=g.member_needing_movement_id AND currency=g.currency AND account_kind='member_held';
 SELECT id INTO credit_id FROM private.wallet_accounts WHERE member_id IS NULL AND currency=g.currency AND account_kind='platform_revenue';
 IF n<>1 OR t.id IS NULL OR t.transaction_kind IS DISTINCT FROM 'requester_platform_charge'
  OR t.financial_component_id IS DISTINCT FROM c.id OR t.alignment_id IS DISTINCT FROM g.alignment_id OR t.currency IS DISTINCT FROM g.currency
  OR t.created_at IS DISTINCT FROM f.finalized_at OR t.provider IS NOT NULL OR t.provider_reference IS NOT NULL
  OR debit_id IS NULL OR credit_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact activation charge transaction required'; END IF;
 SELECT count(*),count(*) FILTER(WHERE amount_minor=c.amount_minor AND created_at=f.finalized_at AND isfinite(created_at)
  AND ((account_id=debit_id AND direction='debit') OR (account_id=credit_id AND direction='credit')))
  INTO n,matches FROM private.wallet_postings WHERE transaction_id=t.id;
 IF n<>2 OR matches<>2 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact activation charge postings required'; END IF;
 PERFORM private.assert_wallet_transaction_balanced(t.id);
END;

DECLARE v_need uuid; v_member uuid; v_now timestamptz;
BEGIN
  SELECT movement_need_id INTO v_need FROM public.alignments
    WHERE id=p_alignment_id AND status='awaiting_activation_payment' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Alignment is not awaiting activation payment'; END IF;
  PERFORM 1 FROM public.movement_needs WHERE id=v_need FOR UPDATE;
  FOR v_member IN SELECT r.member_id FROM private.required_face_members(p_alignment_id) r ORDER BY r.member_id LOOP
    PERFORM 1 FROM public.members WHERE id=v_member FOR UPDATE;
  END LOOP;
  v_now:=clock_timestamp();
  IF EXISTS (SELECT 1 FROM private.required_face_members(p_alignment_id) r
    WHERE NOT private.has_current_alignment_face_check(p_alignment_id,r.member_id,v_now)) THEN
    RAISE EXCEPTION 'Fresh face verification required for every movement participant';
  END IF;
END;

DECLARE p private.financial_proposals%ROWTYPE; n public.movement_needs%ROWTYPE;
  capacity integer;
BEGIN
  SELECT * INTO STRICT p FROM private.financial_proposals WHERE id=p_proposal_id FOR UPDATE;
  SELECT * INTO STRICT n FROM public.movement_needs WHERE id=p.movement_need_id FOR SHARE;
  IF ROW(n.member_id,n.origin_area,n.destination_area,n.earliest_departure_at,n.latest_departure_at,n.people_count)
    IS DISTINCT FROM ROW(p.member_needing_movement_id,p.origin_area,p.destination_area,
      p.earliest_departure_at,p.latest_departure_at,p.people_count) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal need snapshot does not match';
  END IF;
  SELECT v.seat_capacity INTO STRICT capacity FROM public.vehicles v WHERE v.id=p.vehicle_id FOR SHARE;
  PERFORM 1 FROM public.member_vehicle_access mva
    WHERE mva.member_id=p.offering_member_id AND mva.vehicle_id=p.vehicle_id AND mva.active FOR SHARE;
  IF NOT FOUND OR capacity<>p.vehicle_seat_capacity THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal vehicle access or capacity does not match';
  END IF;
  IF (SELECT count(*) FROM private.financial_proposal_travellers t WHERE t.proposal_id=p.id)<>p.people_count
    OR (SELECT count(*) FROM public.movement_participants mp
      WHERE mp.movement_need_id=p.movement_need_id AND mp.status='confirmed')<>p.people_count
    OR EXISTS (SELECT 1 FROM public.movement_participants mp
      WHERE mp.movement_need_id=p.movement_need_id AND mp.status='invited')
    OR EXISTS (
      SELECT 1 FROM private.financial_proposal_travellers t WHERE t.proposal_id=p.id AND (
        t.member_id=p.offering_member_id
        OR NOT EXISTS (SELECT 1 FROM public.movement_participants mp
          WHERE mp.id=t.participant_id AND mp.movement_need_id=p.movement_need_id
            AND mp.member_id=t.member_id AND mp.role=t.role AND mp.status='confirmed')
        OR (t.role='primary_requester') IS DISTINCT FROM (t.member_id=p.member_needing_movement_id)
      )
    ) OR NOT EXISTS (SELECT 1 FROM private.financial_proposal_travellers t
      WHERE t.proposal_id=p.id AND t.role='primary_requester' AND t.member_id=p.member_needing_movement_id) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal requires the exact complete confirmed roster';
  END IF;
END;

DECLARE a public.alignments%ROWTYPE; g private.financial_agreements%ROWTYPE;
BEGIN
  PERFORM private.assert_financial_proposal_quote_binding(p);
  PERFORM private.assert_financial_proposal_movement_context_binding(p);
  PERFORM private.assert_financial_proposal_source_compatibility(p);
  PERFORM private.assert_financial_proposal_snapshot_roster(p.id);
  IF p.offering_accepted_at IS NULL OR p.movement_offer_id IS NULL OR p.requester_accepted_at IS NULL
    OR p.alignment_id IS NULL OR p.financial_agreement_id IS NULL OR p.materialized_at IS NULL
    OR p.created_at IS NULL OR NOT isfinite(p.created_at) OR p.expires_at IS NULL OR NOT isfinite(p.expires_at)
    OR p.expires_at<=p.created_at OR NOT isfinite(p.offering_accepted_at) OR NOT isfinite(p.requester_accepted_at) OR NOT isfinite(p.materialized_at)
    OR p.offering_accepted_at>=p.expires_at OR p.requester_accepted_at>=p.expires_at
    OR p.materialized_at>=p.expires_at THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Complete consistent financial materialization required';
  END IF;
  -- Replay owns only proposal UPDATE; it never locks need. Take alignment SHARE before
  -- offer SHARE, matching activation's alignment -> offer dependency; taking
  -- offer UPDATE first on replay could deadlock its journey trigger. First
  -- construction already owns offer UPDATE and its new alignment is private
  -- to this transaction. Replay never upgrades locks into live pending checks.
  SELECT x.* INTO a FROM public.alignments x WHERE x.id=p.alignment_id FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Materialized alignment unavailable';
  END IF;
  PERFORM x.id FROM public.movement_offers x WHERE x.id=p.movement_offer_id FOR SHARE;
  SELECT x.* INTO g FROM private.financial_agreements x WHERE x.id=p.financial_agreement_id FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Materialized financial agreement unavailable';
  END IF;
  -- Replay validates historical identity; operational lifecycle and legacy fee
  -- may progress after acceptance. 0019 also permits no-travel cancellation.
  IF a.status NOT IN ('awaiting_activation_payment','activated','in_progress','completed','cancelled')
    OR a.activation_currency<>p.currency
    OR ROW(a.movement_need_id,a.movement_offer_id,a.offering_member_id,a.member_needing_movement_id)
      IS DISTINCT FROM ROW(p.movement_need_id,p.movement_offer_id,p.offering_member_id,p.member_needing_movement_id)
    -- 0020 permits consent-preserving supersession; validate the exact original
    -- agreement, not whichever version is current later.
    OR g.status NOT IN ('current','superseded') OR g.version<>1
    OR ROW(g.alignment_id,g.offering_member_id,g.member_needing_movement_id,g.financial_model_version,
      g.pricing_policy_version,g.platform_fee_allocation_policy_version,g.currency,g.quoted_platform_fee_total_minor,
      g.offering_accepted_at,g.requester_accepted_at)
      IS DISTINCT FROM ROW(p.alignment_id,p.offering_member_id,p.member_needing_movement_id,p.financial_model_version,
      p.pricing_policy_version,p.platform_fee_allocation_policy_version,p.currency,p.quoted_platform_fee_total_minor,
      p.offering_accepted_at,p.requester_accepted_at)
    OR NOT EXISTS (SELECT 1 FROM public.movement_needs n WHERE n.id=p.movement_need_id
      AND n.member_id=p.member_needing_movement_id AND n.status='closed')
    OR NOT EXISTS (SELECT 1 FROM public.movement_offers o WHERE o.id=p.movement_offer_id AND o.status='accepted')
    OR EXISTS (SELECT 1 FROM public.alignments x WHERE x.movement_need_id=p.movement_need_id
      AND x.id<>p.alignment_id AND x.status IN ('awaiting_activation_payment','activated','in_progress','completed'))
    OR (SELECT count(*) FROM private.financial_components c WHERE c.agreement_id=g.id)<>3
    OR EXISTS (SELECT 1 FROM public.movement_offers o WHERE o.movement_need_id=p.movement_need_id AND o.status='pending')
    OR EXISTS (
      SELECT component_key,amount_minor,responsible_member_id,beneficiary_kind,beneficiary_member_id
      FROM private.financial_components c WHERE c.agreement_id=g.id
      EXCEPT
      SELECT * FROM (VALUES
        ('offering_platform_share'::text,p.quoted_platform_fee_total_minor/2,p.offering_member_id,'platform'::text,NULL::uuid),
        ('requester_platform_share'::text,p.quoted_platform_fee_total_minor-p.quoted_platform_fee_total_minor/2,p.member_needing_movement_id,'platform'::text,NULL::uuid),
        ('movement_contribution'::text,p.quoted_movement_contribution_minor,p.member_needing_movement_id,'member'::text,p.offering_member_id)
      ) expected
    ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Financial materialization graph does not match proposal';
  END IF;
  -- Return status from the same SHARE-locked row whose graph was validated.
  RETURN a.status;
END;

DECLARE s private.movement_context_snapshots%ROWTYPE;
BEGIN
  SELECT x.* INTO s FROM private.movement_context_snapshots x
    WHERE x.id=p.movement_context_snapshot_id;
  IF NOT FOUND OR s.context_schema_version IS DISTINCT FROM 'movement_context_v1'
    OR s.movement_offer_id IS NULL OR p.movement_context_snapshot_version IS NULL
    OR ROW(p.movement_context_snapshot_version,p.movement_need_id,p.member_needing_movement_id,
      p.offering_member_id,p.vehicle_id,p.people_count,p.seats_offered,p.vehicle_seat_capacity,
      p.origin_area,p.destination_area,p.earliest_departure_at,p.latest_departure_at,
      p.proposed_pickup_area,p.proposed_dropoff_area,p.estimated_arrival_minutes)
    IS DISTINCT FROM ROW(s.version,s.movement_need_id,s.requesting_member_id,
      s.offering_member_id,s.vehicle_id,s.people_count,s.seats_offered,s.vehicle_seat_capacity,
      s.requester_origin_area,s.requester_destination_area,s.requester_earliest_departure_at,
      s.requester_latest_departure_at,s.proposed_pickup_area,s.proposed_dropoff_area,s.declared_arrival_minutes) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal requires exact movement context provenance';
  END IF;
  IF p.created_at IS NULL OR NOT isfinite(p.created_at)
    OR p.expires_at IS NULL OR NOT isfinite(p.expires_at) OR p.expires_at<=p.created_at
    OR s.expires_at IS NULL OR NOT isfinite(s.expires_at) OR p.expires_at>s.expires_at THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal lifetime must be finite and snapshot-bounded';
  END IF;
  IF p.movement_offer_id IS NOT NULL AND p.movement_offer_id IS DISTINCT FROM s.movement_offer_id THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal operational offer must equal its historical snapshot source';
  END IF;
END;

DECLARE q private.pricing_quotes%ROWTYPE;
BEGIN
  SELECT x.* INTO q FROM private.pricing_quotes x WHERE x.id=p.pricing_quote_id;
  IF NOT FOUND OR p.pricing_quote_version IS NULL OR
    ROW(p.pricing_quote_version,p.movement_need_id,p.member_needing_movement_id,
      p.offering_member_id,p.currency,p.pricing_policy_version)
    IS DISTINCT FROM ROW(q.version,q.movement_need_id,q.requesting_member_id,
      q.offering_member_id,q.currency,q.pricing_policy_version) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Proposal requires exact pricing quote provenance';
  END IF;
  IF p.created_at IS NULL OR NOT isfinite(p.created_at)
    OR p.expires_at IS NULL OR NOT isfinite(p.expires_at)
    OR p.expires_at<=p.created_at OR p.expires_at>q.expires_at THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Proposal lifetime must be finite and quote-bounded';
  END IF;
END;

DECLARE p private.financial_proposals%ROWTYPE; snapshot_count bigint; proposal_count bigint;
BEGIN
  SELECT x.* INTO STRICT p FROM private.financial_proposals x WHERE x.id=p_proposal_id;
  SELECT count(*) INTO proposal_count FROM private.financial_proposal_travellers t WHERE t.proposal_id=p.id;
  SELECT count(*) INTO snapshot_count FROM private.movement_context_snapshot_travellers t
    WHERE t.snapshot_id=p.movement_context_snapshot_id;
  IF proposal_count<>p.people_count OR snapshot_count<>p.people_count OR proposal_count<>snapshot_count
    OR EXISTS (
      SELECT t.member_id,t.participant_id,t.role FROM private.financial_proposal_travellers t WHERE t.proposal_id=p.id
      EXCEPT
      SELECT t.member_id,t.movement_participant_id,t.role FROM private.movement_context_snapshot_travellers t
        WHERE t.snapshot_id=p.movement_context_snapshot_id
    ) OR EXISTS (
      SELECT t.member_id,t.movement_participant_id,t.role FROM private.movement_context_snapshot_travellers t
        WHERE t.snapshot_id=p.movement_context_snapshot_id
      EXCEPT
      SELECT t.member_id,t.participant_id,t.role FROM private.financial_proposal_travellers t WHERE t.proposal_id=p.id
    ) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal requires the exact historical snapshot roster';
  END IF;
END;

DECLARE q private.pricing_quotes%ROWTYPE; s private.movement_context_snapshots%ROWTYPE;
  g private.pricing_geography_evidence%ROWTYPE;
  qm private.trusted_route_match_evidence%ROWTYPE;
  sm private.trusted_route_match_evidence%ROWTYPE;
  rb private.movement_offer_route_match_bindings%ROWTYPE;
BEGIN
  SELECT x.* INTO q FROM private.pricing_quotes x WHERE x.id=p.pricing_quote_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal quote source unavailable';
  END IF;
  SELECT x.* INTO s FROM private.movement_context_snapshots x WHERE x.id=p.movement_context_snapshot_id;
  IF NOT FOUND OR ROW(q.movement_need_id,q.requesting_member_id,q.offering_member_id,
      q.offering_movement_intent_id,q.offering_intent_version)
    IS DISTINCT FROM ROW(s.movement_need_id,s.requesting_member_id,s.offering_member_id,
      s.offering_movement_intent_id,s.offering_intent_version) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal quote and snapshot movement identities differ';
  END IF;
  SELECT x.* INTO g FROM private.pricing_geography_evidence x WHERE x.id=q.pricing_geography_evidence_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal pricing geography source unavailable';
  END IF;
  SELECT x.* INTO qm FROM private.trusted_route_match_evidence x WHERE x.id=g.route_match_evidence_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal pricing match source unavailable';
  END IF;
  SELECT x.* INTO rb FROM private.movement_offer_route_match_bindings x WHERE x.movement_offer_id=s.movement_offer_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal snapshot offer authorization unavailable';
  END IF;
  SELECT x.* INTO sm FROM private.trusted_route_match_evidence x WHERE x.id=rb.route_match_evidence_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal snapshot match source unavailable';
  END IF;
  -- 0059 copies the exact route and requester-origin state anchor from its match.
  -- 0072 binds the offer match's route to availability and copies its endpoints.
  -- Do not add redundant match-ID comparisons: 0037 already uniquely identifies
  -- a match by need/route/algorithm. Pricing classification identities may
  -- differ while the authoritative route and requester endpoints still agree.
  IF ROW(g.route_evidence_id,g.route_evidence_version,
      qm.requester_origin_location_reference_id,qm.requester_destination_location_reference_id,
      q.state_location_reference_id)
    IS DISTINCT FROM ROW(sm.route_evidence_id,sm.route_evidence_version,
      s.requester_origin_location_id,s.requester_destination_location_id,s.requester_origin_location_id) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal quote and snapshot route or endpoint provenance differs';
  END IF;
END;

DECLARE receipt private.funded_movement_activations%ROWTYPE; evidence record; p private.financial_proposals%ROWTYPE;
BEGIN
 SELECT x.* INTO receipt FROM private.funded_movement_activations x WHERE x.financial_agreement_id=g.id;
 SELECT * INTO evidence FROM private.movement_funding_evidence(g);
 IF receipt.financial_agreement_id IS NULL OR receipt.alignment_id IS DISTINCT FROM a.id
  OR g.alignment_id IS DISTINCT FROM a.id OR receipt.activated_at IS DISTINCT FROM a.activated_at
  OR a.status NOT IN ('activated','in_progress','completed','cancelled')
  OR evidence.fully_held_at IS NULL OR evidence.held_minor<>evidence.required_minor
  OR NOT isfinite(receipt.activated_at) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact historical funded activation required'; END IF;
 SELECT x.* INTO STRICT p FROM private.financial_proposals x WHERE x.financial_agreement_id=g.id;
 -- Receipt certifies current prepared/verified media and member flags at the
 -- original gate. Historical checks do not demand that media remain current now.
 IF EXISTS (
  (SELECT g.offering_member_id AS member_id UNION SELECT t.member_id FROM private.movement_context_snapshot_travellers t WHERE t.snapshot_id=p.movement_context_snapshot_id)
  EXCEPT SELECT x.member_id FROM private.funded_movement_activation_faces x WHERE x.financial_agreement_id=g.id
 ) OR EXISTS (
  SELECT x.member_id FROM private.funded_movement_activation_faces x WHERE x.financial_agreement_id=g.id
  EXCEPT (SELECT g.offering_member_id UNION SELECT t.member_id FROM private.movement_context_snapshot_travellers t WHERE t.snapshot_id=p.movement_context_snapshot_id)
 ) OR EXISTS (
  SELECT 1 FROM private.funded_movement_activation_faces x
  LEFT JOIN private.alignment_face_verifications f ON f.id=x.face_verification_id
  WHERE x.financial_agreement_id=g.id AND (f.id IS NULL OR f.alignment_id IS DISTINCT FROM a.id
   OR f.member_id IS DISTINCT FROM x.member_id OR f.status<>'succeeded'
   OR f.liveness_passed IS DISTINCT FROM true OR f.face_match_passed IS DISTINCT FROM true
   OR f.completed_at IS NULL
   OR f.completed_at>=f.expires_at OR f.expires_at<=receipt.activated_at
   OR NOT isfinite(f.started_at) OR NOT isfinite(f.completed_at) OR NOT isfinite(f.expires_at)
   OR f.attempt_ordinal IS NULL OR f.attempt_ordinal<=0)
 ) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact historical activation face evidence required'; END IF;
 PERFORM private.assert_activation_fee_finalization(g.id);
END;

DECLARE a public.alignments%ROWTYPE; j public.journeys%ROWTYPE; g private.financial_agreements%ROWTYPE;
 request private.funded_movement_completion_requests%ROWTYPE; receipt private.funded_movement_completions%ROWTYPE;
 c private.financial_components%ROWTYPE; t private.wallet_transactions%ROWTYPE;
 response_window private.funded_completion_response_windows%ROWTYPE; review private.funded_completion_disputes%ROWTYPE;
 kind text; debit_id uuid; credit_id uuid; n bigint; matches bigint;
BEGIN
 SELECT x.* INTO STRICT a FROM public.alignments x WHERE x.id=p_alignment;
 SELECT x.* INTO STRICT j FROM public.journeys x JOIN private.funded_movement_coordination_entries e ON e.journey_id=x.id WHERE e.alignment_id=a.id;
 SELECT x.* INTO STRICT g FROM private.financial_agreements x JOIN private.funded_movement_activations e ON e.financial_agreement_id=x.id WHERE e.alignment_id=a.id;
 SELECT x.* INTO request FROM private.funded_movement_completion_requests x WHERE x.alignment_id=a.id;
 SELECT x.* INTO receipt FROM private.funded_movement_completions x WHERE x.alignment_id=a.id;
 SELECT x.* INTO response_window FROM private.funded_completion_response_windows x WHERE x.alignment_id=a.id;
 SELECT x.* INTO review FROM private.funded_completion_disputes x WHERE x.alignment_id=a.id;
 IF request.alignment_id IS NULL AND (response_window.alignment_id IS NOT NULL OR review.alignment_id IS NOT NULL) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Response evidence requires exact completion request'; END IF;
 IF request.alignment_id IS NOT NULL THEN
  IF response_window.alignment_id IS NULL OR response_window.financial_agreement_id IS DISTINCT FROM request.financial_agreement_id
   OR response_window.journey_id IS DISTINCT FROM request.journey_id OR response_window.requested_at IS DISTINCT FROM request.requested_at
   OR NOT isfinite(response_window.response_deadline_at) OR response_window.response_deadline_at IS DISTINCT FROM response_window.requested_at+interval '12 hours' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact immutable response response_window required'; END IF;
 END IF;
 IF review.alignment_id IS NOT NULL THEN
  IF review.financial_agreement_id IS DISTINCT FROM g.id OR review.journey_id IS DISTINCT FROM j.id
   OR review.requester_member_id IS DISTINCT FROM a.member_needing_movement_id OR NOT isfinite(review.opened_at)
   OR review.opened_at>=response_window.response_deadline_at OR receipt.alignment_id IS NOT NULL
   OR a.status<>'in_progress' OR j.status<>'in_progress' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact unsettled requester review required'; END IF;
 END IF;
 IF request.alignment_id IS NULL THEN
  IF receipt.alignment_id IS NOT NULL OR j.completion_requested_at IS NOT NULL OR j.completed_at IS NOT NULL
   OR a.status='completed' OR j.status='completed' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact completion request required'; END IF;
 ELSE
  IF request.financial_agreement_id IS DISTINCT FROM g.id OR request.journey_id IS DISTINCT FROM j.id
   OR request.requested_at IS DISTINCT FROM j.completion_requested_at OR j.started_at IS NULL
   OR NOT isfinite(request.requested_at) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact historical completion request required'; END IF;
  IF receipt.alignment_id IS NULL THEN
   IF a.status<>'in_progress' OR j.status<>'in_progress' OR j.completed_at IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Unsettled completion must remain in progress'; END IF;
  ELSIF receipt.financial_agreement_id IS DISTINCT FROM g.id OR receipt.journey_id IS DISTINCT FROM j.id
   OR receipt.completed_at IS DISTINCT FROM j.completed_at OR NOT isfinite(receipt.completed_at)
   OR receipt.completion_method NOT IN ('requester_confirmed','response_timeout')
   -- Recorded timeout admission used this exact server observation against its
   -- immutable deadline. Never resample a clock to validate historical truth.
   OR (receipt.completion_method='response_timeout' AND receipt.completed_at<response_window.response_deadline_at) OR a.status<>'completed' OR j.status<>'completed' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Complete exact settled lifecycle required';
  END IF;
 END IF;
 PERFORM private.assert_activation_fee_finalization(g.id);
 FOR c IN SELECT x.* FROM private.financial_components x WHERE x.agreement_id=g.id ORDER BY x.id LOOP
  IF c.component_key='requester_platform_share' AND private.activation_fee_is_finalized(g.id) THEN CONTINUE; END IF;
  kind:=CASE c.component_key WHEN 'requester_platform_share' THEN 'requester_platform_charge'
   WHEN 'movement_contribution' THEN 'movement_contribution_settlement' ELSE 'offering_platform_charge' END;
  SELECT x.* INTO t FROM private.wallet_transactions x WHERE x.idempotency_key=kind||':'||c.id::text;
  SELECT count(*) INTO n FROM private.wallet_transactions x WHERE x.financial_component_id=c.id
   AND x.transaction_kind IN ('requester_platform_charge','movement_contribution_settlement','offering_platform_charge');
  IF receipt.alignment_id IS NULL OR c.amount_minor=0 THEN
   IF t.id IS NOT NULL OR n<>0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Partial or zero settlement history forbidden'; END IF;
   CONTINUE;
  END IF;
  SELECT x.id INTO debit_id FROM private.wallet_accounts x WHERE x.currency=g.currency AND
   ((c.component_key='offering_platform_share' AND x.member_id=g.offering_member_id AND x.account_kind='member_withdrawable')
    OR (c.component_key<>'offering_platform_share' AND x.member_id=g.member_needing_movement_id AND x.account_kind='member_held'));
  SELECT x.id INTO credit_id FROM private.wallet_accounts x WHERE x.currency=g.currency AND
   ((c.component_key='movement_contribution' AND x.member_id=g.offering_member_id AND x.account_kind='member_withdrawable')
    OR (c.component_key<>'movement_contribution' AND x.member_id IS NULL AND x.account_kind='platform_revenue'));
  IF n<>1 OR t.id IS NULL OR t.transaction_kind IS DISTINCT FROM kind OR t.currency IS DISTINCT FROM g.currency
   OR t.alignment_id IS DISTINCT FROM a.id OR t.financial_component_id IS DISTINCT FROM c.id
   OR t.provider IS NOT NULL OR t.provider_reference IS NOT NULL OR debit_id IS NULL OR credit_id IS NULL
   OR NOT isfinite(t.created_at) OR t.created_at IS DISTINCT FROM receipt.completed_at THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact historical settlement transaction required'; END IF;
  SELECT count(*),count(*) FILTER(WHERE x.amount_minor=c.amount_minor AND isfinite(x.created_at) AND x.created_at=t.created_at
   AND ((x.account_id=debit_id AND x.direction='debit') OR (x.account_id=credit_id AND x.direction='credit')))
   INTO n,matches FROM private.wallet_postings x WHERE x.transaction_id=t.id;
  IF n<>2 OR matches<>2 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact historical settlement postings required'; END IF;
  PERFORM private.assert_wallet_transaction_balanced(t.id);
 END LOOP;
 IF EXISTS(SELECT 1 FROM private.wallet_transactions x WHERE x.alignment_id=a.id
  AND x.transaction_kind IN ('requester_platform_charge','movement_contribution_settlement','offering_platform_charge')
  AND NOT EXISTS(SELECT 1 FROM private.financial_components fc WHERE fc.id=x.financial_component_id AND fc.agreement_id=g.id)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Competing settlement history forbidden'; END IF;
END;

DECLARE r private.funded_movement_coordination_entries%ROWTYPE; j public.journeys%ROWTYPE;
 a public.alignments%ROWTYPE; g private.financial_agreements%ROWTYPE;
 request private.funded_movement_start_requests%ROWTYPE; started private.funded_movement_starts%ROWTYPE; mp private.journey_meeting_points%ROWTYPE;
BEGIN
 IF EXISTS(SELECT 1 FROM private.funded_no_travel_closures WHERE alignment_id=p_alignment) THEN
  PERFORM private.assert_funded_no_travel(p_alignment);
  SELECT x.* INTO STRICT j FROM public.journeys x JOIN private.funded_no_travel_closures d ON d.journey_id=x.id WHERE d.alignment_id=p_alignment; RETURN j;
 END IF;
 SELECT x.* INTO r FROM private.funded_movement_coordination_entries x WHERE x.alignment_id=p_alignment;
 SELECT x.* INTO a FROM public.alignments x WHERE x.id=p_alignment;
 SELECT x.* INTO g FROM private.financial_agreements x WHERE x.id=r.financial_agreement_id;
 SELECT x.* INTO j FROM public.journeys x WHERE x.id=r.journey_id;
 IF r.alignment_id IS NULL OR j.id IS NULL OR g.id IS NULL
  OR (SELECT count(*) FROM public.journeys WHERE alignment_id=p_alignment)<>1
  OR g.alignment_id IS DISTINCT FROM a.id OR j.alignment_id IS DISTINCT FROM a.id
  OR j.vehicle_id IS DISTINCT FROM (SELECT vehicle_id FROM public.movement_offers WHERE id=a.movement_offer_id)
  OR j.created_at IS DISTINCT FROM r.created_at OR NOT isfinite(r.created_at)
  OR EXISTS(SELECT 1 FROM private.mutual_no_travel_closures c WHERE c.journey_id=j.id)
  OR EXISTS(SELECT 1 FROM private.movement_settlements c WHERE c.journey_id=j.id OR c.alignment_id=a.id)
  OR j.end_requested_by_member_id IS NOT NULL OR j.end_requested_at IS NOT NULL
  OR j.end_confirmed_by_member_id IS NOT NULL OR j.end_confirmed_at IS NOT NULL OR j.end_reason IS NOT NULL OR j.end_method IS NOT NULL THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Complete exact coordination entry required'; END IF;
 SELECT x.* INTO request FROM private.funded_movement_start_requests x WHERE x.alignment_id=a.id;
 SELECT x.* INTO started FROM private.funded_movement_starts x WHERE x.alignment_id=a.id;
 SELECT x.* INTO mp FROM private.journey_meeting_points x WHERE x.journey_id=j.id;
 IF request.alignment_id IS NULL THEN
  IF started.alignment_id IS NOT NULL OR a.status<>'activated' OR j.status<>'not_started'
   OR j.start_requested_at IS NOT NULL OR j.started_at IS NOT NULL THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact financial start request required'; END IF;
 ELSE
  IF request.journey_id IS DISTINCT FROM j.id OR request.requested_at IS DISTINCT FROM j.start_requested_at
   OR NOT isfinite(request.requested_at)
   OR mp.journey_id IS NULL OR mp.revision IS DISTINCT FROM request.meeting_point_revision
   OR mp.place_text<>btrim(mp.place_text) OR length(mp.place_text) NOT BETWEEN 1 AND 200 OR mp.place_text !~ '[^[:space:]]' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact frozen meeting point and start request required'; END IF;
  IF started.alignment_id IS NULL THEN
   IF a.status<>'activated' OR j.status<>'not_started' OR j.started_at IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact financial start confirmation required'; END IF;
  ELSIF started.journey_id IS DISTINCT FROM j.id OR started.started_at IS DISTINCT FROM j.started_at
   OR NOT isfinite(started.started_at)
   OR a.status NOT IN ('in_progress','completed') OR j.status IS DISTINCT FROM a.status THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Complete exact financial start required';
  END IF;
 END IF;
 PERFORM private.assert_funded_activation(g,a);
 PERFORM private.assert_funded_completion(a.id);
 PERFORM private.assert_held_no_travel(a.id);
 RETURN j;
END;

DECLARE d private.funded_movement_disputes%ROWTYPE; a public.alignments%ROWTYPE;
 e private.funded_movement_coordination_entries%ROWTYPE;
BEGIN
 SELECT * INTO d FROM private.funded_movement_disputes WHERE alignment_id=p_alignment;
 IF d.alignment_id IS NULL THEN RETURN; END IF;
 SELECT * INTO STRICT a FROM public.alignments WHERE id=p_alignment;
 SELECT * INTO STRICT e FROM private.funded_movement_coordination_entries WHERE alignment_id=a.id;
 -- 0085 already proves the complete held graph, including absent/partial
 -- release and settlement evidence and exact optional pending start history.
 PERFORM private.assert_undisposed_funded_graph(a.id);
 IF d.financial_agreement_id IS DISTINCT FROM e.financial_agreement_id
  OR d.journey_id IS DISTINCT FROM e.journey_id
  OR d.opened_by_member_id NOT IN(a.offering_member_id,a.member_needing_movement_id)
  -- Server-observed metadata is finite, never a cross-sample ordering proof.
  OR NOT isfinite(d.opened_at)
  OR a.status<>'activated'
  OR EXISTS(SELECT 1 FROM private.funded_no_travel_closures WHERE alignment_id=a.id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact frozen funded graph required'; END IF;
END;

DECLARE a public.alignments%ROWTYPE; j public.journeys%ROWTYPE; g private.financial_agreements%ROWTYPE;
 e private.funded_movement_coordination_entries%ROWTYPE; r private.funded_no_travel_requests%ROWTYPE;
 d private.funded_no_travel_closures%ROWTYPE; c private.financial_components%ROWTYPE;
 t private.wallet_transactions%ROWTYPE; sr private.funded_movement_start_requests%ROWTYPE;
 mp private.journey_meeting_points%ROWTYPE; available_id uuid; held_id uuid; n bigint; matches bigint;
BEGIN
 SELECT x.* INTO STRICT a FROM public.alignments x WHERE x.id=p_alignment;
 SELECT x.* INTO STRICT e FROM private.funded_movement_coordination_entries x WHERE x.alignment_id=a.id;
 SELECT x.* INTO STRICT j FROM public.journeys x WHERE x.id=e.journey_id;
 SELECT x.* INTO STRICT g FROM private.financial_agreements x WHERE x.id=e.financial_agreement_id;
 g:=private.movement_funding_agreement(g.id,g.member_needing_movement_id,g.version);
 PERFORM private.assert_funded_activation(g,a);
 -- Reuse 0083's complete absence/partial-settlement proof, including component
 -- keys whose transaction alignment was forged or belongs to another graph.
 PERFORM private.assert_funded_completion(a.id);
 SELECT x.* INTO d FROM private.funded_no_travel_closures x WHERE x.alignment_id=a.id;
 IF d.alignment_id IS NOT NULL AND private.activation_fee_is_finalized(g.id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Activated contribution remains held for review'; END IF;
 IF j.alignment_id IS DISTINCT FROM a.id OR g.alignment_id IS DISTINCT FROM a.id
  OR (SELECT count(*) FROM public.journeys WHERE alignment_id=a.id)<>1
  OR j.vehicle_id IS DISTINCT FROM (SELECT vehicle_id FROM public.movement_offers WHERE id=a.movement_offer_id)
  OR j.created_at IS DISTINCT FROM e.created_at OR NOT isfinite(e.created_at)
  OR j.started_at IS NOT NULL OR j.completed_at IS NOT NULL OR j.completion_requested_at IS NOT NULL
  OR j.end_requested_by_member_id IS NOT NULL OR j.end_requested_at IS NOT NULL
  OR j.end_confirmed_by_member_id IS NOT NULL OR j.end_confirmed_at IS NOT NULL OR j.end_method IS NOT NULL OR j.end_reason IS NOT NULL
  OR EXISTS(SELECT 1 FROM private.funded_movement_starts WHERE alignment_id=a.id OR journey_id=j.id)
  OR EXISTS(SELECT 1 FROM private.funded_movement_completion_requests WHERE alignment_id=a.id OR journey_id=j.id)
  OR EXISTS(SELECT 1 FROM private.funded_movement_completions WHERE alignment_id=a.id OR journey_id=j.id)
  OR EXISTS(SELECT 1 FROM private.completed_movement_principals WHERE alignment_id=a.id)
  OR EXISTS(SELECT 1 FROM private.completed_movement_ratings WHERE alignment_id=a.id)
  OR EXISTS(SELECT 1 FROM private.movement_settlements WHERE alignment_id=a.id OR journey_id=j.id)
  OR EXISTS(SELECT 1 FROM private.mutual_no_travel_closures WHERE journey_id=j.id)
  OR EXISTS(SELECT 1 FROM private.wallet_transactions WHERE alignment_id=a.id
    AND (transaction_kind IN ('offering_platform_charge','movement_contribution_settlement')
     OR (transaction_kind='requester_platform_charge' AND NOT private.activation_fee_is_finalized(g.id)))) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact unstarted funded lifecycle required'; END IF;
 SELECT x.* INTO sr FROM private.funded_movement_start_requests x WHERE x.alignment_id=a.id;
 IF sr.alignment_id IS NULL THEN
  IF j.start_requested_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact pending start required'; END IF;
 ELSE
  SELECT x.* INTO mp FROM private.journey_meeting_points x WHERE x.journey_id=j.id;
  IF sr.journey_id IS DISTINCT FROM j.id OR sr.requested_at IS DISTINCT FROM j.start_requested_at
   OR NOT isfinite(sr.requested_at)
   OR mp.journey_id IS NULL OR mp.revision IS DISTINCT FROM sr.meeting_point_revision
   OR mp.place_text<>btrim(mp.place_text) OR length(mp.place_text) NOT BETWEEN 1 AND 200 OR mp.place_text !~ '[^[:space:]]' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact frozen pending start required'; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM private.funded_no_travel_requests q WHERE q.alignment_id=a.id AND
  (q.financial_agreement_id IS DISTINCT FROM g.id OR q.journey_id IS DISTINCT FROM j.id
   OR q.first_principal_id NOT IN (a.offering_member_id,a.member_needing_movement_id)
   OR NOT isfinite(q.requested_at)))
  OR EXISTS(SELECT 1 FROM private.funded_no_travel_declines z JOIN private.funded_no_travel_requests q ON q.id=z.request_id
   WHERE q.alignment_id=a.id AND (z.second_principal_id=q.first_principal_id
    OR z.second_principal_id NOT IN(a.offering_member_id,a.member_needing_movement_id)
    OR NOT isfinite(z.declined_at)))
  OR (SELECT count(*) FROM private.funded_no_travel_requests q WHERE q.alignment_id=a.id
   AND NOT EXISTS(SELECT 1 FROM private.funded_no_travel_declines z WHERE z.request_id=q.id))>1 THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact principal intent history required'; END IF;
 IF d.alignment_id IS NULL THEN
  IF a.status<>'activated' OR j.status<>'not_started' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact pre-start lifecycle required'; END IF;
 ELSE
  SELECT x.* INTO STRICT r FROM private.funded_no_travel_requests x WHERE x.id=d.request_id;
  IF d.financial_agreement_id IS DISTINCT FROM g.id OR d.journey_id IS DISTINCT FROM j.id
   OR r.alignment_id IS DISTINCT FROM a.id OR d.first_principal_id IS DISTINCT FROM r.first_principal_id
   OR d.second_principal_id NOT IN(a.offering_member_id,a.member_needing_movement_id)
   OR d.requested_at IS DISTINCT FROM r.requested_at OR NOT isfinite(d.released_at)
   OR d.pending_start_requested_at IS DISTINCT FROM j.start_requested_at
   OR EXISTS(SELECT 1 FROM private.funded_no_travel_declines WHERE request_id=r.id)
   OR a.status<>'cancelled' OR j.status<>'cancelled' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Complete exact funded disposition required'; END IF;
 END IF;
 SELECT id INTO STRICT available_id FROM private.wallet_accounts WHERE member_id=g.member_needing_movement_id AND currency=g.currency AND account_kind='member_available';
 SELECT id INTO STRICT held_id FROM private.wallet_accounts WHERE member_id=g.member_needing_movement_id AND currency=g.currency AND account_kind='member_held';
 FOR c IN SELECT * FROM private.financial_components WHERE agreement_id=g.id ORDER BY id LOOP
  SELECT x.* INTO t FROM private.wallet_transactions x WHERE x.idempotency_key='movement_hold_release:'||c.id::text;
  SELECT count(*) INTO n FROM private.wallet_transactions WHERE financial_component_id=c.id AND transaction_kind='movement_hold_release';
  IF d.alignment_id IS NULL OR c.amount_minor=0 OR c.component_key='offering_platform_share' OR (c.component_key='requester_platform_share' AND private.activation_fee_is_finalized(g.id)) THEN
   IF t.id IS NOT NULL OR n<>0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Partial or zero release forbidden'; END IF;
   CONTINUE;
  END IF;
  IF n<>1 OR t.id IS NULL OR t.transaction_kind IS DISTINCT FROM 'movement_hold_release'
   OR t.financial_component_id IS DISTINCT FROM c.id OR t.alignment_id IS DISTINCT FROM a.id OR t.currency IS DISTINCT FROM g.currency
   OR t.provider IS NOT NULL OR t.provider_reference IS NOT NULL OR t.created_at IS DISTINCT FROM d.released_at THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact release transaction required'; END IF;
  SELECT count(*),count(*) FILTER(WHERE amount_minor=c.amount_minor AND created_at=d.released_at
   AND ((account_id=held_id AND direction='debit') OR (account_id=available_id AND direction='credit')))
   INTO n,matches FROM private.wallet_postings WHERE transaction_id=t.id;
  IF n<>2 OR matches<>2 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact release postings required'; END IF;
  PERFORM private.assert_wallet_transaction_balanced(t.id);
 END LOOP;
 IF EXISTS(SELECT 1 FROM private.wallet_transactions wx WHERE wx.alignment_id=a.id AND wx.transaction_kind='movement_hold_release'
  AND NOT EXISTS(SELECT 1 FROM private.financial_components fc WHERE fc.id=wx.financial_component_id AND fc.agreement_id=g.id)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Competing release history forbidden'; END IF;
END;

DECLARE
  point jsonb;
  longitude_value numeric;
  latitude_value numeric;
BEGIN
  -- Separate type guards from array operations: SQL does not promise OR order.
  IF jsonb_typeof(p_shape) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Route shape must be an object';
  END IF;
  IF p_shape->>'type' IS DISTINCT FROM 'LineString'
    OR jsonb_typeof(p_shape->'coordinates') IS DISTINCT FROM 'array'
    OR (p_shape - 'type' - 'coordinates') IS DISTINCT FROM '{}'::jsonb THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Route shape must be normalized GeoJSON LineString v1';
  END IF;
  IF jsonb_array_length(p_shape->'coordinates') < 2 THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Route shape requires at least two points';
  END IF;
  FOR point IN SELECT value FROM jsonb_array_elements(p_shape->'coordinates')
  LOOP
    IF jsonb_typeof(point) IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Route shape coordinates must be arrays';
    END IF;
    IF jsonb_array_length(point) <> 2
      OR jsonb_typeof(point->0) IS DISTINCT FROM 'number'
      OR jsonb_typeof(point->1) IS DISTINCT FROM 'number' THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Route shape coordinates are invalid';
    END IF;
    longitude_value := (point->>0)::numeric;
    latitude_value := (point->>1)::numeric;
    IF longitude_value < -180 OR longitude_value > 180
      OR latitude_value < -90 OR latitude_value > 90 THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Route shape coordinates are out of range';
    END IF;
  END LOOP;
END;

DECLARE h private.funded_no_travel_holds%ROWTYPE; r private.funded_no_travel_requests%ROWTYPE;
 a public.alignments%ROWTYPE; e private.funded_movement_coordination_entries%ROWTYPE; j public.journeys%ROWTYPE;
BEGIN
 SELECT * INTO h FROM private.funded_no_travel_holds WHERE alignment_id=p_alignment;
 IF h.alignment_id IS NULL THEN RETURN; END IF;
 SELECT * INTO STRICT a FROM public.alignments WHERE id=p_alignment;
 SELECT * INTO STRICT e FROM private.funded_movement_coordination_entries WHERE alignment_id=p_alignment;
 SELECT * INTO STRICT j FROM public.journeys WHERE id=e.journey_id;
 SELECT * INTO STRICT r FROM private.funded_no_travel_requests WHERE id=h.request_id;
 PERFORM private.assert_funded_no_travel(p_alignment);
 IF h.financial_agreement_id IS DISTINCT FROM e.financial_agreement_id OR h.journey_id IS DISTINCT FROM e.journey_id
  OR NOT EXISTS(SELECT 1 FROM private.funded_movement_activations WHERE financial_agreement_id=h.financial_agreement_id AND alignment_id=a.id)
  OR r.alignment_id IS DISTINCT FROM a.id OR r.financial_agreement_id IS DISTINCT FROM h.financial_agreement_id
  OR r.journey_id IS DISTINCT FROM h.journey_id OR h.first_principal_id IS DISTINCT FROM r.first_principal_id
  OR h.second_principal_id NOT IN(a.offering_member_id,a.member_needing_movement_id)
  OR h.first_principal_id=h.second_principal_id OR h.requested_at IS DISTINCT FROM r.requested_at
  OR NOT isfinite(h.observed_at) OR h.pending_start_requested_at IS DISTINCT FROM j.start_requested_at
  OR EXISTS(SELECT 1 FROM private.funded_no_travel_declines WHERE request_id=h.request_id)
  OR EXISTS(SELECT 1 FROM private.funded_movement_disputes WHERE alignment_id=a.id)
  OR EXISTS(SELECT 1 FROM private.funded_no_travel_closures WHERE alignment_id=a.id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact held no-travel provenance required'; END IF;
END;

DECLARE snapshot_row private.movement_context_snapshots%ROWTYPE;
  need_row public.movement_needs%ROWTYPE; intent_row private.offering_movement_intents%ROWTYPE;
  offer_row public.movement_offers%ROWTYPE; current_capacity integer;
BEGIN
  IF current_setting('transaction_isolation')<>'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000',MESSAGE='Movement context validation requires READ COMMITTED';
  END IF;
  SELECT s.* INTO STRICT snapshot_row FROM private.movement_context_snapshots s WHERE s.id=p_snapshot_id;
  SELECT n.* INTO STRICT need_row FROM public.movement_needs n WHERE n.id=snapshot_row.movement_need_id FOR UPDATE;
  -- Reread under lock after the need: a concurrent terminal transition must not
  -- race a future consumer's eligibility check on an already stored snapshot.
  SELECT s.* INTO STRICT snapshot_row FROM private.movement_context_snapshots s WHERE s.id=p_snapshot_id FOR SHARE;
  IF snapshot_row.status<>'current' OR (snapshot_row.expires_at IS NOT NULL AND snapshot_row.expires_at<=clock_timestamp()) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement snapshot is not current and unexpired';
  END IF;
  IF ROW(need_row.member_id,need_row.origin_area,need_row.destination_area,need_row.earliest_departure_at,need_row.latest_departure_at,need_row.people_count)
    IS DISTINCT FROM ROW(snapshot_row.requesting_member_id,snapshot_row.requester_origin_area,snapshot_row.requester_destination_area,
      snapshot_row.requester_earliest_departure_at,snapshot_row.requester_latest_departure_at,snapshot_row.people_count) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement snapshot need declarations do not match';
  END IF;
  IF need_row.status<>'discoverable' OR EXISTS (SELECT 1 FROM public.alignments existing_alignment
    WHERE existing_alignment.movement_need_id=need_row.id
      AND existing_alignment.status IN ('awaiting_activation_payment','activated','in_progress','completed')) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement snapshot requires an available need';
  END IF;
  IF snapshot_row.movement_offer_id IS NOT NULL THEN
    SELECT mo.* INTO STRICT offer_row FROM public.movement_offers mo WHERE mo.id=snapshot_row.movement_offer_id FOR SHARE;
    IF offer_row.status<>'pending' OR ROW(offer_row.movement_need_id,offer_row.offering_member_id,offer_row.vehicle_id,
      offer_row.seats_offered,offer_row.proposed_pickup_area,offer_row.proposed_dropoff_area,offer_row.estimated_arrival_minutes)
      IS DISTINCT FROM ROW(snapshot_row.movement_need_id,snapshot_row.offering_member_id,snapshot_row.vehicle_id,
        snapshot_row.seats_offered,snapshot_row.proposed_pickup_area,snapshot_row.proposed_dropoff_area,snapshot_row.declared_arrival_minutes) THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement snapshot offer does not match';
    END IF;
  END IF;
  PERFORM private.assert_offering_movement_intent(snapshot_row.offering_movement_intent_id);
  SELECT i.* INTO STRICT intent_row FROM private.offering_movement_intents i WHERE i.id=snapshot_row.offering_movement_intent_id;
  IF ROW(intent_row.offering_member_id,intent_row.version,intent_row.earliest_departure_at,intent_row.latest_departure_at)
    IS DISTINCT FROM ROW(snapshot_row.offering_member_id,snapshot_row.offering_intent_version,
      snapshot_row.offering_earliest_departure_at,snapshot_row.offering_latest_departure_at)
    OR NOT EXISTS (SELECT 1 FROM private.offering_movement_intent_locations il WHERE il.intent_id=intent_row.id
      AND il.role='origin' AND il.location_reference_id=snapshot_row.offering_origin_location_id)
    OR NOT EXISTS (SELECT 1 FROM private.offering_movement_intent_locations il WHERE il.intent_id=intent_row.id
      AND il.role='destination' AND il.location_reference_id=snapshot_row.offering_destination_location_id) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement snapshot offering intent does not match';
  END IF;
  IF EXISTS (SELECT 1 FROM private.movement_location_references lr
    WHERE lr.id IN (snapshot_row.requester_origin_location_id,snapshot_row.requester_destination_location_id)
      AND (lr.owner_member_id<>snapshot_row.requesting_member_id OR (lr.expires_at IS NOT NULL AND lr.expires_at<=clock_timestamp()))) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement snapshot requester location owner or expiry does not match';
  END IF;
  SELECT v.seat_capacity INTO STRICT current_capacity FROM public.vehicles v WHERE v.id=snapshot_row.vehicle_id FOR SHARE;
  PERFORM 1 FROM public.member_vehicle_access mva WHERE mva.member_id=snapshot_row.offering_member_id
    AND mva.vehicle_id=snapshot_row.vehicle_id AND mva.active FOR SHARE;
  IF NOT FOUND OR current_capacity<>snapshot_row.vehicle_seat_capacity OR snapshot_row.seats_offered>current_capacity THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement snapshot vehicle access or capacity does not match';
  END IF;
  IF (SELECT count(*) FROM private.movement_context_snapshot_travellers st WHERE st.snapshot_id=snapshot_row.id)<>snapshot_row.people_count
    OR (SELECT count(*) FROM public.movement_participants mp WHERE mp.movement_need_id=need_row.id AND mp.status='confirmed')<>snapshot_row.people_count
    OR EXISTS (SELECT 1 FROM public.movement_participants mp WHERE mp.movement_need_id=need_row.id AND mp.status='invited')
    OR EXISTS (SELECT 1 FROM private.movement_context_snapshot_travellers st WHERE st.snapshot_id=snapshot_row.id AND (
      st.member_id=snapshot_row.offering_member_id
      OR (st.role='primary_requester') IS DISTINCT FROM (st.member_id=snapshot_row.requesting_member_id)
      OR NOT EXISTS (SELECT 1 FROM public.movement_participants mp WHERE mp.id=st.movement_participant_id
        AND mp.movement_need_id=need_row.id AND mp.member_id=st.member_id AND mp.role=st.role AND mp.status='confirmed')))
    OR NOT EXISTS (SELECT 1 FROM private.movement_context_snapshot_travellers st WHERE st.snapshot_id=snapshot_row.id
      AND st.member_id=snapshot_row.requesting_member_id AND st.role='primary_requester') THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement snapshot requires the exact confirmed roster';
  END IF;
END;

DECLARE
  e private.movement_location_resolution_evidence%ROWTYPE;
  s private.movement_location_references%ROWTYPE;
  t private.movement_location_references%ROWTYPE;
  v_now timestamptz;
BEGIN
  SELECT r.* INTO STRICT e FROM private.movement_location_resolution_evidence r WHERE r.id=p_evidence_id;
  SELECT r.* INTO STRICT s FROM private.movement_location_references r WHERE r.id=e.source_location_reference_id FOR UPDATE;
  SELECT r.* INTO STRICT t FROM private.movement_location_references r WHERE r.id=e.resolved_location_reference_id FOR SHARE;
  v_now := clock_timestamp();
  IF s.resolution_status IS DISTINCT FROM 'unresolved'
    OR s.source_kind NOT IN ('member_declared','member_selected')
    OR s.latitude IS NOT NULL OR s.longitude IS NOT NULL
    OR s.resolved_at IS NOT NULL OR s.resolution_version IS NOT NULL
    OR (s.provider_namespace IS NULL)<>(s.provider_place_reference IS NULL)
    OR s.id=t.id OR s.owner_member_id IS DISTINCT FROM t.owner_member_id
    OR s.declared_label IS DISTINCT FROM t.declared_label THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Location resolution source binding is invalid';
  END IF;
  IF t.source_kind IS DISTINCT FROM 'provider_resolved' OR t.resolution_status IS DISTINCT FROM 'resolved'
    OR t.latitude IS NULL OR t.longitude IS NULL
    OR NOT (t.latitude BETWEEN -90 AND 90) OR NOT (t.longitude BETWEEN -180 AND 180)
    OR t.latitude::text IN ('NaN','Infinity','-Infinity') OR t.longitude::text IN ('NaN','Infinity','-Infinity')
    OR t.provider_namespace IS NULL OR t.provider_place_reference IS NULL OR t.resolution_version IS NULL
    OR t.provider_namespace !~ '[^[:space:]]' OR t.provider_place_reference !~ '[^[:space:]]'
    OR t.resolution_version !~ '[^[:space:]]'
    OR e.version<1 OR e.resolution_schema_version IS DISTINCT FROM 'movement_location_resolution_v1'
    OR e.provider_product !~ '[^[:space:]]' OR e.provider_version !~ '[^[:space:]]' THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Location resolution target evidence is invalid';
  END IF;
  IF s.provider_namespace IS NOT NULL AND
    (s.provider_namespace IS DISTINCT FROM t.provider_namespace
      OR s.provider_place_reference IS DISTINCT FROM t.provider_place_reference) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Location resolution must preserve provider selection identity';
  END IF;
  IF t.resolved_at IS NULL OR NOT isfinite(t.resolved_at)
    OR t.resolved_at<s.created_at OR t.resolved_at>t.created_at
    OR t.created_at IS DISTINCT FROM e.recorded_at
    OR (s.expires_at IS NOT NULL AND s.expires_at<=v_now)
    OR (t.expires_at IS NOT NULL AND (t.expires_at<=v_now OR t.expires_at<=t.created_at))
    OR t.expires_at IS DISTINCT FROM LEAST(e.requested_expires_at,s.expires_at) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Location resolution timing or expiry is invalid';
  END IF;
END;

DECLARE
  v_receipt private.movement_location_selection_receipts%ROWTYPE;
  v_location private.movement_location_references%ROWTYPE;
BEGIN
  IF p_request_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Selection request identity is required';
  END IF;

  SELECT *
  INTO v_receipt
  FROM private.movement_location_selection_receipts
  WHERE request_id = p_request_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Selected location receipt does not exist';
  END IF;

  SELECT *
  INTO v_location
  FROM private.movement_location_references
  WHERE id = v_receipt.location_reference_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Selected location reference does not exist';
  END IF;

  IF v_location.source_kind IS DISTINCT FROM 'member_selected'
     OR v_location.resolution_status IS DISTINCT FROM 'unresolved'
     OR v_location.latitude IS NOT NULL
     OR v_location.longitude IS NOT NULL
     OR v_location.resolved_at IS NOT NULL
     OR v_location.resolution_version IS NOT NULL
     OR v_location.provider_namespace IS NULL
     OR v_location.provider_place_reference IS NULL
     OR btrim(v_location.provider_namespace) = ''
     OR btrim(v_location.provider_place_reference) = ''
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Selected location receipt target is invalid';
  END IF;

  IF v_receipt.recorded_at IS DISTINCT FROM v_location.created_at THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Selected location receipt timing is inconsistent';
  END IF;
END;

DECLARE
  b private.movement_offer_availability_bindings%ROWTYPE;
  rb private.movement_offer_route_match_bindings%ROWTYPE;
  a private.offering_movement_availability%ROWTYPE;
  e private.trusted_route_match_evidence%ROWTYPE;
  o public.movement_offers%ROWTYPE;
  n public.movement_needs%ROWTYPE;
BEGIN
  SELECT x.* INTO STRICT b FROM private.movement_offer_availability_bindings x WHERE x.movement_offer_id=p_offer_id;
  SELECT x.* INTO STRICT n FROM public.movement_needs x WHERE x.id=b.movement_need_id FOR UPDATE;
  SELECT x.* INTO STRICT o FROM public.movement_offers x WHERE x.id=p_offer_id FOR UPDATE;
  PERFORM private.lock_offer_availability_intent(n.id,b.offering_movement_intent_id);
  PERFORM private.assert_movement_offer_route_match_binding(o.id);
  SELECT x.* INTO STRICT rb FROM private.movement_offer_route_match_bindings x WHERE x.movement_offer_id=o.id;
  SELECT x.* INTO STRICT e FROM private.trusted_route_match_evidence x WHERE x.id=rb.route_match_evidence_id;
  SELECT x.* INTO STRICT a FROM private.offering_movement_availability x WHERE x.id=b.availability_id;
  IF o.movement_need_id IS DISTINCT FROM n.id
    OR o.offering_member_id IS DISTINCT FROM b.offering_member_id
    OR rb.offering_movement_intent_id IS DISTINCT FROM b.offering_movement_intent_id
    OR a.offering_movement_intent_id IS DISTINCT FROM b.offering_movement_intent_id
    OR a.offering_member_id IS DISTINCT FROM b.offering_member_id
    OR a.vehicle_id IS DISTINCT FROM o.vehicle_id
    OR a.route_evidence_id IS DISTINCT FROM e.route_evidence_id
    OR a.route_evidence_version IS DISTINCT FROM e.route_evidence_version THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Movement offer availability binding does not match';
  END IF;
  -- 0044 locks exact route -> availability FOR UPDATE -> vehicle/access,
  -- revalidating live route, intent, lifecycle, expiry and access eligibility.
  PERFORM private.assert_offering_movement_availability(a.id);
  SELECT x.* INTO STRICT a FROM private.offering_movement_availability x WHERE x.id=b.availability_id;
  IF o.status<>'pending' OR n.status<>'discoverable'
    OR o.seats_offered<n.people_count OR o.seats_offered>a.total_places
    OR a.remaining_places<n.people_count THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Insufficient eligible availability for the complete requester group';
  END IF;
END;

DECLARE
  a private.offering_movement_availability%ROWTYPE;
  i private.offering_movement_intents%ROWTYPE;
  e private.offering_route_evidence%ROWTYPE;
  v_capacity integer;
BEGIN
  IF current_setting('transaction_isolation')<>'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000', MESSAGE='Availability validation requires READ COMMITTED';
  END IF;
  SELECT x.* INTO STRICT a FROM private.offering_movement_availability x WHERE x.id=p_availability_id;
  SELECT x.* INTO STRICT i FROM private.offering_movement_intents x
    WHERE x.id=a.offering_movement_intent_id FOR UPDATE;
  PERFORM private.assert_offering_movement_intent(i.id);
  SELECT x.* INTO STRICT e FROM private.offering_route_evidence x WHERE x.id=a.route_evidence_id FOR UPDATE;
  PERFORM private.assert_offering_route_evidence(e.id);
  SELECT x.* INTO STRICT a FROM private.offering_movement_availability x WHERE x.id=p_availability_id FOR UPDATE;
  IF a.offering_member_id IS DISTINCT FROM i.offering_member_id
    OR e.offering_movement_intent_id IS DISTINCT FROM i.id
    OR e.offering_member_id IS DISTINCT FROM a.offering_member_id
    OR e.version IS DISTINCT FROM a.route_evidence_version THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Availability trusted movement binding does not match';
  END IF;
  SELECT v.seat_capacity INTO STRICT v_capacity FROM public.vehicles v WHERE v.id=a.vehicle_id FOR SHARE;
  PERFORM 1 FROM public.member_vehicle_access mva
    WHERE mva.vehicle_id=a.vehicle_id AND mva.member_id=a.offering_member_id AND mva.active FOR SHARE;
  IF NOT FOUND OR a.total_places>v_capacity THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Availability requires active vehicle access and sufficient capacity';
  END IF;
  -- Stop discovery at earliest declared departure; there is no independent
  -- departure event in this foundation and no inference from GPS.
  IF a.status<>'open' OR a.remaining_places<1 OR a.expires_at<=clock_timestamp()
    OR i.earliest_departure_at<=clock_timestamp()
    OR a.expires_at>LEAST(i.earliest_departure_at,i.expires_at,e.expires_at) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Availability is not open and eligible';
  END IF;
END;

DECLARE intent_row private.offering_movement_intents%ROWTYPE;
BEGIN
  SELECT i.* INTO STRICT intent_row FROM private.offering_movement_intents i WHERE i.id=p_intent_id FOR SHARE;
  IF intent_row.status<>'current' OR (intent_row.expires_at IS NOT NULL AND intent_row.expires_at<=clock_timestamp()) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Offering intent is not current and unexpired';
  END IF;
  -- Role CHECK + primary key + count prove one of each role, not two origins.
  IF (SELECT count(*) FROM private.offering_movement_intent_locations il WHERE il.intent_id=p_intent_id)<>2 THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Offering intent requires exactly origin and destination';
  END IF;
  IF EXISTS (SELECT 1 FROM private.offering_movement_intent_locations il
    JOIN private.movement_location_references lr ON lr.id=il.location_reference_id
    WHERE il.intent_id=p_intent_id AND (lr.owner_member_id<>intent_row.offering_member_id
      OR (lr.expires_at IS NOT NULL AND lr.expires_at<=clock_timestamp()))) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Offering intent location owner or expiry does not match';
  END IF;
END;

DECLARE
  evidence_row private.offering_route_evidence%ROWTYPE;
  intent_row private.offering_movement_intents%ROWTYPE;
  origin_row private.movement_location_references%ROWTYPE;
  destination_row private.movement_location_references%ROWTYPE;
BEGIN
  SELECT e.* INTO STRICT evidence_row
  FROM private.offering_route_evidence e
  WHERE e.id = p_evidence_id
  FOR UPDATE;

  IF evidence_row.status <> 'current'
    OR (evidence_row.expires_at IS NOT NULL AND evidence_row.expires_at <= clock_timestamp()) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Offering route evidence is not current and unexpired';
  END IF;

  SELECT i.* INTO STRICT intent_row
  FROM private.offering_movement_intents i
  WHERE i.id = evidence_row.offering_movement_intent_id
  FOR SHARE;

  IF intent_row.offering_member_id <> evidence_row.offering_member_id
    OR intent_row.status <> 'current'
    OR (intent_row.expires_at IS NOT NULL AND intent_row.expires_at <= clock_timestamp()) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Offering route evidence intent is not eligible';
  END IF;

  IF NOT EXISTS (
      SELECT 1 FROM private.offering_movement_intent_locations il
      WHERE il.intent_id=intent_row.id AND il.role='origin'
        AND il.location_reference_id=evidence_row.origin_location_reference_id
    ) OR NOT EXISTS (
      SELECT 1 FROM private.offering_movement_intent_locations il
      WHERE il.intent_id=intent_row.id AND il.role='destination'
        AND il.location_reference_id=evidence_row.destination_location_reference_id
    ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Offering route evidence endpoints do not match intent';
  END IF;

  SELECT lr.* INTO STRICT origin_row
  FROM private.movement_location_references lr
  WHERE lr.id=evidence_row.origin_location_reference_id;
  SELECT lr.* INTO STRICT destination_row
  FROM private.movement_location_references lr
  WHERE lr.id=evidence_row.destination_location_reference_id;

  IF origin_row.owner_member_id <> evidence_row.offering_member_id
    OR destination_row.owner_member_id <> evidence_row.offering_member_id
    OR origin_row.resolution_status <> 'resolved'
    OR destination_row.resolution_status <> 'resolved'
    OR origin_row.source_kind <> 'provider_resolved'
    OR destination_row.source_kind <> 'provider_resolved'
    OR (origin_row.expires_at IS NOT NULL AND origin_row.expires_at <= clock_timestamp())
    OR (destination_row.expires_at IS NOT NULL AND destination_row.expires_at <= clock_timestamp()) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Offering route evidence requires resolved eligible endpoints';
  END IF;

  PERFORM private.assert_geojson_linestring_v1(evidence_row.route_shape);
END;

DECLARE m private.trusted_route_match_evidence%ROWTYPE; deadline timestamptz;
BEGIN
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000',MESSAGE='Pricing geography evidence requires READ COMMITTED';
  END IF;
  PERFORM 1 FROM public.movement_needs n WHERE n.id=p.movement_need_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Pricing geography movement need unavailable';
  END IF;
  -- Check the immutable need binding before entering the canonical context, so
  -- malformed input cannot make it acquire a second, differently ordered need.
  SELECT e.* INTO STRICT m FROM private.trusted_route_match_evidence e WHERE e.id=p.route_match_evidence_id;
  IF m.movement_need_id IS DISTINCT FROM p.movement_need_id THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Pricing geography context mismatch';
  END IF;
  PERFORM private.assert_trusted_route_match_evidence(m.id);
  SELECT e.* INTO STRICT m FROM private.trusted_route_match_evidence e WHERE e.id=p.route_match_evidence_id FOR SHARE;
  IF ROW(p.route_match_evidence_version,p.requesting_member_id,p.offering_member_id,
      p.offering_movement_intent_id,p.offering_intent_version,p.route_evidence_id,p.route_evidence_version,p.state_location_reference_id)
    IS DISTINCT FROM ROW(m.version,m.requesting_member_id,m.offering_member_id,
      m.offering_movement_intent_id,m.offering_intent_version,m.route_evidence_id,m.route_evidence_version,m.requester_origin_location_reference_id)
    OR m.status<>'current' OR (m.expires_at IS NOT NULL AND m.expires_at<=clock_timestamp()) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Pricing geography context mismatch or stale match';
  END IF;
  SELECT coalesce(n.latest_departure_at,n.earliest_departure_at) INTO STRICT deadline
    FROM public.movement_needs n WHERE n.id=p.movement_need_id;
  IF p.status IS DISTINCT FROM 'current' OR p.expires_at IS NULL
    OR NOT isfinite(p.expires_at) OR p.expires_at<=clock_timestamp()
    OR p.expires_at>deadline OR (m.expires_at IS NOT NULL AND p.expires_at>m.expires_at)
    OR p.generated_at IS NULL OR NOT isfinite(p.generated_at)
    OR p.generated_at IS DISTINCT FROM p.created_at THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Pricing geography evidence time or lifecycle invalid';
  END IF;
END;

DECLARE event jsonb; event_position numeric; previous_position numeric:=-1; seen jsonb:='[]'::jsonb;
BEGIN
  IF jsonb_typeof(p_events) IS DISTINCT FROM 'array' OR p_distance IS NULL OR p_distance<=0 THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Invalid pricing geography event sequence';
  END IF;
  FOR event IN SELECT value FROM jsonb_array_elements(p_events) LOOP
    IF jsonb_typeof(event) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Invalid pricing geography event';
    END IF;
    IF jsonb_typeof(event->'event_type') IS DISTINCT FROM 'string'
      OR jsonb_typeof(event->'position_meters') IS DISTINCT FROM 'number'
      OR (event-'event_type'-'position_meters')<>'{}'::jsonb
      OR event->>'event_type' NOT IN ('core_stage_entry','major_transport_transition') THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Invalid pricing geography event fields';
    END IF;
    event_position:=(event->>'position_meters')::numeric;
    IF event_position<>trunc(event_position) OR event_position<0 OR event_position>p_distance
      OR event_position<previous_position OR seen @> jsonb_build_array(event) THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Invalid pricing geography event order or position';
    END IF;
    previous_position:=event_position;
    seen:=seen||jsonb_build_array(event);
  END LOOP;
END;

DECLARE e private.pricing_geography_evidence%ROWTYPE;
BEGIN
  SELECT x.* INTO STRICT e FROM private.pricing_geography_evidence x WHERE x.id=p_evidence_id;
  PERFORM private.assert_pricing_geography_context(e);
  -- Lock and re-read only after dependencies; a concurrent lifecycle transition
  -- cannot be mistaken for a current evidence row.
  SELECT x.* INTO STRICT e FROM private.pricing_geography_evidence x WHERE x.id=p_evidence_id FOR SHARE;
  IF e.status<>'current' OR e.expires_at<=clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Pricing geography evidence is not current and unexpired';
  END IF;
  -- Recheck deadlines after any evidence-row wait, using already held context locks.
  PERFORM private.assert_pricing_geography_context(e);
  PERFORM private.assert_pricing_geography_events(e.geographic_events,e.pricing_corridor_distance_meters);
END;

DECLARE q private.pricing_quotes%ROWTYPE;
BEGIN
  SELECT x.* INTO STRICT q FROM private.pricing_quotes x WHERE x.id=p_quote_id;
  PERFORM private.assert_pricing_quote_context(q);
  SELECT x.* INTO STRICT q FROM private.pricing_quotes x WHERE x.id=p_quote_id FOR SHARE;
  -- Re-read lifecycle and recheck time/source after any quote-row lock wait.
  PERFORM private.assert_pricing_quote_context(q);
END;

DECLARE e private.pricing_geography_evidence%ROWTYPE;
BEGIN
  SELECT x.* INTO e FROM private.pricing_geography_evidence x WHERE x.id=p.pricing_geography_evidence_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact pricing geography evidence unavailable';
  END IF;
  IF ROW(p.pricing_geography_evidence_version,p.movement_need_id,p.requesting_member_id,
      p.offering_member_id,p.offering_movement_intent_id,p.offering_intent_version,p.state_location_reference_id)
    IS DISTINCT FROM ROW(e.version,e.movement_need_id,e.requesting_member_id,
      e.offering_member_id,e.offering_movement_intent_id,e.offering_intent_version,e.state_location_reference_id) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Quote does not match exact pricing geography bindings';
  END IF;
  -- Owns READ COMMITTED and need -> endpoints -> intent -> route -> match ->
  -- geography locks and fresh eligibility. Do not take a quote lock first.
  PERFORM private.assert_pricing_geography_evidence(e.id);
  SELECT x.* INTO STRICT e FROM private.pricing_geography_evidence x WHERE x.id=p.pricing_geography_evidence_id FOR SHARE;
  IF e.pricing_range_supported IS DISTINCT FROM true
    OR e.pricing_corridor_distance_meters<=0 OR e.pricing_corridor_distance_meters>100000 THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Quote requires supported pricing geography evidence';
  END IF;
  IF p.status IS DISTINCT FROM 'current' OR p.created_at IS NULL OR NOT isfinite(p.created_at)
    OR p.expires_at IS NULL OR NOT isfinite(p.expires_at)
    OR p.expires_at<=p.created_at OR p.expires_at<=clock_timestamp() OR p.expires_at>e.expires_at THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Quote lifecycle or evidence-bounded timestamps invalid';
  END IF;
END;

DECLARE
  a private.offering_movement_availability%ROWTYPE;
  e private.trusted_route_match_evidence%ROWTYPE;
BEGIN
  PERFORM 1 FROM public.get_requester_availability_matching_context_for_server(
    p_requesting_member_id,p_movement_need_id,p_availability_id);
  SELECT x.* INTO STRICT a FROM private.offering_movement_availability x WHERE x.id=p_availability_id;
  SELECT x.* INTO STRICT e FROM private.trusted_route_match_evidence x WHERE x.id=p_evidence_id FOR SHARE;
  IF e.movement_need_id IS DISTINCT FROM p_movement_need_id
    OR e.requesting_member_id IS DISTINCT FROM p_requesting_member_id
    OR e.offering_member_id IS DISTINCT FROM a.offering_member_id
    OR e.offering_movement_intent_id IS DISTINCT FROM a.offering_movement_intent_id
    OR e.route_evidence_id IS DISTINCT FROM a.route_evidence_id
    OR e.route_evidence_version IS DISTINCT FROM a.route_evidence_version
    OR p_requesting_member_id=a.offering_member_id THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Interest evidence does not match requester and availability';
  END IF;
  PERFORM private.assert_trusted_route_match_evidence(e.id);
END;

DECLARE
  i private.requester_movement_interests%ROWTYPE;
  a private.offering_movement_availability%ROWTYPE;
  e private.trusted_route_match_evidence%ROWTYPE;
BEGIN
  SELECT x.* INTO STRICT i FROM private.requester_movement_interests x WHERE x.id=p_interest_id;
  PERFORM private.assert_requester_interest_support(
    i.requesting_member_id,i.movement_need_id,i.availability_id,i.route_match_evidence_id);
  -- Interest is locked last; withdrawal locks only interest and never support.
  SELECT x.* INTO STRICT i FROM private.requester_movement_interests x WHERE x.id=p_interest_id FOR SHARE;
  SELECT x.* INTO STRICT a FROM private.offering_movement_availability x WHERE x.id=i.availability_id;
  SELECT x.* INTO STRICT e FROM private.trusted_route_match_evidence x WHERE x.id=i.route_match_evidence_id;
  IF i.status<>'active' OR i.expires_at<=clock_timestamp()
    OR i.offering_member_id IS DISTINCT FROM a.offering_member_id
    OR i.offering_movement_intent_id IS DISTINCT FROM a.offering_movement_intent_id
    OR i.route_match_evidence_version IS DISTINCT FROM e.version
    OR i.expires_at>LEAST(a.expires_at,e.expires_at) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Interest is not active with current exact support';
  END IF;
END;

DECLARE
  v_xmin numeric;
  v_ymin numeric;
  v_xmax numeric;
  v_ymax numeric;
BEGIN
  IF p_bbox IS NULL
     OR jsonb_typeof(p_bbox) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Transport geography coverage bbox must be an object';
  END IF;

  IF (
    SELECT array_agg(k ORDER BY k)
    FROM jsonb_object_keys(p_bbox) AS k
  ) IS DISTINCT FROM ARRAY['xmax','xmin','ymax','ymin']::text[] THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Transport geography coverage bbox has invalid fields';
  END IF;

  IF jsonb_typeof(p_bbox->'xmin') IS DISTINCT FROM 'number'
     OR jsonb_typeof(p_bbox->'ymin') IS DISTINCT FROM 'number'
     OR jsonb_typeof(p_bbox->'xmax') IS DISTINCT FROM 'number'
     OR jsonb_typeof(p_bbox->'ymax') IS DISTINCT FROM 'number' THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Transport geography coverage bbox coordinates must be numeric';
  END IF;

  BEGIN
    v_xmin := (p_bbox->>'xmin')::numeric;
    v_ymin := (p_bbox->>'ymin')::numeric;
    v_xmax := (p_bbox->>'xmax')::numeric;
    v_ymax := (p_bbox->>'ymax')::numeric;
  EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'Transport geography coverage bbox coordinates must be numeric';
  END;

  IF v_xmin IS NULL
     OR v_ymin IS NULL
     OR v_xmax IS NULL
     OR v_ymax IS NULL
     OR v_xmin < -180
     OR v_xmax > 180
     OR v_ymin < -90
     OR v_ymax > 90
     OR v_xmin >= v_xmax
     OR v_ymin >= v_ymax THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Transport geography coverage bbox is invalid';
  END IF;
END;

DECLARE
  v_dataset private.transport_geography_datasets%ROWTYPE;
BEGIN
  IF p_transport_geography_version IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '22004',
      MESSAGE = 'Transport geography version required';
  END IF;

  SELECT d.*
  INTO STRICT v_dataset
  FROM private.transport_geography_datasets d
  WHERE d.transport_geography_version = p_transport_geography_version;

  PERFORM private.assert_transport_geography_bbox(v_dataset.coverage_bbox);

  IF v_dataset.status IS DISTINCT FROM 'approved' THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Transport geography dataset is not approved for new classification';
  END IF;

  -- Lock only after validating the factual record. Re-read status so a
  -- concurrent retirement/supersession cannot be treated as approved.
  SELECT d.*
  INTO STRICT v_dataset
  FROM private.transport_geography_datasets d
  WHERE d.transport_geography_version = p_transport_geography_version
  FOR SHARE;

  PERFORM private.assert_transport_geography_bbox(v_dataset.coverage_bbox);

  IF v_dataset.status IS DISTINCT FROM 'approved' THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Transport geography dataset is not approved for new classification';
  END IF;
EXCEPTION
  WHEN no_data_found THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Exact approved transport geography dataset unavailable';
END;

DECLARE a public.alignments%ROWTYPE; j public.journeys%ROWTYPE; g private.financial_agreements%ROWTYPE;
 e private.funded_movement_coordination_entries%ROWTYPE; r private.funded_no_travel_requests%ROWTYPE;
 d private.funded_no_travel_closures%ROWTYPE; c private.financial_components%ROWTYPE;
 t private.wallet_transactions%ROWTYPE; sr private.funded_movement_start_requests%ROWTYPE;
 mp private.journey_meeting_points%ROWTYPE; available_id uuid; held_id uuid; n bigint; matches bigint;
BEGIN
 SELECT x.* INTO STRICT a FROM public.alignments x WHERE x.id=p_alignment;
 IF EXISTS(SELECT 1 FROM private.funded_no_travel_holds WHERE alignment_id=a.id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='No-travel funds remain held for review'; END IF;
 IF EXISTS(SELECT 1 FROM private.funded_no_travel_closures WHERE alignment_id=a.id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Undisposed pre-start graph required'; END IF;
 SELECT x.* INTO STRICT e FROM private.funded_movement_coordination_entries x WHERE x.alignment_id=a.id;
 SELECT x.* INTO STRICT j FROM public.journeys x WHERE x.id=e.journey_id;
 SELECT x.* INTO STRICT g FROM private.financial_agreements x WHERE x.id=e.financial_agreement_id;
 g:=private.movement_funding_agreement(g.id,g.member_needing_movement_id,g.version);
 PERFORM private.assert_funded_activation(g,a);
 -- Reuse 0083's complete absence/partial-settlement proof, including component
 -- keys whose transaction alignment was forged or belongs to another graph.
 PERFORM private.assert_funded_completion(a.id);
 SELECT x.* INTO d FROM private.funded_no_travel_closures x WHERE x.alignment_id=a.id;
 IF d.alignment_id IS NOT NULL AND private.activation_fee_is_finalized(g.id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Activated contribution remains held for review'; END IF;
 IF j.alignment_id IS DISTINCT FROM a.id OR g.alignment_id IS DISTINCT FROM a.id
  OR (SELECT count(*) FROM public.journeys WHERE alignment_id=a.id)<>1
  OR j.vehicle_id IS DISTINCT FROM (SELECT vehicle_id FROM public.movement_offers WHERE id=a.movement_offer_id)
  OR j.created_at IS DISTINCT FROM e.created_at OR NOT isfinite(e.created_at)
  OR j.started_at IS NOT NULL OR j.completed_at IS NOT NULL OR j.completion_requested_at IS NOT NULL
  OR j.end_requested_by_member_id IS NOT NULL OR j.end_requested_at IS NOT NULL
  OR j.end_confirmed_by_member_id IS NOT NULL OR j.end_confirmed_at IS NOT NULL OR j.end_method IS NOT NULL OR j.end_reason IS NOT NULL
  OR EXISTS(SELECT 1 FROM private.funded_movement_starts WHERE alignment_id=a.id OR journey_id=j.id)
  OR EXISTS(SELECT 1 FROM private.funded_movement_completion_requests WHERE alignment_id=a.id OR journey_id=j.id)
  OR EXISTS(SELECT 1 FROM private.funded_movement_completions WHERE alignment_id=a.id OR journey_id=j.id)
  OR EXISTS(SELECT 1 FROM private.completed_movement_principals WHERE alignment_id=a.id)
  OR EXISTS(SELECT 1 FROM private.completed_movement_ratings WHERE alignment_id=a.id)
  OR EXISTS(SELECT 1 FROM private.movement_settlements WHERE alignment_id=a.id OR journey_id=j.id)
  OR EXISTS(SELECT 1 FROM private.mutual_no_travel_closures WHERE journey_id=j.id)
  OR EXISTS(SELECT 1 FROM private.wallet_transactions WHERE alignment_id=a.id
    AND (transaction_kind IN ('offering_platform_charge','movement_contribution_settlement')
     OR (transaction_kind='requester_platform_charge' AND NOT private.activation_fee_is_finalized(g.id)))) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact unstarted funded lifecycle required'; END IF;
 SELECT x.* INTO sr FROM private.funded_movement_start_requests x WHERE x.alignment_id=a.id;
 IF sr.alignment_id IS NULL THEN
  IF j.start_requested_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact pending start required'; END IF;
 ELSE
  SELECT x.* INTO mp FROM private.journey_meeting_points x WHERE x.journey_id=j.id;
  IF sr.journey_id IS DISTINCT FROM j.id OR sr.requested_at IS DISTINCT FROM j.start_requested_at
   OR NOT isfinite(sr.requested_at)
   OR mp.journey_id IS NULL OR mp.revision IS DISTINCT FROM sr.meeting_point_revision
   OR mp.place_text<>btrim(mp.place_text) OR length(mp.place_text) NOT BETWEEN 1 AND 200 OR mp.place_text !~ '[^[:space:]]' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact frozen pending start required'; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM private.funded_no_travel_requests q WHERE q.alignment_id=a.id AND
  (q.financial_agreement_id IS DISTINCT FROM g.id OR q.journey_id IS DISTINCT FROM j.id
   OR q.first_principal_id NOT IN (a.offering_member_id,a.member_needing_movement_id)
   OR NOT isfinite(q.requested_at)))
  OR EXISTS(SELECT 1 FROM private.funded_no_travel_declines z JOIN private.funded_no_travel_requests q ON q.id=z.request_id
   WHERE q.alignment_id=a.id AND (z.second_principal_id=q.first_principal_id
    OR z.second_principal_id NOT IN(a.offering_member_id,a.member_needing_movement_id)
    OR NOT isfinite(z.declined_at)))
  OR (SELECT count(*) FROM private.funded_no_travel_requests q WHERE q.alignment_id=a.id
   AND NOT EXISTS(SELECT 1 FROM private.funded_no_travel_declines z WHERE z.request_id=q.id))>1 THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact principal intent history required'; END IF;
 IF d.alignment_id IS NULL THEN
  IF a.status<>'activated' OR j.status<>'not_started' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact pre-start lifecycle required'; END IF;
 ELSE
  SELECT x.* INTO STRICT r FROM private.funded_no_travel_requests x WHERE x.id=d.request_id;
  IF d.financial_agreement_id IS DISTINCT FROM g.id OR d.journey_id IS DISTINCT FROM j.id
   OR r.alignment_id IS DISTINCT FROM a.id OR d.first_principal_id IS DISTINCT FROM r.first_principal_id
   OR d.second_principal_id NOT IN(a.offering_member_id,a.member_needing_movement_id)
   OR d.requested_at IS DISTINCT FROM r.requested_at OR NOT isfinite(d.released_at)
   OR d.pending_start_requested_at IS DISTINCT FROM j.start_requested_at
   OR EXISTS(SELECT 1 FROM private.funded_no_travel_declines WHERE request_id=r.id)
   OR a.status<>'cancelled' OR j.status<>'cancelled' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Complete exact funded disposition required'; END IF;
 END IF;
 SELECT id INTO STRICT available_id FROM private.wallet_accounts WHERE member_id=g.member_needing_movement_id AND currency=g.currency AND account_kind='member_available';
 SELECT id INTO STRICT held_id FROM private.wallet_accounts WHERE member_id=g.member_needing_movement_id AND currency=g.currency AND account_kind='member_held';
 FOR c IN SELECT * FROM private.financial_components WHERE agreement_id=g.id ORDER BY id LOOP
  SELECT x.* INTO t FROM private.wallet_transactions x WHERE x.idempotency_key='movement_hold_release:'||c.id::text;
  SELECT count(*) INTO n FROM private.wallet_transactions WHERE financial_component_id=c.id AND transaction_kind='movement_hold_release';
  IF d.alignment_id IS NULL OR c.amount_minor=0 OR c.component_key='offering_platform_share' OR (c.component_key='requester_platform_share' AND private.activation_fee_is_finalized(g.id)) THEN
   IF t.id IS NOT NULL OR n<>0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Partial or zero release forbidden'; END IF;
   CONTINUE;
  END IF;
  IF n<>1 OR t.id IS NULL OR t.transaction_kind IS DISTINCT FROM 'movement_hold_release'
   OR t.financial_component_id IS DISTINCT FROM c.id OR t.alignment_id IS DISTINCT FROM a.id OR t.currency IS DISTINCT FROM g.currency
   OR t.provider IS NOT NULL OR t.provider_reference IS NOT NULL OR t.created_at IS DISTINCT FROM d.released_at THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact release transaction required'; END IF;
  SELECT count(*),count(*) FILTER(WHERE amount_minor=c.amount_minor AND created_at=d.released_at
   AND ((account_id=held_id AND direction='debit') OR (account_id=available_id AND direction='credit')))
   INTO n,matches FROM private.wallet_postings WHERE transaction_id=t.id;
  IF n<>2 OR matches<>2 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact release postings required'; END IF;
  PERFORM private.assert_wallet_transaction_balanced(t.id);
 END LOOP;
 IF EXISTS(SELECT 1 FROM private.wallet_transactions wx WHERE wx.alignment_id=a.id AND wx.transaction_kind='movement_hold_release'
  AND NOT EXISTS(SELECT 1 FROM private.financial_components fc WHERE fc.id=wx.financial_component_id AND fc.agreement_id=g.id)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Competing release history forbidden'; END IF;
END;

DECLARE
  v_debits numeric;
  v_credits numeric;
  v_posting_count bigint;
BEGIN
  IF p_transaction_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='Wallet transaction id required';
  END IF;

  PERFORM 1
  FROM private.wallet_transactions t
  WHERE t.id = p_transaction_id
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Wallet transaction unavailable';
  END IF;

  SELECT
    count(*),
    COALESCE(sum(p.amount_minor) FILTER (WHERE p.direction='debit'), 0),
    COALESCE(sum(p.amount_minor) FILTER (WHERE p.direction='credit'), 0)
  INTO v_posting_count, v_debits, v_credits
  FROM private.wallet_postings p
  WHERE p.transaction_id = p_transaction_id;

  IF v_posting_count < 2 OR v_debits <= 0 OR v_credits <= 0 OR v_debits IS DISTINCT FROM v_credits THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Wallet transaction must contain balanced debit and credit postings';
  END IF;
END;

BEGIN
 INSERT INTO private.funded_completion_response_windows VALUES(NEW.alignment_id,NEW.financial_agreement_id,NEW.journey_id,NEW.requested_at,NEW.requested_at+interval '12 hours');
 RETURN NULL;
END;

DECLARE
  g numeric; f numeric; o numeric; r numeric; c numeric; net numeric;
  amount numeric;
BEGIN
  IF p_seat_price_minor IS NULL OR p_people_count IS NULL
    OR p_financial_model_version IS NULL OR p_platform_fee_allocation_policy_version IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='Complete economic inputs and policy identities required';
  END IF;
  IF p_seat_price_minor<=0 OR p_people_count<=0
    OR p_financial_model_version<>'shared_platform_fee_v1'
    OR p_platform_fee_allocation_policy_version<>'equal_split_requester_remainder_v1' THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Positive occupied-seat inputs and supported economic policies required';
  END IF;

  -- Cast BEFORE multiplication. Displayed price is the complete per-seat amount.
  g:=p_seat_price_minor::numeric * p_people_count::numeric;
  -- Exact nonnegative HALF-UP: floor((3*G+5)/10). div avoids division rounding.
  f:=div(g*3+5,10);
  -- Preserve 0020's floor/remainder split; no independent percentage rounding.
  o:=div(f,2);
  r:=f-o;
  c:=g-r;
  net:=c-o;

  -- Check every output before any narrowing cast; zero components are valid.
  FOREACH amount IN ARRAY ARRAY[g,f,o,r,c,net] LOOP
    IF amount<0 OR amount>9223372036854775807::numeric THEN
      RAISE EXCEPTION USING ERRCODE='22003', MESSAGE='Financial economic output exceeds bigint range';
    END IF;
  END LOOP;
  RETURN QUERY SELECT g::bigint,f::bigint,o::bigint,r::bigint,c::bigint,net::bigint;
END;

BEGIN
 PERFORM private.record_completed_movement_principals(NEW.alignment_id);
 RETURN NULL;
END;

DECLARE j public.journeys%ROWTYPE; a public.alignments%ROWTYPE;
  caller uuid := auth.uid(); closed_time timestamptz;
BEGIN
  IF EXISTS(SELECT 1 FROM public.journeys lifecycle_journey WHERE lifecycle_journey.id=p_journey_id AND private.is_financial_alignment(lifecycle_journey.alignment_id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial coordination lifecycle unavailable'; END IF;
  SELECT * INTO STRICT j FROM public.journeys WHERE id=p_journey_id FOR UPDATE;
  SELECT * INTO STRICT a FROM public.alignments WHERE id=j.alignment_id FOR UPDATE;
  closed_time := clock_timestamp();
  IF caller IS NULL OR caller NOT IN (a.offering_member_id,a.member_needing_movement_id)
    OR j.end_requested_by_member_id IS NULL OR j.end_requested_at IS NULL
    OR j.end_requested_by_member_id NOT IN (a.offering_member_id,a.member_needing_movement_id)
    OR j.end_requested_by_member_id=caller THEN
    RAISE EXCEPTION 'Two principal consents required';
  END IF;
  IF a.status<>'activated' OR j.status<>'not_started' OR j.started_at IS NOT NULL
    OR j.completed_at IS NOT NULL OR a.activated_at IS NULL THEN
    RAISE EXCEPTION 'Movement is not eligible for no-travel closure';
  END IF;
  -- State/timestamps alone are not payment evidence (trusted historical imports
  -- can contain inconsistent rows). Match the existing 0014 activation evidence.
  -- Do not lock payment after alignment: payment success uses payment->alignment.
  IF NOT EXISTS (
    SELECT 1 FROM private.alignment_activation_payments p
    WHERE p.alignment_id=a.id AND p.status='succeeded' AND p.succeeded_at IS NOT NULL
      AND p.payer_member_id=a.offering_member_id
      AND p.amount_minor=a.activation_fee_minor AND p.currency=a.activation_currency
  ) THEN
    RAISE EXCEPTION 'Successful activation payment required';
  END IF;
  -- Never silently delete an inconsistent pre-existing entitlement.
  IF EXISTS (SELECT 1 FROM private.movement_settlements s WHERE s.journey_id=j.id OR s.alignment_id=a.id) THEN
    RAISE EXCEPTION 'Existing settlement requires reviewed resolution';
  END IF;
  UPDATE public.journeys SET status='cancelled',start_requested_at=NULL,
    end_confirmed_by_member_id=caller,end_confirmed_at=closed_time,
    end_method='mutual_no_travel_after_activation',updated_at=now() WHERE id=j.id;
  UPDATE public.alignments SET status='cancelled',updated_at=now() WHERE id=a.id;
  INSERT INTO private.mutual_no_travel_closures
    (journey_id,first_principal_id,second_principal_id,first_consented_at,closed_at,invalidated_start_requested_at)
    VALUES(j.id,j.end_requested_by_member_id,caller,j.end_requested_at,closed_time,j.start_requested_at);
END;

DECLARE a public.alignments%ROWTYPE;
BEGIN
 a:=private.funded_coordination_alignment(p_need,true);
 PERFORM j.id FROM public.journeys j WHERE j.alignment_id=a.id FOR UPDATE;
 PERFORM private.assert_funded_coordination_entry(a.id);
 IF a.status<>'completed' OR NOT EXISTS(SELECT 1 FROM private.funded_movement_completions r WHERE r.alignment_id=a.id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact funded completion required'; END IF;
 PERFORM m.id FROM public.members m WHERE m.id IN(a.offering_member_id,a.member_needing_movement_id) ORDER BY m.id FOR UPDATE;
 IF (SELECT count(*) FROM private.completed_movement_principals p WHERE p.alignment_id=a.id)<>2
  OR NOT EXISTS(SELECT 1 FROM private.completed_movement_principals p JOIN private.funded_movement_completions r USING(alignment_id)
   WHERE p.alignment_id=a.id AND p.member_id=a.offering_member_id AND p.person_role='offering_member' AND p.completed_at=r.completed_at)
  OR NOT EXISTS(SELECT 1 FROM private.completed_movement_principals p JOIN private.funded_movement_completions r USING(alignment_id)
   WHERE p.alignment_id=a.id AND p.member_id=a.member_needing_movement_id AND p.person_role='primary_requester' AND p.completed_at=r.completed_at) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact completed principals required'; END IF;
 RETURN a;
END;

DECLARE
  v_now timestamptz; v_minute timestamptz; v_day timestamptz;
  v_minute_count integer; v_day_count integer;
  v_minute_limit integer; v_day_limit integer; v_retry integer := 0;
BEGIN
  -- Fresh statement snapshots after the lock wait are required by this design.
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000',MESSAGE='Quota requires READ COMMITTED';
  END IF;
  IF p_operation IS NULL OR p_operation NOT IN ('location_search','location_resolution') THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Invalid quota operation';
  END IF;
  -- One existing row serializes all quota admissions for this member, including
  -- missing buckets. No member data is changed. Different members do not block
  -- each other. Both operations briefly serialize, but have independent counts.
  PERFORM 1 FROM public.members m WHERE m.id=p_verified_member_id FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Quota member unavailable';
  END IF;
  v_now := coalesce(p_server_time,clock_timestamp());
  IF NOT isfinite(v_now) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Invalid quota time';
  END IF;
  v_minute := date_trunc('minute',v_now AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
  v_day := date_trunc('day',v_now AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
  IF p_operation='location_search' THEN
    v_minute_limit := 30; v_day_limit := 300;
  ELSE
    v_minute_limit := 10; v_day_limit := 100;
  END IF;
  SELECT b.request_count INTO v_minute_count FROM private.location_provider_quota_buckets b
  WHERE b.member_id=p_verified_member_id AND b.operation=p_operation
    AND b.window_kind='minute' AND b.window_start=v_minute;
  SELECT b.request_count INTO v_day_count FROM private.location_provider_quota_buckets b
  WHERE b.member_id=p_verified_member_id AND b.operation=p_operation
    AND b.window_kind='day' AND b.window_start=v_day;
  IF coalesce(v_minute_count,0)>=v_minute_limit THEN
    v_retry := greatest(1,ceil(extract(epoch FROM (v_minute+interval '1 minute'-v_now)))::integer);
  END IF;
  IF coalesce(v_day_count,0)>=v_day_limit THEN
    -- UTC timestamp arithmetic avoids session timezone / DST day lengths.
    -- If both block, waiting for the later reset avoids another certain denial.
    v_retry := greatest(v_retry,ceil(extract(epoch FROM
      (((v_day AT TIME ZONE 'UTC')+interval '1 day') AT TIME ZONE 'UTC')-v_now))::integer);
  END IF;
  IF v_retry>0 THEN
    RETURN QUERY SELECT false,least(86400,greatest(1,v_retry));
    RETURN;
  END IF;
  -- One statement updates both windows; any error rolls back both. Only the
  -- exact primary-key conflict is handled; unrelated uniqueness errors escape.
  INSERT INTO private.location_provider_quota_buckets AS b
    (member_id,operation,window_kind,window_start,request_count,updated_at)
  VALUES (p_verified_member_id,p_operation,'minute',v_minute,1,v_now),
         (p_verified_member_id,p_operation,'day',v_day,1,v_now)
  ON CONFLICT (member_id,operation,window_kind,window_start)
  DO UPDATE SET request_count=b.request_count+1,updated_at=EXCLUDED.updated_at;
  RETURN QUERY SELECT true,0;
END;

DECLARE
  v_now timestamptz;
  v_minute timestamptz;
  v_day timestamptz;

  v_minute_count integer;
  v_day_count integer;

  v_minute_limit integer := 10;
  v_day_limit integer := 100;

  v_retry integer := 0;
BEGIN
  IF current_setting(
    'transaction_isolation'
  ) <> 'read committed' THEN
    RAISE EXCEPTION USING
      ERRCODE = '25000',
      MESSAGE =
        'Route quota requires READ COMMITTED';
  END IF;

  IF p_verified_member_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE =
        'Route quota member is required';
  END IF;

  -- One existing member row serializes first-bucket creation
  -- for this member without mutating member data.
  PERFORM 1
  FROM public.members m
  WHERE m.id = p_verified_member_id
  FOR NO KEY UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE =
        'Route quota member unavailable';
  END IF;

  v_now :=
    coalesce(
      p_server_time,
      clock_timestamp()
    );

  IF NOT isfinite(v_now) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE =
        'Invalid route quota time';
  END IF;

  v_minute :=
    date_trunc(
      'minute',
      v_now AT TIME ZONE 'UTC'
    ) AT TIME ZONE 'UTC';

  v_day :=
    date_trunc(
      'day',
      v_now AT TIME ZONE 'UTC'
    ) AT TIME ZONE 'UTC';

  SELECT b.request_count
  INTO v_minute_count
  FROM private.route_provider_quota_buckets b
  WHERE b.member_id = p_verified_member_id
    AND b.window_kind = 'minute'
    AND b.window_start = v_minute;

  SELECT b.request_count
  INTO v_day_count
  FROM private.route_provider_quota_buckets b
  WHERE b.member_id = p_verified_member_id
    AND b.window_kind = 'day'
    AND b.window_start = v_day;

  IF coalesce(
    v_minute_count,
    0
  ) >= v_minute_limit THEN
    v_retry :=
      greatest(
        1,
        ceil(
          extract(
            epoch FROM (
              v_minute
              + interval '1 minute'
              - v_now
            )
          )
        )::integer
      );
  END IF;

  IF coalesce(
    v_day_count,
    0
  ) >= v_day_limit THEN
    v_retry :=
      greatest(
        v_retry,
        ceil(
          extract(
            epoch FROM (
              (
                (
                  v_day
                  AT TIME ZONE 'UTC'
                )
                + interval '1 day'
              )
              AT TIME ZONE 'UTC'
            ) - v_now
          )
        )::integer
      );
  END IF;

  IF v_retry > 0 THEN
    RETURN QUERY
    SELECT
      false,
      least(
        86400,
        greatest(
          1,
          v_retry
        )
      );

    RETURN;
  END IF;

  -- Both quota windows are changed by one statement.
  -- Any later error rolls both changes back.
  INSERT INTO
    private.route_provider_quota_buckets AS b
    (
      member_id,
      window_kind,
      window_start,
      request_count,
      updated_at
    )
  VALUES
    (
      p_verified_member_id,
      'minute',
      v_minute,
      1,
      v_now
    ),
    (
      p_verified_member_id,
      'day',
      v_day,
      1,
      v_now
    )
  ON CONFLICT (
    member_id,
    window_kind,
    window_start
  )
  DO UPDATE SET
    request_count =
      b.request_count + 1,
    updated_at =
      EXCLUDED.updated_at;

  RETURN QUERY
  SELECT true, 0;
END;

DECLARE
  v_member_id uuid;

  v_need_record
    public.movement_needs%ROWTYPE;

  v_vehicle_record
    public.vehicles%ROWTYPE;

  v_evidence
    private.trusted_route_match_evidence%ROWTYPE;

  v_availability private.offering_movement_availability%ROWTYPE;

  v_pickup_area text;
  v_dropoff_area text;

  v_offer_id uuid;
  v_offer_status text;
  v_created_at timestamptz;
BEGIN
  IF current_setting('transaction_isolation')
       <> 'read committed' THEN
    RAISE EXCEPTION USING
      ERRCODE = '25000',
      MESSAGE =
        'Movement offer creation requires READ COMMITTED';
  END IF;


  v_member_id := auth.uid();

  IF v_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;


  IF NOT EXISTS(SELECT 1 FROM public.members m WHERE m.id=v_member_id) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Authenticated member required';
  END IF;

  IF p_movement_need_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '22004',
      MESSAGE = 'Movement need is required';
  END IF;


  IF p_route_match_evidence_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '22004',
      MESSAGE =
        'Trusted route-match evidence is required';
  END IF;


  IF p_availability_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '22004',
      MESSAGE = 'Availability is required';
  END IF;


  -- =======================================================
  -- Movement need is the serialization boundary.
  --
  -- This preserves the lock order already used by trusted
  -- route-match evidence creation.
  -- =======================================================

  SELECT mn.*
  INTO v_need_record
  FROM public.movement_needs mn
  WHERE mn.id = p_movement_need_id
  FOR UPDATE;


  IF NOT FOUND THEN
    RAISE EXCEPTION 'Movement need not found';
  END IF;


  IF v_need_record.status <> 'discoverable' THEN
    RAISE EXCEPTION 'Movement need is not discoverable';
  END IF;


  IF v_need_record.member_id = v_member_id THEN
    RAISE EXCEPTION
      'You cannot offer on your own movement need';
  END IF;


  IF EXISTS (
    SELECT 1
    FROM public.alignments a
    WHERE a.movement_need_id = v_need_record.id
      AND a.status IN (
        'awaiting_activation_payment',
        'activated',
        'in_progress',
        'completed'
      )
  ) THEN
    RAISE EXCEPTION
      'This movement need already has an active or completed alignment';
  END IF;


  -- =======================================================
  -- Exact trusted route-match evidence
  -- =======================================================

  SELECT e.*
  INTO v_evidence
  FROM private.trusted_route_match_evidence e
  WHERE e.id = p_route_match_evidence_id;


  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE =
        'Trusted route-match evidence is unavailable';
  END IF;


  IF v_evidence.movement_need_id
       IS DISTINCT FROM v_need_record.id THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE =
        'Trusted route-match evidence does not belong to this movement need';
  END IF;


  IF v_evidence.offering_member_id
       IS DISTINCT FROM v_member_id THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE =
        'Trusted route-match evidence does not belong to the authenticated member';
  END IF;


  SELECT a.* INTO v_availability
  FROM private.offering_movement_availability a WHERE a.id=p_availability_id;
  IF NOT FOUND OR v_availability.offering_member_id IS DISTINCT FROM v_member_id THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Own offering availability required';
  END IF;
  IF v_availability.offering_movement_intent_id IS DISTINCT FROM v_evidence.offering_movement_intent_id
    OR v_availability.route_evidence_id IS DISTINCT FROM v_evidence.route_evidence_id
    OR v_availability.route_evidence_version IS DISTINCT FROM v_evidence.route_evidence_version THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Availability does not match the exact trusted route-match context';
  END IF;
  PERFORM private.lock_offer_availability_intent(v_need_record.id,v_evidence.offering_movement_intent_id);

  -- This re-runs the authoritative trusted matching context.
  -- It proves that the exact evidence is still current,
  -- unexpired and bound to the still-current offering intent
  -- and trusted route.
  PERFORM
    private.assert_trusted_route_match_evidence(
      v_evidence.id
    );


  -- Re-read after validation while the movement-need lock still
  -- prevents a competing route-match writer from superseding
  -- the evidence.
  SELECT e.*
  INTO STRICT v_evidence
  FROM private.trusted_route_match_evidence e
  WHERE e.id = p_route_match_evidence_id;


  IF v_evidence.status <> 'current'
     OR (
       v_evidence.expires_at IS NOT NULL
       AND v_evidence.expires_at <= clock_timestamp()
     ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE =
        'Trusted route-match evidence is not current and unexpired';
  END IF;


  -- =======================================================
  -- Existing vehicle/access/capacity behavior
  -- =======================================================

  PERFORM private.assert_offering_movement_availability(v_availability.id);
  SELECT a.* INTO STRICT v_availability FROM private.offering_movement_availability a WHERE a.id=p_availability_id;
  IF v_need_record.people_count>v_availability.remaining_places OR p_seats_offered>v_availability.total_places THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Insufficient eligible availability for the complete requester group';
  END IF;

  SELECT *
  INTO v_vehicle_record
  FROM public.vehicles AS v
  WHERE v.id = v_availability.vehicle_id;


  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vehicle not found';
  END IF;


  IF NOT EXISTS (
    SELECT 1
    FROM public.member_vehicle_access AS mva
    WHERE mva.member_id = v_member_id
      AND mva.vehicle_id = v_availability.vehicle_id
      AND mva.active = TRUE
  ) THEN
    RAISE EXCEPTION
      'Vehicle access not found for the authenticated user';
  END IF;


  IF p_seats_offered IS NULL THEN
    RAISE EXCEPTION 'Seats offered is required';
  END IF;


  IF p_seats_offered < 1 THEN
    RAISE EXCEPTION
      'Seats offered must be at least 1';
  END IF;


  IF p_seats_offered > v_vehicle_record.seat_capacity THEN
    RAISE EXCEPTION
      'Seats offered cannot exceed the vehicle seat capacity';
  END IF;


  IF p_seats_offered < v_need_record.people_count THEN
    RAISE EXCEPTION
      'Seats offered are fewer than the travellers declared for this movement';
  END IF;


  IF p_estimated_arrival_minutes IS NOT NULL
     AND p_estimated_arrival_minutes < 0 THEN
    RAISE EXCEPTION
      'Estimated arrival minutes cannot be negative';
  END IF;


  v_pickup_area := p_proposed_pickup_area;

  IF v_pickup_area IS NOT NULL THEN
    v_pickup_area := trim(v_pickup_area);

    IF v_pickup_area = '' THEN
      v_pickup_area := NULL;
    END IF;

    IF length(v_pickup_area) > 200 THEN
      RAISE EXCEPTION
        'Proposed pickup area must be 200 characters or fewer';
    END IF;
  END IF;


  v_dropoff_area := p_proposed_dropoff_area;

  IF v_dropoff_area IS NOT NULL THEN
    v_dropoff_area := trim(v_dropoff_area);

    IF v_dropoff_area = '' THEN
      v_dropoff_area := NULL;
    END IF;

    IF length(v_dropoff_area) > 200 THEN
      RAISE EXCEPTION
        'Proposed dropoff area must be 200 characters or fewer';
    END IF;
  END IF;


  -- =======================================================
  -- Offer and private authorization are one transaction
  -- =======================================================

  INSERT INTO public.movement_offers (
    movement_need_id,
    offering_member_id,
    vehicle_id,
    seats_offered,
    proposed_pickup_area,
    proposed_dropoff_area,
    estimated_arrival_minutes,
    status,
    created_at,
    updated_at
  )
  VALUES (
    v_need_record.id,
    v_member_id,
    v_availability.vehicle_id,
    p_seats_offered,
    v_pickup_area,
    v_dropoff_area,
    p_estimated_arrival_minutes,
    'pending',
    NOW(),
    NOW()
  )
  RETURNING
    public.movement_offers.id,
    public.movement_offers.status,
    public.movement_offers.created_at
  INTO
    v_offer_id,
    v_offer_status,
    v_created_at;


  INSERT INTO private.movement_offer_route_match_bindings (
    movement_offer_id,
    movement_need_id,
    offering_member_id,
    offering_movement_intent_id,
    route_match_evidence_id,
    route_match_evidence_version,
    binding_schema_version,
    bound_at
  )
  VALUES (
    v_offer_id,
    v_need_record.id,
    v_member_id,
    v_evidence.offering_movement_intent_id,
    v_evidence.id,
    v_evidence.version,
    'movement_offer_route_match_binding_v1',
    clock_timestamp()
  );


  PERFORM
    private.assert_movement_offer_route_match_binding(
      v_offer_id
    );


  SET CONSTRAINTS
    private.movement_offer_route_match_binding_complete
    IMMEDIATE;

  SET CONSTRAINTS
    private.movement_offer_route_match_binding_complete
    DEFERRED;


  INSERT INTO private.movement_offer_availability_bindings(
    movement_offer_id,movement_need_id,availability_id,offering_member_id,offering_movement_intent_id
  ) VALUES(v_offer_id,v_need_record.id,v_availability.id,v_member_id,v_evidence.offering_movement_intent_id);
  -- The immediate binding trigger revalidates 0042 and 0044 together.
  -- Pending offers never change remaining_places.

  RETURN QUERY
  SELECT
    v_offer_id,
    v_offer_status,
    v_created_at;
END;

DECLARE
  v_now timestamptz := statement_timestamp();
  v_deadline timestamptz := statement_timestamp() + interval '24 hours';
BEGIN
  IF NEW.earliest_departure_at IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Earliest departure is required';
  END IF;

  IF NOT isfinite(NEW.earliest_departure_at)
     OR (NEW.latest_departure_at IS NOT NULL AND NOT isfinite(NEW.latest_departure_at)) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Departure times must be finite';
  END IF;

  IF NEW.earliest_departure_at < v_now THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Earliest departure cannot be in the past';
  END IF;

  IF NEW.earliest_departure_at > v_deadline THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Earliest departure must be within the next 24 hours';
  END IF;

  IF NEW.latest_departure_at IS NOT NULL THEN
    IF NEW.latest_departure_at < NEW.earliest_departure_at THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Latest departure cannot be before earliest departure';
    END IF;

    IF NEW.latest_departure_at > v_deadline THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Latest departure must be within the next 24 hours';
    END IF;
  END IF;

  RETURN NEW;
END;

DECLARE a public.alignments%ROWTYPE; j public.journeys%ROWTYPE; g private.financial_agreements%ROWTYPE;
 account record; owner uuid; stamp timestamptz;
 held_id uuid; withdrawable_id uuid; revenue_id uuid;
 r numeric; contribution numeric; o numeric; held numeric; withdrawable numeric:=0; revenue numeric:=0;
 balance numeric; maximum constant numeric:=9223372036854775807;
BEGIN
 a:=private.funded_coordination_alignment(p_movement_need_id);
 IF p_method NOT IN ('requester_confirmed','response_timeout') OR p_method IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact completion method required'; END IF;
 IF (p_method='requester_confirmed' AND auth.uid() IS DISTINCT FROM a.member_needing_movement_id)
  OR (p_method='response_timeout' AND auth.uid() NOT IN(a.member_needing_movement_id,a.offering_member_id)) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact completion principal required'; END IF;
 PERFORM x.id FROM public.journeys x WHERE x.alignment_id=a.id FOR UPDATE;
 j:=private.assert_funded_coordination_entry(a.id);
 IF EXISTS(SELECT 1 FROM private.funded_movement_completions WHERE alignment_id=a.id) THEN
  RETURN;
 END IF;
 IF a.status<>'in_progress' OR j.status<>'in_progress' OR j.completion_requested_at IS NULL THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact offerer completion request required'; END IF;
 IF EXISTS(SELECT 1 FROM private.funded_completion_disputes WHERE alignment_id=a.id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Completion is under review'; END IF;
 SELECT x.* INTO STRICT g FROM private.financial_agreements x JOIN private.funded_movement_activations f ON f.financial_agreement_id=x.id WHERE f.alignment_id=a.id;
 -- All member gates precede all member account locks. Never upgrade SHARE locks.
 PERFORM m.id FROM public.members m WHERE m.id IN (a.offering_member_id,a.member_needing_movement_id) ORDER BY m.id FOR UPDATE;
 PERFORM x.id FROM private.wallet_accounts x WHERE x.member_id IN (a.offering_member_id,a.member_needing_movement_id)
  AND x.currency=g.currency ORDER BY x.id FOR UPDATE;
 FOR owner IN SELECT m.id FROM public.members m WHERE m.id IN (a.offering_member_id,a.member_needing_movement_id) ORDER BY m.id LOOP
  IF (SELECT count(*) FROM private.wallet_accounts WHERE member_id=owner AND currency=g.currency) NOT IN (0,3)
   OR EXISTS(SELECT 1 FROM private.wallet_accounts WHERE member_id=owner AND currency=g.currency AND status<>'active')
   OR (owner=a.member_needing_movement_id AND (SELECT count(*) FROM private.wallet_accounts WHERE member_id=owner AND currency=g.currency)<>3) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Complete active settlement wallets required'; END IF;
 END LOOP;
 SELECT max(amount_minor) FILTER(WHERE component_key='requester_platform_share'),
  max(amount_minor) FILTER(WHERE component_key='movement_contribution'),max(amount_minor) FILTER(WHERE component_key='offering_platform_share')
  INTO r,contribution,o FROM private.financial_components WHERE agreement_id=g.id;
 IF private.activation_fee_is_finalized(g.id) THEN r:=0; END IF;
 SELECT id INTO STRICT held_id FROM private.wallet_accounts WHERE member_id=a.member_needing_movement_id AND currency=g.currency AND account_kind='member_held';
 SELECT id INTO withdrawable_id FROM private.wallet_accounts WHERE member_id=a.offering_member_id AND currency=g.currency AND account_kind='member_withdrawable';
 FOR account IN SELECT x.* FROM private.wallet_accounts x WHERE x.member_id IN (a.offering_member_id,a.member_needing_movement_id) AND x.currency=g.currency LOOP
  SELECT coalesce(sum(CASE WHEN direction='credit' THEN amount_minor::numeric ELSE -amount_minor::numeric END),0)
   INTO balance FROM private.wallet_postings WHERE account_id=account.id;
  IF balance<0 OR balance>maximum THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Settlement wallet outside supported range'; END IF;
  IF account.id=held_id THEN held:=balance; END IF;
  IF account.id=withdrawable_id THEN withdrawable:=balance; END IF;
 END LOOP;
 IF held IS NULL OR held<r+contribution OR withdrawable+contribution>maximum OR withdrawable+contribution-o<0 THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Insufficient or overflowing settlement balances'; END IF;
 -- Setup is inside the same rollback subtransaction as all lifecycle/ledger writes.
 BEGIN
  PERFORM public.ensure_ngn_wallet_accounts_for_server(a.offering_member_id);
  SELECT id INTO STRICT withdrawable_id FROM private.wallet_accounts WHERE member_id=a.offering_member_id AND currency=g.currency AND account_kind='member_withdrawable';
  INSERT INTO private.wallet_accounts(member_id,account_kind,currency) VALUES(NULL,'platform_revenue',g.currency)
   ON CONFLICT(account_kind,currency) WHERE member_id IS NULL DO NOTHING;
  SELECT id INTO STRICT revenue_id FROM private.wallet_accounts WHERE member_id IS NULL AND account_kind='platform_revenue' AND currency=g.currency FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM private.wallet_accounts WHERE id=revenue_id AND status='active') THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Active platform revenue account required'; END IF;
  SELECT coalesce(sum(CASE WHEN direction='credit' THEN amount_minor::numeric ELSE -amount_minor::numeric END),0)
   INTO revenue FROM private.wallet_postings WHERE account_id=revenue_id;
  IF revenue<0 OR revenue+r+o>maximum THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Platform revenue outside supported range'; END IF;
  -- Every potentially blocking member/account/provisioning/revenue wait precedes this instant.
  -- The receipt actor trigger takes the sole admission sample and chooses the
  -- effective method after these waits; callers never supply temporal authority.
  stamp:=NULL;
  -- A single statement constructs the complete graph. Every writable stage
  -- consumes RETURNING from its predecessor. Immediate constraint triggers run
  -- at statement end, after all postings and both lifecycle updates; deferred
  -- callers retain their mode and also receive the explicit full assertion below.
  WITH evidence AS (
   INSERT INTO private.funded_movement_completions AS receipt VALUES(a.id,g.id,j.id,stamp,p_method)
   RETURNING receipt.alignment_id,receipt.financial_agreement_id,receipt.journey_id,receipt.completed_at
  ), components AS MATERIALIZED (
   SELECT c.*,e.alignment_id,e.completed_at,
    CASE c.component_key WHEN 'requester_platform_share' THEN 'requester_platform_charge'
     WHEN 'movement_contribution' THEN 'movement_contribution_settlement' ELSE 'offering_platform_charge' END kind,
    CASE c.component_key WHEN 'requester_platform_share' THEN 1 WHEN 'movement_contribution' THEN 2 ELSE 3 END ordinal
   FROM evidence e JOIN private.financial_components c ON c.agreement_id=e.financial_agreement_id
   WHERE c.amount_minor>0 AND (c.component_key<>'requester_platform_share' OR NOT private.activation_fee_is_finalized(g.id))
  ), transactions AS (
   INSERT INTO private.wallet_transactions(transaction_kind,currency,alignment_id,financial_component_id,idempotency_key,created_at)
    SELECT c.kind,g.currency,c.alignment_id,c.id,c.kind||':'||c.id::text,c.completed_at
     FROM components c ORDER BY c.ordinal
   RETURNING id,financial_component_id,created_at
  ), postings AS (
   INSERT INTO private.wallet_postings(transaction_id,account_id,direction,amount_minor,created_at)
    SELECT t.id,
     CASE WHEN side.direction='debit' THEN
       CASE WHEN c.component_key='offering_platform_share' THEN withdrawable_id ELSE held_id END
      ELSE CASE WHEN c.component_key='movement_contribution' THEN withdrawable_id ELSE revenue_id END END,
     side.direction,c.amount_minor,t.created_at
    FROM transactions t JOIN components c ON c.id=t.financial_component_id
    CROSS JOIN (VALUES('debit'::text,1),('credit'::text,2)) side(direction,ordinal)
    ORDER BY c.ordinal,side.ordinal
   RETURNING id
  ), completed_journey AS (
   UPDATE public.journeys x SET status='completed',completed_at=e.completed_at,updated_at=e.completed_at
    FROM evidence e WHERE x.id=e.journey_id AND (SELECT count(*) FROM postings)>=0
   RETURNING x.alignment_id,x.completed_at
  )
  UPDATE public.alignments x SET status='completed',updated_at=d.completed_at
   FROM completed_journey d WHERE x.id=d.alignment_id;
  PERFORM private.assert_funded_coordination_entry(a.id);
 EXCEPTION WHEN OTHERS THEN RAISE;
 END;
 RETURN;
END;

DECLARE v_need uuid;
BEGIN
  FOR v_need IN SELECT DISTINCT id FROM unnest(ARRAY[
    CASE WHEN TG_OP<>'INSERT' THEN OLD.movement_need_id END,
    CASE WHEN TG_OP<>'DELETE' THEN NEW.movement_need_id END]) id WHERE id IS NOT NULL ORDER BY id
  LOOP
    PERFORM 1 FROM public.movement_needs WHERE id=v_need FOR UPDATE;
    IF EXISTS (SELECT 1 FROM public.alignments WHERE movement_need_id=v_need
      AND status IN ('awaiting_activation_payment','activated','in_progress','completed')) THEN
      RAISE EXCEPTION 'Accepted movement roster is frozen';
    END IF;
  END LOOP;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;

DECLARE g private.financial_agreements%ROWTYPE; caller uuid:=auth.uid();
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25000',MESSAGE='Activation requires READ COMMITTED'; END IF;
 IF p_id IS NULL OR p_version IS NULL THEN RAISE EXCEPTION USING ERRCODE='22004',MESSAGE='Exact agreement and version required'; END IF;
 SELECT x.* INTO g FROM private.financial_agreements x WHERE x.id=p_id;
 IF caller IS NULL OR NOT FOUND OR g.member_needing_movement_id IS DISTINCT FROM caller THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Own requester agreement required'; END IF;
 IF p_version<1 OR g.version<>p_version THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact agreement version required'; END IF;
 SELECT x.* INTO STRICT g FROM private.financial_agreements x WHERE x.id=p_id FOR SHARE;
 IF p_lock THEN PERFORM 1 FROM public.alignments x WHERE x.id=g.alignment_id FOR UPDATE;
 ELSE PERFORM 1 FROM public.alignments x WHERE x.id=g.alignment_id FOR SHARE; END IF;
 -- Reuses all 0077 quote/snapshot/roster/consent/economics/three-component checks.
 RETURN private.movement_funding_agreement(p_id,caller,p_version);
END;

DECLARE a public.alignments%ROWTYPE; g private.financial_agreements%ROWTYPE;
 p private.financial_proposals%ROWTYPE; caller uuid:=auth.uid();
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION USING ERRCODE='25000',MESSAGE='Coordination requires READ COMMITTED'; END IF;
 IF p_need IS NULL THEN RAISE EXCEPTION USING ERRCODE='22004',MESSAGE='Movement need required'; END IF;
 IF caller IS NULL OR NOT EXISTS(SELECT 1 FROM public.members WHERE id=caller) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Authenticated member required'; END IF;
 IF (SELECT count(*) FROM public.alignments WHERE movement_need_id=p_need)<>1 THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact funded movement required'; END IF;
 SELECT x.* INTO STRICT a FROM public.alignments x WHERE x.movement_need_id=p_need;
 IF caller NOT IN (a.offering_member_id,a.member_needing_movement_id)
  AND (p_principal OR NOT EXISTS(SELECT 1 FROM public.movement_participants t
   WHERE t.movement_need_id=p_need AND t.member_id=caller AND t.status='confirmed' AND t.role='invited_participant')) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact movement principal required'; END IF;
 SELECT x.* INTO g FROM private.financial_agreements x
  JOIN private.funded_movement_activations r ON r.financial_agreement_id=x.id WHERE r.alignment_id=a.id;
 IF g.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact funded activation required'; END IF;
 SELECT x.* INTO STRICT g FROM private.financial_agreements x WHERE x.id=g.id FOR SHARE;
 SELECT x.* INTO STRICT a FROM public.alignments x WHERE x.id=g.alignment_id FOR UPDATE;
 IF a.movement_need_id IS DISTINCT FROM p_need OR a.status NOT IN ('activated','in_progress','completed')
  OR (p_principal AND caller NOT IN (a.offering_member_id,a.member_needing_movement_id)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Activated exact movement required'; END IF;
 g:=private.movement_funding_agreement(g.id,g.member_needing_movement_id,g.version);
 PERFORM private.assert_funded_activation(g,a);
 SELECT x.* INTO STRICT p FROM private.financial_proposals x WHERE x.financial_agreement_id=g.id;
 IF NOT EXISTS(SELECT 1 FROM public.movement_offers o JOIN public.vehicles v ON v.id=o.vehicle_id
  WHERE o.id=a.movement_offer_id AND o.status='accepted' AND o.vehicle_id=p.vehicle_id
   AND o.movement_need_id=a.movement_need_id AND o.offering_member_id=a.offering_member_id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact accepted offer vehicle required'; END IF;
 -- An in-progress selector is historical only with the exact committed start graph.
 IF a.status IN ('in_progress','completed') THEN PERFORM private.assert_funded_coordination_entry(a.id); END IF;
 RETURN a;
END;

DECLARE a public.alignments%ROWTYPE; g private.financial_agreements%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25000',MESSAGE='READ COMMITTED required'; END IF;
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.members WHERE id=auth.uid())
  OR p_need IS NULL OR (SELECT count(*) FROM public.alignments WHERE movement_need_id=p_need)<>1 THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Movement end unavailable'; END IF;
 SELECT * INTO STRICT a FROM public.alignments WHERE movement_need_id=p_need;
 IF auth.uid() NOT IN(a.offering_member_id,a.member_needing_movement_id) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Movement end unavailable'; END IF;
 SELECT x.* INTO STRICT g FROM private.financial_agreements x JOIN private.funded_movement_activations f ON f.financial_agreement_id=x.id WHERE f.alignment_id=a.id;
 PERFORM x.id FROM private.financial_agreements x WHERE x.id=g.id FOR SHARE;
 SELECT * INTO STRICT a FROM public.alignments WHERE id=g.alignment_id FOR UPDATE;
 IF a.movement_need_id IS DISTINCT FROM p_need OR auth.uid() NOT IN(a.offering_member_id,a.member_needing_movement_id) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Movement end unavailable'; END IF;
 -- materialization assertion takes the compatible offer SHARE before journey.
 g:=private.movement_funding_agreement(g.id,g.member_needing_movement_id,g.version);
 PERFORM x.id FROM public.journeys x WHERE x.alignment_id=a.id FOR UPDATE;
 PERFORM private.assert_undisposed_funded_graph(a.id);
 RETURN a;
END;

DECLARE a public.alignments%ROWTYPE; g private.financial_agreements%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25000',MESSAGE='READ COMMITTED required'; END IF;
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.members WHERE id=auth.uid())
  OR p_need IS NULL OR (SELECT count(*) FROM public.alignments WHERE movement_need_id=p_need)<>1 THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Movement end unavailable'; END IF;
 SELECT * INTO STRICT a FROM public.alignments WHERE movement_need_id=p_need;
 IF auth.uid() NOT IN(a.offering_member_id,a.member_needing_movement_id) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Movement end unavailable'; END IF;
 SELECT x.* INTO STRICT g FROM private.financial_agreements x JOIN private.funded_movement_activations f ON f.financial_agreement_id=x.id WHERE f.alignment_id=a.id;
 PERFORM x.id FROM private.financial_agreements x WHERE x.id=g.id FOR SHARE;
 SELECT * INTO STRICT a FROM public.alignments WHERE id=g.alignment_id FOR UPDATE;
 IF a.movement_need_id IS DISTINCT FROM p_need OR auth.uid() NOT IN(a.offering_member_id,a.member_needing_movement_id) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Movement end unavailable'; END IF;
