DECLARE g private.financial_agreements%ROWTYPE; a public.alignments%ROWTYPE; p private.financial_proposals%ROWTYPE;
BEGIN
 SELECT x.* INTO g FROM private.financial_agreements x JOIN private.funded_movement_activations r ON r.financial_agreement_id=x.id WHERE r.alignment_id=p_alignment;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT x.* INTO STRICT p FROM private.financial_proposals x WHERE x.financial_agreement_id=g.id;
 PERFORM private.assert_financial_proposal_materialization(p);
 SELECT x.* INTO STRICT a FROM public.alignments x WHERE x.id=p_alignment;
 PERFORM private.assert_funded_activation(g,a);
 RETURN true;
EXCEPTION WHEN check_violation OR no_data_found OR too_many_rows THEN RETURN false;
END;

BEGIN
  IF current_setting('transaction_isolation')<>'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000', MESSAGE='Offer availability requires READ COMMITTED';
  END IF;
  PERFORM 1 FROM public.movement_needs n WHERE n.id=p_need_id FOR UPDATE;
  PERFORM lr.id FROM private.movement_location_references lr
    JOIN private.movement_need_locations nl ON nl.location_reference_id=lr.id
    WHERE nl.movement_need_id=p_need_id ORDER BY lr.id FOR SHARE OF lr;
  PERFORM 1 FROM private.offering_movement_intents i WHERE i.id=p_intent_id FOR UPDATE;
END;

DECLARE ids uuid[]; selected_id uuid; selected_alignment uuid; financial_alignment public.alignments%ROWTYPE; financial_journey public.journeys%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN RETURN; END IF;
  IF EXISTS(SELECT 1 FROM public.alignments a WHERE a.movement_need_id=p_need AND private.is_financial_alignment(a.id)) THEN
    -- Do not run reveal (which locks alignment) before the canonical agreement lock.
    BEGIN
      financial_alignment:=private.funded_coordination_alignment(p_need,false);
      IF NOT EXISTS(SELECT 1 FROM public.journeys j WHERE j.alignment_id=financial_alignment.id) THEN RETURN; END IF;
      IF p_lock THEN PERFORM j.id FROM public.journeys j WHERE j.alignment_id=financial_alignment.id FOR UPDATE;
      ELSE PERFORM j.id FROM public.journeys j WHERE j.alignment_id=financial_alignment.id FOR SHARE; END IF;
      financial_journey:=private.assert_funded_coordination_entry(financial_alignment.id);
      IF NOT EXISTS(SELECT 1 FROM private.post_activation_reveal_subjects(p_need,auth.uid()) s WHERE s.alignment_id=financial_alignment.id) THEN RETURN; END IF;
      RETURN QUERY SELECT financial_journey.id,financial_alignment.id,financial_alignment.offering_member_id,
        financial_alignment.member_needing_movement_id,financial_journey.status,financial_journey.start_requested_at,financial_journey.started_at;
      RETURN;
    EXCEPTION WHEN check_violation OR insufficient_privilege OR no_data_found OR too_many_rows THEN RETURN;
    END;
  END IF;
  SELECT array_agg(j.id) INTO ids FROM public.journeys j
  JOIN public.alignments a ON a.id=j.alignment_id
  WHERE a.movement_need_id=p_need AND EXISTS (
    SELECT 1 FROM private.post_activation_reveal_subjects(p_need,auth.uid()) s WHERE s.alignment_id=a.id
  );
  IF cardinality(ids) IS DISTINCT FROM 1 THEN RETURN; END IF;
  selected_id:=ids[1];
  IF p_lock THEN
    SELECT j.alignment_id INTO selected_alignment FROM public.journeys j WHERE j.id=selected_id FOR UPDATE;
    PERFORM 1 FROM public.alignments a WHERE a.id=selected_alignment FOR UPDATE;
  END IF;
  RETURN QUERY SELECT j.id,a.id,a.offering_member_id,a.member_needing_movement_id,
    j.status,j.start_requested_at,j.started_at
  FROM public.journeys j JOIN public.alignments a ON a.id=j.alignment_id
  WHERE j.id=selected_id AND a.movement_need_id=p_need AND EXISTS (
    SELECT 1 FROM private.post_activation_reveal_subjects(p_need,auth.uid()) s WHERE s.alignment_id=a.id
  );
END;

DECLARE ids uuid[]; selected_id uuid; selected_alignment uuid; a public.alignments%ROWTYPE;
BEGIN
  IF EXISTS(SELECT 1 FROM public.alignments lifecycle_candidate WHERE lifecycle_candidate.movement_need_id=p_movement_need_id AND private.is_financial_alignment(lifecycle_candidate.id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial coordination lifecycle unavailable'; END IF;
  IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM public.members m WHERE m.id=auth.uid()) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Movement end unavailable';
  END IF;
  SELECT array_agg(j.id) INTO ids FROM public.journeys j
    JOIN public.alignments x ON x.id=j.alignment_id WHERE x.movement_need_id=p_movement_need_id;
  IF cardinality(ids) IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Movement end unavailable';
  END IF;
  selected_id:=ids[1];
  IF NOT EXISTS (SELECT 1 FROM public.journeys j JOIN public.alignments x ON x.id=j.alignment_id
    WHERE j.id=selected_id AND auth.uid() IN (x.offering_member_id,x.member_needing_movement_id)) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Movement end unavailable';
  END IF;
  SELECT j.alignment_id INTO selected_alignment FROM public.journeys j WHERE j.id=selected_id FOR UPDATE;
  SELECT x.* INTO a FROM public.alignments x WHERE x.id=selected_alignment FOR UPDATE;
  SELECT array_agg(j.id) INTO ids FROM public.journeys j
    JOIN public.alignments x ON x.id=j.alignment_id WHERE x.movement_need_id=p_movement_need_id;
  IF cardinality(ids) IS DISTINCT FROM 1 OR ids[1] IS DISTINCT FROM selected_id
    OR a.movement_need_id IS DISTINCT FROM p_movement_need_id
    OR auth.uid() NOT IN (a.offering_member_id,a.member_needing_movement_id)
    OR NOT (
      EXISTS (SELECT 1 FROM private.movement_coordination_context(p_movement_need_id,false) c
        WHERE c.journey_id=selected_id AND c.alignment_id=a.id)
      OR (a.status='cancelled' AND EXISTS (
        SELECT 1 FROM private.mutual_no_travel_closures n JOIN public.journeys j ON j.id=n.journey_id
        WHERE j.id=selected_id AND j.status='cancelled' AND j.started_at IS NULL AND j.completed_at IS NULL
          AND auth.uid() IN (n.first_principal_id,n.second_principal_id)))
    ) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Movement end unavailable';
  END IF;
  RETURN selected_id;
END;

DECLARE g private.financial_agreements%ROWTYPE; p private.financial_proposals%ROWTYPE;
BEGIN
  IF p_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='22004',MESSAGE='Exact agreement required'; END IF;
  IF p_caller IS NULL OR NOT EXISTS(SELECT 1 FROM public.members m WHERE m.id=p_caller) THEN
    RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Authenticated member required'; END IF;
  SELECT x.* INTO g FROM private.financial_agreements x WHERE x.id=p_id;
  IF NOT FOUND OR g.member_needing_movement_id IS DISTINCT FROM p_caller THEN
    RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Own requester agreement required'; END IF;
  IF p_version IS NOT NULL AND (p_version<1 OR p_version IS DISTINCT FROM g.version) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact agreement version required'; END IF;
  IF (SELECT count(*) FROM private.financial_proposals x WHERE x.financial_agreement_id=g.id)<>1 THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Authoritative materialized agreement required'; END IF;
  SELECT x.* INTO STRICT p FROM private.financial_proposals x WHERE x.financial_agreement_id=g.id;
  -- Immutable proposal reads, never proposal UPDATE. 0077 takes alignment SHARE
  -- -> offer SHARE -> agreement SHARE. Compatible with its replay and with
  -- 0020's agreement UPDATE -> alignment SHARE deferred validation.
  PERFORM private.assert_financial_proposal_materialization(p);
  SELECT x.* INTO STRICT g FROM private.financial_agreements x WHERE x.id=p_id FOR SHARE;
  IF g.currency<>'NGN' OR g.offering_accepted_at IS NULL OR g.requester_accepted_at IS NULL
    OR g.member_needing_movement_id IS DISTINCT FROM p_caller
    OR (p_version IS NOT NULL AND g.version IS DISTINCT FROM p_version) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Accepted exact requester agreement required'; END IF;
  RETURN g;
END;

DECLARE c private.financial_components%ROWTYPE; t private.wallet_transactions%ROWTYPE;
  receipt private.movement_funding_holds%ROWTYPE; total numeric; available_id uuid; held_id uuid;
  latest timestamptz; positive_count integer:=0; posting_count bigint; matching_count bigint;
BEGIN
  SELECT sum(x.amount_minor::numeric) INTO total FROM private.financial_components x
    WHERE x.agreement_id=g.id AND x.component_key IN ('requester_platform_share','movement_contribution');
  IF total IS NULL OR total<0 OR total>9223372036854775807::numeric THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Requester obligation outside supported range'; END IF;
  SELECT x.* INTO receipt FROM private.movement_funding_holds x WHERE x.financial_agreement_id=g.id;
  IF receipt.financial_agreement_id IS NULL THEN
    IF EXISTS(SELECT 1 FROM private.wallet_transactions x JOIN private.financial_components fc ON fc.id=x.financial_component_id
      WHERE fc.agreement_id=g.id AND fc.component_key IN ('requester_platform_share','movement_contribution') AND x.transaction_kind='movement_hold')
      OR EXISTS(SELECT 1 FROM private.wallet_transactions x JOIN private.financial_components fc
        ON x.idempotency_key='movement_hold:'||fc.id::text WHERE fc.agreement_id=g.id
        AND fc.component_key IN ('requester_platform_share','movement_contribution')) THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Partial funding history cannot be repaired'; END IF;
    RETURN QUERY SELECT total::bigint,0::bigint,NULL::timestamptz; RETURN;
  END IF;
  -- Historical account identities remain valid even if a later zero-balance
  -- closure occurred. Aggregate balances are deliberately not replay evidence.
  SELECT x.id INTO available_id FROM private.wallet_accounts x WHERE x.member_id=g.member_needing_movement_id
    AND x.currency=g.currency AND x.account_kind='member_available';
  SELECT x.id INTO held_id FROM private.wallet_accounts x WHERE x.member_id=g.member_needing_movement_id
    AND x.currency=g.currency AND x.account_kind='member_held';
  IF available_id IS NULL OR held_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Historical funding accounts unavailable'; END IF;
  FOR c IN SELECT x.* FROM private.financial_components x WHERE x.agreement_id=g.id
    AND x.component_key IN ('requester_platform_share','movement_contribution') ORDER BY x.id LOOP
    SELECT x.* INTO t FROM private.wallet_transactions x WHERE x.idempotency_key='movement_hold:'||c.id::text;
    IF c.amount_minor=0 THEN
      IF t.id IS NOT NULL OR EXISTS(SELECT 1 FROM private.wallet_transactions x
        WHERE x.financial_component_id=c.id AND x.transaction_kind='movement_hold') THEN
        RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Zero obligation must have no hold transaction'; END IF;
      CONTINUE;
    END IF;
    positive_count:=positive_count+1;
    IF t.id IS NULL OR t.transaction_kind<>'movement_hold' OR t.financial_component_id IS DISTINCT FROM c.id
      OR t.alignment_id IS DISTINCT FROM g.alignment_id OR t.currency<>g.currency
      OR t.provider IS NOT NULL OR t.provider_reference IS NOT NULL
      OR NOT isfinite(t.created_at) THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact historical component hold required'; END IF;
    SELECT count(*),count(*) FILTER(WHERE x.amount_minor=c.amount_minor AND
      ((x.account_id=available_id AND x.direction='debit') OR (x.account_id=held_id AND x.direction='credit')))
      INTO posting_count,matching_count FROM private.wallet_postings x WHERE x.transaction_id=t.id;
    IF posting_count<>2 OR matching_count<>2 THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact historical hold postings required'; END IF;
    PERFORM private.assert_wallet_transaction_balanced(t.id);
    latest:=greatest(latest,t.created_at);
  END LOOP;
  IF NOT isfinite(receipt.fully_held_at)
    OR (positive_count>0 AND receipt.fully_held_at IS DISTINCT FROM latest) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact persisted funding timestamp required'; END IF;
  RETURN QUERY SELECT total::bigint,total::bigint,receipt.fully_held_at;
END;

DECLARE a public.alignments%ROWTYPE; r private.funded_no_travel_requests%ROWTYPE;
 d private.funded_no_travel_closures%ROWTYPE; h private.funded_no_travel_holds%ROWTYPE; j public.journeys%ROWTYPE; g private.financial_agreements%ROWTYPE;
BEGIN
 IF p_action NOT IN('request','confirm','decline') OR p_action IS NULL
  OR (p_reason IS NOT NULL AND (length(btrim(p_reason)) NOT BETWEEN 1 AND 500)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement end unavailable'; END IF;
 a:=private.funded_no_travel_alignment(p_need);
 -- Consent receipt FKs also acquire member KEY SHARE locks. Take BOTH principal
 -- UPDATE gates in 0083 UUID order before any receipt insert, even for request
 -- and decline, so later confirmation never upgrades an implicit FK lock.
 PERFORM m.id FROM public.members m WHERE m.id IN(a.offering_member_id,a.member_needing_movement_id) ORDER BY m.id FOR UPDATE;
 SELECT * INTO h FROM private.funded_no_travel_holds WHERE alignment_id=a.id;
 IF h.alignment_id IS NOT NULL THEN
  PERFORM private.assert_held_no_travel(a.id);
  SELECT * INTO STRICT r FROM private.funded_no_travel_requests WHERE id=h.request_id;
  IF (p_action='request' AND auth.uid()=h.first_principal_id AND p_reason IS NOT DISTINCT FROM r.reason)
   OR (p_action='confirm' AND auth.uid()=h.second_principal_id) THEN RETURN; END IF;
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Conflicting held no-travel action';
 END IF;
 SELECT * INTO d FROM private.funded_no_travel_closures WHERE alignment_id=a.id;
 IF d.alignment_id IS NOT NULL THEN
  SELECT * INTO STRICT r FROM private.funded_no_travel_requests WHERE id=d.request_id;
  IF (p_action='request' AND auth.uid()=d.first_principal_id AND p_reason IS NOT DISTINCT FROM r.reason)
   OR (p_action='confirm' AND auth.uid()=d.second_principal_id) THEN RETURN; END IF;
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Conflicting terminal action';
 END IF;
 SELECT q.* INTO r FROM private.funded_no_travel_requests q WHERE q.alignment_id=a.id
  AND NOT EXISTS(SELECT 1 FROM private.funded_no_travel_declines z WHERE z.request_id=q.id);
 IF p_action='request' THEN
  IF r.id IS NOT NULL THEN
   IF r.first_principal_id=auth.uid() AND r.reason IS NOT DISTINCT FROM p_reason THEN RETURN; END IF;
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Explicit confirmation required'; END IF;
  SELECT x.* INTO STRICT j FROM public.journeys x WHERE x.alignment_id=a.id;
  INSERT INTO private.funded_no_travel_requests(alignment_id,financial_agreement_id,journey_id,first_principal_id,requested_at,reason)
   SELECT a.id,e.financial_agreement_id,j.id,auth.uid(),clock_timestamp(),p_reason FROM private.funded_movement_coordination_entries e WHERE e.alignment_id=a.id;
  PERFORM private.assert_funded_no_travel(a.id); RETURN;
 END IF;
 IF r.id IS NULL OR r.first_principal_id=auth.uid() THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Other principal request required'; END IF;
 IF p_action='decline' THEN
  INSERT INTO private.funded_no_travel_declines VALUES(r.id,auth.uid(),clock_timestamp());
  PERFORM private.assert_funded_no_travel(a.id); RETURN;
 END IF;
 SELECT * INTO STRICT j FROM public.journeys WHERE id=r.journey_id;
 SELECT * INTO STRICT g FROM private.financial_agreements WHERE id=r.financial_agreement_id;
 -- Neither new nor legacy activated users can create a new refund receipt.
 -- Preserve existing legacy release history above; otherwise record no travel
 -- without changing the original held amounts or fee timing.
 INSERT INTO private.funded_no_travel_holds
  VALUES(a.id,g.id,j.id,r.id,r.first_principal_id,auth.uid(),r.requested_at,clock_timestamp(),j.start_requested_at);
 PERFORM private.assert_held_no_travel(a.id);
END;

BEGIN
  IF NEW.attempt_ordinal IS DISTINCT FROM OLD.attempt_ordinal THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Face attempt ordinal is immutable';
  END IF;
  RETURN NEW;
END;

BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial agreement history cannot be deleted';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.status<>'current' OR NEW.offering_accepted_at IS NOT NULL OR NEW.requester_accepted_at IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Publish a current unaccepted financial agreement first';
    END IF;
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW)-ARRAY['status','offering_accepted_at','requester_accepted_at'])
    IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','offering_accepted_at','requester_accepted_at']) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Published financial agreement terms are immutable';
  END IF;
  IF OLD.status='superseded' AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Superseded financial agreement is immutable';
  END IF;
  IF (OLD.offering_accepted_at IS NOT NULL AND NEW.offering_accepted_at IS DISTINCT FROM OLD.offering_accepted_at)
    OR (OLD.requester_accepted_at IS NOT NULL AND NEW.requester_accepted_at IS DISTINCT FROM OLD.requester_accepted_at) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial acceptance is write-once';
  END IF;
  IF NEW.status='superseded' AND
    ROW(NEW.offering_accepted_at,NEW.requester_accepted_at)
      IS DISTINCT FROM ROW(OLD.offering_accepted_at,OLD.requester_accepted_at) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Accept the current version before superseding it';
  END IF;
  RETURN NEW;
END;

DECLARE agreement_status text;
BEGIN
  IF TG_OP<>'INSERT' THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Published financial components are immutable';
  END IF;
  -- Serialize construction with supersession and acceptance on the parent.
  SELECT a.status INTO agreement_status FROM private.financial_agreements a
    WHERE a.id=NEW.agreement_id FOR UPDATE;
  IF agreement_status IS DISTINCT FROM 'current' THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Components require a current financial agreement';
  END IF;
  RETURN NEW;
END;

BEGIN
 IF OLD.activated_at IS NOT NULL AND EXISTS(SELECT 1 FROM private.funded_movement_activations WHERE alignment_id=OLD.id) THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial coordination lifecycle unavailable'; END IF;
  IF EXISTS(SELECT 1 FROM private.funded_no_travel_closures WHERE alignment_id=OLD.id) THEN
   IF OLD.status='activated' AND NEW.status='cancelled'
    AND (to_jsonb(NEW)-ARRAY['status','updated_at']) IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','updated_at'])
    AND EXISTS(SELECT 1 FROM private.funded_no_travel_closures d WHERE d.alignment_id=OLD.id) THEN RETURN NEW; END IF;
   IF to_jsonb(NEW) IS NOT DISTINCT FROM to_jsonb(OLD) THEN RETURN NEW; END IF;
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Funded no-travel is terminal';
  END IF;
  IF (to_jsonb(NEW)-'updated_at') IS NOT DISTINCT FROM (to_jsonb(OLD)-'updated_at') THEN RETURN NEW; END IF;
  IF OLD.status='in_progress' AND NEW.status='completed'
   AND (to_jsonb(NEW)-ARRAY['status','updated_at']) IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','updated_at'])
   AND EXISTS(SELECT 1 FROM private.funded_movement_completions x WHERE x.alignment_id=OLD.id) THEN RETURN NEW; END IF;
  IF OLD.status='activated' AND NEW.status='in_progress'
   AND (to_jsonb(NEW)-ARRAY['status','updated_at']) IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','updated_at'])
   AND EXISTS(SELECT 1 FROM private.funded_movement_starts x WHERE x.alignment_id=OLD.id) THEN RETURN NEW; END IF;
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial coordination lifecycle unavailable';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END;

DECLARE r private.funded_movement_coordination_entries%ROWTYPE; a public.alignments%ROWTYPE;
BEGIN
 IF TG_OP='TRUNCATE' THEN
  IF EXISTS(SELECT 1 FROM public.journeys j WHERE private.is_financial_alignment(j.alignment_id)) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial coordination lifecycle unavailable'; END IF; RETURN NULL;
 END IF;
 IF TG_OP<>'INSERT' AND private.is_financial_alignment(OLD.alignment_id) THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial coordination lifecycle unavailable'; END IF;
  IF EXISTS(SELECT 1 FROM private.funded_no_travel_closures WHERE alignment_id=OLD.alignment_id) THEN
   IF OLD.status='not_started' AND OLD.started_at IS NULL AND NEW.status='cancelled'
    AND (to_jsonb(NEW)-ARRAY['status','updated_at']) IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','updated_at'])
    AND EXISTS(SELECT 1 FROM private.funded_no_travel_closures d WHERE d.alignment_id=OLD.alignment_id AND d.journey_id=OLD.id AND d.released_at=NEW.updated_at) THEN RETURN NEW; END IF;
   IF to_jsonb(NEW) IS NOT DISTINCT FROM to_jsonb(OLD) THEN RETURN NEW; END IF;
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Funded no-travel is terminal';
  END IF;
  IF to_jsonb(NEW) IS NOT DISTINCT FROM to_jsonb(OLD) THEN RETURN NEW; END IF;
  IF OLD.status='in_progress' AND OLD.completed_at IS NULL
   AND (to_jsonb(NEW)-ARRAY['status','completion_requested_at','completed_at','updated_at'])
    IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','completion_requested_at','completed_at','updated_at']) THEN
   IF OLD.completion_requested_at IS NULL AND NEW.status='in_progress' AND NEW.completed_at IS NULL
    AND EXISTS(SELECT 1 FROM private.funded_movement_completion_requests x WHERE x.alignment_id=OLD.alignment_id
     AND x.journey_id=OLD.id AND x.requested_at=NEW.completion_requested_at)
    AND NOT EXISTS(SELECT 1 FROM private.funded_movement_completions x WHERE x.alignment_id=OLD.alignment_id) THEN RETURN NEW; END IF;
   IF OLD.completion_requested_at IS NOT NULL AND NEW.status='completed' AND NEW.completion_requested_at=OLD.completion_requested_at
    AND EXISTS(SELECT 1 FROM private.funded_movement_completions x WHERE x.alignment_id=OLD.alignment_id
     AND x.journey_id=OLD.id AND x.completed_at=NEW.completed_at) THEN RETURN NEW; END IF;
  END IF;
  IF (to_jsonb(NEW)-ARRAY['status','start_requested_at','started_at','updated_at'])
   IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','start_requested_at','started_at','updated_at']) THEN
   IF OLD.status='not_started' AND OLD.start_requested_at IS NULL AND OLD.started_at IS NULL
    AND NEW.status='not_started' AND NEW.started_at IS NULL
    AND EXISTS(SELECT 1 FROM private.funded_movement_start_requests x WHERE x.alignment_id=OLD.alignment_id
     AND x.journey_id=OLD.id AND x.requested_at=NEW.start_requested_at)
    AND NOT EXISTS(SELECT 1 FROM private.funded_movement_starts x WHERE x.alignment_id=OLD.alignment_id) THEN RETURN NEW; END IF;
   IF OLD.status='not_started' AND OLD.start_requested_at IS NOT NULL AND OLD.started_at IS NULL
    AND NEW.status='in_progress' AND NEW.start_requested_at=OLD.start_requested_at
    AND EXISTS(SELECT 1 FROM private.funded_movement_starts x WHERE x.alignment_id=OLD.alignment_id
     AND x.journey_id=OLD.id AND x.started_at=NEW.started_at) THEN RETURN NEW; END IF;
  END IF;
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial coordination lifecycle unavailable';
 END IF;
 IF TG_OP<>'DELETE' AND private.is_financial_alignment(NEW.alignment_id) THEN
  SELECT x.* INTO r FROM private.funded_movement_coordination_entries x WHERE x.journey_id=NEW.id;
  SELECT x.* INTO a FROM public.alignments x WHERE x.id=NEW.alignment_id;
  IF r.journey_id IS NULL OR r.alignment_id IS DISTINCT FROM NEW.alignment_id OR a.status<>'activated'
   OR NOT EXISTS(SELECT 1 FROM private.funded_movement_activations f WHERE f.alignment_id=a.id AND f.financial_agreement_id=r.financial_agreement_id)
   OR NEW.vehicle_id IS DISTINCT FROM (SELECT vehicle_id FROM public.movement_offers WHERE id=a.movement_offer_id)
   OR NEW.created_at IS DISTINCT FROM r.created_at OR NEW.updated_at IS DISTINCT FROM r.created_at
   OR NEW.status<>'not_started' OR NEW.start_requested_at IS NOT NULL OR NEW.started_at IS NOT NULL
   OR NEW.completion_requested_at IS NOT NULL OR NEW.completed_at IS NOT NULL
   OR NEW.end_requested_by_member_id IS NOT NULL OR NEW.end_requested_at IS NOT NULL
   OR NEW.end_confirmed_by_member_id IS NOT NULL OR NEW.end_confirmed_at IS NOT NULL
   OR NEW.end_reason IS NOT NULL OR NEW.end_method IS NOT NULL THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact funded coordination provenance required'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END;

DECLARE s private.movement_context_snapshots%ROWTYPE;
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal history cannot be deleted';
  END IF;
  PERFORM private.assert_financial_proposal_quote_binding(NEW);
  PERFORM private.assert_financial_proposal_movement_context_binding(NEW);
  PERFORM private.assert_financial_proposal_source_compatibility(NEW);
  IF TG_OP='INSERT' THEN
    SELECT x.* INTO STRICT s FROM private.movement_context_snapshots x
      WHERE x.id=NEW.movement_context_snapshot_id;
    -- Stronger locks FIRST: 0045 owns need UPDATE -> offer UPDATE -> requester
    -- endpoints -> intent UPDATE -> route -> availability UPDATE -> vehicle/access.
    -- Never upgrade quote SHARE locks into this chain. Future writers must take
    -- these dependencies before existing proposal history rows.
    PERFORM private.assert_movement_offer_availability_binding(s.movement_offer_id);
    PERFORM private.assert_pricing_quote(NEW.pricing_quote_id);
    -- Dependencies are already locked. Retain snapshot SHARE until transaction
    -- end; FK KEY SHARE alone would not block a non-key status UPDATE.
    PERFORM private.assert_movement_context_snapshot(NEW.movement_context_snapshot_id);
    -- Fresh clock eligibility after quote/snapshot waits, with locks held.
    PERFORM private.assert_movement_offer_availability_binding(s.movement_offer_id);
    PERFORM private.assert_pricing_quote(NEW.pricing_quote_id);
    IF NEW.status<>'current' OR NEW.offering_accepted_at IS NOT NULL OR NEW.requester_accepted_at IS NOT NULL
      OR NEW.movement_offer_id IS NOT NULL OR NEW.alignment_id IS NOT NULL
      OR NEW.financial_agreement_id IS NOT NULL OR NEW.materialized_at IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Create an unaccepted unbound current proposal first';
    END IF;
    IF NOT isfinite(NEW.created_at) THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal creation time cannot be future-dated';
    END IF;
    IF NEW.expires_at IS NOT NULL AND NEW.expires_at <= clock_timestamp() THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal cannot be created already expired';
    END IF;
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW)-ARRAY['status','offering_accepted_at','requester_accepted_at',
      'movement_offer_id','alignment_id','financial_agreement_id','materialized_at'])
    IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','offering_accepted_at','requester_accepted_at',
      'movement_offer_id','alignment_id','financial_agreement_id','materialized_at']) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal economics and snapshots are immutable';
  END IF;
  IF OLD.status='superseded' AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Superseded proposal is immutable';
  END IF;
  IF OLD.materialized_at IS NOT NULL AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Materialized proposal is immutable';
  END IF;
  IF (OLD.offering_accepted_at IS NOT NULL AND NEW.offering_accepted_at IS DISTINCT FROM OLD.offering_accepted_at)
    OR (OLD.requester_accepted_at IS NOT NULL AND NEW.requester_accepted_at IS DISTINCT FROM OLD.requester_accepted_at)
    OR (OLD.movement_offer_id IS NOT NULL AND NEW.movement_offer_id IS DISTINCT FROM OLD.movement_offer_id)
    OR (OLD.alignment_id IS NOT NULL AND NEW.alignment_id IS DISTINCT FROM OLD.alignment_id)
    OR (OLD.financial_agreement_id IS NOT NULL AND NEW.financial_agreement_id IS DISTINCT FROM OLD.financial_agreement_id)
    OR (OLD.materialized_at IS NOT NULL AND NEW.materialized_at IS DISTINCT FROM OLD.materialized_at) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal consent and links are write-once';
  END IF;
  IF (to_jsonb(NEW)-'status') IS DISTINCT FROM (to_jsonb(OLD)-'status') THEN
    IF NEW.status<>'current' OR (NEW.expires_at IS NOT NULL AND NEW.expires_at<=clock_timestamp()) THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal is not current and unexpired';
    END IF;
    IF (NEW.offering_accepted_at IS NOT NULL AND NOT isfinite(NEW.offering_accepted_at))
      OR (NEW.requester_accepted_at IS NOT NULL AND NOT isfinite(NEW.requester_accepted_at))
      OR (NEW.materialized_at IS NOT NULL AND NOT isfinite(NEW.materialized_at)) THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal evidence cannot be future-dated';
    END IF;
  END IF;
  RETURN NEW;
END;

DECLARE p private.financial_proposals%ROWTYPE;
BEGIN
  IF TG_OP<>'INSERT' THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal roster history is immutable';
  END IF;
  SELECT * INTO STRICT p FROM private.financial_proposals WHERE id=NEW.proposal_id FOR UPDATE;
  IF p.status<>'current' OR p.offering_accepted_at IS NOT NULL OR p.requester_accepted_at IS NOT NULL
    OR p.movement_offer_id IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal roster construction has ended';
  END IF;
  RETURN NEW;
END;

BEGIN
 IF EXISTS(SELECT 1 FROM public.alignments a JOIN private.funded_movement_activations r ON r.alignment_id=a.id
  WHERE a.movement_offer_id=OLD.id)
  AND (TG_OP='DELETE' OR (to_jsonb(NEW)-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'updated_at')) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Funded accepted offer is immutable'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END;

BEGIN
 IF TG_OP='TRUNCATE' THEN
  IF EXISTS(SELECT 1 FROM private.funded_movement_start_requests) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial start meeting point is frozen'; END IF; RETURN NULL;
 END IF;
 IF EXISTS(SELECT 1 FROM private.funded_movement_start_requests x WHERE x.journey_id=CASE WHEN TG_OP='INSERT' THEN NEW.journey_id ELSE OLD.journey_id END)
  OR (TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM private.funded_movement_start_requests x WHERE x.journey_id=NEW.journey_id)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial start meeting point is frozen'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END;

BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.rating IS NOT NULL OR NEW.completed_movements<>0 THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Authoritative reputation required'; END IF;
 ELSIF (NEW.rating,NEW.completed_movements) IS DISTINCT FROM (OLD.rating,OLD.completed_movements) THEN
  IF NEW.completed_movements IS DISTINCT FROM (SELECT count(*) FROM private.completed_movement_principals p WHERE p.member_id=NEW.id)
   OR NEW.rating IS DISTINCT FROM (SELECT round(avg(r.stars::numeric),2) FROM private.completed_movement_ratings r WHERE r.reviewed_member_id=NEW.id) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Authoritative reputation required'; END IF;
 END IF;
 RETURN NEW;
END;

DECLARE parent_status text;
BEGIN
  IF TG_OP<>'INSERT' THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement context relationships are immutable';
  END IF;
  IF TG_TABLE_NAME='offering_movement_intent_locations' THEN
    SELECT i.status INTO STRICT parent_status FROM private.offering_movement_intents i WHERE i.id=NEW.intent_id FOR UPDATE;
  ELSE
    SELECT s.status INTO STRICT parent_status FROM private.movement_context_snapshots s WHERE s.id=NEW.snapshot_id FOR UPDATE;
  END IF;
  IF parent_status<>'current' THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement context relationship requires a current parent';
  END IF;
  RETURN NEW;
END;

BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement context history cannot be deleted';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NOT isfinite(NEW.created_at) OR (NEW.expires_at IS NOT NULL AND NEW.expires_at<=clock_timestamp()) THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement context creation time or expiry is invalid';
    END IF;
    IF TG_TABLE_NAME='movement_location_references' THEN
      IF NEW.resolved_at IS NOT NULL AND (NOT isfinite(NEW.resolved_at) OR NEW.resolved_at>NEW.created_at) THEN
        RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Location resolution cannot be future-dated';
      END IF;
    ELSIF NEW.status<>'current' THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement context versions must start current';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_TABLE_NAME='movement_location_references' THEN
    IF NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Location inputs are immutable';
    END IF;
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW)-'status') IS DISTINCT FROM (to_jsonb(OLD)-'status') THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement context fields are immutable';
  END IF;
  IF OLD.status<>'current' AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement context lifecycle cannot reopen or change terminal state';
  END IF;
  IF TG_TABLE_NAME='offering_movement_intents' AND NEW.status='expired' AND OLD.status='current'
    AND (NEW.expires_at IS NULL OR NEW.expires_at>clock_timestamp()) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Intent expiry has not elapsed';
  END IF;
  RETURN NEW;
END;

