BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE =
        'Trusted route-match evidence history cannot be deleted';
  END IF;


  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'current' THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE =
          'Trusted route-match evidence must start current';
    END IF;


    IF NOT isfinite(NEW.created_at)
       OR NOT isfinite(NEW.calculated_at) OR NEW.calculated_at > NEW.created_at
       OR (
         NEW.expires_at IS NOT NULL
         AND NEW.expires_at <= clock_timestamp()
       ) THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE =
          'Trusted route-match evidence timestamps are invalid';
    END IF;


    RETURN NEW;
  END IF;


  -- Evidence facts are immutable.
  -- Only lifecycle status may change.
  IF (
    to_jsonb(NEW) - 'status'
  ) IS DISTINCT FROM (
    to_jsonb(OLD) - 'status'
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE =
        'Trusted route-match evidence fields are immutable';
  END IF;


  IF OLD.status <> 'current'
     AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE =
        'Trusted route-match evidence lifecycle cannot reopen';
  END IF;


  IF NEW.status NOT IN (
    'superseded',
    'expired'
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE =
        'Trusted route-match evidence lifecycle transition is invalid';
  END IF;


  IF NEW.status = 'expired'
     AND (
       NEW.expires_at IS NULL
       OR NEW.expires_at > clock_timestamp()
     ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE =
        'Trusted route-match evidence expiry has not elapsed';
  END IF;


  RETURN NEW;
END;

DECLARE
  v_balance numeric;
BEGIN
  IF TG_OP IN ('DELETE', 'TRUNCATE') THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Wallet account history cannot be removed';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Wallet account must start active';
    END IF;
    RETURN NEW;
  END IF;

  IF (to_jsonb(NEW) - 'status') IS DISTINCT FROM (to_jsonb(OLD) - 'status') THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Wallet account identity is immutable';
  END IF;

  IF OLD.status IS DISTINCT FROM 'active' OR NEW.status IS DISTINCT FROM 'closed' THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Wallet account lifecycle cannot reopen or change terminal state';
  END IF;

  SELECT COALESCE(
    sum(
      CASE
        WHEN p.direction = 'credit' THEN p.amount_minor::numeric
        ELSE -p.amount_minor::numeric
      END
    ),
    0
  )
  INTO v_balance
  FROM private.wallet_postings p
  WHERE p.account_id = OLD.id;

  IF v_balance IS DISTINCT FROM 0::numeric THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Wallet account with nonzero balance cannot be closed';
  END IF;

  RETURN NEW;
END;

