DECLARE g private.financial_agreements%ROWTYPE; a public.alignments%ROWTYPE; c private.financial_components%ROWTYPE; f private.funded_movement_activations%ROWTYPE; funding record;
 account record; balance numeric; held numeric; revenue numeric; revenue_id uuid;
BEGIN
 SELECT * INTO STRICT g FROM private.financial_agreements WHERE id=NEW.financial_agreement_id;
 g:=private.funded_activation_agreement(g.id,g.version,true);
 SELECT * INTO STRICT a FROM public.alignments WHERE id=g.alignment_id;
 PERFORM private.assert_alignment_face_ready(a.id);
 SELECT * INTO STRICT c FROM private.financial_components WHERE agreement_id=g.id AND component_key='requester_platform_share';
 SELECT * INTO STRICT f FROM private.funded_movement_activations WHERE financial_agreement_id=g.id;
 SELECT * INTO funding FROM private.movement_funding_evidence(g);
 IF g.status<>'current' OR a.status<>'awaiting_activation_payment' OR a.activated_at IS NOT NULL
  OR NEW.alignment_id IS DISTINCT FROM a.id OR NEW.financial_component_id IS DISTINCT FROM c.id
  OR NEW.requester_member_id IS DISTINCT FROM auth.uid() OR NEW.requester_member_id IS DISTINCT FROM g.member_needing_movement_id
  OR NEW.amount_minor IS DISTINCT FROM c.amount_minor OR NEW.currency IS DISTINCT FROM g.currency
  OR NEW.finalized_at IS DISTINCT FROM f.activated_at OR NOT isfinite(NEW.finalized_at)
  OR funding.fully_held_at IS NULL OR funding.held_minor<>funding.required_minor
  OR EXISTS(SELECT 1 FROM private.funded_activation_fee_legacy WHERE financial_agreement_id=g.id)
  OR EXISTS(SELECT 1 FROM private.required_face_members(a.id) r WHERE NOT private.has_current_alignment_face_check(a.id,r.member_id,NEW.finalized_at)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact requester activation construction required'; END IF;
 -- Trusted direct constructors must obey the same member/account gates and
 -- active-wallet, aggregate-balance and overflow admission as the public RPC.
 PERFORM x.id FROM private.wallet_accounts x WHERE x.member_id=g.member_needing_movement_id AND x.currency=g.currency ORDER BY x.id FOR UPDATE;
 IF (SELECT count(*) FROM private.wallet_accounts WHERE member_id=g.member_needing_movement_id AND currency=g.currency)<>3
  OR EXISTS(SELECT 1 FROM private.wallet_accounts WHERE member_id=g.member_needing_movement_id AND currency=g.currency AND status<>'active') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Complete active activation wallet required'; END IF;
 FOR account IN SELECT * FROM private.wallet_accounts WHERE member_id=g.member_needing_movement_id AND currency=g.currency LOOP
  SELECT coalesce(sum(CASE WHEN direction='credit' THEN amount_minor::numeric ELSE -amount_minor::numeric END),0) INTO balance FROM private.wallet_postings WHERE account_id=account.id;
  IF balance<0 OR balance>9223372036854775807::numeric THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Activation wallet outside supported range'; END IF;
  IF account.account_kind='member_held' THEN held:=balance; END IF;
 END LOOP;
 IF held IS NULL OR held<funding.required_minor THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact activation obligations must remain held'; END IF;
 IF c.amount_minor>0 THEN
  SELECT id INTO STRICT revenue_id FROM private.wallet_accounts WHERE member_id IS NULL AND currency=g.currency AND account_kind='platform_revenue' FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM private.wallet_accounts WHERE id=revenue_id AND status='active') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Active revenue account required'; END IF;
  SELECT coalesce(sum(CASE WHEN direction='credit' THEN amount_minor::numeric ELSE -amount_minor::numeric END),0) INTO revenue FROM private.wallet_postings WHERE account_id=revenue_id;
  IF revenue<0 OR revenue+c.amount_minor>9223372036854775807::numeric THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Activation revenue outside supported range'; END IF;
 END IF;
 RETURN NEW;
END;

BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.status IN ('activated','in_progress','completed') THEN RAISE EXCEPTION 'Alignment must activate through payment'; END IF;
    RETURN NEW;
  END IF;
  -- Session bindings must never refer to the old participants/offer while the
  -- same UPDATE activates a different movement. Existing RPCs never rebind these.
  IF ROW(NEW.movement_need_id,NEW.movement_offer_id,NEW.member_needing_movement_id,NEW.offering_member_id)
    IS DISTINCT FROM ROW(OLD.movement_need_id,OLD.movement_offer_id,OLD.member_needing_movement_id,OLD.offering_member_id) THEN
    RAISE EXCEPTION 'Alignment participant and offer bindings are immutable';
  END IF;
  IF OLD.status='awaiting_activation_payment' AND NEW.status IN ('in_progress','completed') THEN
    RAISE EXCEPTION 'Alignment must activate through payment';
  END IF;
  IF NEW.status<>'activated' OR OLD.status='activated' THEN RETURN NEW; END IF;
  IF OLD.status<>'awaiting_activation_payment' THEN RAISE EXCEPTION 'Invalid activation transition'; END IF;
  PERFORM private.assert_alignment_face_ready(NEW.id);
  RETURN NEW;
END;

DECLARE
  v_plate text;
BEGIN
  -- Do not obstruct mutual completion/cancellation of historical movements.
  IF TG_OP = 'UPDATE' AND NEW.status NOT IN (
    'awaiting_activation_payment', 'activated', 'in_progress'
  ) THEN
    RETURN NEW;
  END IF;

  SELECT v.plate_number INTO v_plate
  FROM public.movement_offers mo
  JOIN public.vehicles v ON v.id = mo.vehicle_id
  WHERE mo.id = NEW.movement_offer_id
    AND mo.movement_need_id = NEW.movement_need_id
    AND mo.offering_member_id = NEW.offering_member_id
  FOR SHARE OF v;

  IF NOT FOUND OR v_plate IS NULL OR btrim(v_plate) = '' THEN
    RAISE EXCEPTION 'A vehicle plate must be recorded before alignment or activation';
  END IF;
  RETURN NEW;
END;

DECLARE a public.alignments%ROWTYPE; j public.journeys%ROWTYPE; w private.funded_completion_response_windows%ROWTYPE;
BEGIN
 SELECT x.* INTO STRICT a FROM public.alignments x WHERE x.id=NEW.alignment_id;
 a:=private.funded_coordination_alignment(a.movement_need_id);
 PERFORM x.id FROM public.journeys x WHERE x.alignment_id=a.id FOR UPDATE;
 PERFORM m.id FROM public.members m WHERE m.id IN(a.offering_member_id,a.member_needing_movement_id) ORDER BY m.id FOR UPDATE;
 j:=private.assert_funded_coordination_entry(a.id);
 SELECT * INTO STRICT w FROM private.funded_completion_response_windows WHERE alignment_id=a.id;
 IF auth.uid() IS DISTINCT FROM a.member_needing_movement_id OR NEW.requester_member_id IS DISTINCT FROM auth.uid()
  OR NEW.financial_agreement_id IS DISTINCT FROM w.financial_agreement_id OR NEW.journey_id IS DISTINCT FROM w.journey_id
  OR j.status<>'in_progress' OR a.status<>'in_progress' OR j.completion_requested_at IS NULL
  OR EXISTS(SELECT 1 FROM private.funded_movement_completions WHERE alignment_id=a.id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact requester completion review required'; END IF;
 -- Single server observation admits the live response-window decision.
 NEW.opened_at:=clock_timestamp();
 IF NEW.opened_at>=w.response_deadline_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Response window expired'; END IF;
 RETURN NEW;
END;

BEGIN
  IF NEW.status<>'pending' THEN RAISE EXCEPTION 'New activation payment must be pending'; END IF;
  PERFORM private.assert_alignment_face_ready(NEW.alignment_id);
  RETURN NEW;
END;

DECLARE g private.financial_agreements%ROWTYPE;
BEGIN
 IF NEW.status='activated' AND OLD.status IS DISTINCT FROM NEW.status AND private.is_financial_alignment(NEW.id) THEN
  SELECT x.* INTO g FROM private.financial_agreements x JOIN private.funded_movement_activations r ON r.financial_agreement_id=x.id WHERE r.alignment_id=NEW.id;
  IF g.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Funded activation receipt required'; END IF;
  PERFORM private.assert_funded_activation(g,NEW);
 END IF;
 IF EXISTS(SELECT 1 FROM private.funded_movement_activations r WHERE r.alignment_id=OLD.id)
  AND OLD.activated_at IS NOT NULL AND NEW.activated_at IS DISTINCT FROM OLD.activated_at THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Funded activation timestamp is immutable'; END IF;
 RETURN NEW;
END;

DECLARE a public.alignments%ROWTYPE; j public.journeys%ROWTYPE; g uuid; deadline timestamptz;
BEGIN
 SELECT x.* INTO STRICT a FROM public.alignments x WHERE x.id=NEW.alignment_id;
 a:=private.funded_coordination_alignment(a.movement_need_id);
 PERFORM x.id FROM public.journeys x WHERE x.alignment_id=a.id FOR UPDATE;
 PERFORM m.id FROM public.members m WHERE m.id IN(a.offering_member_id,a.member_needing_movement_id) ORDER BY m.id FOR UPDATE;
 j:=private.assert_funded_coordination_entry(a.id);
 SELECT financial_agreement_id INTO STRICT g FROM private.funded_movement_activations WHERE alignment_id=a.id;
 IF NEW.journey_id IS DISTINCT FROM j.id OR NEW.financial_agreement_id IS DISTINCT FROM g
  OR a.status<>'in_progress' OR j.status<>'in_progress' OR j.completed_at IS NOT NULL THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact in-progress financial movement required'; END IF;
 IF TG_TABLE_NAME='funded_movement_completion_requests' THEN
  IF auth.uid() IS DISTINCT FROM a.offering_member_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact offerer required'; END IF;
  IF j.completion_requested_at IS NOT NULL OR NOT isfinite(NEW.requested_at) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact first completion request required'; END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM private.funded_completion_disputes WHERE alignment_id=a.id) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Completion is under review'; END IF;
  IF j.completion_requested_at IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact offerer completion request required'; END IF;
  IF NEW.completion_method='requester_confirmed' THEN
   IF auth.uid() IS DISTINCT FROM a.member_needing_movement_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact requester required'; END IF;
  ELSIF NEW.completion_method='response_timeout' THEN
   IF auth.uid() NOT IN(a.offering_member_id,a.member_needing_movement_id) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact timeout principal required'; END IF;
  ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact completion method required'; END IF;
  SELECT w.response_deadline_at INTO STRICT deadline FROM private.funded_completion_response_windows w
   WHERE w.alignment_id=a.id AND w.financial_agreement_id=g AND w.journey_id=j.id
    AND w.requested_at=j.completion_requested_at;
  -- Live policy admission ONLY, after canonical construction and money waits.
  -- One server observation chooses the basis and supplies all RETURNING metadata.
  NEW.completed_at:=clock_timestamp();
  IF NEW.completed_at>=deadline THEN
   NEW.completion_method:='response_timeout';
  ELSIF NEW.completion_method='response_timeout' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Response window remains open';
  END IF;
 END IF;
 RETURN NEW;
END;

DECLARE a public.alignments%ROWTYPE; e private.funded_movement_coordination_entries%ROWTYPE;
BEGIN
 SELECT * INTO STRICT a FROM public.alignments WHERE id=NEW.alignment_id;
 a:=private.funded_dispute_alignment(a.movement_need_id);
 PERFORM m.id FROM public.members m WHERE m.id IN(a.offering_member_id,a.member_needing_movement_id) ORDER BY m.id FOR UPDATE;
 SELECT * INTO STRICT e FROM private.funded_movement_coordination_entries WHERE alignment_id=a.id;
 IF a.status<>'activated' OR NEW.opened_by_member_id IS DISTINCT FROM auth.uid()
  OR NEW.financial_agreement_id IS DISTINCT FROM e.financial_agreement_id
  OR NEW.journey_id IS DISTINCT FROM e.journey_id
  OR NOT isfinite(NEW.opened_at)
  OR EXISTS(SELECT 1 FROM private.funded_no_travel_closures WHERE alignment_id=a.id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact authenticated pre-start dispute required'; END IF;
 RETURN NEW;
END;

DECLARE a public.alignments%ROWTYPE; r private.funded_no_travel_requests%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='funded_no_travel_declines' THEN
  SELECT * INTO STRICT r FROM private.funded_no_travel_requests WHERE id=NEW.request_id;
  SELECT * INTO STRICT a FROM public.alignments WHERE id=r.alignment_id;
 ELSE SELECT * INTO STRICT a FROM public.alignments WHERE id=NEW.alignment_id; END IF;
 IF auth.uid() IS NULL OR auth.uid() NOT IN(a.offering_member_id,a.member_needing_movement_id)
  OR a.status<>'activated' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact principal pre-start action required'; END IF;
 IF EXISTS(SELECT 1 FROM private.funded_no_travel_holds WHERE alignment_id=a.id)
  OR TG_TABLE_NAME='funded_no_travel_closures' THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='No user release or new intent after held no-travel'; END IF;
 PERFORM private.assert_funded_no_travel(a.id);
 IF TG_TABLE_NAME='funded_no_travel_requests' THEN
  IF NEW.first_principal_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact requesting principal required'; END IF;
 ELSE
  IF TG_TABLE_NAME='funded_no_travel_closures' THEN SELECT * INTO STRICT r FROM private.funded_no_travel_requests WHERE id=NEW.request_id; END IF;
  IF NEW.second_principal_id IS DISTINCT FROM auth.uid() OR r.first_principal_id=auth.uid()
   OR r.alignment_id IS DISTINCT FROM a.id OR EXISTS(SELECT 1 FROM private.funded_no_travel_declines WHERE request_id=r.id) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact distinct confirming principal required'; END IF;
 END IF;
 RETURN NEW;
END;

DECLARE c private.financial_components%ROWTYPE; g private.financial_agreements%ROWTYPE; r private.funded_movement_completions%ROWTYPE; kind text;
BEGIN
 IF NEW.financial_component_id IS NULL THEN RETURN NEW; END IF;
 SELECT x.* INTO STRICT c FROM private.financial_components x WHERE x.id=NEW.financial_component_id;
 SELECT x.* INTO STRICT g FROM private.financial_agreements x WHERE x.id=c.agreement_id;
 -- Unmaterialized legacy agreements retain their existing foundation behavior.
 IF NOT EXISTS(SELECT 1 FROM private.financial_proposals WHERE financial_agreement_id=g.id) THEN RETURN NEW; END IF;
 IF NEW.transaction_kind='movement_hold' THEN RETURN NEW; END IF;
 IF c.component_key='requester_platform_share' AND private.activation_fee_is_finalized(g.id) THEN
  IF auth.uid() IS DISTINCT FROM g.member_needing_movement_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact activation requester required'; END IF;
  PERFORM id FROM private.financial_agreements WHERE id=g.id FOR SHARE;
  PERFORM id FROM public.alignments WHERE id=g.alignment_id FOR UPDATE;
  IF NEW.transaction_kind IS DISTINCT FROM 'requester_platform_charge' OR c.amount_minor<=0
   OR NEW.alignment_id IS DISTINCT FROM g.alignment_id OR NEW.currency IS DISTINCT FROM g.currency
   OR NEW.idempotency_key IS DISTINCT FROM 'requester_platform_charge:'||c.id::text
   OR NEW.provider IS NOT NULL OR NEW.provider_reference IS NOT NULL
   OR NOT EXISTS(SELECT 1 FROM private.funded_activation_fee_finalizations f JOIN private.funded_movement_activations a ON a.financial_agreement_id=f.financial_agreement_id
    JOIN public.alignments lifecycle ON lifecycle.id=a.alignment_id WHERE f.financial_agreement_id=g.id
     AND f.financial_component_id=c.id AND f.finalized_at=NEW.created_at AND a.activated_at=f.finalized_at
     AND lifecycle.status='awaiting_activation_payment' AND lifecycle.activated_at IS NULL) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact activation-backed requester charge required'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.transaction_kind='movement_hold_release' THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='No user release after funded activation';
 END IF;
 IF NEW.transaction_kind NOT IN ('requester_platform_charge','movement_contribution_settlement','offering_platform_charge') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Unsupported financial component ledger action'; END IF;
 SELECT x.* INTO r FROM private.funded_movement_completions x WHERE x.alignment_id=g.alignment_id;
 kind:=CASE c.component_key WHEN 'requester_platform_share' THEN 'requester_platform_charge'
  WHEN 'movement_contribution' THEN 'movement_contribution_settlement' ELSE 'offering_platform_charge' END;
 IF auth.uid() IS NULL OR NOT (auth.uid()=g.member_needing_movement_id OR
  (r.completion_method='response_timeout' AND auth.uid()=g.offering_member_id)) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact settlement requester required'; END IF;
 IF EXISTS(SELECT 1 FROM private.funded_completion_disputes WHERE alignment_id=g.alignment_id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Completion is under review'; END IF;
 IF r.alignment_id IS NULL OR r.financial_agreement_id IS DISTINCT FROM g.id OR c.amount_minor<=0
  OR NEW.alignment_id IS DISTINCT FROM g.alignment_id OR NEW.currency IS DISTINCT FROM g.currency
  OR NEW.transaction_kind IS DISTINCT FROM kind OR NEW.idempotency_key IS DISTINCT FROM kind||':'||c.id::text
  OR NEW.created_at IS DISTINCT FROM r.completed_at OR NEW.provider IS NOT NULL OR NEW.provider_reference IS NOT NULL THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact completion-backed settlement required'; END IF;
 RETURN NEW;
END;

DECLARE a public.alignments%ROWTYPE; j public.journeys%ROWTYPE; request private.funded_movement_start_requests%ROWTYPE;
BEGIN
 SELECT x.* INTO STRICT a FROM public.alignments x WHERE x.id=NEW.alignment_id;
 j:=private.assert_funded_coordination_entry(a.id);
 IF NEW.journey_id IS DISTINCT FROM j.id OR a.status<>'activated' OR j.status<>'not_started' OR j.started_at IS NOT NULL THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact pre-start graph required'; END IF;
 IF TG_TABLE_NAME='funded_movement_start_requests' THEN
  IF auth.uid() IS DISTINCT FROM a.offering_member_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact offerer required'; END IF;
  IF j.start_requested_at IS NOT NULL OR NOT isfinite(NEW.requested_at)
   OR NOT EXISTS(SELECT 1 FROM private.journey_meeting_points mp WHERE mp.journey_id=j.id AND mp.revision=NEW.meeting_point_revision
    AND mp.place_text=btrim(mp.place_text) AND length(mp.place_text) BETWEEN 1 AND 200 AND mp.place_text ~ '[^[:space:]]') THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact valid meeting point required'; END IF;
 ELSE
  IF auth.uid() IS DISTINCT FROM a.member_needing_movement_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact requester required'; END IF;
  SELECT x.* INTO request FROM private.funded_movement_start_requests x WHERE x.alignment_id=a.id;
  IF request.alignment_id IS NULL OR request.journey_id<>j.id OR NOT isfinite(NEW.started_at) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact offerer request required'; END IF;
 END IF;
 RETURN NEW;
END;

DECLARE a public.alignments%ROWTYPE; r private.funded_no_travel_requests%ROWTYPE; e private.funded_movement_coordination_entries%ROWTYPE; j public.journeys%ROWTYPE;
BEGIN
 SELECT * INTO STRICT a FROM public.alignments WHERE id=NEW.alignment_id;
 a:=private.funded_no_travel_alignment(a.movement_need_id);
 PERFORM m.id FROM public.members m WHERE m.id IN(a.offering_member_id,a.member_needing_movement_id) ORDER BY m.id FOR UPDATE;
 SELECT * INTO STRICT r FROM private.funded_no_travel_requests WHERE id=NEW.request_id;
 SELECT * INTO STRICT e FROM private.funded_movement_coordination_entries WHERE alignment_id=a.id;
 SELECT * INTO STRICT j FROM public.journeys WHERE id=e.journey_id;
 IF NOT EXISTS(SELECT 1 FROM private.funded_movement_activations WHERE financial_agreement_id=NEW.financial_agreement_id AND alignment_id=a.id)
  OR NEW.financial_agreement_id IS DISTINCT FROM e.financial_agreement_id OR NEW.journey_id IS DISTINCT FROM j.id
  OR r.alignment_id IS DISTINCT FROM a.id OR r.financial_agreement_id IS DISTINCT FROM e.financial_agreement_id
  OR r.journey_id IS DISTINCT FROM j.id OR NEW.first_principal_id IS DISTINCT FROM r.first_principal_id
  OR NEW.second_principal_id IS DISTINCT FROM auth.uid() OR r.first_principal_id=auth.uid()
  OR auth.uid() NOT IN(a.offering_member_id,a.member_needing_movement_id)
  OR NEW.requested_at IS DISTINCT FROM r.requested_at OR NOT isfinite(NEW.observed_at)
  OR NEW.pending_start_requested_at IS DISTINCT FROM j.start_requested_at
  OR EXISTS(SELECT 1 FROM private.funded_no_travel_declines WHERE request_id=r.id)
  OR EXISTS(SELECT 1 FROM private.funded_movement_disputes WHERE alignment_id=a.id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact distinct no-travel consent required'; END IF;
 RETURN NEW;
END;

BEGIN
 IF NEW.completed_at IS NOT NULL AND NEW.started_at IS NOT NULL AND NEW.completed_at<NEW.started_at
  AND NOT EXISTS(SELECT 1 FROM private.funded_movement_completions r
   WHERE r.alignment_id=NEW.alignment_id AND r.journey_id=NEW.id AND r.completed_at=NEW.completed_at
    AND isfinite(r.completed_at)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Journey completion requires exact temporal provenance'; END IF;
 RETURN NEW;
END;

BEGIN
  IF OLD.start_requested_at IS NULL AND NEW.start_requested_at IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM private.journey_meeting_points mp WHERE mp.journey_id=NEW.id AND mp.place_text=btrim(mp.place_text) AND length(mp.place_text) BETWEEN 1 AND 200 AND mp.place_text ~ '[^[:space:]]'
  ) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Meeting point required'; END IF;
  RETURN NEW;
END;

DECLARE
  s private.movement_location_references%ROWTYPE;
  r private.movement_location_selection_receipts%ROWTYPE;
  a private.movement_location_selection_attestations%ROWTYPE;
BEGIN
  IF current_setting('transaction_isolation')<>'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000', MESSAGE='Verified selection requires READ COMMITTED';
  END IF;
  -- Same denial for missing and foreign sources. Lock source before evidence,
  -- consistent with 0026; receipt and attestation are immutable.
  SELECT l.* INTO s FROM private.movement_location_references l
  WHERE l.id=p_source_location_reference_id AND l.owner_member_id=p_verified_member_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Verified selected location unavailable';
  END IF;
  SELECT x.* INTO r FROM private.movement_location_selection_receipts x WHERE x.location_reference_id=s.id;
  SELECT x.* INTO a FROM private.movement_location_selection_attestations x WHERE x.selection_request_id=r.request_id;
  IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM public.members m WHERE m.id=p_verified_member_id)
    OR s.source_kind IS DISTINCT FROM 'member_selected' OR s.resolution_status IS DISTINCT FROM 'unresolved'
    OR s.latitude IS NOT NULL OR s.longitude IS NOT NULL OR s.resolved_at IS NOT NULL OR s.resolution_version IS NOT NULL
    OR s.provider_namespace IS NULL OR s.provider_place_reference IS NULL
    OR a.verified_at IS DISTINCT FROM r.recorded_at OR a.verified_at IS DISTINCT FROM s.created_at
    OR (s.expires_at IS NOT NULL AND s.expires_at<=clock_timestamp()) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Verified selected location unavailable';
  END IF;
  PERFORM private.assert_movement_location_selection_receipt(r.request_id);
  -- Proof validity is checked at acceptance, not at recovery/resolution time.
  RETURN s;
END;

DECLARE selected uuid; g private.financial_agreements%ROWTYPE; a public.alignments%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='wallet_postings' THEN SELECT alignment_id INTO selected FROM private.wallet_transactions WHERE id=NEW.transaction_id;
 ELSE selected:=NEW.alignment_id; END IF;
 SELECT x.* INTO g FROM private.financial_agreements x JOIN private.funded_movement_activations f ON f.financial_agreement_id=x.id WHERE f.alignment_id=selected;
 IF g.id IS NOT NULL THEN SELECT * INTO STRICT a FROM public.alignments WHERE id=selected; PERFORM private.assert_funded_activation(g,a); END IF;
 RETURN NULL;
END;

DECLARE a public.alignments%ROWTYPE; stamp timestamptz;
BEGIN
 PERFORM private.assert_funded_coordination_entry(NEW.alignment_id);
 SELECT x.* INTO STRICT a FROM public.alignments x WHERE x.id=NEW.alignment_id;
 SELECT r.completed_at INTO STRICT stamp FROM private.funded_movement_completions r WHERE r.alignment_id=a.id;
 IF NEW.completed_at IS DISTINCT FROM stamp OR NEW.member_id IS DISTINCT FROM
  (CASE NEW.person_role WHEN 'offering_member' THEN a.offering_member_id WHEN 'primary_requester' THEN a.member_needing_movement_id END) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact completed principal required'; END IF;
 RETURN NEW;
END;

DECLARE a public.alignments%ROWTYPE; need uuid; completed timestamptz;
BEGIN
 SELECT x.movement_need_id INTO STRICT need FROM public.alignments x WHERE x.id=NEW.alignment_id;
 a:=private.completed_movement_rating_alignment(need);
 SELECT r.completed_at INTO STRICT completed FROM private.funded_movement_completions r WHERE r.alignment_id=a.id;
 IF NEW.reviewer_member_id IS DISTINCT FROM auth.uid()
  OR NEW.reviewed_member_id IS DISTINCT FROM (CASE WHEN auth.uid()=a.offering_member_id THEN a.member_needing_movement_id ELSE a.offering_member_id END)
  OR NOT isfinite(NEW.submitted_at) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact historical rating required'; END IF;
 RETURN NEW;
END;

DECLARE agreement_id_to_check uuid; a private.financial_agreements%ROWTYPE;
  alignment_offering uuid; alignment_requester uuid;
  component_count bigint; offering_share bigint; requester_share bigint;
BEGIN
  IF TG_TABLE_NAME='financial_agreements' THEN agreement_id_to_check:=NEW.id;
  ELSE agreement_id_to_check:=NEW.agreement_id; END IF;
  SELECT * INTO STRICT a FROM private.financial_agreements
    WHERE id=agreement_id_to_check FOR UPDATE;
  -- These are the authoritative alignment bindings, already immutable under
  -- 0016. Do not infer principals again from a potentially changed offer/roster.
  SELECT x.offering_member_id,x.member_needing_movement_id
    INTO STRICT alignment_offering,alignment_requester
    FROM public.alignments x WHERE x.id=a.alignment_id FOR SHARE;
  IF a.offering_member_id IS DISTINCT FROM alignment_offering
    OR a.member_needing_movement_id IS DISTINCT FROM alignment_requester THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial principals must match alignment';
  END IF;
  SELECT count(*),
    max(c.amount_minor) FILTER (WHERE c.component_key='offering_platform_share'),
    max(c.amount_minor) FILTER (WHERE c.component_key='requester_platform_share')
    INTO component_count,offering_share,requester_share
    FROM private.financial_components c WHERE c.agreement_id=a.id;
  -- Key CHECK + UNIQUE + count=3 also prove every required key is present.
  -- Apply to superseded versions too: supersession cannot hide incomplete data.
  IF component_count<>3 THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial agreement requires exactly three components';
  END IF;
  IF EXISTS (
    SELECT 1 FROM private.financial_components c WHERE c.agreement_id=a.id AND (
      c.responsible_member_id IS DISTINCT FROM CASE WHEN c.component_key='offering_platform_share'
        THEN a.offering_member_id ELSE a.member_needing_movement_id END
      OR (c.component_key='movement_contribution' AND c.beneficiary_member_id IS DISTINCT FROM a.offering_member_id)
    )
  ) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial component parties must match agreement';
  END IF;
  -- Nonnegative bigint division is floor. The second comparison assigns the
  -- remainder and proves the sum without overflowing on malformed input.
  IF offering_share IS DISTINCT FROM a.quoted_platform_fee_total_minor / 2
    OR requester_share IS DISTINCT FROM a.quoted_platform_fee_total_minor - a.quoted_platform_fee_total_minor / 2 THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Platform shares must follow requester-remainder allocation';
  END IF;
  RETURN NULL;
END;

DECLARE proposal_to_check uuid; p private.financial_proposals%ROWTYPE;
  o public.movement_offers%ROWTYPE; a public.alignments%ROWTYPE;
  g private.financial_agreements%ROWTYPE;
BEGIN
  IF TG_TABLE_NAME='financial_proposal_travellers' THEN proposal_to_check:=NEW.proposal_id;
  ELSE
    IF TG_OP='UPDATE' THEN
      IF (to_jsonb(NEW)-'status') IS NOT DISTINCT FROM (to_jsonb(OLD)-'status') THEN RETURN NULL; END IF;
    END IF;
    proposal_to_check:=NEW.id;
  END IF;
  PERFORM private.assert_financial_proposal_context(proposal_to_check);
  SELECT * INTO STRICT p FROM private.financial_proposals WHERE id=proposal_to_check;
  IF (p.offering_accepted_at IS NOT NULL OR p.requester_accepted_at IS NOT NULL OR p.movement_offer_id IS NOT NULL)
    AND p.expires_at IS NOT NULL AND p.expires_at<=clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal expired before deferred validation';
  END IF;
  IF p.alignment_id IS NULL AND (
    NOT EXISTS (SELECT 1 FROM public.movement_needs n WHERE n.id=p.movement_need_id AND n.status='discoverable')
    OR EXISTS (
  SELECT 1
  FROM public.alignments existing_alignment
  WHERE existing_alignment.movement_need_id = p.movement_need_id
    AND existing_alignment.status IN (
      'awaiting_activation_payment',
      'activated',
      'in_progress',
      'completed'
    )
)
  ) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Unmaterialized proposal requires an available movement need';
  END IF;
  IF p.movement_offer_id IS NULL THEN
    IF p.offering_accepted_at IS NOT NULL
      OR p.requester_accepted_at IS NOT NULL
      OR p.alignment_id IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal consent requires its bound movement offer';
    END IF;
  ELSE
    IF p.offering_accepted_at IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Bound movement offer requires offering-member acceptance';
    END IF;

    SELECT * INTO STRICT o
    FROM public.movement_offers
    WHERE id=p.movement_offer_id
    FOR SHARE;

    IF ROW(o.movement_need_id,o.offering_member_id,o.vehicle_id,o.seats_offered,
        o.proposed_pickup_area,o.proposed_dropoff_area,o.estimated_arrival_minutes)
      IS DISTINCT FROM ROW(p.movement_need_id,p.offering_member_id,p.vehicle_id,p.seats_offered,
        p.proposed_pickup_area,p.proposed_dropoff_area,p.estimated_arrival_minutes) THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal offer binding does not match';
    END IF;

    IF p.alignment_id IS NULL AND o.status <> 'pending' THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Unmaterialized proposal requires a pending bound offer';
    END IF;

    IF p.alignment_id IS NOT NULL AND o.status <> 'accepted' THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Materialized proposal requires an accepted bound offer';
    END IF;
  END IF;

  IF p.requester_accepted_at IS NULL AND p.alignment_id IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Materialization requires requester acceptance';
  END IF;

  IF p.requester_accepted_at IS NOT NULL AND p.alignment_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Requester acceptance must materialize in the same transaction';
  END IF;

  IF p.alignment_id IS NOT NULL THEN
    SELECT * INTO STRICT a FROM public.alignments WHERE id=p.alignment_id FOR SHARE;
    SELECT * INTO STRICT g FROM private.financial_agreements WHERE id=p.financial_agreement_id FOR SHARE;
    IF a.status<>'awaiting_activation_payment' OR g.status<>'current'
      OR ROW(a.movement_need_id,a.movement_offer_id,a.offering_member_id,a.member_needing_movement_id)
      IS DISTINCT FROM ROW(p.movement_need_id,p.movement_offer_id,p.offering_member_id,p.member_needing_movement_id)
      OR ROW(g.alignment_id,g.offering_member_id,g.member_needing_movement_id,g.financial_model_version,
        g.pricing_policy_version,g.platform_fee_allocation_policy_version,g.currency,g.quoted_platform_fee_total_minor,
        g.offering_accepted_at,g.requester_accepted_at)
      IS DISTINCT FROM ROW(p.alignment_id,p.offering_member_id,p.member_needing_movement_id,p.financial_model_version,
        p.pricing_policy_version,p.platform_fee_allocation_policy_version,p.currency,p.quoted_platform_fee_total_minor,
        p.offering_accepted_at,p.requester_accepted_at)
      OR NOT EXISTS (SELECT 1 FROM private.financial_components c
        WHERE c.agreement_id=g.id AND c.component_key='movement_contribution'
          AND c.amount_minor=p.quoted_movement_contribution_minor) THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Proposal materialization does not match';
    END IF;
  END IF;
  RETURN NULL;
END;

