DECLARE caller uuid := auth.uid(); need_id uuid;
BEGIN
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000', MESSAGE='Movement offer acceptance requires READ COMMITTED';
  END IF;
  IF caller IS NULL OR NOT EXISTS (SELECT 1 FROM public.members m WHERE m.id=caller) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Authenticated member required';
  END IF;
  SELECT o.movement_need_id INTO need_id FROM public.movement_offers o WHERE o.id=p_movement_offer_id;
  PERFORM n.id FROM public.movement_needs n WHERE n.id=need_id AND n.member_id=caller FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Own movement need required';
  END IF;
  -- Fresh query AFTER the need wait sees concurrent committed issuance. No
  -- proposal locks here; future financial writers retain the 0074 order.
  IF EXISTS (SELECT 1 FROM private.financial_proposals p WHERE p.movement_need_id=need_id) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Financial proposal sequence requires financial requester materialization';
  END IF;
  RETURN QUERY SELECT * FROM private.accept_movement_offer_legacy_internal(p_movement_offer_id);
END;

DECLARE
  caller uuid := auth.uid();
  p private.financial_proposals%ROWTYPE;
  s private.movement_context_snapshots%ROWTYPE;
  accepted_at timestamptz;
BEGIN
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000', MESSAGE='Financial proposal consent requires READ COMMITTED';
  END IF;
  IF p_financial_proposal_id IS NULL OR p_expected_proposal_version IS NULL OR p_movement_offer_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='Complete exact proposal and offer identities required';
  END IF;
  IF p_expected_proposal_version<1 THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Positive expected proposal version required';
  END IF;
  IF caller IS NULL OR NOT EXISTS (SELECT 1 FROM public.members m WHERE m.id=caller) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Authenticated member required';
  END IF;
  -- Discover immutable selectors only; reject foreign principals/offers before
  -- locking another movement need. Never lock proposal history first.
  SELECT x.* INTO p FROM private.financial_proposals x WHERE x.id=p_financial_proposal_id;
  IF NOT FOUND OR p.offering_member_id IS DISTINCT FROM caller THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Own financial proposal required';
  END IF;
  IF p.version IS DISTINCT FROM p_expected_proposal_version OR p.status<>'current'
    OR p.expires_at IS NULL OR p.expires_at<=clock_timestamp()
    OR p.requester_accepted_at IS NOT NULL OR p.alignment_id IS NOT NULL
    OR p.financial_agreement_id IS NOT NULL OR p.materialized_at IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Exact current unmaterialized proposal required';
  END IF;
  SELECT x.* INTO STRICT s FROM private.movement_context_snapshots x WHERE x.id=p.movement_context_snapshot_id;
  IF s.movement_offer_id IS DISTINCT FROM p_movement_offer_id THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Proposal operational offer must equal its historical snapshot source';
  END IF;
  PERFORM private.assert_financial_proposal_quote_binding(p);
  PERFORM private.assert_financial_proposal_movement_context_binding(p);
  PERFORM private.assert_financial_proposal_source_compatibility(p);

  -- Same strong-dependency order as 0074/0045: need UPDATE -> offer UPDATE ->
  -- requester endpoints -> intent UPDATE -> route -> availability UPDATE ->
  -- vehicle/access -> quote SHARE -> snapshot SHARE -> proposal history UPDATE.
  PERFORM private.assert_movement_offer_availability_binding(s.movement_offer_id);
  PERFORM private.assert_pricing_quote(p.pricing_quote_id);
  PERFORM private.assert_movement_context_snapshot_offer_binding(s);
  PERFORM private.assert_movement_context_snapshot(s.id);
  PERFORM x.id FROM private.financial_proposals x
    WHERE x.movement_need_id=p.movement_need_id AND x.offering_member_id=p.offering_member_id
    ORDER BY x.version FOR UPDATE;

  -- READ COMMITTED fresh reads after every possible blocking dependency/history
  -- wait. Existing immutable selectors cannot change; live sources can expire.
  SELECT x.* INTO STRICT p FROM private.financial_proposals x WHERE x.id=p_financial_proposal_id;
  SELECT x.* INTO STRICT s FROM private.movement_context_snapshots x WHERE x.id=p.movement_context_snapshot_id;
  IF p.offering_member_id IS DISTINCT FROM caller OR p.version IS DISTINCT FROM p_expected_proposal_version
    OR p.status<>'current' OR p.expires_at IS NULL OR NOT isfinite(p.expires_at)
    OR p.expires_at<=clock_timestamp()
    OR p.requester_accepted_at IS NOT NULL OR p.alignment_id IS NOT NULL
    OR p.financial_agreement_id IS NOT NULL OR p.materialized_at IS NOT NULL
    OR s.movement_offer_id IS DISTINCT FROM p_movement_offer_id
    OR (p.movement_offer_id IS NOT NULL AND p.movement_offer_id IS DISTINCT FROM p_movement_offer_id)
    OR (p.offering_accepted_at IS NULL) IS DISTINCT FROM (p.movement_offer_id IS NULL) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Exact current unmaterialized proposal required';
  END IF;
  PERFORM private.assert_movement_offer_availability_binding(s.movement_offer_id);
  PERFORM private.assert_pricing_quote(p.pricing_quote_id);
  PERFORM private.assert_movement_context_snapshot_offer_binding(s);
  PERFORM private.assert_movement_context_snapshot(s.id);
  PERFORM private.assert_financial_proposal_quote_binding(p);
  PERFORM private.assert_financial_proposal_movement_context_binding(p);
  PERFORM private.assert_financial_proposal_source_compatibility(p);
  PERFORM private.assert_financial_proposal_context(p.id);
  PERFORM private.assert_financial_proposal_snapshot_roster(p.id);
  IF NOT EXISTS (SELECT 1 FROM public.movement_needs n WHERE n.id=p.movement_need_id AND n.status='discoverable')
    OR EXISTS (SELECT 1 FROM public.alignments a WHERE a.movement_need_id=p.movement_need_id
      AND a.status IN ('awaiting_activation_payment','activated','in_progress','completed')) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Unmaterialized proposal requires an available movement need';
  END IF;
  accepted_at:=clock_timestamp();
  IF accepted_at>=p.expires_at THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Proposal expired before consent';
  END IF;
  IF p.offering_accepted_at IS NOT NULL THEN
    IF NOT isfinite(p.offering_accepted_at)
      OR p.offering_accepted_at>=p.expires_at THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Invalid existing offering consent';
    END IF;
    RETURN QUERY SELECT p.id,p.version,p.status,p.movement_offer_id,p.offering_accepted_at;
    RETURN;
  END IF;

  -- One UPDATE supplies both fields: no intermediate incomplete consent state,
  -- even when the caller already has completeness constraints IMMEDIATE.
  UPDATE private.financial_proposals x
    SET movement_offer_id=p_movement_offer_id, offering_accepted_at=accepted_at
    WHERE x.id=p.id RETURNING x.* INTO p;
  -- Drain only the two parent UPDATE checks, then restore the established
  -- producer convention (INITIALLY DEFERRED). Errors roll back the whole call.
  SET CONSTRAINTS private.financial_proposal_complete,private.financial_proposal_movement_context_complete IMMEDIATE;
  SET CONSTRAINTS private.financial_proposal_complete,private.financial_proposal_movement_context_complete DEFERRED;
  RETURN QUERY SELECT p.id,p.version,p.status,p.movement_offer_id,p.offering_accepted_at;
END;

DECLARE caller uuid:=auth.uid(); p private.financial_proposals%ROWTYPE;
  s private.movement_context_snapshots%ROWTYPE; n public.movement_needs%ROWTYPE;
  operational record; replay_alignment_status text; created_agreement_id uuid; agreement_version bigint; accepted_at timestamptz; completed_at timestamptz;
BEGIN
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000', MESSAGE='Financial materialization requires READ COMMITTED';
  END IF;
  IF p_financial_proposal_id IS NULL OR p_expected_proposal_version IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='Exact proposal identity and version required';
  END IF;
  IF p_expected_proposal_version<1 THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Positive expected proposal version required';
  END IF;
  IF caller IS NULL OR NOT EXISTS (SELECT 1 FROM public.members m WHERE m.id=caller) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Authenticated member required';
  END IF;
  -- Immutable discovery only; no history/FK locks before the need boundary.
  SELECT x.* INTO p FROM private.financial_proposals x WHERE x.id=p_financial_proposal_id;
  IF NOT FOUND OR p.member_needing_movement_id IS DISTINCT FROM caller THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Own requester financial proposal required';
  END IF;
  PERFORM private.assert_financial_proposal_quote_binding(p);
  PERFORM private.assert_financial_proposal_movement_context_binding(p);
  PERFORM private.assert_financial_proposal_source_compatibility(p);
  SELECT x.* INTO STRICT s FROM private.movement_context_snapshots x WHERE x.id=p.movement_context_snapshot_id;
  -- Isolate construction locks. If another requester finishes while our need
  -- lock waits, roll this subtransaction back before entering historical replay.
  -- Payment/face readiness locks alignment BEFORE need; retaining construction's
  -- need lock while waiting for that alignment would create a reverse-order cycle.
  BEGIN
  IF p.requester_accepted_at IS NOT NULL OR p.alignment_id IS NOT NULL
    OR p.financial_agreement_id IS NOT NULL OR p.materialized_at IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='Z7701', MESSAGE='Switch to materialization replay';
  END IF;
  SELECT x.* INTO STRICT n FROM public.movement_needs x WHERE x.id=p.movement_need_id FOR UPDATE;
  IF n.member_id IS DISTINCT FROM caller THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Authoritative movement requester required';
  END IF;
  -- A concurrent duplicate can have completed while the need lock waited.
  -- Fresh-read BEFORE pending-offer/availability assertions: replay must not
  -- reserve capacity again or validate consumed support as a pending offer.
  SELECT x.* INTO STRICT p FROM private.financial_proposals x WHERE x.id=p_financial_proposal_id;
  IF p.requester_accepted_at IS NOT NULL OR p.alignment_id IS NOT NULL
    OR p.financial_agreement_id IS NOT NULL OR p.materialized_at IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='Z7701', MESSAGE='Switch to materialization replay';
  END IF;
  IF p.member_needing_movement_id IS DISTINCT FROM caller OR p.version IS DISTINCT FROM p_expected_proposal_version
    OR p.status<>'current' OR p.expires_at IS NULL OR NOT isfinite(p.expires_at)
    OR p.expires_at<=clock_timestamp()
    OR p.offering_accepted_at IS NULL OR p.movement_offer_id IS NULL
    OR p.movement_offer_id IS DISTINCT FROM s.movement_offer_id THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Exact current offerer-consented proposal required';
  END IF;


  IF n.status<>'discoverable' OR EXISTS (SELECT 1 FROM public.alignments a
    WHERE a.movement_need_id=n.id AND a.status IN ('awaiting_activation_payment','activated','in_progress','completed')) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Unmaterialized proposal requires an available movement need';
  END IF;
  PERFORM x.id FROM public.movement_offers x WHERE x.id=s.movement_offer_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Exact movement offer unavailable';
  END IF;

  -- Same canonical strong dependencies as 0074/0076 before proposal history:
  -- need UPDATE -> offer UPDATE -> endpoints -> intent UPDATE -> route ->
  -- availability UPDATE -> vehicle/access -> quote SHARE -> snapshot SHARE.
  PERFORM private.assert_movement_offer_availability_binding(s.movement_offer_id);
  PERFORM private.assert_pricing_quote(p.pricing_quote_id);
  PERFORM private.assert_movement_context_snapshot_offer_binding(s);
  PERFORM private.assert_movement_context_snapshot(s.id);
  PERFORM x.id FROM private.financial_proposals x
    WHERE x.movement_need_id=p.movement_need_id AND x.offering_member_id=p.offering_member_id
    ORDER BY x.version FOR UPDATE;
  SELECT x.* INTO STRICT p FROM private.financial_proposals x WHERE x.id=p_financial_proposal_id;
  SELECT x.* INTO STRICT s FROM private.movement_context_snapshots x WHERE x.id=p.movement_context_snapshot_id;
  SELECT x.* INTO STRICT n FROM public.movement_needs x WHERE x.id=p.movement_need_id;
  IF p.version IS DISTINCT FROM p_expected_proposal_version OR p.status<>'current'
    OR p.member_needing_movement_id IS DISTINCT FROM caller OR n.member_id IS DISTINCT FROM caller
    OR p.expires_at<=clock_timestamp()
    OR p.offering_accepted_at IS NULL OR NOT isfinite(p.offering_accepted_at)
    OR p.offering_accepted_at>=p.expires_at OR p.movement_offer_id IS DISTINCT FROM s.movement_offer_id
    OR p.requester_accepted_at IS NOT NULL OR p.alignment_id IS NOT NULL
    OR p.financial_agreement_id IS NOT NULL OR p.materialized_at IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Exact unmaterialized offerer-consented proposal required';
  END IF;
  PERFORM private.assert_movement_offer_availability_binding(p.movement_offer_id);
  PERFORM private.assert_pricing_quote(p.pricing_quote_id);
  PERFORM private.assert_movement_context_snapshot_offer_binding(s);
  PERFORM private.assert_movement_context_snapshot(s.id);
  PERFORM private.assert_financial_proposal_quote_binding(p);
  PERFORM private.assert_financial_proposal_movement_context_binding(p);
  PERFORM private.assert_financial_proposal_source_compatibility(p);
  PERFORM private.assert_financial_proposal_context(p.id);
  PERFORM private.assert_financial_proposal_snapshot_roster(p.id);
  accepted_at:=clock_timestamp();
  IF accepted_at>=p.expires_at THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Proposal expired before requester acceptance';
  END IF;
  -- If trusted snapshot construction happened earlier in this transaction,
  -- drain its INSERT checks while the offer/need are still pending/available.
  -- Those construction-only validators cannot be deferred past consumption.
  SET CONSTRAINTS private.movement_context_snapshot_complete,private.movement_context_travellers_complete IMMEDIATE;
  SET CONSTRAINTS private.movement_context_snapshot_complete,private.movement_context_travellers_complete DEFERRED;

  -- Reuse 0045 exactly, under already-owned stronger dependencies/history.
  -- It asserts live eligibility again and atomically consumes people_count,
  -- creates the pre-payment alignment, accepts/closes/rejects operational rows.
  -- No proposal row is written until the complete financial graph exists.
  SELECT x.* INTO STRICT operational FROM private.accept_movement_offer_legacy_internal(p.movement_offer_id) x;
  IF operational.movement_offer_id IS DISTINCT FROM p.movement_offer_id
    OR operational.movement_need_id IS DISTINCT FROM p.movement_need_id
    OR operational.alignment_status IS DISTINCT FROM 'awaiting_activation_payment' THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Operational materialization identity mismatch';
  END IF;
  -- Construction alone must prove the exact initial legacy alignment shape.
  PERFORM x.id FROM public.alignments x WHERE x.id=operational.alignment_id
    AND x.status='awaiting_activation_payment' AND x.activated_at IS NULL
    AND x.activation_fee_minor IS NULL AND x.activation_currency='NGN'
    AND ROW(x.movement_need_id,x.movement_offer_id,x.offering_member_id,x.member_needing_movement_id)
      IS NOT DISTINCT FROM ROW(p.movement_need_id,p.movement_offer_id,p.offering_member_id,p.member_needing_movement_id);
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Exact initial pre-payment alignment required';
  END IF;
  -- New alignment is transaction-owned, with no prior agreement history. The
  -- 0020 history scope is alignment_id, NOT proposal history's version scope.
  SELECT coalesce(max(x.version)::bigint,0)+1 INTO agreement_version
    FROM private.financial_agreements x WHERE x.alignment_id=operational.alignment_id;
  IF agreement_version<>1 THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='New alignment must have empty agreement history';
  END IF;
  SET CONSTRAINTS private.financial_agreement_complete,private.financial_components_complete DEFERRED;
  INSERT INTO private.financial_agreements(alignment_id,offering_member_id,member_needing_movement_id,version,
    financial_model_version,pricing_policy_version,platform_fee_allocation_policy_version,currency,
    quoted_platform_fee_total_minor,created_at,status)
  VALUES(operational.alignment_id,p.offering_member_id,p.member_needing_movement_id,agreement_version::integer,
    p.financial_model_version,p.pricing_policy_version,p.platform_fee_allocation_policy_version,p.currency,
    p.quoted_platform_fee_total_minor,clock_timestamp(),'current') RETURNING id INTO created_agreement_id;
  INSERT INTO private.financial_components(agreement_id,component_key,amount_minor,responsible_member_id,
    beneficiary_kind,beneficiary_member_id,created_at) VALUES
    (created_agreement_id,'offering_platform_share',p.quoted_platform_fee_total_minor/2,p.offering_member_id,'platform',NULL,clock_timestamp()),
    (created_agreement_id,'requester_platform_share',p.quoted_platform_fee_total_minor-p.quoted_platform_fee_total_minor/2,p.member_needing_movement_id,'platform',NULL,clock_timestamp()),
    (created_agreement_id,'movement_contribution',p.quoted_movement_contribution_minor,p.member_needing_movement_id,'member',p.offering_member_id,clock_timestamp());
  UPDATE private.financial_agreements x SET offering_accepted_at=p.offering_accepted_at,requester_accepted_at=accepted_at
    WHERE x.id=created_agreement_id;
  completed_at:=clock_timestamp();
  IF completed_at>=p.expires_at THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Proposal expired during materialization';
  END IF;
  UPDATE private.financial_proposals x SET requester_accepted_at=accepted_at,alignment_id=operational.alignment_id,
    financial_agreement_id=created_agreement_id,materialized_at=completed_at WHERE x.id=p.id RETURNING x.* INTO p;
  PERFORM private.assert_financial_proposal_materialization(p);
  SET CONSTRAINTS private.financial_agreement_complete,private.financial_components_complete,
    private.financial_proposal_complete,private.financial_proposal_movement_context_complete IMMEDIATE;
  SET CONSTRAINTS private.financial_agreement_complete,private.financial_components_complete,
    private.financial_proposal_complete,private.financial_proposal_movement_context_complete DEFERRED;
  RETURN QUERY SELECT p.id,p.version,p.status,p.movement_offer_id,p.alignment_id,
    operational.alignment_status,p.financial_agreement_id,p.requester_accepted_at,p.materialized_at;
  RETURN;
  EXCEPTION WHEN SQLSTATE 'Z7701' THEN
    -- Rollback releases ONLY locks acquired in this construction subtransaction.
    -- No write has happened on either switch path, and all other errors propagate.
    NULL;
  END;

  -- Persisted graph replay: no live need/intent/availability/quote locks and no
  -- mutations. Never upgrade historical locks back into construction support.
  -- Original expiry bounds recorded consent/materialization, not historical reads.
  -- 0021 makes materialized proposals immutable, including their current status.
  SELECT x.* INTO STRICT p FROM private.financial_proposals x WHERE x.id=p_financial_proposal_id FOR UPDATE;
  IF p.member_needing_movement_id IS DISTINCT FROM caller OR p.version IS DISTINCT FROM p_expected_proposal_version
    OR p.status<>'current' OR p.expires_at IS NULL OR NOT isfinite(p.expires_at)

    OR NOT EXISTS(SELECT 1 FROM public.movement_needs replay_need WHERE replay_need.id=p.movement_need_id AND replay_need.member_id=caller) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Own exact materialized proposal required';
  END IF;
  replay_alignment_status:=private.assert_financial_proposal_materialization(p);
  RETURN QUERY SELECT p.id,p.version,p.status,p.movement_offer_id,p.alignment_id,
    replay_alignment_status,p.financial_agreement_id,p.requester_accepted_at,p.materialized_at;
END;

DECLARE g private.financial_agreements%ROWTYPE; a public.alignments%ROWTYPE; evidence record; stamp timestamptz; component private.financial_components%ROWTYPE;
 held_id uuid; revenue_id uuid; account record; balance numeric; held numeric; revenue numeric;
BEGIN
 g:=private.funded_activation_agreement(p_financial_agreement_id,p_expected_agreement_version,true);
 SELECT x.* INTO STRICT a FROM public.alignments x WHERE x.id=g.alignment_id;
 IF EXISTS(SELECT 1 FROM private.funded_movement_activations x WHERE x.financial_agreement_id=g.id) THEN
  PERFORM private.assert_funded_activation(g,a);
  RETURN QUERY SELECT g.id,g.version,a.id,a.status,a.activated_at; RETURN;
 END IF;
 IF g.status<>'current' OR a.status<>'awaiting_activation_payment' OR a.activated_at IS NOT NULL THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Current pre-activation agreement required'; END IF;
 -- Existing gate owns alignment -> need -> every required member in UUID order.
 PERFORM private.assert_alignment_face_ready(a.id);
 SELECT * INTO evidence FROM private.movement_funding_evidence(g);
 IF evidence.fully_held_at IS NULL OR evidence.held_minor<>evidence.required_minor THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Completed exact requester funding required'; END IF;
 -- Capture time AFTER every wait, and check the same authoritative face predicate
 -- at precisely the timestamp to be recorded (not a statement-start timestamp).
 SELECT * INTO STRICT component FROM private.financial_components WHERE agreement_id=g.id AND component_key='requester_platform_share';
 -- Face readiness already owns the sorted required-member gates. All account
 -- locks follow those gates, and no SHARE lock is upgraded.
 PERFORM x.id FROM private.wallet_accounts x WHERE x.member_id=g.member_needing_movement_id AND x.currency=g.currency ORDER BY x.id FOR UPDATE;
 IF (SELECT count(*) FROM private.wallet_accounts WHERE member_id=g.member_needing_movement_id AND currency=g.currency)<>3
  OR EXISTS(SELECT 1 FROM private.wallet_accounts WHERE member_id=g.member_needing_movement_id AND currency=g.currency AND status<>'active') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Complete active activation wallet required'; END IF;
 FOR account IN SELECT * FROM private.wallet_accounts WHERE member_id=g.member_needing_movement_id AND currency=g.currency LOOP
  SELECT coalesce(sum(CASE WHEN direction='credit' THEN amount_minor::numeric ELSE -amount_minor::numeric END),0) INTO balance FROM private.wallet_postings WHERE account_id=account.id;
  IF balance<0 OR balance>9223372036854775807::numeric THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Activation wallet outside supported range'; END IF;
  IF account.account_kind='member_held' THEN held_id:=account.id;held:=balance; END IF;
 END LOOP;
 IF held<evidence.required_minor THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact activation obligations must remain held'; END IF;
 IF component.amount_minor>0 THEN
  INSERT INTO private.wallet_accounts(member_id,account_kind,currency) VALUES(NULL,'platform_revenue',g.currency)
   ON CONFLICT(account_kind,currency) WHERE member_id IS NULL DO NOTHING;
  SELECT id INTO STRICT revenue_id FROM private.wallet_accounts WHERE member_id IS NULL AND currency=g.currency AND account_kind='platform_revenue' FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM private.wallet_accounts WHERE id=revenue_id AND status='active') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Active revenue account required'; END IF;
  SELECT coalesce(sum(CASE WHEN direction='credit' THEN amount_minor::numeric ELSE -amount_minor::numeric END),0) INTO revenue FROM private.wallet_postings WHERE account_id=revenue_id;
  IF revenue<0 OR revenue+component.amount_minor>9223372036854775807::numeric THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Activation revenue outside supported range'; END IF;
 END IF;
 -- The authoritative activation/fee observation follows every construction,
 -- account/provisioning/revenue wait. It is paired metadata, not chronology.
 stamp:=clock_timestamp();
 IF EXISTS(SELECT 1 FROM private.required_face_members(a.id) r
  WHERE NOT private.has_current_alignment_face_check(a.id,r.member_id,stamp)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Fresh face verification required'; END IF;
 WITH activated AS (
  INSERT INTO private.funded_movement_activations VALUES(g.id,a.id,stamp) RETURNING *
 ), faces AS (
  INSERT INTO private.funded_movement_activation_faces AS face(financial_agreement_id,member_id,face_verification_id)
  SELECT e.financial_agreement_id,r.member_id,(SELECT f.id FROM private.alignment_face_verifications f WHERE f.alignment_id=a.id AND f.member_id=r.member_id ORDER BY f.attempt_ordinal DESC LIMIT 1)
   FROM activated e CROSS JOIN LATERAL private.required_face_members(e.alignment_id) r RETURNING face.financial_agreement_id
 ), fee AS (
  INSERT INTO private.funded_activation_fee_finalizations
  SELECT e.financial_agreement_id,e.alignment_id,component.id,g.member_needing_movement_id,component.amount_minor,g.currency,e.activated_at
   FROM activated e WHERE (SELECT count(*) FROM faces)>=0 RETURNING *
 ), charge AS (
  INSERT INTO private.wallet_transactions(transaction_kind,currency,alignment_id,financial_component_id,idempotency_key,created_at)
  SELECT 'requester_platform_charge',f.currency,f.alignment_id,f.financial_component_id,'requester_platform_charge:'||f.financial_component_id::text,f.finalized_at FROM fee f WHERE f.amount_minor>0
  RETURNING id,created_at
 ), postings AS (
  INSERT INTO private.wallet_postings(transaction_id,account_id,direction,amount_minor,created_at)
  SELECT t.id,CASE side.direction WHEN 'debit' THEN held_id ELSE revenue_id END,side.direction,component.amount_minor,t.created_at
   FROM charge t CROSS JOIN (VALUES('debit'::text),('credit'::text)) side(direction) RETURNING id
 ) UPDATE public.alignments x SET status='activated',activated_at=f.finalized_at,updated_at=f.finalized_at
   FROM fee f WHERE x.id=f.alignment_id AND (SELECT count(*) FROM postings)>=0 RETURNING x.* INTO a;
 PERFORM private.assert_funded_activation(g,a);
 RETURN QUERY SELECT g.id,g.version,a.id,a.status,a.activated_at;
END;

DECLARE v_session private.alignment_face_verifications%ROWTYPE; v_now timestamptz;
BEGIN
  SELECT * INTO v_session FROM private.alignment_face_verifications WHERE id=p_session_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Face verification unavailable'; END IF;
  PERFORM 1 FROM public.alignments WHERE id=v_session.alignment_id AND status='awaiting_activation_payment' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Face verification unavailable'; END IF;
  PERFORM 1 FROM public.members WHERE id=v_session.member_id FOR UPDATE;
  SELECT * INTO v_session FROM private.alignment_face_verifications WHERE id=p_session_id FOR UPDATE;
  IF NOT EXISTS (SELECT 1 FROM private.required_face_members(v_session.alignment_id) r WHERE r.member_id=v_session.member_id)
    OR p_matched_media_id IS DISTINCT FROM v_session.media_id
    OR NOT EXISTS (SELECT 1 FROM public.member_media mm
      JOIN private.profile_photo_submissions ps ON ps.media_id=mm.id AND ps.member_id=mm.member_id
        AND ps.status='ready' AND ps.processed_at IS NOT NULL
      WHERE mm.id=v_session.media_id AND mm.member_id=v_session.member_id
        AND mm.media_type='photo' AND mm.is_current FOR SHARE OF ps) THEN
    RAISE EXCEPTION 'Face verification unavailable';
  END IF;
  IF p_liveness_passed IS NULL OR p_face_match_passed IS NULL THEN RAISE EXCEPTION 'Verification result required'; END IF;
  IF v_session.status='succeeded' AND p_liveness_passed AND p_face_match_passed THEN RETURN; END IF;
  IF v_session.status <> 'pending' THEN RAISE EXCEPTION 'Face verification is not pending'; END IF;
  v_now:=clock_timestamp();
  UPDATE private.alignment_face_verifications SET
    status=CASE WHEN expires_at<=v_now THEN 'expired'
      WHEN p_liveness_passed AND p_face_match_passed THEN 'succeeded' ELSE 'failed' END,
    liveness_passed=p_liveness_passed,face_match_passed=p_face_match_passed,completed_at=v_now
  WHERE id=p_session_id;
  IF v_now<v_session.expires_at AND p_liveness_passed AND p_face_match_passed THEN
    UPDATE public.member_media SET verified=true WHERE id=v_session.media_id;
    UPDATE public.members SET profile_media_verified=true WHERE id=v_session.member_id;
  END IF;
END;

DECLARE f private.alignment_face_verifications%ROWTYPE;
BEGIN
  SELECT * INTO f FROM private.alignment_face_verifications s
    WHERE s.provider=p_provider AND s.provider_reference=p_provider_reference;
  IF NOT FOUND THEN RAISE EXCEPTION 'Callback unavailable'; END IF;
  -- Match 0016 lock order; concurrent callbacks serialize before result checks.
  PERFORM 1 FROM public.alignments WHERE id=f.alignment_id FOR UPDATE;
  PERFORM 1 FROM public.members WHERE id=f.member_id FOR UPDATE;
  SELECT * INTO f FROM private.alignment_face_verifications WHERE id=f.id FOR UPDATE;
  IF p_matched_media_id IS DISTINCT FROM f.media_id
    OR p_liveness_passed IS NULL OR p_face_match_passed IS NULL THEN
    RAISE EXCEPTION 'Callback unavailable';
  END IF;
  IF f.status IN ('succeeded','failed') THEN
    IF f.liveness_passed IS DISTINCT FROM p_liveness_passed
      OR f.face_match_passed IS DISTINCT FROM p_face_match_passed THEN
      RAISE EXCEPTION 'Callback unavailable';
    END IF;
    -- Acknowledge the recorded fact, without re-verifying media, extending expiry,
    -- restoring readiness or changing history even after activation/replacement.
    RETURN f.status;
  END IF;
  IF f.status<>'pending' THEN RAISE EXCEPTION 'Callback unavailable'; END IF;
  PERFORM public.complete_alignment_face_verification_for_server(
    f.id,p_matched_media_id,p_liveness_passed,p_face_match_passed);
  SELECT status INTO f.status FROM private.alignment_face_verifications WHERE id=f.id;
  RETURN f.status;
END;

DECLARE
  v_caller_member_id uuid;
  v_journey_record public.journeys%ROWTYPE;
  v_alignment_record public.alignments%ROWTYPE;
  v_returned_completed_at timestamptz;
BEGIN
  IF EXISTS(SELECT 1 FROM public.journeys lifecycle_journey WHERE lifecycle_journey.id=p_journey_id AND private.is_financial_alignment(lifecycle_journey.alignment_id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial coordination lifecycle unavailable'; END IF;
  v_caller_member_id := auth.uid();

  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  -- Load and lock the journey
  SELECT *
  INTO v_journey_record
  FROM public.journeys j
  WHERE j.id = p_journey_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Journey not found';
  END IF;

  -- Load and lock the alignment
  SELECT *
  INTO v_alignment_record
  FROM public.alignments a
  WHERE a.id = v_journey_record.alignment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alignment not found';
  END IF;

  -- Caller must be the primary requester (member_needing_movement_id)
  IF v_alignment_record.member_needing_movement_id <> v_caller_member_id THEN
    RAISE EXCEPTION 'Only the primary requester may confirm journey completion';
  END IF;

  -- Idempotency check: if both already completed, return existing completed_at
  IF v_journey_record.status = 'completed' AND v_alignment_record.status = 'completed' THEN
    v_returned_completed_at := v_journey_record.completed_at;
    RETURN QUERY
    SELECT
      p_journey_id AS journey_id,
      'completed'::text AS journey_status,
      v_returned_completed_at AS completed_at;
    RETURN;
  END IF;

  -- Validate journey state
  IF v_journey_record.status <> 'in_progress' THEN
    RAISE EXCEPTION 'Journey is not in_progress';
  END IF;

  -- Validate alignment state
  IF v_alignment_record.status <> 'in_progress' THEN
    RAISE EXCEPTION 'Alignment is not in_progress';
  END IF;

  -- Validate journey has been started
  IF v_journey_record.started_at IS NULL THEN
    RAISE EXCEPTION 'Journey has not been started';
  END IF;

  -- Validate completion was requested
  IF v_journey_record.completion_requested_at IS NULL THEN
    RAISE EXCEPTION 'Journey completion has not been requested';
  END IF;

  -- Atomically update both journey and alignment
  UPDATE public.journeys j
  SET
    status = 'completed',
    completed_at = NOW(),
    updated_at = NOW()
  WHERE j.id = p_journey_id
  RETURNING j.completed_at
  INTO v_returned_completed_at;

  UPDATE public.alignments a
  SET
    status = 'completed',
    updated_at = NOW()
  WHERE a.id = v_alignment_record.id;

  RETURN QUERY
  SELECT
    p_journey_id AS journey_id,
    'completed'::text AS journey_status,
    v_returned_completed_at AS completed_at;
END;

DECLARE
  v_caller_member_id uuid;
  v_journey_record public.journeys%ROWTYPE;
  v_alignment_record public.alignments%ROWTYPE;
  v_returned_started_at timestamptz;
BEGIN
  IF EXISTS(SELECT 1 FROM public.journeys lifecycle_journey WHERE lifecycle_journey.id=p_journey_id AND private.is_financial_alignment(lifecycle_journey.alignment_id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial coordination lifecycle unavailable'; END IF;
  v_caller_member_id := auth.uid();

  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  -- Load and lock the journey
  SELECT *
  INTO v_journey_record
  FROM public.journeys j
  WHERE j.id = p_journey_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Journey not found';
  END IF;

  -- Load and lock the alignment
  SELECT *
  INTO v_alignment_record
  FROM public.alignments a
  WHERE a.id = v_journey_record.alignment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alignment not found';
  END IF;

  -- Caller must be the primary requester (member_needing_movement_id)
  IF v_alignment_record.member_needing_movement_id <> v_caller_member_id THEN
    RAISE EXCEPTION 'Only the primary requester may confirm journey start';
  END IF;

  -- Idempotency check: if both already in_progress, return existing started_at
  IF v_journey_record.status = 'in_progress' AND v_alignment_record.status = 'in_progress' THEN
    v_returned_started_at := v_journey_record.started_at;
    RETURN QUERY
    SELECT
      p_journey_id AS journey_id,
      'in_progress'::text AS journey_status,
      v_returned_started_at AS started_at;
    RETURN;
  END IF;

  -- Validate journey state
  IF v_journey_record.status <> 'not_started' THEN
    RAISE EXCEPTION 'Journey is not in not_started state';
  END IF;

  -- Validate start was requested
  IF v_journey_record.start_requested_at IS NULL THEN
    RAISE EXCEPTION 'Journey start has not been requested';
  END IF;

  -- Validate alignment state
  IF v_alignment_record.status <> 'activated' THEN
    RAISE EXCEPTION 'Alignment is not activated';
  END IF;

  -- Atomically update both journey and alignment
  UPDATE public.journeys j
  SET
    status = 'in_progress',
    started_at = NOW(),
    updated_at = NOW()
  WHERE j.id = p_journey_id
  RETURNING j.started_at
  INTO v_returned_started_at;

  UPDATE public.alignments a
  SET
    status = 'in_progress',
    updated_at = NOW()
  WHERE a.id = v_alignment_record.id;

  RETURN QUERY
  SELECT
    p_journey_id AS journey_id,
    'in_progress'::text AS journey_status,
    v_returned_started_at AS started_at;
END;

DECLARE
  v_caller_member_id uuid;
  v_journey_record public.journeys%ROWTYPE;
  v_alignment_record public.alignments%ROWTYPE;
  v_offering_member_id uuid;
  v_requester_member_id uuid;
  v_settlement_exists boolean;
BEGIN
  IF EXISTS(SELECT 1 FROM public.journeys lifecycle_journey WHERE lifecycle_journey.id=p_journey_id AND private.is_financial_alignment(lifecycle_journey.alignment_id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial coordination lifecycle unavailable'; END IF;
  v_caller_member_id := auth.uid();

  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  -- Load and lock the journey
  SELECT *
  INTO v_journey_record
  FROM public.journeys j
  WHERE j.id = p_journey_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Journey not found';
  END IF;

  -- Load and lock the alignment
  SELECT *
  INTO v_alignment_record
  FROM public.alignments a
  WHERE a.id = v_journey_record.alignment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alignment not found';
  END IF;

  v_offering_member_id := v_alignment_record.offering_member_id;
  v_requester_member_id := v_alignment_record.member_needing_movement_id;

  -- Caller must be one of the principal members
  IF v_caller_member_id <> v_offering_member_id AND v_caller_member_id <> v_requester_member_id THEN
    RAISE EXCEPTION 'Only principal movement members may confirm movement end';
  END IF;

  -- Terminal retries cannot create another consent or settlement.
  IF v_journey_record.status='cancelled' AND v_alignment_record.status='cancelled'
    AND EXISTS (SELECT 1 FROM private.mutual_no_travel_closures c WHERE c.journey_id=p_journey_id) THEN
    RETURN QUERY SELECT p_journey_id, 'cancelled'::text, 'cancelled'::text, 'mutual_no_travel'::text, NULL::timestamptz, false::boolean;
    RETURN;
  END IF;
  -- Idempotency: if both already completed, return safely
  IF v_journey_record.status = 'completed' AND v_alignment_record.status = 'completed' THEN
    -- Verify settlement exists
    SELECT EXISTS(
      SELECT 1
      FROM private.movement_settlements ms
      WHERE ms.journey_id = p_journey_id
    ) INTO v_settlement_exists;

    RETURN QUERY
    SELECT
      p_journey_id,
      v_journey_record.status,
      v_alignment_record.status,
      'completed'::text,
      v_journey_record.completed_at,
      v_settlement_exists;
    RETURN;
  END IF;

  -- Must have a pending end request
  IF v_journey_record.end_requested_by_member_id IS NULL THEN
    RAISE EXCEPTION 'No pending end request to confirm';
  END IF;

  -- Caller cannot confirm their own request
  IF v_journey_record.end_requested_by_member_id = v_caller_member_id THEN
    RAISE EXCEPTION 'You cannot confirm your own end request';
  END IF;

  -- Validate state: must be in a valid ending state
  IF NOT (
    (v_alignment_record.status = 'activated' AND v_journey_record.status = 'not_started')
    OR
    (v_alignment_record.status = 'in_progress' AND v_journey_record.status = 'in_progress')
  ) THEN
    RAISE EXCEPTION 'Movement is not in a state that allows mutual ending';
  END IF;

  -- Both rows are locked in journey-then-alignment order. A request is not a start.
  IF v_alignment_record.status='activated' AND v_journey_record.status='not_started' THEN
    PERFORM private.close_mutual_no_travel(p_journey_id);
    RETURN QUERY SELECT p_journey_id, 'cancelled'::text, 'cancelled'::text, 'mutual_no_travel'::text, NULL::timestamptz, false::boolean;
    RETURN;
  END IF;
  -- Confirm the end request
  UPDATE public.journeys j
  SET
    end_confirmed_by_member_id = v_caller_member_id,
    end_confirmed_at = NOW(),
    status = 'completed',
    completed_at = COALESCE(j.completed_at, NOW()),
    end_method = 'mutual_user_end',
    updated_at = NOW()
  WHERE j.id = p_journey_id;

  UPDATE public.alignments a
  SET
    status = 'completed',
    updated_at = NOW()
  WHERE a.id = v_alignment_record.id;

  -- Create settlement entitlement
  INSERT INTO private.movement_settlements (
    alignment_id,
    journey_id,
    beneficiary_member_id,
    status,
    created_at
  )
  VALUES (
    v_alignment_record.id,
    p_journey_id,
    v_offering_member_id,
    'pending_amount',
    NOW()
  )
  ON CONFLICT (alignment_id) DO NOTHING;

  -- Check if settlement was created
  SELECT EXISTS(
    SELECT 1
    FROM private.movement_settlements ms
    WHERE ms.journey_id = p_journey_id
  ) INTO v_settlement_exists;

  -- Reload both records for return
  SELECT *
  INTO v_journey_record
  FROM public.journeys j
  WHERE j.id = p_journey_id;

  SELECT *
  INTO v_alignment_record
  FROM public.alignments a
  WHERE a.id = v_alignment_record.id;

  RETURN QUERY
  SELECT
    p_journey_id,
    v_journey_record.status,
    v_alignment_record.status,
    'completed'::text,
    v_journey_record.completed_at,
    v_settlement_exists;
END;

BEGIN
 PERFORM private.finalize_funded_completion(p_movement_need_id,'requester_confirmed');
 RETURN QUERY SELECT * FROM public.get_my_funded_movement_completion_status(p_movement_need_id);
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING ERRCODE=SQLSTATE,MESSAGE='Movement completion unavailable';
END;

DECLARE a public.alignments%ROWTYPE; j public.journeys%ROWTYPE; mp private.journey_meeting_points%ROWTYPE; stamp timestamptz;
BEGIN
 a:=private.funded_coordination_alignment(p_movement_need_id);
 IF auth.uid() IS DISTINCT FROM a.member_needing_movement_id THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact requester required'; END IF;
 PERFORM x.id FROM public.journeys x WHERE x.alignment_id=a.id FOR UPDATE;
 j:=private.assert_funded_coordination_entry(a.id);
 -- Historical exact replay performs no operational or evidence writes.
 IF EXISTS(SELECT 1 FROM private.funded_movement_starts WHERE alignment_id=a.id) THEN
  RETURN QUERY SELECT * FROM public.get_my_movement_start_status(p_movement_need_id); RETURN;
 END IF;
 IF a.status<>'activated' OR j.status<>'not_started' OR j.started_at IS NOT NULL OR j.start_requested_at IS NULL THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact offerer request required'; END IF;
 SELECT x.* INTO mp FROM private.journey_meeting_points x WHERE x.journey_id=j.id FOR SHARE;
 IF mp.journey_id IS NULL OR mp.place_text<>btrim(mp.place_text) OR length(mp.place_text) NOT BETWEEN 1 AND 200 OR mp.place_text !~ '[^[:space:]]' THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Valid meeting point required'; END IF;
 -- All graph/journey/meeting-point waits and revalidation precede this instant.
 stamp:=clock_timestamp();
 BEGIN
  SET CONSTRAINTS private.funded_start_request_complete,private.funded_start_complete,public.funded_start_journey_complete,public.funded_start_alignment_complete DEFERRED;
  INSERT INTO private.funded_movement_starts VALUES(a.id,j.id,stamp);
  UPDATE public.journeys x SET status='in_progress',started_at=stamp,updated_at=stamp WHERE x.id=j.id;
  UPDATE public.alignments x SET status='in_progress',updated_at=stamp WHERE x.id=a.id;
  PERFORM private.assert_funded_coordination_entry(a.id);
  SET CONSTRAINTS private.funded_start_request_complete,private.funded_start_complete,public.funded_start_journey_complete,public.funded_start_alignment_complete IMMEDIATE;
 EXCEPTION WHEN OTHERS THEN RAISE;
 END;
 RETURN QUERY SELECT * FROM public.get_my_movement_start_status(p_movement_need_id);
END;

DECLARE selected uuid;
BEGIN
 IF EXISTS(SELECT 1 FROM public.alignments x WHERE x.movement_need_id=p_movement_need_id AND private.is_financial_alignment(x.id)) THEN
  PERFORM private.mutate_funded_no_travel(p_movement_need_id,'confirm');
 ELSE
  selected:=private.movement_end_context(p_movement_need_id); PERFORM * FROM public.confirm_movement_end(selected);
 END IF;
 RETURN QUERY SELECT * FROM public.get_my_movement_end_status_by_need(p_movement_need_id);
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement end unavailable';
END;

DECLARE c record;
BEGIN
  IF EXISTS(SELECT 1 FROM public.alignments lifecycle_candidate WHERE lifecycle_candidate.movement_need_id=p_movement_need_id AND private.is_financial_alignment(lifecycle_candidate.id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial coordination lifecycle unavailable'; END IF;
  SELECT * INTO c FROM private.movement_coordination_context(p_movement_need_id,true);
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Coordination unavailable'; END IF;
  IF auth.uid()<>c.requester_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Coordination unavailable'; END IF;
  IF NOT EXISTS (SELECT 1 FROM private.journey_meeting_points mp WHERE mp.journey_id=c.journey_id AND mp.place_text=btrim(mp.place_text) AND length(mp.place_text) BETWEEN 1 AND 200 AND mp.place_text ~ '[^[:space:]]') THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Meeting point required';
  END IF;
  IF c.requested_at IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Coordination unavailable'; END IF;
  PERFORM * FROM public.confirm_journey_start(c.journey_id);
  RETURN QUERY SELECT * FROM public.get_my_movement_coordination_status(p_movement_need_id);
END;

