DECLARE
  v_alignment_record public.alignments%ROWTYPE;
  v_provider text;
  v_payment_id uuid;
  v_recorded_status text;
BEGIN
  IF private.is_financial_alignment(p_alignment_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial movement requires funded activation'; END IF;
  SELECT *
  INTO v_alignment_record
  FROM public.alignments AS a
  WHERE a.id = p_alignment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alignment not found';
  END IF;

  IF v_alignment_record.status <> 'awaiting_activation_payment' THEN
    RAISE EXCEPTION 'Alignment is not awaiting activation payment';
  END IF;

  -- Recheck even when returning an existing pending payment. Future provider
  -- initiation must occur only after this RPC succeeds and commits.
  PERFORM private.assert_alignment_face_ready(p_alignment_id);

  IF p_amount_minor IS NULL THEN
    RAISE EXCEPTION 'Amount is required';
  END IF;

  IF p_amount_minor < 0 THEN
    RAISE EXCEPTION 'Amount must be zero or greater';
  END IF;

  IF p_currency IS NULL OR trim(p_currency) = '' THEN
    RAISE EXCEPTION 'Currency is required';
  END IF;

  IF p_currency !~ '^[A-Z]{3}$' THEN
    RAISE EXCEPTION 'Currency must be exactly three uppercase letters';
  END IF;

  v_provider := p_provider;
  IF v_provider IS NOT NULL THEN
    v_provider := trim(v_provider);
    IF v_provider = '' THEN
      v_provider := NULL;
    END IF;
    IF length(v_provider) > 100 THEN
      RAISE EXCEPTION 'Provider must be 100 characters or fewer';
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM private.alignment_activation_payments AS ap
    WHERE ap.alignment_id = p_alignment_id
      AND ap.status = 'succeeded'
  ) THEN
    RAISE EXCEPTION 'This alignment already has a succeeded activation payment';
  END IF;

  SELECT ap.id, ap.status
  INTO v_payment_id, v_recorded_status
  FROM private.alignment_activation_payments AS ap
  WHERE ap.alignment_id = p_alignment_id
    AND ap.status = 'pending';

  IF FOUND THEN
    RETURN QUERY
    SELECT
      v_payment_id,
      p_alignment_id,
      v_recorded_status,
      ap.amount_minor,
      ap.currency
    FROM private.alignment_activation_payments AS ap
    WHERE ap.id = v_payment_id;
    RETURN;
  END IF;

  INSERT INTO private.alignment_activation_payments (
    alignment_id,
    payer_member_id,
    amount_minor,
    currency,
    status,
    provider,
    created_at,
    updated_at
  )
  VALUES (
    p_alignment_id,
    v_alignment_record.offering_member_id,
    p_amount_minor,
    p_currency,
    'pending',
    v_provider,
    NOW(),
    NOW()
  )
  RETURNING private.alignment_activation_payments.id,
            private.alignment_activation_payments.amount_minor,
            private.alignment_activation_payments.currency,
            private.alignment_activation_payments.status
  INTO v_payment_id, p_amount_minor, p_currency, v_recorded_status;

  UPDATE public.alignments AS a
  SET
    activation_fee_minor = p_amount_minor,
    activation_currency = p_currency,
    updated_at = NOW()
  WHERE a.id = p_alignment_id;

  RETURN QUERY
  SELECT v_payment_id, p_alignment_id, v_recorded_status, p_amount_minor, p_currency;
END;

DECLARE
  v_journey_exists BOOLEAN;
  v_vehicle_id UUID;
  v_offer_record public.movement_offers%ROWTYPE;
BEGIN
  -- Financial activation unlocks reveal, but creates no journey. Legacy trigger
  -- behavior remains unchanged for non-financial alignments.
  IF private.is_financial_alignment(NEW.id) THEN RETURN NEW; END IF;
  -- Only react when transitioning INTO 'activated'
  IF NEW.status = 'activated' AND (OLD.status IS NULL OR OLD.status <> 'activated') THEN

    -- Check if journey already exists for this alignment
    SELECT EXISTS(
      SELECT 1
      FROM public.journeys j
      WHERE j.alignment_id = NEW.id
    ) INTO v_journey_exists;

    IF NOT v_journey_exists THEN
      -- Load the accepted movement offer to get the vehicle
      SELECT *
      INTO v_offer_record
      FROM public.movement_offers mo
      WHERE mo.id = NEW.movement_offer_id
      FOR SHARE;

      IF FOUND THEN
        v_vehicle_id := v_offer_record.vehicle_id;
      ELSE
        -- This should not happen if alignment is well-formed, but protect against it
        RAISE EXCEPTION 'Movement offer not found for alignment';
      END IF;

      -- Insert journey with status 'not_started'
      INSERT INTO public.journeys (
        alignment_id,
        vehicle_id,
        status,
        created_at,
        updated_at
      )
      VALUES (
        NEW.id,
        v_vehicle_id,
        'not_started',
        NOW(),
        NOW()
      );
    END IF;
  END IF;

  RETURN NEW;
END;

BEGIN
  RETURN QUERY SELECT * FROM private.create_movement_offer_internal(
    p_movement_need_id, p_route_match_evidence_id, p_availability_id,
    p_seats_offered, p_proposed_pickup_area, p_proposed_dropoff_area,
    p_estimated_arrival_minutes);
END;

DECLARE
  v_member_id uuid := auth.uid();
  v_interest private.requester_movement_interests%ROWTYPE;
BEGIN
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION USING ERRCODE = '25000',
      MESSAGE = 'Interest offer creation requires READ COMMITTED';
  END IF;
  IF v_member_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.members m WHERE m.id = v_member_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Authenticated member required';
  END IF;
  IF p_interest_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22004', MESSAGE = 'Interest is required';
  END IF;

  -- Preliminary immutable bindings only: do not lock interest before support.
  SELECT i.* INTO v_interest FROM private.requester_movement_interests i
  WHERE i.id = p_interest_id AND i.offering_member_id = v_member_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Requester interest unavailable';
  END IF;

  -- 0047 takes need UPDATE -> requester endpoints SHARE -> intent UPDATE ->
  -- exact route -> availability UPDATE -> vehicle/access -> match SHARE ->
  -- interest SHARE. It proves every immutable binding and current support.
  -- Withdrawal locks only interest; the SHARE lock blocks withdrawal through
  -- offer construction. No support lock is upgraded by this wrapper.
  PERFORM private.assert_requester_movement_interest(v_interest.id);
  SELECT i.* INTO STRICT v_interest FROM private.requester_movement_interests i
  WHERE i.id = p_interest_id;

  -- Explicit final ownership/lifecycle check under the assertion's locks.
  IF v_interest.offering_member_id IS DISTINCT FROM v_member_id
    OR v_interest.requesting_member_id = v_member_id
    OR v_interest.status <> 'active'
    OR v_interest.expires_at <= clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Interest is not actionable';
  END IF;

  -- Reuse objective evidence, never recompute it. The unchanged constructor
  -- revalidates evidence/availability and proposal fields before inserting.
  -- Existing 0042 evidence-to-offer uniqueness remains in force.
  RETURN QUERY SELECT * FROM private.create_movement_offer_internal(
    v_interest.movement_need_id, v_interest.route_match_evidence_id,
    v_interest.availability_id, p_seats_offered, p_proposed_pickup_area,
    p_proposed_dropoff_area, p_estimated_arrival_minutes);
END;

DECLARE
  v_caller_member_id uuid;
  v_share_token text;
  v_expires_at timestamptz;
BEGIN
  v_caller_member_id := auth.uid();
  
  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  -- Verify caller exists in public.members
  IF NOT EXISTS (
    SELECT 1
    FROM public.members m
    WHERE m.id = v_caller_member_id
  ) THEN
    RAISE EXCEPTION 'Member profile not found';
  END IF;
  
  -- Generate a high-entropy opaque token using explicitly qualified extension function
  v_share_token := encode(extensions.gen_random_bytes(32), 'hex');
  
  -- Set expiration to 24 hours from now
  v_expires_at := NOW() + INTERVAL '24 hours';
  
  -- Insert the share
  INSERT INTO private.member_profile_shares (
    member_id,
    share_token,
    status,
    expires_at,
    created_at
  )
  VALUES (
    v_caller_member_id,
    v_share_token,
    'active',
    v_expires_at,
    NOW()
  );
  
  RETURN QUERY
  SELECT v_share_token, v_expires_at;
END;

DECLARE
  v_member_id uuid;
  v_now timestamptz;

  v_origin private.movement_location_references%ROWTYPE;
  v_destination private.movement_location_references%ROWTYPE;
  v_location private.movement_location_references%ROWTYPE;

  v_existing
    private.offering_movement_intent_creation_receipts%ROWTYPE;

  v_intent_id uuid;
  v_intent_key uuid;
BEGIN
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION USING
      ERRCODE = '25000',
      MESSAGE = 'Offering movement intent intake requires READ COMMITTED';
  END IF;

  -- Existing movement-app identity contract:
  -- public.members.id = auth.users.id = auth.uid().
  v_member_id := auth.uid();

  IF v_member_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'Authentication required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.members m
    WHERE m.id = v_member_id
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'Member record not found for the authenticated user';
  END IF;

  IF p_request_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Offering movement intent request identity is required';
  END IF;

  IF p_origin_location_reference_id IS NULL
     OR p_destination_location_reference_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Offering movement intent origin and destination are required';
  END IF;

  IF p_origin_location_reference_id
       = p_destination_location_reference_id THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Offering movement intent requires distinct origin and destination';
  END IF;

  IF p_earliest_departure_at IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Offering movement intent earliest departure is required';
  END IF;

  IF NOT isfinite(p_earliest_departure_at)
     OR (
       p_latest_departure_at IS NOT NULL
       AND NOT isfinite(p_latest_departure_at)
     ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Offering movement intent departure times must be finite';
  END IF;

  IF p_latest_departure_at IS NOT NULL
     AND p_latest_departure_at < p_earliest_departure_at THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Offering movement intent latest departure cannot be before earliest departure';
  END IF;

  -- -------------------------------------------------------
  -- Fast idempotent replay path.
  -- -------------------------------------------------------

  SELECT r.*
  INTO v_existing
  FROM private.offering_movement_intent_creation_receipts r
  WHERE r.request_id = p_request_id;

  IF FOUND THEN
    IF v_existing.offering_member_id IS DISTINCT FROM v_member_id
       OR v_existing.origin_location_reference_id
            IS DISTINCT FROM p_origin_location_reference_id
       OR v_existing.destination_location_reference_id
            IS DISTINCT FROM p_destination_location_reference_id
       OR v_existing.earliest_departure_at
            IS DISTINCT FROM p_earliest_departure_at
       OR v_existing.latest_departure_at
            IS DISTINCT FROM p_latest_departure_at THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'Offering movement intent request replay does not match the original request';
    END IF;

    PERFORM private.assert_offering_movement_intent(
      v_existing.offering_movement_intent_id
    );

    RETURN QUERY
    SELECT v_existing.offering_movement_intent_id;

    RETURN;
  END IF;

  -- -------------------------------------------------------
  -- Lock both trusted endpoint rows in deterministic UUID
  -- order. This avoids opposite origin/destination lock order
  -- between concurrent requests.
  -- -------------------------------------------------------

  FOR v_location IN
    SELECT lr.*
    FROM private.movement_location_references lr
    WHERE lr.id IN (
      p_origin_location_reference_id,
      p_destination_location_reference_id
    )
    ORDER BY lr.id
    FOR SHARE
  LOOP
    IF v_location.id = p_origin_location_reference_id THEN
      v_origin := v_location;
    ELSIF v_location.id = p_destination_location_reference_id THEN
      v_destination := v_location;
    END IF;
  END LOOP;

  IF v_origin.id IS NULL OR v_destination.id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Offering movement intent trusted location was not found';
  END IF;

  v_now := clock_timestamp();

  IF v_origin.owner_member_id IS DISTINCT FROM v_member_id
     OR v_destination.owner_member_id IS DISTINCT FROM v_member_id THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'Offering movement intent locations do not belong to the authenticated member';
  END IF;

  IF v_origin.resolution_status <> 'resolved'
     OR v_destination.resolution_status <> 'resolved'
     OR v_origin.source_kind <> 'provider_resolved'
     OR v_destination.source_kind <> 'provider_resolved' THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Offering movement intent requires trusted resolved locations';
  END IF;

  IF v_origin.latitude IS NULL
     OR v_origin.longitude IS NULL
     OR v_destination.latitude IS NULL
     OR v_destination.longitude IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Offering movement intent trusted coordinates are incomplete';
  END IF;

  IF (
       v_origin.expires_at IS NOT NULL
       AND v_origin.expires_at <= v_now
     )
     OR (
       v_destination.expires_at IS NOT NULL
       AND v_destination.expires_at <= v_now
     ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Offering movement intent trusted location has expired';
  END IF;

  -- -------------------------------------------------------
  -- First creation / concurrent retry-safe creation.
  --
  -- The nested block is a PL/pgSQL subtransaction. If a
  -- concurrent request wins the same request_id race, every
  -- insert below from the losing attempt is rolled back.
  -- -------------------------------------------------------

  BEGIN
    v_now := clock_timestamp();
    v_intent_key := gen_random_uuid();

    INSERT INTO private.offering_movement_intents (
      offering_member_id,
      intent_key,
      version,
      earliest_departure_at,
      latest_departure_at,
      created_at,
      expires_at,
      status
    )
    VALUES (
      v_member_id,
      v_intent_key,
      1,
      p_earliest_departure_at,
      p_latest_departure_at,
      v_now,
      NULL,
      'current'
    )
    RETURNING id
    INTO v_intent_id;

    INSERT INTO private.offering_movement_intent_locations (
      intent_id,
      role,
      location_reference_id
    )
    VALUES
      (
        v_intent_id,
        'origin',
        p_origin_location_reference_id
      ),
      (
        v_intent_id,
        'destination',
        p_destination_location_reference_id
      );

    -- Explicitly validate completeness now rather than waiting
    -- only for the deferred constraint trigger at transaction end.
    PERFORM private.assert_offering_movement_intent(v_intent_id);

    INSERT INTO
      private.offering_movement_intent_creation_receipts (
        request_id,
        offering_member_id,
        offering_movement_intent_id,
        origin_location_reference_id,
        destination_location_reference_id,
        earliest_departure_at,
        latest_departure_at,
        recorded_at
      )
    VALUES (
      p_request_id,
      v_member_id,
      v_intent_id,
      p_origin_location_reference_id,
      p_destination_location_reference_id,
      p_earliest_departure_at,
      p_latest_departure_at,
      v_now
    );

  EXCEPTION
    WHEN unique_violation THEN
      -- If another transaction won the same idempotency request,
      -- this subtransaction has already removed the losing intent
      -- and its child rows. Re-read the winner.
      SELECT r.*
      INTO v_existing
      FROM private.offering_movement_intent_creation_receipts r
      WHERE r.request_id = p_request_id;

      IF NOT FOUND THEN
        RAISE;
      END IF;

      IF v_existing.offering_member_id IS DISTINCT FROM v_member_id
         OR v_existing.origin_location_reference_id
              IS DISTINCT FROM p_origin_location_reference_id
         OR v_existing.destination_location_reference_id
              IS DISTINCT FROM p_destination_location_reference_id
         OR v_existing.earliest_departure_at
              IS DISTINCT FROM p_earliest_departure_at
         OR v_existing.latest_departure_at
              IS DISTINCT FROM p_latest_departure_at THEN
        RAISE EXCEPTION USING
          ERRCODE = '23514',
          MESSAGE = 'Offering movement intent request replay does not match the original request';
      END IF;

      PERFORM private.assert_offering_movement_intent(
        v_existing.offering_movement_intent_id
      );

      RETURN QUERY
      SELECT v_existing.offering_movement_intent_id;

      RETURN;
  END;

  RETURN QUERY
  SELECT v_intent_id;
END;

DECLARE v_id uuid;
BEGIN
  PERFORM 1 FROM public.members WHERE id=p_member_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Member not found'; END IF;
  INSERT INTO private.profile_photo_submissions(member_id,submission_storage_path,submitted_mime_type,submitted_size_bytes)
  VALUES (p_member_id,p_submission_storage_path,p_submitted_mime_type,p_submitted_size_bytes) RETURNING id INTO v_id;
  RETURN v_id;
END;

DECLARE
  v_member_id uuid := auth.uid();
  i private.requester_movement_interests%ROWTYPE;
  a private.offering_movement_availability%ROWTYPE;
  e private.trusted_route_match_evidence%ROWTYPE;
BEGIN
  IF current_setting('transaction_isolation')<>'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000', MESSAGE='Interest creation requires READ COMMITTED';
  END IF;
  IF v_member_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.members m WHERE m.id=v_member_id) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Authenticated member required';
  END IF;
  IF p_request_id IS NULL OR p_movement_need_id IS NULL OR p_availability_id IS NULL OR p_route_match_evidence_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='Request, movement need, availability and exact evidence are required';
  END IF;
  -- Serialize request-key replays across different needs before support locks.
  PERFORM pg_advisory_xact_lock(hashtextextended('requester-interest:'||v_member_id::text||':'||p_request_id::text,0));
  SELECT x.* INTO i FROM private.requester_movement_interests x
    WHERE x.requesting_member_id=v_member_id AND x.request_id=p_request_id;
  IF FOUND THEN
    IF i.movement_need_id IS DISTINCT FROM p_movement_need_id
      OR i.availability_id IS DISTINCT FROM p_availability_id
      OR i.route_match_evidence_id IS DISTINCT FROM p_route_match_evidence_id THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Interest request replay has different bindings';
    END IF;
    IF i.status='active' THEN PERFORM private.assert_requester_movement_interest(i.id); END IF;
    SELECT x.* INTO STRICT i FROM private.requester_movement_interests x WHERE x.id=i.id;
    RETURN QUERY SELECT i.id,i.status,i.created_at;
    RETURN;
  END IF;
  PERFORM private.assert_requester_interest_support(
    v_member_id,p_movement_need_id,p_availability_id,p_route_match_evidence_id);
  SELECT x.* INTO STRICT a FROM private.offering_movement_availability x WHERE x.id=p_availability_id;
  SELECT x.* INTO STRICT e FROM private.trusted_route_match_evidence x WHERE x.id=p_route_match_evidence_id;
  INSERT INTO private.requester_movement_interests (
    request_id,movement_need_id,requesting_member_id,availability_id,offering_member_id,
    offering_movement_intent_id,route_match_evidence_id,route_match_evidence_version,expires_at
  ) VALUES (
    p_request_id,p_movement_need_id,v_member_id,a.id,a.offering_member_id,
    a.offering_movement_intent_id,e.id,e.version,LEAST(a.expires_at,e.expires_at)
  ) RETURNING * INTO i;
  RETURN QUERY SELECT i.id,i.status,i.created_at;
END;

DECLARE
  v_caller_member_id uuid;
  v_journey_record public.journeys%ROWTYPE;
  v_alignment_record public.alignments%ROWTYPE;
  v_offering_member_id uuid;
  v_requester_member_id uuid;
BEGIN
  IF EXISTS(SELECT 1 FROM public.journeys lifecycle_journey WHERE lifecycle_journey.id=p_journey_id AND private.is_financial_alignment(lifecycle_journey.alignment_id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial coordination lifecycle unavailable'; END IF;
  v_caller_member_id := auth.uid();

  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  -- Load and lock the journey
  SELECT *
  INTO v_journey_record
  FROM public.journeys j
  WHERE j.id = p_journey_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Journey not found';
  END IF;

  -- Load and lock the alignment
  SELECT *
  INTO v_alignment_record
  FROM public.alignments a
  WHERE a.id = v_journey_record.alignment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alignment not found';
  END IF;

  v_offering_member_id := v_alignment_record.offering_member_id;
  v_requester_member_id := v_alignment_record.member_needing_movement_id;

  -- Caller must be one of the principal members
  IF v_caller_member_id <> v_offering_member_id AND v_caller_member_id <> v_requester_member_id THEN
    RAISE EXCEPTION 'Only principal movement members may decline movement end';
  END IF;

  -- Must have a pending end request
  IF v_journey_record.end_requested_by_member_id IS NULL THEN
    RAISE EXCEPTION 'No pending end request to decline';
  END IF;

  -- Caller cannot decline their own request
  IF v_journey_record.end_requested_by_member_id = v_caller_member_id THEN
    RAISE EXCEPTION 'You cannot decline your own end request';
  END IF;

  -- Terminal consent must never be cleared.
  IF v_journey_record.status IN ('completed','cancelled','failed') THEN
    RAISE EXCEPTION 'Movement is already terminal';
  END IF;

  -- Clear the pending end request and any stale confirmation fields
  UPDATE public.journeys j
  SET
    end_requested_by_member_id = NULL,
    end_requested_at = NULL,
    end_confirmed_by_member_id = NULL,
    end_confirmed_at = NULL,
    end_reason = NULL,
    updated_at = NOW()
  WHERE j.id = p_journey_id;

  RETURN QUERY
  SELECT
    p_journey_id,
    v_journey_record.status,
    v_alignment_record.status,
    'no_pending_end_request'::text;
END;

DECLARE selected uuid;
BEGIN
 IF EXISTS(SELECT 1 FROM public.alignments x WHERE x.movement_need_id=p_movement_need_id AND private.is_financial_alignment(x.id)) THEN
  PERFORM private.mutate_funded_no_travel(p_movement_need_id,'decline');
 ELSE
  selected:=private.movement_end_context(p_movement_need_id); PERFORM * FROM public.decline_movement_end(selected);
 END IF;
 RETURN QUERY SELECT * FROM public.get_my_movement_end_status_by_need(p_movement_need_id);
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement end unavailable';
END;

DECLARE a public.alignments%ROWTYPE; w private.funded_completion_response_windows%ROWTYPE; review private.funded_completion_disputes%ROWTYPE;
BEGIN
 IF p_reason_category IS NULL OR p_reason_category NOT IN('completion_concern','movement_concern') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Bounded review category required'; END IF;
 a:=private.funded_coordination_alignment(p_movement_need_id);
 IF auth.uid() IS DISTINCT FROM a.member_needing_movement_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact requester required'; END IF;
 PERFORM x.id FROM public.journeys x WHERE x.alignment_id=a.id FOR UPDATE;
 PERFORM m.id FROM public.members m WHERE m.id IN(a.offering_member_id,a.member_needing_movement_id) ORDER BY m.id FOR UPDATE;
 SELECT * INTO STRICT w FROM private.funded_completion_response_windows WHERE alignment_id=a.id;
 SELECT * INTO review FROM private.funded_completion_disputes WHERE alignment_id=a.id;
 IF review.alignment_id IS NOT NULL THEN
  IF review.reason_category IS DISTINCT FROM p_reason_category THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Conflicting completion review'; END IF;
 ELSE
  INSERT INTO private.funded_completion_disputes VALUES(a.id,w.financial_agreement_id,w.journey_id,auth.uid(),NULL,p_reason_category);
 END IF;
 RETURN QUERY SELECT * FROM public.get_my_funded_movement_completion_status(p_movement_need_id);
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING ERRCODE=SQLSTATE,MESSAGE='Movement completion unavailable';
END;

DECLARE
  v_total integer;
  v_active integer;
  v_kinds integer;
  v_available uuid;
  v_held uuid;
  v_withdrawable uuid;
BEGIN
  IF p_member_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='Member id required';
  END IF;

  PERFORM 1
  FROM public.members m
  WHERE m.id = p_member_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23503', MESSAGE='Member unavailable';
  END IF;

  -- Serialize with other provisioning calls and the 0066 top-up member gate.
  -- Lock existing accounts against concurrent closure before checking their state.
  PERFORM 1 FROM private.wallet_accounts a
  WHERE a.member_id = p_member_id AND a.currency = 'NGN'
  ORDER BY a.id FOR SHARE;

  SELECT count(*)::integer,
    count(*) FILTER (WHERE a.status = 'active')::integer,
    count(DISTINCT a.account_kind) FILTER (WHERE a.account_kind IN
      ('member_available','member_held','member_withdrawable'))::integer
  INTO v_total, v_active, v_kinds
  FROM private.wallet_accounts a
  WHERE a.member_id = p_member_id AND a.currency = 'NGN';

  IF v_total <> 0 AND (v_total <> 3 OR v_active <> 3 OR v_kinds <> 3) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Member wallet unavailable';
  END IF;

  IF v_total = 0 THEN
  INSERT INTO private.wallet_accounts(member_id, account_kind, currency)
  SELECT p_member_id, k.account_kind, 'NGN'
  FROM (VALUES
    ('member_available'::text),
    ('member_held'::text),
    ('member_withdrawable'::text)
  ) AS k(account_kind)
  ON CONFLICT (member_id, account_kind, currency)
    WHERE member_id IS NOT NULL
  DO NOTHING;
  END IF;

  SELECT
    count(*)::integer,
    count(*) FILTER (WHERE a.status='active')::integer,
    min(a.id::text) FILTER (WHERE a.account_kind='member_available')::uuid,
    min(a.id::text) FILTER (WHERE a.account_kind='member_held')::uuid,
    min(a.id::text) FILTER (WHERE a.account_kind='member_withdrawable')::uuid
  INTO v_total, v_active, v_available, v_held, v_withdrawable
  FROM private.wallet_accounts a
  WHERE a.member_id = p_member_id
    AND a.currency = 'NGN'
    AND a.account_kind IN ('member_available','member_held','member_withdrawable');

  IF v_total IS DISTINCT FROM 3
     OR v_active IS DISTINCT FROM 3
     OR v_available IS NULL
     OR v_held IS NULL
     OR v_withdrawable IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Member wallet unavailable';
  END IF;

  RETURN QUERY
  SELECT p_member_id, 'NGN'::text, v_available, v_held, v_withdrawable;
END;

BEGIN
  UPDATE private.profile_photo_submissions SET status='failed',processed_at=clock_timestamp()
    WHERE id=p_submission_id AND status='pending';
  IF NOT FOUND THEN RAISE EXCEPTION 'Submission is not pending'; END IF;
END;

DECLARE
  v_member_id uuid;
  v_alignment_record public.alignments%ROWTYPE;
  v_payment_record private.alignment_activation_payments%ROWTYPE;
BEGIN
  IF private.is_financial_alignment(p_alignment_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Use movement activation status'; END IF;
  v_member_id := auth.uid();

  IF v_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT *
  INTO v_alignment_record
  FROM public.alignments AS a
  WHERE a.id = p_alignment_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alignment not found';
  END IF;

  IF v_alignment_record.member_needing_movement_id <> v_member_id
    AND v_alignment_record.offering_member_id <> v_member_id THEN
    RAISE EXCEPTION 'You are not a participant in this alignment';
  END IF;

  SELECT *
  INTO v_payment_record
  FROM private.alignment_activation_payments AS ap
  WHERE ap.alignment_id = p_alignment_id
  ORDER BY
    CASE
      WHEN ap.status = 'succeeded' THEN 1
      WHEN ap.status = 'pending' THEN 2
      WHEN ap.status IN ('failed', 'cancelled') THEN 3
      ELSE 4
    END ASC,
    ap.created_at DESC
  LIMIT 1;

  RETURN QUERY
  SELECT
    v_alignment_record.id AS alignment_id,
    v_alignment_record.status AS alignment_status,
    v_alignment_record.activation_fee_minor,
    v_alignment_record.activation_currency,
    COALESCE(v_payment_record.status, NULL::text) AS payment_status,
    (v_alignment_record.offering_member_id = v_member_id
      AND v_alignment_record.status = 'awaiting_activation_payment')::boolean AS payment_required_from_me,
    v_alignment_record.activated_at
  ;
END;

DECLARE
  v_member_id uuid;
  v_alignment_record public.alignments%ROWTYPE;
BEGIN
  v_member_id := auth.uid();

  IF v_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT *
  INTO v_alignment_record
  FROM public.alignments AS a
  WHERE a.id = p_alignment_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alignment not found';
  END IF;

  IF v_alignment_record.member_needing_movement_id <> v_member_id
    AND v_alignment_record.offering_member_id <> v_member_id THEN
    RAISE EXCEPTION 'You are not a participant in this alignment';
  END IF;

  RETURN QUERY
  SELECT
    a.id AS alignment_id,
    a.movement_need_id,
    a.movement_offer_id,
    a.status AS alignment_status,
    a.activation_fee_minor,
    a.activation_currency,
    a.activated_at,
    a.created_at,
    a.updated_at
  FROM public.alignments AS a
  WHERE a.id = p_alignment_id;
