DECLARE a public.alignments%ROWTYPE;
BEGIN
 a:=private.completed_movement_rating_alignment(p_movement_need_id);
 RETURN QUERY SELECT 1,p.person_role,m.first_name,m.rating,m.completed_movements,r.stars IS NOT NULL,r.stars
 FROM private.completed_movement_principals p JOIN public.members m ON m.id=p.member_id
 LEFT JOIN private.completed_movement_ratings r ON r.alignment_id=p.alignment_id
  AND r.reviewed_member_id=p.member_id AND r.reviewer_member_id=auth.uid()
 WHERE p.alignment_id=a.id AND p.member_id<>auth.uid();
END;

DECLARE
  v_member_id uuid;
  v_now timestamptz := clock_timestamp();
BEGIN
  v_member_id := auth.uid();

  IF v_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  RETURN QUERY
  SELECT mn.id
  FROM public.movement_needs AS mn
  WHERE mn.member_id = v_member_id
    AND mn.status = 'discoverable'
    AND COALESCE(
      mn.latest_departure_at,
      mn.earliest_departure_at
    ) > v_now
  ORDER BY
    mn.created_at DESC,
    mn.id DESC
  LIMIT 1;
END;

DECLARE a public.alignments%ROWTYPE; j public.journeys%ROWTYPE; w private.funded_completion_response_windows%ROWTYPE; r private.funded_movement_completions%ROWTYPE; review boolean;
BEGIN
 a:=private.funded_coordination_alignment(p_movement_need_id);
 PERFORM x.id FROM public.journeys x WHERE x.alignment_id=a.id FOR UPDATE;
 j:=private.assert_funded_coordination_entry(a.id);
 SELECT * INTO w FROM private.funded_completion_response_windows WHERE alignment_id=a.id;
 review:=EXISTS(SELECT 1 FROM private.funded_completion_disputes WHERE alignment_id=a.id);
 -- The sole live policy is window expiry. Historical validators never sample it.
 IF j.status='in_progress' AND w.alignment_id IS NOT NULL AND NOT review AND clock_timestamp()>=w.response_deadline_at THEN
  PERFORM private.finalize_funded_completion(p_movement_need_id,'response_timeout');
  j:=private.assert_funded_coordination_entry(a.id);
 END IF;
 SELECT * INTO r FROM private.funded_movement_completions WHERE alignment_id=a.id;
 RETURN QUERY SELECT j.status,j.completion_requested_at,j.completed_at,
  auth.uid()=a.offering_member_id AND j.status='in_progress' AND j.completion_requested_at IS NULL,
  auth.uid()=a.member_needing_movement_id AND j.status='in_progress' AND j.completion_requested_at IS NOT NULL AND NOT review,
  CASE WHEN j.status='completed' THEN 'settled'::text WHEN review THEN 'under_review'::text WHEN w.alignment_id IS NOT NULL THEN 'awaiting_confirmation'::text ELSE 'not_ready'::text END,
  w.response_deadline_at,r.completion_method,
  auth.uid()=a.member_needing_movement_id AND j.status='in_progress' AND w.alignment_id IS NOT NULL AND NOT review,
  review;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING ERRCODE=SQLSTATE,MESSAGE='Movement completion unavailable';
END;

DECLARE a public.alignments%ROWTYPE;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.alignments x WHERE x.movement_need_id=p_movement_need_id AND private.is_financial_alignment(x.id)) THEN
  -- Preserve explicit navigation for an already existing, validated legacy
  -- container. This is not eligibility for the funded construction RPC.
  RETURN QUERY SELECT p_movement_need_id,false FROM private.movement_coordination_context(p_movement_need_id,false) c
   WHERE auth.uid() IN (c.offering_id,c.requester_id) AND c.journey_status='not_started';
  RETURN;
 END IF;
 BEGIN
  a:=private.funded_coordination_alignment(p_movement_need_id);
  IF EXISTS(SELECT 1 FROM public.journeys WHERE alignment_id=a.id)
   OR EXISTS(SELECT 1 FROM private.funded_movement_coordination_entries WHERE alignment_id=a.id) THEN
   PERFORM x.id FROM public.journeys x WHERE x.alignment_id=a.id FOR SHARE;
   PERFORM private.assert_funded_coordination_entry(a.id);
  END IF;
  RETURN QUERY SELECT p_movement_need_id,true;
 EXCEPTION WHEN check_violation OR insufficient_privilege OR no_data_found OR too_many_rows THEN RETURN;
 END;
END;

DECLARE a public.alignments%ROWTYPE; j public.journeys%ROWTYPE; d private.funded_movement_disputes%ROWTYPE;
BEGIN
 IF EXISTS(SELECT 1 FROM private.funded_movement_disputes receipt JOIN public.alignments x ON x.id=receipt.alignment_id WHERE x.movement_need_id=p_movement_need_id) THEN
  a:=private.funded_dispute_alignment(p_movement_need_id);
  SELECT * INTO STRICT j FROM public.journeys WHERE alignment_id=a.id;
 ELSE
 -- Terminal mutual no-travel is readable through its exact historical selector.
 IF EXISTS(SELECT 1 FROM public.alignments WHERE movement_need_id=p_movement_need_id AND status='cancelled') THEN
  a:=private.funded_no_travel_alignment(p_movement_need_id);
 ELSE
  a:=private.funded_coordination_alignment(p_movement_need_id);
  PERFORM id FROM public.journeys WHERE alignment_id=a.id FOR UPDATE;
 END IF;
 j:=private.assert_funded_coordination_entry(a.id);
 END IF;
 PERFORM private.assert_funded_dispute(a.id);
 SELECT * INTO d FROM private.funded_movement_disputes WHERE alignment_id=a.id;
 RETURN QUERY SELECT d.alignment_id IS NOT NULL,
  d.alignment_id IS NULL AND a.status='activated' AND j.status='not_started' AND NOT EXISTS(SELECT 1 FROM private.funded_no_travel_holds h WHERE h.alignment_id=a.id),
  coalesce(d.opened_by_member_id=auth.uid(),false),d.opened_at;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement review unavailable';
END;

DECLARE
  v_caller_member_id uuid;
  v_journey_record public.journeys%ROWTYPE;
  v_alignment_record public.alignments%ROWTYPE;
BEGIN
  v_caller_member_id := auth.uid();
  
  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  -- Load the journey
  SELECT *
  INTO v_journey_record
  FROM public.journeys j
  WHERE j.id = p_journey_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Journey not found';
  END IF;
  
  -- Load the alignment
  SELECT *
  INTO v_alignment_record
  FROM public.alignments a
  WHERE a.id = v_journey_record.alignment_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alignment not found';
  END IF;
  
  -- Caller must be one of the two participants
  IF v_alignment_record.member_needing_movement_id <> v_caller_member_id
    AND v_alignment_record.offering_member_id <> v_caller_member_id THEN
    RAISE EXCEPTION 'You are not a participant in this journey';
  END IF;
  
  RETURN QUERY
  SELECT
    v_journey_record.id AS journey_id,
    v_journey_record.status AS journey_status,
    v_journey_record.start_requested_at,
    v_journey_record.started_at,
    v_journey_record.completion_requested_at,
    v_journey_record.completed_at;
END;

DECLARE g private.financial_agreements%ROWTYPE; a public.alignments%ROWTYPE; evidence record; ready boolean;
BEGIN
 g:=private.funded_activation_agreement(p_financial_agreement_id,p_expected_agreement_version,false);
 SELECT x.* INTO STRICT a FROM public.alignments x WHERE x.id=g.alignment_id;
 IF EXISTS(SELECT 1 FROM private.funded_movement_activations x WHERE x.financial_agreement_id=g.id) THEN
  PERFORM private.assert_funded_activation(g,a);
  RETURN QUERY SELECT g.id,g.version,a.id,a.status,'activated'::text,a.activated_at; RETURN;
 END IF;
 IF g.status<>'current' OR a.status<>'awaiting_activation_payment' OR a.activated_at IS NOT NULL THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Activation unavailable'; END IF;
 -- Same member gate as 0078. SHARE never claims readiness as a reservation:
 -- activation rechecks under UPDATE locks. Projection performs no writes.
 PERFORM m.id FROM public.members m JOIN private.required_face_members(a.id) r ON r.member_id=m.id ORDER BY m.id FOR SHARE OF m;
 SELECT * INTO evidence FROM private.movement_funding_evidence(g);
 ready:=NOT EXISTS(SELECT 1 FROM private.required_face_members(a.id) r WHERE NOT private.has_current_alignment_face_check(a.id,r.member_id,clock_timestamp()));
 RETURN QUERY SELECT g.id,g.version,a.id,a.status,CASE WHEN evidence.fully_held_at IS NULL THEN 'funding_required'
  WHEN NOT ready THEN 'identity_required' ELSE 'ready_to_activate' END,NULL::timestamptz;
END;

DECLARE
  v_caller_member_id uuid;
  v_journey_record public.journeys%ROWTYPE;
  v_alignment_record public.alignments%ROWTYPE;
  v_end_status text;
  v_requested_by_me boolean;
  v_action_required_from_me boolean;
BEGIN
  v_caller_member_id := auth.uid();

  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  -- Load the journey
  SELECT *
  INTO v_journey_record
  FROM public.journeys j
  WHERE j.id = p_journey_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Journey not found';
  END IF;

  -- Load the alignment
  SELECT *
  INTO v_alignment_record
  FROM public.alignments a
  WHERE a.id = v_journey_record.alignment_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alignment not found';
  END IF;

  -- Caller must be a principal member
  IF v_caller_member_id <> v_alignment_record.offering_member_id
    AND v_caller_member_id <> v_alignment_record.member_needing_movement_id THEN
    RAISE EXCEPTION 'You are not a principal member of this movement';
  END IF;

  -- Determine end status
  IF v_journey_record.status='cancelled' AND v_alignment_record.status='cancelled'
    AND EXISTS (SELECT 1 FROM private.mutual_no_travel_closures c WHERE c.journey_id=p_journey_id) THEN
    v_end_status := 'mutual_no_travel';
    v_requested_by_me := false;
    v_action_required_from_me := false;
  ELSIF v_journey_record.status = 'completed' THEN
    v_end_status := 'completed';
    v_requested_by_me := false;
    v_action_required_from_me := false;
  ELSIF v_journey_record.end_requested_by_member_id IS NULL THEN
    v_end_status := 'no_pending_end_request';
    v_requested_by_me := false;
    v_action_required_from_me := false;
  ELSIF v_journey_record.end_requested_by_member_id = v_caller_member_id THEN
    v_end_status := 'awaiting_other_member';
    v_requested_by_me := true;
    v_action_required_from_me := false;
  ELSE
    v_end_status := 'action_required_from_me';
    v_requested_by_me := false;
    v_action_required_from_me := true;
  END IF;

  RETURN QUERY
  SELECT
    p_journey_id,
    v_journey_record.status,
    v_alignment_record.status,
    v_end_status,
    v_requested_by_me,
    v_action_required_from_me,
    v_journey_record.end_requested_at,
    v_journey_record.completed_at;
END;

DECLARE a public.alignments%ROWTYPE; j public.journeys%ROWTYPE; r private.funded_no_travel_requests%ROWTYPE;
 d private.funded_no_travel_closures%ROWTYPE; selected uuid; amount bigint;
BEGIN
 IF EXISTS(SELECT 1 FROM public.alignments x WHERE x.movement_need_id=p_movement_need_id AND private.is_financial_alignment(x.id)) THEN
  a:=private.funded_no_travel_alignment(p_movement_need_id);
  SELECT * INTO STRICT j FROM public.journeys WHERE alignment_id=a.id;
  IF EXISTS(SELECT 1 FROM private.funded_no_travel_holds WHERE alignment_id=a.id) THEN
   PERFORM private.assert_held_no_travel(a.id);
   RETURN QUERY SELECT 'not_started'::text,'no_travel_held'::text,false,false,h.requested_at,NULL::timestamptz,
    'held_review_required'::text,NULL::bigint,'NGN'::text FROM private.funded_no_travel_holds h WHERE h.alignment_id=a.id;
   RETURN;
  END IF;
  SELECT * INTO d FROM private.funded_no_travel_closures WHERE alignment_id=a.id;
  IF d.alignment_id IS NOT NULL THEN
   SELECT sum(amount_minor::numeric)::bigint INTO amount FROM private.financial_components WHERE agreement_id=d.financial_agreement_id
    AND (component_key='movement_contribution' OR (component_key='requester_platform_share' AND NOT private.activation_fee_is_finalized(d.financial_agreement_id)));
   RETURN QUERY SELECT 'cancelled'::text,'mutual_no_travel'::text,false,false,d.requested_at,NULL::timestamptz,
    CASE WHEN auth.uid()=a.member_needing_movement_id THEN 'released_to_me'::text ELSE 'released_to_requester'::text END,amount,'NGN'::text;
  ELSE
   SELECT q.* INTO r FROM private.funded_no_travel_requests q WHERE q.alignment_id=a.id
    AND NOT EXISTS(SELECT 1 FROM private.funded_no_travel_declines z WHERE z.request_id=q.id);
   RETURN QUERY SELECT j.status,CASE WHEN r.id IS NULL THEN 'no_pending_end_request'::text
    WHEN r.first_principal_id=auth.uid() THEN 'awaiting_other_member'::text ELSE 'action_required_from_me'::text END,
    coalesce(r.first_principal_id=auth.uid(),false),coalesce(r.first_principal_id<>auth.uid(),false),r.requested_at,NULL::timestamptz,
    'held'::text,NULL::bigint,'NGN'::text;
  END IF; RETURN;
 END IF;
 selected:=private.movement_end_context(p_movement_need_id);
 RETURN QUERY SELECT s.journey_status,s.end_status,s.requested_by_me,s.action_required_from_me,s.requested_at,s.completed_at,
  'legacy'::text,NULL::bigint,NULL::text FROM public.get_my_movement_end_status(selected) s;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement end unavailable';
END;

DECLARE g private.financial_agreements%ROWTYPE; evidence record;
BEGIN
  g:=private.movement_funding_agreement(p_financial_agreement_id,auth.uid());
  PERFORM m.id FROM public.members m WHERE m.id=g.member_needing_movement_id FOR SHARE;
  SELECT * INTO evidence FROM private.movement_funding_evidence(g);
  RETURN QUERY SELECT g.id,g.version,g.alignment_id,CASE WHEN evidence.fully_held_at IS NULL THEN 'not_held' ELSE 'held' END,
    evidence.required_minor,evidence.held_minor,g.currency,evidence.fully_held_at;
END;

DECLARE
  v_caller_member_id uuid;
  v_need_record public.movement_needs%ROWTYPE;
  v_confirmed_count integer;
  v_pending_count integer;
BEGIN
  v_caller_member_id := auth.uid();
  
  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  -- Load the movement need
  SELECT *
  INTO v_need_record
  FROM public.movement_needs mn
  WHERE mn.id = p_movement_need_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Movement need not found';
  END IF;
  
  -- Caller must own the movement need
  IF v_need_record.member_id <> v_caller_member_id THEN
    RAISE EXCEPTION 'Only the movement need owner may view group readiness';
  END IF;
  
  -- Count confirmed participants
  SELECT COUNT(*)
  INTO v_confirmed_count
  FROM public.movement_participants mp
  WHERE mp.movement_need_id = p_movement_need_id
    AND mp.status = 'confirmed';
  
  -- Count pending (invited) participants
  SELECT COUNT(*)
  INTO v_pending_count
  FROM public.movement_participants mp
  WHERE mp.movement_need_id = p_movement_need_id
    AND mp.status = 'invited';
  
  RETURN QUERY
  SELECT
    p_movement_need_id,
    v_need_record.people_count,
    v_confirmed_count,
    v_pending_count,
    GREATEST(v_need_record.people_count - v_confirmed_count - v_pending_count, 0)::integer,
    (v_confirmed_count = v_need_record.people_count AND v_pending_count = 0)::boolean;
END;

DECLARE
  v_caller_member_id uuid;
  v_journey_record public.journeys%ROWTYPE;
  v_alignment_record public.alignments%ROWTYPE;
  v_settlement_record private.movement_settlements%ROWTYPE;
  v_movement_completed boolean;
  v_settlement_is_for_me boolean;
BEGIN
  v_caller_member_id := auth.uid();
  
  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  -- Load the journey
  SELECT *
  INTO v_journey_record
  FROM public.journeys j
  WHERE j.id = p_journey_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Journey not found';
  END IF;
  
  -- Load the alignment
  SELECT *
  INTO v_alignment_record
  FROM public.alignments a
  WHERE a.id = v_journey_record.alignment_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alignment not found';
  END IF;
  
  -- Caller must be a principal member
  IF v_caller_member_id <> v_alignment_record.offering_member_id
    AND v_caller_member_id <> v_alignment_record.member_needing_movement_id THEN
    RAISE EXCEPTION 'You are not a principal member of this movement';
  END IF;
  
  -- Check completion status
  v_movement_completed := (v_journey_record.status = 'completed' AND v_alignment_record.status = 'completed');
  
  -- Load settlement if it exists
  SELECT *
  INTO v_settlement_record
  FROM private.movement_settlements ms
  WHERE ms.journey_id = p_journey_id;
  
  IF FOUND THEN
    v_settlement_is_for_me := (v_settlement_record.beneficiary_member_id = v_caller_member_id);
  ELSE
    v_settlement_is_for_me := false;
  END IF;
  
  RETURN QUERY
  SELECT
    p_journey_id,
    v_movement_completed,
    COALESCE(v_settlement_record.status, 'no_settlement'::text),
    v_settlement_is_for_me,
    v_settlement_record.settled_at;
END;

DECLARE
  v_member_id uuid;
BEGIN
  v_member_id := auth.uid();
  IF v_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  RETURN QUERY
  SELECT a.movement_need_id
  FROM public.alignments AS a
  WHERE a.member_needing_movement_id = v_member_id
    AND a.status IN ('awaiting_activation_payment', 'activated')
  ORDER BY a.created_at DESC, a.id DESC
  LIMIT 1;
END;

DECLARE
  v_caller uuid := auth.uid();
  v_total integer;
  v_active integer;
  v_available numeric;
  v_held numeric;
  v_withdrawable numeric;
  v_bigint_max constant numeric := 9223372036854775807;
BEGIN
  IF v_caller IS NULL
     OR NOT EXISTS (SELECT 1 FROM public.members m WHERE m.id=v_caller) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Authenticated member required';
  END IF;

  SELECT
    count(*)::integer,
    count(*) FILTER (WHERE a.status='active')::integer
  INTO v_total, v_active
  FROM private.wallet_accounts a
  WHERE a.member_id = v_caller
    AND a.currency = 'NGN'
    AND a.account_kind IN ('member_available','member_held','member_withdrawable');

  IF v_total = 0 THEN
    RETURN QUERY SELECT 'NGN'::text, false, 0::bigint, 0::bigint, 0::bigint;
    RETURN;
  END IF;

  IF v_total IS DISTINCT FROM 3 OR v_active IS DISTINCT FROM 3 THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Member wallet unavailable';
  END IF;

  -- Member wallet accounts are liability-style accounts: credits increase the
  -- member-visible balance and debits decrease it. Provider clearing uses a
  -- different accounting side and is never projected by this member RPC.
  SELECT
    COALESCE(sum(CASE WHEN p.direction='credit' THEN p.amount_minor::numeric ELSE -p.amount_minor::numeric END)
      FILTER (WHERE a.account_kind='member_available'), 0),
    COALESCE(sum(CASE WHEN p.direction='credit' THEN p.amount_minor::numeric ELSE -p.amount_minor::numeric END)
      FILTER (WHERE a.account_kind='member_held'), 0),
    COALESCE(sum(CASE WHEN p.direction='credit' THEN p.amount_minor::numeric ELSE -p.amount_minor::numeric END)
      FILTER (WHERE a.account_kind='member_withdrawable'), 0)
  INTO v_available, v_held, v_withdrawable
  FROM private.wallet_accounts a
  LEFT JOIN private.wallet_postings p ON p.account_id=a.id
  WHERE a.member_id=v_caller
    AND a.currency='NGN'
    AND a.status='active'
    AND a.account_kind IN ('member_available','member_held','member_withdrawable');

  IF v_available < 0 OR v_held < 0 OR v_withdrawable < 0
     OR v_available > v_bigint_max
     OR v_held > v_bigint_max
     OR v_withdrawable > v_bigint_max THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Member wallet unavailable';
  END IF;

  RETURN QUERY
  SELECT 'NGN'::text, true,
    v_available::bigint,
    v_held::bigint,
    v_withdrawable::bigint;
END;

DECLARE
  v_intent private.offering_movement_intents%ROWTYPE;
  v_origin_id uuid;
  v_destination_id uuid;
  v_origin private.movement_location_references%ROWTYPE;
  v_destination private.movement_location_references%ROWTYPE;
  v_now timestamptz;
BEGIN
  IF p_offering_movement_intent_id IS NULL
     OR p_offering_member_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '22004',
      MESSAGE = 'Offering movement intent and member are required';
  END IF;

  SELECT i.*
  INTO v_intent
  FROM private.offering_movement_intents i
  WHERE i.id = p_offering_movement_intent_id
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'Offering movement intent not found';
  END IF;

  v_now := clock_timestamp();

  IF v_intent.offering_member_id <> p_offering_member_id THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'Offering movement intent does not belong to member';
  END IF;

  IF v_intent.status <> 'current'
     OR (
       v_intent.expires_at IS NOT NULL
       AND v_intent.expires_at <= v_now
     ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Offering movement intent is not eligible for route generation';
  END IF;

  PERFORM private.assert_offering_movement_intent(v_intent.id);

  SELECT il.location_reference_id
  INTO STRICT v_origin_id
  FROM private.offering_movement_intent_locations il
  WHERE il.intent_id = v_intent.id
    AND il.role = 'origin';

  SELECT il.location_reference_id
  INTO STRICT v_destination_id
  FROM private.offering_movement_intent_locations il
  WHERE il.intent_id = v_intent.id
    AND il.role = 'destination';

  IF v_origin_id = v_destination_id THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Route generation requires distinct origin and destination';
  END IF;

  SELECT lr.*
  INTO STRICT v_origin
  FROM private.movement_location_references lr
  WHERE lr.id = v_origin_id
  FOR SHARE;

  SELECT lr.*
  INTO STRICT v_destination
  FROM private.movement_location_references lr
  WHERE lr.id = v_destination_id
  FOR SHARE;

  v_now := clock_timestamp();

  IF v_origin.owner_member_id <> v_intent.offering_member_id
     OR v_destination.owner_member_id <> v_intent.offering_member_id THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Route generation endpoint ownership is invalid';
  END IF;

  IF v_origin.resolution_status <> 'resolved'
     OR v_destination.resolution_status <> 'resolved'
     OR v_origin.source_kind <> 'provider_resolved'
     OR v_destination.source_kind <> 'provider_resolved' THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Route generation requires resolved provider endpoints';
  END IF;

  IF v_origin.latitude IS NULL
     OR v_origin.longitude IS NULL
     OR v_destination.latitude IS NULL
     OR v_destination.longitude IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Route generation coordinates are incomplete';
  END IF;

  IF NOT (v_origin.latitude BETWEEN -90 AND 90)
     OR NOT (v_origin.longitude BETWEEN -180 AND 180)
     OR NOT (v_destination.latitude BETWEEN -90 AND 90)
     OR NOT (v_destination.longitude BETWEEN -180 AND 180)
     OR v_origin.latitude::text IN ('NaN','Infinity','-Infinity')
     OR v_origin.longitude::text IN ('NaN','Infinity','-Infinity')
     OR v_destination.latitude::text IN ('NaN','Infinity','-Infinity')
     OR v_destination.longitude::text IN ('NaN','Infinity','-Infinity') THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Route generation coordinates are invalid';
  END IF;

  IF (
       v_origin.expires_at IS NOT NULL
       AND v_origin.expires_at <= v_now
     )
     OR (
       v_destination.expires_at IS NOT NULL
       AND v_destination.expires_at <= v_now
     ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Route generation endpoints are expired';
  END IF;

  RETURN QUERY
  SELECT
    v_intent.id,
    v_intent.offering_member_id,
    v_origin.id,
    v_origin.latitude,
    v_origin.longitude,
    v_destination.id,
    v_destination.latitude,
    v_destination.longitude;
END;

BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  RETURN QUERY
  SELECT concat_ws(' ', btrim(v.color), btrim(v.make), nullif(btrim(v.model), '')),
    v.plate_number
  FROM public.vehicles v
  -- Fail closed for historical plate-less vehicles or later trusted corrections.
  WHERE nullif(btrim(v.plate_number), '') IS NOT NULL AND EXISTS (
    SELECT 1 FROM private.post_activation_reveal_subjects(p_movement_need_id, auth.uid()) s
    WHERE s.vehicle_id = v.id
  );
END;

DECLARE
  v_member_id uuid := auth.uid();
  i private.requester_movement_interests%ROWTYPE;
BEGIN
  IF current_setting('transaction_isolation')<>'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000', MESSAGE='Interest reading requires READ COMMITTED';
  END IF;
  IF v_member_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Authenticated member required';
  END IF;
  IF p_interest_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='Interest is required';
  END IF;
  SELECT x.* INTO i FROM private.requester_movement_interests x
    WHERE x.id=p_interest_id AND x.offering_member_id=v_member_id AND x.status='active';
  IF NOT FOUND THEN RETURN; END IF;
  BEGIN
    PERFORM private.assert_requester_movement_interest(i.id);
  EXCEPTION WHEN check_violation OR no_data_found OR raise_exception OR insufficient_privilege THEN
    RETURN;
  END;
  RETURN QUERY
  SELECT i.id,n.id,od.discovery_area_label,dd.discovery_area_label,n.people_count,
    n.earliest_departure_at,n.latest_departure_at,e.requester_origin_distance_to_route_meters,i.created_at
  FROM public.movement_needs n
  JOIN private.trusted_route_match_evidence e ON e.id=i.route_match_evidence_id
  JOIN private.trusted_location_discovery_areas od ON od.resolved_location_reference_id=e.requester_origin_location_reference_id
  JOIN private.trusted_location_discovery_areas dd ON dd.resolved_location_reference_id=e.requester_destination_location_reference_id
  WHERE n.id=i.movement_need_id;
END;

DECLARE
  s private.movement_location_references%ROWTYPE;
  e private.movement_location_resolution_evidence%ROWTYPE;
  v_expiry timestamptz;
BEGIN
  s := private.require_verified_location_selection(p_verified_member_id,p_source_location_reference_id);
  IF p_producer_request_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Resolution operation identity is required';
  END IF;
  SELECT x.* INTO e FROM private.movement_location_resolution_evidence x WHERE x.producer_request_id=p_producer_request_id;
  IF FOUND THEN
    IF e.source_location_reference_id IS DISTINCT FROM s.id THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Resolution operation unavailable';
    END IF;
    PERFORM private.assert_movement_location_resolution_evidence(e.id);
    SELECT l.expires_at INTO v_expiry FROM private.movement_location_references l WHERE l.id=e.resolved_location_reference_id;
  END IF;
  RETURN QUERY SELECT s.provider_namespace,s.provider_place_reference,s.created_at,s.expires_at,
    e.id,e.resolved_location_reference_id,e.version,v_expiry;
END;

DECLARE
  s private.movement_location_references%ROWTYPE;
  e private.movement_location_resolution_evidence%ROWTYPE;

  v_expiry timestamptz;
  v_has_state boolean := false;
BEGIN
  s :=
    private.require_verified_location_selection(
      p_verified_member_id,
      p_source_location_reference_id
    );

  IF p_producer_request_id IS NULL THEN
    RAISE EXCEPTION
      USING
        ERRCODE='23514',
        MESSAGE='Resolution operation identity is required';
  END IF;

  SELECT x.*
  INTO e
  FROM private.movement_location_resolution_evidence x
  WHERE x.producer_request_id
        =p_producer_request_id;

  IF FOUND THEN
    IF
      e.source_location_reference_id
        IS DISTINCT FROM s.id
    THEN
      RAISE EXCEPTION
        USING
          ERRCODE='23514',
          MESSAGE='Resolution operation unavailable';
    END IF;

    PERFORM
      private.assert_movement_location_resolution_evidence(
        e.id
      );

    SELECT l.expires_at
    INTO v_expiry
    FROM private.movement_location_references l
    WHERE l.id=e.resolved_location_reference_id;

    SELECT EXISTS (
      SELECT 1
      FROM private.trusted_location_state_evidence state
      WHERE state.resolution_evidence_id=e.id
    )
    INTO v_has_state;

    IF v_has_state THEN
      PERFORM
        private.assert_trusted_location_state_evidence(
          e.id
        );
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    s.provider_namespace,
    s.provider_place_reference,
    s.created_at,
    s.expires_at,
    e.id,
    e.resolved_location_reference_id,
    e.version,
    v_expiry,
    v_has_state;
END;

DECLARE
  v_id uuid;
  s private.movement_location_references%ROWTYPE;
BEGIN
  SELECT r.location_reference_id INTO v_id FROM private.movement_location_selection_receipts r WHERE r.request_id=p_selection_request_id;
  s := private.require_verified_location_selection(p_verified_member_id,v_id);
  RETURN QUERY SELECT s.id,s.declared_label;
END;

BEGIN
  INSERT INTO public.members (id)
  VALUES (NEW.id)
  ON CONFLICT (id) DO NOTHING;

  RETURN NEW;
END;

DECLARE caller uuid:=auth.uid(); g private.financial_agreements%ROWTYPE; evidence record; c private.financial_components%ROWTYPE;
 available_id uuid; held_id uuid; transaction_id uuid; funding_at timestamptz; stamp timestamptz;
 available_balance numeric; held_balance numeric; withdrawable_balance numeric; total bigint; active_count bigint;
BEGIN
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000',MESSAGE='Movement hold requires READ COMMITTED'; END IF;
  IF p_expected_agreement_version IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004',MESSAGE='Exact agreement version required'; END IF;
  g:=private.movement_funding_agreement(p_financial_agreement_id,caller,p_expected_agreement_version);
  -- Wallet gate AFTER shared financial locks. Existing provisioning/top-up also
  -- take member UPDATE before account locks. Hold never takes need/proposal UPDATE.
  PERFORM m.id FROM public.members m WHERE m.id=caller FOR UPDATE;
  SELECT * INTO evidence FROM private.movement_funding_evidence(g);
  IF evidence.fully_held_at IS NOT NULL THEN
    RETURN QUERY SELECT g.id,g.version,g.alignment_id,'held'::text,evidence.required_minor,evidence.held_minor,g.currency,evidence.fully_held_at; RETURN;
  END IF;
  IF g.status<>'current' OR NOT EXISTS(SELECT 1 FROM public.alignments a WHERE a.id=g.alignment_id
    AND a.status='awaiting_activation_payment' AND a.activated_at IS NULL) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='First funding requires current pre-activation agreement'; END IF;
  PERFORM x.id FROM private.wallet_accounts x WHERE x.member_id=caller AND x.currency=g.currency ORDER BY x.id FOR UPDATE;
  SELECT count(*),count(*) FILTER(WHERE x.status='active'),
    min(x.id::text) FILTER(WHERE x.account_kind='member_available')::uuid,
    min(x.id::text) FILTER(WHERE x.account_kind='member_held')::uuid
    INTO total,active_count,available_id,held_id FROM private.wallet_accounts x WHERE x.member_id=caller AND x.currency=g.currency;
  IF total<>3 OR active_count<>3 OR available_id IS NULL OR held_id IS NULL
    OR NOT EXISTS(SELECT 1 FROM private.wallet_accounts x WHERE x.member_id=caller AND x.currency=g.currency AND x.account_kind='member_withdrawable') THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Complete active requester wallet required'; END IF;
  SELECT coalesce(sum(CASE WHEN wp.direction='credit' THEN wp.amount_minor::numeric ELSE -wp.amount_minor::numeric END)
      FILTER(WHERE wa.account_kind='member_available'),0),
    coalesce(sum(CASE WHEN wp.direction='credit' THEN wp.amount_minor::numeric ELSE -wp.amount_minor::numeric END)
      FILTER(WHERE wa.account_kind='member_held'),0),
    coalesce(sum(CASE WHEN wp.direction='credit' THEN wp.amount_minor::numeric ELSE -wp.amount_minor::numeric END)
      FILTER(WHERE wa.account_kind='member_withdrawable'),0)
    INTO available_balance,held_balance,withdrawable_balance FROM private.wallet_accounts wa
    LEFT JOIN private.wallet_postings wp ON wp.account_id=wa.id WHERE wa.member_id=caller AND wa.currency=g.currency;
  IF available_balance<0 OR held_balance<0 OR withdrawable_balance<0
    OR available_balance>9223372036854775807::numeric OR withdrawable_balance>9223372036854775807::numeric
    OR held_balance+evidence.required_minor>9223372036854775807::numeric THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Requester wallet outside supported range'; END IF;
  IF available_balance<evidence.required_minor THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Insufficient available movement balance'; END IF;
  -- Defer only ledger construction checks, then explicitly drain them. No writes
  -- occur before all authorization, wallet, amount and insufficiency checks.
  SET CONSTRAINTS private.wallet_transaction_balanced_after_transaction,private.wallet_transaction_balanced_after_posting DEFERRED;
  FOR c IN SELECT x.* FROM private.financial_components x WHERE x.agreement_id=g.id
    AND x.component_key IN ('requester_platform_share','movement_contribution') AND x.amount_minor>0 ORDER BY x.id LOOP
    INSERT INTO private.wallet_transactions(transaction_kind,currency,alignment_id,financial_component_id,idempotency_key)
    VALUES('movement_hold',g.currency,g.alignment_id,c.id,'movement_hold:'||c.id::text) RETURNING id,created_at INTO transaction_id,stamp;
    INSERT INTO private.wallet_postings(transaction_id,account_id,direction,amount_minor)
    VALUES(transaction_id,available_id,'debit',c.amount_minor),(transaction_id,held_id,'credit',c.amount_minor);
    funding_at:=greatest(funding_at,stamp);
    PERFORM private.assert_wallet_transaction_balanced(transaction_id);
  END LOOP;
  -- Zero-only obligations use this immutable receipt's recorded completion time.
  INSERT INTO private.movement_funding_holds VALUES(g.id,coalesce(funding_at,clock_timestamp()));
  SELECT * INTO evidence FROM private.movement_funding_evidence(g);
  SET CONSTRAINTS private.wallet_transaction_balanced_after_transaction,private.wallet_transaction_balanced_after_posting IMMEDIATE;
  SET CONSTRAINTS private.wallet_transaction_balanced_after_transaction,private.wallet_transaction_balanced_after_posting DEFERRED;
  RETURN QUERY SELECT g.id,g.version,g.alignment_id,'held'::text,evidence.required_minor,evidence.held_minor,g.currency,evidence.fully_held_at;
END;

DECLARE
  v_caller_member_id uuid;
  v_need_record public.movement_needs%ROWTYPE;
  v_target_member_exists boolean;
  v_existing_participant public.movement_participants%ROWTYPE;
  v_new_participant_id uuid;
  v_invited_at timestamptz;
  v_active_slot_count integer;
BEGIN
  v_caller_member_id := auth.uid();
  
  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  -- Fetch and lock the movement need FIRST (consistent lock order)
  SELECT *
  INTO v_need_record
  FROM public.movement_needs mn
  WHERE mn.id = p_movement_need_id
  FOR UPDATE;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Movement need not found';
  END IF;
  
  -- Caller must own the movement need
  IF v_need_record.member_id <> v_caller_member_id THEN
    RAISE EXCEPTION 'Only the movement need owner may invite participants';
  END IF;
  
  -- Movement need must still be discoverable
  IF v_need_record.status <> 'discoverable' THEN
    RAISE EXCEPTION 'Movement need is not discoverable; cannot invite participants';
  END IF;
  
  -- Caller cannot invite themselves
  IF p_member_id = v_caller_member_id THEN
    RAISE EXCEPTION 'You cannot invite yourself';
  END IF;
  
  -- Target member must exist
  SELECT EXISTS(
    SELECT 1
    FROM public.members m
    WHERE m.id = p_member_id
  ) INTO v_target_member_exists;
  
  IF NOT v_target_member_exists THEN
    RAISE EXCEPTION 'Target member does not exist';
  END IF;
  
  -- Check for existing participant row (with lock to prevent concurrent updates)
  SELECT *
  INTO v_existing_participant
  FROM public.movement_participants mp
  WHERE mp.movement_need_id = p_movement_need_id
    AND mp.member_id = p_member_id
  FOR UPDATE;
  
  IF FOUND THEN
    -- Already confirmed: reject clearly
    IF v_existing_participant.status = 'confirmed' THEN
      RAISE EXCEPTION 'This member is already a confirmed participant';
    END IF;
    
    -- Already invited: idempotent return
    IF v_existing_participant.status = 'invited' THEN
      RETURN QUERY
      SELECT
        v_existing_participant.id,
        v_existing_participant.movement_need_id,
        v_existing_participant.status,
        v_existing_participant.invited_at;
      RETURN;
    END IF;
    
    -- Declined or removed: allow re-invitation, but check capacity first
    IF v_existing_participant.status IN ('declined', 'removed') THEN
      -- Check current active slots (before re-inviting this member)
      SELECT COUNT(*)
      INTO v_active_slot_count
      FROM public.movement_participants mp
      WHERE mp.movement_need_id = p_movement_need_id
        AND mp.status IN ('confirmed', 'invited');
      
      IF v_active_slot_count >= v_need_record.people_count THEN
        RAISE EXCEPTION 'Movement group already has all declared traveller slots filled';
      END IF;
      
      UPDATE public.movement_participants mp
      SET
        status = 'invited',
        invited_by_member_id = v_caller_member_id,
        invited_at = NOW(),
        responded_at = NULL,
        updated_at = NOW()
      WHERE mp.id = v_existing_participant.id;
      
      v_invited_at := NOW();
      v_new_participant_id := v_existing_participant.id;
    END IF;
  ELSE
    -- New invitation: check capacity first
    SELECT COUNT(*)
    INTO v_active_slot_count
    FROM public.movement_participants mp
    WHERE mp.movement_need_id = p_movement_need_id
      AND mp.status IN ('confirmed', 'invited');
    
    IF v_active_slot_count >= v_need_record.people_count THEN
      RAISE EXCEPTION 'Movement group already has all declared traveller slots filled';
    END IF;
    
    INSERT INTO public.movement_participants (
      movement_need_id,
      member_id,
      role,
      status,
      invited_by_member_id,
      invited_at,
      responded_at,
      created_at,
      updated_at
    )
    VALUES (
      p_movement_need_id,
      p_member_id,
      'invited_participant',
      'invited',
      v_caller_member_id,
      NOW(),
      NULL,
      NOW(),
      NOW()
    )
    RETURNING public.movement_participants.id, public.movement_participants.invited_at
    INTO v_new_participant_id, v_invited_at;
  END IF;
  
  RETURN QUERY
  SELECT
    v_new_participant_id,
    p_movement_need_id,
    'invited'::text,
    v_invited_at;
END;

DECLARE
  v_caller_member_id uuid;
  v_share_record private.member_profile_shares%ROWTYPE;
  v_target_member_id uuid;
  v_need_record public.movement_needs%ROWTYPE;
  v_target_member_exists boolean;
  v_existing_participant public.movement_participants%ROWTYPE;
  v_new_participant_id uuid;
  v_invited_at timestamptz;
  v_active_slot_count integer;
BEGIN
  v_caller_member_id := auth.uid();
  
  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  -- Validate share token input
  IF p_share_token IS NULL OR trim(p_share_token) = '' THEN
    RAISE EXCEPTION 'Share token is required';
  END IF;
  
    -- Initial token read WITHOUT row lock.
  -- We only use this first read to identify the intended target member.
  SELECT *
  INTO v_share_record
  FROM private.member_profile_shares mps
  WHERE mps.share_token = p_share_token;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Share token not found';
  END IF;

  v_target_member_id := v_share_record.member_id;

  -- Lock the movement need FIRST so all group mutations serialize
  -- consistently through the movement need.
  SELECT *
  INTO v_need_record
  FROM public.movement_needs mn
  WHERE mn.id = p_movement_need_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Movement need not found';
  END IF;

  -- Caller must own the movement need.
  IF v_need_record.member_id <> v_caller_member_id THEN
    RAISE EXCEPTION 'Only the movement need owner may invite participants';
  END IF;

  -- Movement need must still be discoverable.
  IF v_need_record.status <> 'discoverable' THEN
    RAISE EXCEPTION 'Movement need is not discoverable; cannot invite participants';
  END IF;

  -- Re-read and lock the SAME share token AFTER movement_need is locked.
  -- This second read is authoritative and protects against concurrent revocation.
  SELECT *
  INTO v_share_record
  FROM private.member_profile_shares mps
  WHERE mps.share_token = p_share_token
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Share token not found';
  END IF;

  -- Token must still resolve to the same target member.
  IF v_share_record.member_id <> v_target_member_id THEN
    RAISE EXCEPTION 'Share token target changed unexpectedly';
  END IF;

  -- Token must still be active.
  IF v_share_record.status = 'revoked' THEN
    RAISE EXCEPTION 'This share has been revoked';
  END IF;

  IF v_share_record.status <> 'active' THEN
    RAISE EXCEPTION 'This share token is not active';
  END IF;

  -- Token must still be unexpired.
  IF v_share_record.expires_at <= NOW() THEN
    RAISE EXCEPTION 'This share token has expired';
  END IF;
  
  -- Caller cannot invite themselves
  IF v_target_member_id = v_caller_member_id THEN
    RAISE EXCEPTION 'You cannot invite yourself';
  END IF;
  
  -- Target member must exist
  SELECT EXISTS(
    SELECT 1
    FROM public.members m
    WHERE m.id = v_target_member_id
  ) INTO v_target_member_exists;
  
  IF NOT v_target_member_exists THEN
    RAISE EXCEPTION 'Target member does not exist';
  END IF;
  
  -- Check for existing participant row (with lock)
  SELECT *
  INTO v_existing_participant
  FROM public.movement_participants mp
  WHERE mp.movement_need_id = p_movement_need_id
    AND mp.member_id = v_target_member_id
  FOR UPDATE;
  
  IF FOUND THEN
    -- Already confirmed: reject clearly
    IF v_existing_participant.status = 'confirmed' THEN
      RAISE EXCEPTION 'This member is already a confirmed participant';
    END IF;
    
    -- Already invited: idempotent return
    IF v_existing_participant.status = 'invited' THEN
      RETURN QUERY
      SELECT
        v_existing_participant.id,
        v_existing_participant.movement_need_id,
        v_existing_participant.status,
        v_existing_participant.invited_at;
      RETURN;
    END IF;
    
    -- Declined or removed: allow re-invitation, but check capacity first
    IF v_existing_participant.status IN ('declined', 'removed') THEN
      -- Check current active slots (before re-inviting this member)
      SELECT COUNT(*)
      INTO v_active_slot_count
      FROM public.movement_participants mp
      WHERE mp.movement_need_id = p_movement_need_id
        AND mp.status IN ('confirmed', 'invited');
      
      IF v_active_slot_count >= v_need_record.people_count THEN
        RAISE EXCEPTION 'Movement group already has all declared traveller slots filled';
      END IF;
      
      UPDATE public.movement_participants mp
      SET
        status = 'invited',
        invited_by_member_id = v_caller_member_id,
        invited_at = NOW(),
        responded_at = NULL,
        updated_at = NOW()
      WHERE mp.id = v_existing_participant.id;
      
      v_invited_at := NOW();
      v_new_participant_id := v_existing_participant.id;
    END IF;
  ELSE
    -- New invitation: check capacity first
    SELECT COUNT(*)
    INTO v_active_slot_count
    FROM public.movement_participants mp
    WHERE mp.movement_need_id = p_movement_need_id
      AND mp.status IN ('confirmed', 'invited');
    
    IF v_active_slot_count >= v_need_record.people_count THEN
      RAISE EXCEPTION 'Movement group already has all declared traveller slots filled';
    END IF;
    
    INSERT INTO public.movement_participants (
      movement_need_id,
      member_id,
      role,
      status,
      invited_by_member_id,
      invited_at,
      responded_at,
      created_at,
      updated_at
    )
    VALUES (
      p_movement_need_id,
      v_target_member_id,
      'invited_participant',
      'invited',
      v_caller_member_id,
      NOW(),
      NULL,
      NOW(),
      NOW()
    )
    RETURNING public.movement_participants.id, public.movement_participants.invited_at
    INTO v_new_participant_id, v_invited_at;
  END IF;
  
  RETURN QUERY
  SELECT
    v_new_participant_id,
    p_movement_need_id,
    'invited'::text,
    v_invited_at;
END;

DECLARE
  q private.pricing_quotes%ROWTYPE;
  s private.movement_context_snapshots%ROWTYPE;
  p private.financial_proposals%ROWTYPE;
  previous private.financial_proposals%ROWTYPE;
  economics record;
  replay_count bigint;
  next_version bigint;
BEGIN
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000', MESSAGE='Financial proposal issuer requires READ COMMITTED';
  END IF;
  IF p_pricing_quote_id IS NULL OR p_expected_pricing_quote_version IS NULL
    OR p_movement_context_snapshot_id IS NULL OR p_expected_movement_context_snapshot_version IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='Complete exact proposal source identities required';
  END IF;
  IF p_expected_pricing_quote_version<1 OR p_expected_movement_context_snapshot_version<1 THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Positive expected proposal source versions required';
  END IF;

  -- Discover immutable selectors without locking quote/snapshot/history first.
  SELECT x.* INTO q FROM private.pricing_quotes x WHERE x.id=p_pricing_quote_id;
  IF NOT FOUND OR q.version IS DISTINCT FROM p_expected_pricing_quote_version THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Exact proposal pricing quote unavailable';
  END IF;
  SELECT x.* INTO s FROM private.movement_context_snapshots x WHERE x.id=p_movement_context_snapshot_id;
  IF NOT FOUND OR s.version IS DISTINCT FROM p_expected_movement_context_snapshot_version THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Exact proposal movement snapshot unavailable';
  END IF;
  -- Reject cross-need/intent selectors before they can acquire a second need lock.
  p.pricing_quote_id:=q.id;
  p.movement_context_snapshot_id:=s.id;
  PERFORM private.assert_financial_proposal_source_compatibility(p);

  -- 0045 owns need UPDATE -> offer UPDATE -> requester endpoints -> intent
  -- UPDATE -> route -> availability UPDATE -> vehicle/access. Strong locks first.
  PERFORM private.assert_movement_offer_availability_binding(s.movement_offer_id);
  PERFORM private.assert_pricing_quote(q.id);
  PERFORM private.assert_movement_context_snapshot_offer_binding(s);
  PERFORM private.assert_movement_context_snapshot(s.id);
  -- The need UPDATE lock serializes this scope even when history is empty.
  PERFORM x.id FROM private.financial_proposals x
    WHERE x.movement_need_id=s.movement_need_id AND x.offering_member_id=s.offering_member_id
    ORDER BY x.version FOR UPDATE;
  -- Fresh eligibility and clock checks after all waits, with dependencies retained.
  PERFORM private.assert_movement_offer_availability_binding(s.movement_offer_id);
  PERFORM private.assert_pricing_quote(q.id);
  PERFORM private.assert_movement_context_snapshot(s.id);
  SELECT x.* INTO STRICT q FROM private.pricing_quotes x WHERE x.id=p_pricing_quote_id;
  SELECT x.* INTO STRICT s FROM private.movement_context_snapshots x WHERE x.id=p_movement_context_snapshot_id;

  p.id:=gen_random_uuid();
  p.movement_need_id:=s.movement_need_id;
  p.offering_member_id:=s.offering_member_id;
  p.member_needing_movement_id:=s.requesting_member_id;
  p.vehicle_id:=s.vehicle_id;
  p.financial_model_version:='shared_platform_fee_v1';
  p.platform_fee_allocation_policy_version:='equal_split_requester_remainder_v1';
  p.pricing_policy_version:=q.pricing_policy_version;
  p.currency:=q.currency;
  SELECT * INTO STRICT economics FROM private.calculate_financial_proposal_economics(
    q.seat_price_minor,s.people_count,p.financial_model_version,p.platform_fee_allocation_policy_version);
  p.quoted_platform_fee_total_minor:=economics.quoted_platform_fee_total_minor;
  p.quoted_movement_contribution_minor:=economics.quoted_movement_contribution_minor;
  p.origin_area:=s.requester_origin_area;
  p.destination_area:=s.requester_destination_area;
  p.earliest_departure_at:=s.requester_earliest_departure_at;
  p.latest_departure_at:=s.requester_latest_departure_at;
  p.people_count:=s.people_count;
  p.seats_offered:=s.seats_offered;
  p.vehicle_seat_capacity:=s.vehicle_seat_capacity;
  p.proposed_pickup_area:=s.proposed_pickup_area;
  p.proposed_dropoff_area:=s.proposed_dropoff_area;
  p.estimated_arrival_minutes:=s.declared_arrival_minutes;
  p.route_evidence_id:=NULL;
  p.pricing_quote_id:=q.id;
  p.pricing_quote_version:=q.version;
  p.movement_context_snapshot_id:=s.id;
  p.movement_context_snapshot_version:=s.version;
  p.created_at:=clock_timestamp();
  p.expires_at:=least(q.expires_at,s.expires_at);
  p.status:='current';
  p.offering_accepted_at:=NULL;
  p.requester_accepted_at:=NULL;
  p.movement_offer_id:=NULL;
  p.alignment_id:=NULL;
  p.financial_agreement_id:=NULL;
  p.materialized_at:=NULL;
  PERFORM private.assert_financial_proposal_quote_binding(p);
  PERFORM private.assert_financial_proposal_movement_context_binding(p);
  PERFORM private.assert_financial_proposal_source_compatibility(p);

  -- Replay includes terminal proposal history, never resurrects it, and requires
  -- live eligible sources just like new issuance. Fail closed on ambiguous history.
  SELECT count(*) INTO replay_count FROM private.financial_proposals x
    WHERE x.pricing_quote_id=q.id AND x.pricing_quote_version=q.version
      AND x.movement_context_snapshot_id=s.id AND x.movement_context_snapshot_version=s.version
      AND x.financial_model_version=p.financial_model_version
      AND x.platform_fee_allocation_policy_version=p.platform_fee_allocation_policy_version;
  IF replay_count>1 THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Ambiguous financial proposal replay history';
  END IF;
  IF replay_count=1 THEN
    SELECT x.* INTO STRICT previous FROM private.financial_proposals x
      WHERE x.pricing_quote_id=q.id AND x.pricing_quote_version=q.version
        AND x.movement_context_snapshot_id=s.id AND x.movement_context_snapshot_version=s.version
        AND x.financial_model_version=p.financial_model_version
        AND x.platform_fee_allocation_policy_version=p.platform_fee_allocation_policy_version;
    IF (to_jsonb(previous)-ARRAY['id','version','created_at','expires_at','status',
        'offering_accepted_at','requester_accepted_at','movement_offer_id','alignment_id','financial_agreement_id','materialized_at'])
      IS DISTINCT FROM (to_jsonb(p)-ARRAY['id','version','created_at','expires_at','status',
        'offering_accepted_at','requester_accepted_at','movement_offer_id','alignment_id','financial_agreement_id','materialized_at']) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Financial proposal replay payload mismatch';
    END IF;
    PERFORM private.assert_financial_proposal_quote_binding(previous);
    PERFORM private.assert_financial_proposal_movement_context_binding(previous);
    PERFORM private.assert_financial_proposal_source_compatibility(previous);
    PERFORM private.assert_financial_proposal_snapshot_roster(previous.id);
    RETURN QUERY SELECT previous.id,previous.version,previous.status,previous.created_at,previous.expires_at;
    RETURN;
  END IF;

  SELECT coalesce(max(x.version)::bigint,0)+1 INTO next_version FROM private.financial_proposals x
    WHERE x.movement_need_id=s.movement_need_id AND x.offering_member_id=s.offering_member_id;
  IF next_version>2147483647 THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Financial proposal version exhausted';
  END IF;
  p.version:=next_version::integer;
  IF EXISTS (SELECT 1 FROM private.financial_proposals x
    WHERE x.movement_need_id=s.movement_need_id AND x.offering_member_id=s.offering_member_id
      AND x.status='current' AND (x.offering_accepted_at IS NOT NULL OR x.requester_accepted_at IS NOT NULL
        OR x.movement_offer_id IS NOT NULL OR x.alignment_id IS NOT NULL
        OR x.financial_agreement_id IS NOT NULL OR x.materialized_at IS NOT NULL)) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Progressed financial proposal cannot be superseded by issuance';
  END IF;
  -- Follow existing producer convention: scope construction deferral to the four
  -- parent/child checks, force final validation, then leave them normally deferred.
  SET CONSTRAINTS private.financial_proposal_complete,private.financial_proposal_roster_complete,
    private.financial_proposal_movement_context_complete,private.financial_proposal_snapshot_roster_complete DEFERRED;
  UPDATE private.financial_proposals x SET status='superseded'
    WHERE x.movement_need_id=s.movement_need_id AND x.offering_member_id=s.offering_member_id AND x.status='current';
  INSERT INTO private.financial_proposals SELECT p.*;
  INSERT INTO private.financial_proposal_travellers(proposal_id,member_id,participant_id,role)
    SELECT p.id,t.member_id,t.movement_participant_id,t.role
    FROM private.movement_context_snapshot_travellers t WHERE t.snapshot_id=s.id ORDER BY t.movement_participant_id;
  PERFORM private.assert_financial_proposal_snapshot_roster(p.id);
  SET CONSTRAINTS private.financial_proposal_complete,private.financial_proposal_roster_complete,
    private.financial_proposal_movement_context_complete,private.financial_proposal_snapshot_roster_complete IMMEDIATE;
  SET CONSTRAINTS private.financial_proposal_complete,private.financial_proposal_roster_complete,
    private.financial_proposal_movement_context_complete,private.financial_proposal_snapshot_roster_complete DEFERRED;
  RETURN QUERY SELECT p.id,p.version,p.status,p.created_at,p.expires_at;
END;

DECLARE
  v_member_id uuid := auth.uid();
  v_candidate record;
  v_visible boolean;
  v_returned integer := 0;
BEGIN
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION USING ERRCODE = '25000', MESSAGE = 'Availability recovery requires READ COMMITTED';
  END IF;
  IF v_member_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.members m WHERE m.id = v_member_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Authenticated member required';
  END IF;
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Recovery limit must be between 1 and 50';
  END IF;

  <<candidates>>
  FOR v_candidate IN
    SELECT a.id
    FROM private.offering_movement_availability a
    JOIN private.offering_movement_intents i ON i.id = a.offering_movement_intent_id
    WHERE a.offering_member_id = v_member_id
    ORDER BY i.earliest_departure_at ASC, a.created_at ASC, a.id ASC
  LOOP
    v_visible := false;
    BEGIN
      -- Only eligibility failures from the existing assertion are skippable.
      -- Projection errors, deadlocks, cancellations and other SQL errors escape.
      BEGIN
        PERFORM private.assert_offering_movement_availability(v_candidate.id);
      EXCEPTION WHEN check_violation OR no_data_found THEN
        CONTINUE candidates;
      END;

      SELECT a.id, a.offering_movement_intent_id, a.vehicle_id,
        a.total_places, a.remaining_places, a.expires_at,
        od.discovery_area_label, dd.discovery_area_label,
        i.earliest_departure_at, i.latest_departure_at,
        v.make, v.model, v.year, v.color
      INTO availability_id, offering_movement_intent_id, vehicle_id,
        total_places, remaining_places, expires_at, origin_area, destination_area,
        earliest_departure_at, latest_departure_at,
        vehicle_make, vehicle_model, vehicle_year, vehicle_color
      FROM private.offering_movement_availability a
      JOIN private.offering_movement_intents i ON i.id = a.offering_movement_intent_id
      JOIN private.offering_route_evidence e ON e.id = a.route_evidence_id
      JOIN private.trusted_location_discovery_areas od
        ON od.resolved_location_reference_id = e.origin_location_reference_id
      JOIN private.trusted_location_discovery_areas dd
        ON dd.resolved_location_reference_id = e.destination_location_reference_id
      JOIN public.vehicles v ON v.id = a.vehicle_id
      WHERE a.id = v_candidate.id AND a.offering_member_id = v_member_id;
      v_visible := FOUND;

      -- As in 0048, release validation locks before acquiring the next intent.
      -- Subtransaction rollback releases locks; local output variables survive.
      RAISE SQLSTATE 'ZX054' USING MESSAGE = 'Release recovery candidate locks';
    EXCEPTION WHEN SQLSTATE 'ZX054' THEN
      NULL;
    END;
    IF v_visible THEN
      RETURN NEXT;
      v_returned := v_returned + 1;
      EXIT candidates WHEN v_returned >= p_limit;
    END IF;
  END LOOP candidates;
END;

DECLARE
  v_member_id uuid := auth.uid();
  v_candidate record;
  v_visible boolean;
  v_returned integer := 0;
BEGIN
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION USING
      ERRCODE = '25000', MESSAGE = 'Interest inbox requires READ COMMITTED';
  END IF;
  IF v_member_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.members m WHERE m.id = v_member_id
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501', MESSAGE = 'Authenticated member required';
  END IF;
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514', MESSAGE = 'Inbox limit must be between 1 and 50';
  END IF;

  -- Missing and foreign availability ids are indistinguishable to the caller.
  IF p_availability_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM private.offering_movement_availability a
    WHERE a.id = p_availability_id AND a.offering_member_id = v_member_id
  ) THEN
    RETURN;
  END IF;

  -- Candidate selection is private and ownership-scoped. The result limit is
  -- applied AFTER authoritative validation, so stale history cannot crowd out
  -- later actionable interests. The existing 0047 offerer index supports order.
  <<candidates>>
  FOR v_candidate IN
    SELECT i.id
    FROM private.requester_movement_interests i
    JOIN private.offering_movement_availability a ON a.id = i.availability_id
    WHERE i.offering_member_id = v_member_id
      AND a.offering_member_id = v_member_id
      AND i.status = 'active'
      AND i.expires_at > clock_timestamp()
      AND (p_availability_id IS NULL OR i.availability_id = p_availability_id)
    ORDER BY i.created_at ASC, i.id ASC
  LOOP
    v_visible := false;
    BEGIN
      -- Preserve 0047's complete authoritative support and lock contract.
      -- Expected eligibility exceptions are caught ONLY around this assertion;
      -- SQL/projection errors, deadlocks and cancellations propagate normally.
      BEGIN
        PERFORM private.assert_requester_movement_interest(v_candidate.id);
      EXCEPTION
        WHEN check_violation OR no_data_found THEN
          CONTINUE candidates;
        WHEN raise_exception THEN
          IF SQLERRM IN (
            'Movement need not found',
            'Offering movement availability not found',
            'Offering movement intent not found'
          ) THEN
            CONTINUE candidates;
          END IF;
          RAISE;
        WHEN insufficient_privilege THEN
          IF SQLERRM IN (
            'Verified member does not own this movement need',
            'Offering movement intent does not belong to member'
          ) THEN
            CONTINUE candidates;
          END IF;
          RAISE;
      END;

      -- Project only the established 0047 safe fields, plus availability id.
      -- No precise-label fallback and no profile/contact/media expansion.
      SELECT i.id, n.id, a.id,
        od.discovery_area_label, dd.discovery_area_label, n.people_count,
        n.earliest_departure_at, n.latest_departure_at,
        e.requester_origin_distance_to_route_meters, i.created_at
      INTO interest_id, movement_need_id, availability_id,
        origin_area, destination_area, people_count,
        earliest_departure_at, latest_departure_at,
        requester_origin_distance_to_route_meters, interest_created_at
      FROM private.requester_movement_interests i
      JOIN private.offering_movement_availability a ON a.id = i.availability_id
      JOIN public.movement_needs n ON n.id = i.movement_need_id
      JOIN private.trusted_route_match_evidence e ON e.id = i.route_match_evidence_id
      JOIN private.trusted_location_discovery_areas od
        ON od.resolved_location_reference_id = e.requester_origin_location_reference_id
      JOIN private.trusted_location_discovery_areas dd
        ON dd.resolved_location_reference_id = e.requester_destination_location_reference_id
      WHERE i.id = v_candidate.id
        AND i.offering_member_id = v_member_id
        AND a.offering_member_id = v_member_id
        AND i.status = 'active'
        AND i.expires_at > clock_timestamp();
      v_visible := FOUND;

      -- Release this candidate's validation locks even on success. Otherwise
      -- a multi-need inbox would hold intent/availability locks from one need
      -- while acquiring the next need lock, reversing 0045/0046's lock order.
      -- PostgreSQL exception rollback releases locks acquired in this block;
      -- local output variables survive. ZX048 is an internal control signal,
      -- never a caught database-error category. There are no persistent writes.
      -- https://www.postgresql.org/docs/current/explicit-locking.html
      RAISE SQLSTATE 'ZX048' USING MESSAGE = 'Release inbox candidate locks';
    EXCEPTION WHEN SQLSTATE 'ZX048' THEN
      NULL;
    END;

    IF v_visible THEN
      RETURN NEXT;
      v_returned := v_returned + 1;
      EXIT candidates WHEN v_returned >= p_limit;
    END IF;
  END LOOP candidates;
END;

DECLARE
  v_payment_record private.alignment_activation_payments%ROWTYPE;
  v_alignment_record public.alignments%ROWTYPE;
  v_provider_reference text;
  v_activated_at timestamptz;
BEGIN
  IF EXISTS(SELECT 1 FROM private.alignment_activation_payments ap WHERE ap.id=p_payment_id AND private.is_financial_alignment(ap.alignment_id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial movement requires funded activation'; END IF;
  SELECT *
  INTO v_payment_record
  FROM private.alignment_activation_payments AS ap
  WHERE ap.id = p_payment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payment not found';
  END IF;

  SELECT *
  INTO v_alignment_record
  FROM public.alignments AS a
  WHERE a.id = v_payment_record.alignment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alignment not found';
  END IF;

  IF v_payment_record.payer_member_id <> v_alignment_record.offering_member_id THEN
    RAISE EXCEPTION 'Payment payer does not match the alignment offering member';
  END IF;

  IF v_alignment_record.activation_fee_minor IS DISTINCT FROM v_payment_record.amount_minor
    OR v_alignment_record.activation_currency IS DISTINCT FROM v_payment_record.currency THEN
    RAISE EXCEPTION 'Payment amount or currency does not match alignment activation fee';
  END IF;

  IF v_payment_record.status = 'succeeded' AND v_alignment_record.status = 'activated' THEN
    RETURN QUERY
    SELECT
      v_alignment_record.id,
      v_alignment_record.status,
      v_alignment_record.activated_at;
    RETURN;
  END IF;

  IF v_payment_record.status <> 'pending' THEN
    RAISE EXCEPTION 'Payment is not pending';
  END IF;

  IF v_alignment_record.status <> 'awaiting_activation_payment' THEN
    RAISE EXCEPTION 'Alignment is not awaiting activation payment';
  END IF;

  v_provider_reference := p_provider_reference;
  IF v_provider_reference IS NOT NULL THEN
    v_provider_reference := trim(v_provider_reference);
    IF v_provider_reference = '' THEN
      v_provider_reference := NULL;
    END IF;
    IF length(v_provider_reference) > 255 THEN
      RAISE EXCEPTION 'Provider reference must be 255 characters or fewer';
    END IF;
  END IF;

  UPDATE private.alignment_activation_payments AS ap
  SET
    status = 'succeeded',
    provider_reference = v_provider_reference,
    succeeded_at = NOW(),
    updated_at = NOW()
  WHERE ap.id = p_payment_id;

  UPDATE public.alignments AS a
  SET
    status = 'activated',
    activated_at = NOW(),
    updated_at = NOW()
  WHERE a.id = v_alignment_record.id
  RETURNING a.activated_at
  INTO v_activated_at;

  RETURN QUERY
  SELECT
    v_alignment_record.id,
    'activated'::text,
    v_activated_at;
END;

DECLARE a public.alignments%ROWTYPE; j public.journeys%ROWTYPE; g uuid; stamp timestamptz; next_id uuid;
BEGIN
 a:=private.funded_coordination_alignment(p_movement_need_id);
 IF EXISTS(SELECT 1 FROM public.journeys WHERE alignment_id=a.id)
  OR EXISTS(SELECT 1 FROM private.funded_movement_coordination_entries WHERE alignment_id=a.id) THEN
  PERFORM x.id FROM public.journeys x WHERE x.alignment_id=a.id FOR SHARE;
  j:=private.assert_funded_coordination_entry(a.id);
 ELSE
  SELECT financial_agreement_id INTO STRICT g FROM private.funded_movement_activations WHERE alignment_id=a.id;
  stamp:=clock_timestamp(); next_id:=gen_random_uuid();
  -- Receipt precedes the journey so the INSERT guard can require exact provenance.
  -- Defer only this new FK, drain it immediately, and roll its mode back on error.
  BEGIN
   SET CONSTRAINTS private.funded_coordination_entry_journey_fk DEFERRED;
   INSERT INTO private.funded_movement_coordination_entries VALUES(g,a.id,next_id,stamp);
   INSERT INTO public.journeys(id,alignment_id,vehicle_id,status,created_at,updated_at)
    SELECT next_id,a.id,o.vehicle_id,'not_started',stamp,stamp FROM public.movement_offers o WHERE o.id=a.movement_offer_id;
   j:=private.assert_funded_coordination_entry(a.id);
   SET CONSTRAINTS private.funded_coordination_entry_journey_fk IMMEDIATE;
  EXCEPTION WHEN OTHERS THEN RAISE;
  END;
 END IF;
 RETURN QUERY SELECT p_movement_need_id,j.status,true;
END;

DECLARE a public.alignments%ROWTYPE; d private.funded_movement_disputes%ROWTYPE;
BEGIN
 IF p_reason_category IS NULL OR p_reason_category NOT IN('unable_to_agree','movement_concern') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Bounded dispute category required'; END IF;
 a:=private.funded_dispute_alignment(p_movement_need_id);
 PERFORM m.id FROM public.members m WHERE m.id IN(a.offering_member_id,a.member_needing_movement_id) ORDER BY m.id FOR UPDATE;
 PERFORM private.assert_funded_dispute(a.id);
 SELECT * INTO d FROM private.funded_movement_disputes WHERE alignment_id=a.id;
 IF d.alignment_id IS NOT NULL THEN
  IF d.opened_by_member_id IS DISTINCT FROM auth.uid() OR d.reason_category IS DISTINCT FROM p_reason_category THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Conflicting dispute opening'; END IF;
 ELSE
  IF a.status<>'activated' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Pre-start dispute required'; END IF;
  INSERT INTO private.funded_movement_disputes
   -- Observe once after construction locks. Provenance/state establish causality;
   -- this sample may equal or precede earlier server timestamps (0082).
   SELECT a.id,e.financial_agreement_id,e.journey_id,auth.uid(),clock_timestamp(),p_reason_category
   FROM private.funded_movement_coordination_entries e WHERE e.alignment_id=a.id;
 END IF;
 RETURN QUERY SELECT * FROM public.get_my_funded_movement_dispute_status(p_movement_need_id);
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement review unavailable';
END;

DECLARE
  v_member_id uuid := auth.uid();
  i private.offering_movement_intents%ROWTYPE;
  e private.offering_route_evidence%ROWTYPE;
  a private.offering_movement_availability%ROWTYPE;
  v_id uuid;
BEGIN
  IF current_setting('transaction_isolation')<>'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000', MESSAGE='Availability opening requires READ COMMITTED';
  END IF;
  IF v_member_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.members m WHERE m.id=v_member_id) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Authenticated member required';
  END IF;
  IF p_request_id IS NULL OR p_offering_movement_intent_id IS NULL OR p_vehicle_id IS NULL
    OR p_total_places IS NULL OR p_total_places<1 THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Availability request, intent, vehicle and positive places are required';
  END IF;
  -- Serialize this member/request pair even when conflicting retries name
  -- different intents. Hash collisions only serialize unrelated requests.
  PERFORM pg_advisory_xact_lock(hashtextextended('availability:'||v_member_id::text||':'||p_request_id::text,0));
  SELECT x.* INTO i FROM private.offering_movement_intents x
    WHERE x.id=p_offering_movement_intent_id AND x.offering_member_id=v_member_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Own offering movement intent required';
  END IF;
  SELECT x.* INTO a FROM private.offering_movement_availability x
    WHERE x.offering_member_id=v_member_id AND x.request_id=p_request_id;
  IF FOUND THEN
    IF a.offering_movement_intent_id IS DISTINCT FROM i.id
      OR a.vehicle_id IS DISTINCT FROM p_vehicle_id OR a.total_places IS DISTINCT FROM p_total_places THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Availability request replay does not match';
    END IF;
    -- An old request never rebinds to a newer route or resets capacity.
    PERFORM private.assert_offering_movement_availability(a.id);
    RETURN QUERY SELECT a.id;
    RETURN;
  END IF;
  PERFORM private.assert_offering_movement_intent(i.id);
  SELECT x.* INTO e FROM private.offering_route_evidence x
    WHERE x.offering_movement_intent_id=i.id AND x.offering_member_id=v_member_id AND x.status='current' FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Current trusted route for own intent required';
  END IF;
  PERFORM private.assert_offering_route_evidence(e.id);
  IF EXISTS(SELECT 1 FROM private.offering_movement_availability x WHERE x.offering_movement_intent_id=i.id) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Intent already has an availability lifetime';
  END IF;
  INSERT INTO private.offering_movement_availability(
    request_id,offering_movement_intent_id,offering_member_id,route_evidence_id,route_evidence_version,
    vehicle_id,total_places,remaining_places,expires_at
  ) VALUES (
    p_request_id,i.id,v_member_id,e.id,e.version,p_vehicle_id,p_total_places,p_total_places,
    LEAST(i.earliest_departure_at,i.expires_at,e.expires_at)
  ) RETURNING id INTO v_id;
  -- The immediate INSERT assertion locks/checks vehicle access and capacity,
  -- and revalidates every trusted binding before this RPC can return success.
  RETURN QUERY SELECT v_id;
END;

DECLARE v_member uuid; v_submission private.profile_photo_submissions%ROWTYPE; v_media uuid;
BEGIN
  SELECT member_id INTO v_member FROM private.profile_photo_submissions WHERE id=p_submission_id;
  PERFORM 1 FROM public.members WHERE id=v_member FOR UPDATE;
  SELECT * INTO v_submission FROM private.profile_photo_submissions WHERE id=p_submission_id FOR UPDATE;
  IF NOT FOUND OR v_submission.status <> 'pending' THEN RAISE EXCEPTION 'Submission is not pending'; END IF;
  IF NOT private.valid_face_object_key(p_processed_storage_path) THEN RAISE EXCEPTION 'Invalid processed photo key'; END IF;
  -- Serialize key allocation across members without imposing a new uniqueness
  -- constraint on historical media. Hash collisions only cause extra waiting.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_processed_storage_path,16));
  IF EXISTS (SELECT 1 FROM public.member_media WHERE storage_path=p_processed_storage_path) THEN
    RAISE EXCEPTION 'Processed photo key has already been used';
  END IF;
  UPDATE public.member_media SET is_current=false WHERE member_id=v_member AND media_type='photo' AND is_current;
  INSERT INTO public.member_media(member_id,media_type,storage_path,verified,is_current)
  VALUES (v_member,'photo',p_processed_storage_path,false,true) RETURNING id INTO v_media;
  UPDATE public.members SET profile_media_verified=false WHERE id=v_member;
  UPDATE private.profile_photo_submissions SET status='superseded' WHERE member_id=v_member AND status='ready';
  UPDATE private.profile_photo_submissions SET status='ready',media_id=v_media,processed_at=clock_timestamp() WHERE id=p_submission_id;
  -- Success is historical evidence. Exact-current-media readiness invalidates
  -- old successes without rewriting their result, timestamps or provider data.
  UPDATE private.alignment_face_verifications SET status='superseded' WHERE member_id=v_member AND status='pending';
  DELETE FROM private.post_activation_photo_tokens WHERE subject_member_id=v_member;
  RETURN v_media;
END;

DECLARE
  v_caller_member_id uuid;
  v_share_record private.member_profile_shares%ROWTYPE;
  v_member_record public.members%ROWTYPE;
BEGIN
  v_caller_member_id := auth.uid();
  
  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  -- Validate share token input
  IF p_share_token IS NULL OR trim(p_share_token) = '' THEN
    RAISE EXCEPTION 'Share token is required';
  END IF;
  
  -- Find the share token (share lock for concurrent-safe reads)
  SELECT *
  INTO v_share_record
  FROM private.member_profile_shares mps
  WHERE mps.share_token = p_share_token
  FOR SHARE;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Share token not found';
  END IF;
  
  -- Token must be active
  IF v_share_record.status = 'revoked' THEN
    RAISE EXCEPTION 'This share has been revoked';
  END IF;
  
  IF v_share_record.status <> 'active' THEN
    RAISE EXCEPTION 'This share token is not active';
  END IF;
  
  -- Check if expired (status may be 'active' but token can still expire)
  IF v_share_record.expires_at <= NOW() THEN
    RAISE EXCEPTION 'This share token has expired';
  END IF;
  
  -- Load the shared member's profile
  SELECT *
  INTO v_member_record
  FROM public.members m
  WHERE m.id = v_share_record.member_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Member profile not found';
  END IF;
  
  -- Return safe preview (no member_id, email, phone, DOB, identity data, storage paths)
  RETURN QUERY
  SELECT
    v_member_record.first_name,
    EXTRACT(YEAR FROM AGE(v_member_record.date_of_birth))::integer AS age,
    (v_member_record.identity_verified AND v_member_record.profile_media_verified)::boolean AS verified,
    v_member_record.rating,
    v_member_record.completed_movements,
    v_member_record.common_movement_area;
END;

DECLARE a public.alignments%ROWTYPE; target uuid; prior integer;
BEGIN
 IF p_person_number IS NULL OR p_person_number<>1 OR p_stars IS NULL OR p_stars NOT BETWEEN 1 AND 5 THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Valid rating selection required'; END IF;
 a:=private.completed_movement_rating_alignment(p_movement_need_id);
 -- The selector has acquired agreement -> alignment -> journey -> sorted member
 -- gates, before any rating insertion. No aggregate read before the gate wait.
 SELECT p.member_id INTO STRICT target FROM private.completed_movement_principals p WHERE p.alignment_id=a.id AND p.member_id<>auth.uid();
 SELECT r.stars INTO prior FROM private.completed_movement_ratings r WHERE r.alignment_id=a.id
  AND r.reviewer_member_id=auth.uid() AND r.reviewed_member_id=target;
 IF prior IS NOT NULL AND prior<>p_stars THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Submitted rating is immutable'; END IF;
 IF prior IS NULL THEN
  INSERT INTO private.completed_movement_ratings VALUES(a.id,auth.uid(),target,p_stars,clock_timestamp());
 END IF;
 RETURN QUERY SELECT * FROM public.get_my_completed_movement_rating_targets(p_movement_need_id);
END;

DECLARE
  s private.movement_location_references%ROWTYPE;
BEGIN
  s := private.require_verified_location_selection(p_verified_member_id,p_source_location_reference_id);
  IF s.provider_namespace IS DISTINCT FROM p_provider_namespace OR s.provider_place_reference IS DISTINCT FROM p_provider_place_reference THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Resolution provider selection identity does not match';
  END IF;
  -- Deployment owner retains execution; service_role cannot invoke 0026 directly.
  -- Preserve its authoritative validation, source lock, versioning and retry logic.
  RETURN QUERY SELECT r.* FROM public.record_location_resolution_for_server(
    p_source_location_reference_id,p_producer_request_id,p_provider_namespace,p_provider_product,p_provider_version,
    p_provider_place_reference,p_resolution_version,p_latitude,p_longitude,p_resolved_at,p_expires_at
  ) r;
END;

DECLARE
  v_source private.movement_location_references%ROWTYPE;
  v_existing private.movement_location_resolution_evidence%ROWTYPE;
  v_target private.movement_location_references%ROWTYPE;
  v_now timestamptz;
  v_attested_at timestamptz;
  v_expiry timestamptz;
  v_version integer;
  v_target_id uuid;
  v_evidence_id uuid;
  v_text text;
BEGIN
  IF current_setting('transaction_isolation')<>'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000', MESSAGE='Location resolution requires READ COMMITTED';
  END IF;
  IF p_source_location_reference_id IS NULL OR p_producer_request_id IS NULL
    OR p_provider_namespace IS NULL OR p_provider_product IS NULL OR p_provider_version IS NULL
    OR p_provider_place_reference IS NULL OR p_resolution_version IS NULL
    OR p_latitude IS NULL OR p_longitude IS NULL OR p_resolved_at IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Complete trusted location resolution is required';
  END IF;
  FOREACH v_text IN ARRAY ARRAY[p_provider_namespace,p_provider_product,p_provider_version,p_resolution_version]
  LOOP
    IF v_text<>btrim(v_text) OR length(v_text) NOT BETWEEN 1 AND 100 OR v_text !~ '[^[:space:]]' THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Location resolution provider metadata is invalid';
    END IF;
  END LOOP;
  IF p_provider_place_reference<>btrim(p_provider_place_reference)
    OR length(p_provider_place_reference) NOT BETWEEN 1 AND 500 OR p_provider_place_reference !~ '[^[:space:]]' THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Location resolution provider place reference is invalid';
  END IF;
  IF NOT (p_latitude BETWEEN -90 AND 90) OR NOT (p_longitude BETWEEN -180 AND 180)
    OR p_latitude::text IN ('NaN','Infinity','-Infinity') OR p_longitude::text IN ('NaN','Infinity','-Infinity') THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Location resolution coordinates are invalid';
  END IF;

  SELECT r.* INTO v_source FROM private.movement_location_references r
  WHERE r.id=p_source_location_reference_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Location resolution source not found';
  END IF;
  v_now := clock_timestamp();
  IF v_source.resolution_status IS DISTINCT FROM 'unresolved'
    OR v_source.source_kind NOT IN ('member_declared','member_selected')
    OR v_source.latitude IS NOT NULL OR v_source.longitude IS NOT NULL
    OR v_source.resolved_at IS NOT NULL OR v_source.resolution_version IS NOT NULL
    OR (v_source.provider_namespace IS NULL)<>(v_source.provider_place_reference IS NULL)
    OR (v_source.expires_at IS NOT NULL AND v_source.expires_at<=v_now) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Location resolution source is not eligible';
  END IF;
  IF v_source.provider_namespace IS NOT NULL AND
    (v_source.provider_namespace IS DISTINCT FROM p_provider_namespace
      OR v_source.provider_place_reference IS DISTINCT FROM p_provider_place_reference) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Location resolution must preserve provider selection identity';
  END IF;
  IF NOT isfinite(p_resolved_at) OR p_resolved_at<v_source.created_at OR p_resolved_at>v_now
    OR (p_expires_at IS NOT NULL AND (NOT isfinite(p_expires_at) OR p_expires_at<=v_now)) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Location resolution timestamps are invalid';
  END IF;

  SELECT e.* INTO v_existing FROM private.movement_location_resolution_evidence e
  WHERE e.producer_request_id=p_producer_request_id;
  IF FOUND THEN
    SELECT r.* INTO STRICT v_target FROM private.movement_location_references r
    WHERE r.id=v_existing.resolved_location_reference_id FOR SHARE;
    IF v_existing.source_location_reference_id IS DISTINCT FROM v_source.id
      OR v_existing.provider_product IS DISTINCT FROM p_provider_product
      OR v_existing.provider_version IS DISTINCT FROM p_provider_version
      OR v_existing.requested_expires_at IS DISTINCT FROM p_expires_at
      OR v_target.provider_namespace IS DISTINCT FROM p_provider_namespace
      OR v_target.provider_place_reference IS DISTINCT FROM p_provider_place_reference
      OR v_target.resolution_version IS DISTINCT FROM p_resolution_version
      OR v_target.latitude IS DISTINCT FROM p_latitude OR v_target.longitude IS DISTINCT FROM p_longitude
      OR v_target.resolved_at IS DISTINCT FROM p_resolved_at THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Location resolution request does not match recorded evidence';
    END IF;
    -- Reacquires source/target in the same order and checks time AFTER all waits.
    PERFORM private.assert_movement_location_resolution_evidence(v_existing.id);
    RETURN QUERY SELECT v_existing.id,v_target.id,v_existing.version,v_target.expires_at;
    RETURN;
  END IF;

  SELECT COALESCE(MAX(e.version),0)+1 INTO v_version
  FROM private.movement_location_resolution_evidence e WHERE e.source_location_reference_id=v_source.id;
  v_attested_at := clock_timestamp();
  IF NOT isfinite(p_resolved_at) OR p_resolved_at<v_source.created_at OR p_resolved_at>v_attested_at
    OR (p_expires_at IS NOT NULL AND (NOT isfinite(p_expires_at) OR p_expires_at<=v_attested_at)) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Location resolution timestamps are invalid';
  END IF;
  -- PostgreSQL LEAST ignores NULL; two NULL deadlines deliberately mean no expiry.
  v_expiry := LEAST(p_expires_at,v_source.expires_at);
  IF v_expiry IS NOT NULL AND v_expiry<=v_attested_at THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Location resolution expiry elapsed before recording';
  END IF;
  INSERT INTO private.movement_location_references(
    owner_member_id,declared_label,source_kind,resolution_status,latitude,longitude,
    provider_namespace,provider_place_reference,resolution_version,resolved_at,created_at,expires_at
  ) VALUES (
    v_source.owner_member_id,v_source.declared_label,'provider_resolved','resolved',p_latitude,p_longitude,
    p_provider_namespace,p_provider_place_reference,p_resolution_version,p_resolved_at,v_attested_at,v_expiry
  ) RETURNING id INTO v_target_id;
  INSERT INTO private.movement_location_resolution_evidence(
    source_location_reference_id,resolved_location_reference_id,version,producer_request_id,
    provider_product,provider_version,resolution_schema_version,requested_expires_at,recorded_at
  ) VALUES (
    v_source.id,v_target_id,v_version,p_producer_request_id,p_provider_product,p_provider_version,
    'movement_location_resolution_v1',p_expires_at,v_attested_at
  ) RETURNING id INTO v_evidence_id;
  -- No caught uniqueness errors: statement atomicity removes a losing target too.
  PERFORM private.assert_movement_location_resolution_evidence(v_evidence_id);
  RETURN QUERY SELECT v_evidence_id,v_target_id,v_version,v_expiry;
END;

DECLARE
  v_intent private.offering_movement_intents%ROWTYPE;
  v_origin private.movement_location_references%ROWTYPE;
  v_destination private.movement_location_references%ROWTYPE;
  v_existing private.offering_route_evidence%ROWTYPE;
  v_origin_id uuid;
  v_destination_id uuid;
  v_effective_expires_at timestamptz;
  v_next_version integer;
  v_new_id uuid;
  v_now timestamptz;
  v_attested_at timestamptz;
BEGIN
  IF p_offering_movement_intent_id IS NULL
    OR p_provider_namespace IS NULL
    OR p_provider_product IS NULL
    OR p_provider_version IS NULL
    OR p_provider_route_reference IS NULL
    OR p_route_shape IS NULL
    OR p_route_distance_meters IS NULL
    OR p_route_duration_seconds IS NULL
    OR p_generated_at IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='Complete trusted route evidence is required';
  END IF;

  SELECT i.* INTO v_intent
  FROM private.offering_movement_intents i
  WHERE i.id=p_offering_movement_intent_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='Offering movement intent not found';
  END IF;

  v_now := clock_timestamp();
  IF v_intent.status<>'current'
    OR (v_intent.expires_at IS NOT NULL AND v_intent.expires_at<=v_now) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Offering movement intent is not eligible for route evidence';
  END IF;

  PERFORM private.assert_offering_movement_intent(v_intent.id);

  SELECT il.location_reference_id INTO STRICT v_origin_id
  FROM private.offering_movement_intent_locations il
  WHERE il.intent_id=v_intent.id AND il.role='origin';

  SELECT il.location_reference_id INTO STRICT v_destination_id
  FROM private.offering_movement_intent_locations il
  WHERE il.intent_id=v_intent.id AND il.role='destination';

  SELECT lr.* INTO STRICT v_origin
  FROM private.movement_location_references lr
  WHERE lr.id=v_origin_id FOR SHARE;

  SELECT lr.* INTO STRICT v_destination
  FROM private.movement_location_references lr
  WHERE lr.id=v_destination_id FOR SHARE;

  v_now := clock_timestamp();
  IF v_origin.owner_member_id<>v_intent.offering_member_id
    OR v_destination.owner_member_id<>v_intent.offering_member_id
    OR v_origin.resolution_status<>'resolved'
    OR v_destination.resolution_status<>'resolved'
    OR v_origin.source_kind<>'provider_resolved'
    OR v_destination.source_kind<>'provider_resolved'
    OR (v_origin.expires_at IS NOT NULL AND v_origin.expires_at<=v_now)
    OR (v_destination.expires_at IS NOT NULL AND v_destination.expires_at<=v_now) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Trusted route evidence requires resolved eligible intent endpoints';
  END IF;

  IF NOT isfinite(p_generated_at)
    OR p_generated_at>v_now
    OR p_generated_at<v_intent.created_at
    OR p_generated_at<v_origin.resolved_at
    OR p_generated_at<v_destination.resolved_at THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Trusted route evidence generation time is invalid';
  END IF;

  IF p_expires_at IS NOT NULL
    AND (NOT isfinite(p_expires_at) OR p_expires_at<=v_now) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Trusted route evidence expiry is invalid';
  END IF;

  IF p_route_distance_meters<=0 OR p_route_duration_seconds<=0 THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Trusted route evidence distance and duration must be positive';
  END IF;

  PERFORM private.assert_geojson_linestring_v1(p_route_shape);

  v_effective_expires_at := LEAST(
    p_expires_at,
    v_intent.expires_at,
    v_origin.expires_at,
    v_destination.expires_at
  );

  IF v_effective_expires_at IS NOT NULL AND v_effective_expires_at<=v_now THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Trusted route evidence dependencies are expired';
  END IF;

  SELECT e.* INTO v_existing
  FROM private.offering_route_evidence e
  WHERE e.offering_movement_intent_id=v_intent.id
    AND e.provider_namespace=p_provider_namespace
    AND e.provider_product=p_provider_product
    AND e.provider_version=p_provider_version
    AND e.provider_route_reference=p_provider_route_reference
  FOR UPDATE;

  -- Replay preserves the stored generation time despite a later observation.
  IF FOUND THEN
    v_now := clock_timestamp();
    IF v_existing.offering_movement_intent_id IS DISTINCT FROM v_intent.id
      OR v_existing.offering_member_id IS DISTINCT FROM v_intent.offering_member_id
      OR v_existing.origin_location_reference_id IS DISTINCT FROM v_origin.id
      OR v_existing.destination_location_reference_id IS DISTINCT FROM v_destination.id
      OR v_existing.evidence_schema_version IS DISTINCT FROM 'offering_route_evidence_v1'
      OR v_existing.route_shape_format IS DISTINCT FROM 'geojson_linestring_v1'
      OR v_existing.route_shape IS DISTINCT FROM p_route_shape
      OR v_existing.route_distance_meters IS DISTINCT FROM p_route_distance_meters
      OR v_existing.route_duration_seconds IS DISTINCT FROM p_route_duration_seconds
      OR v_existing.expires_at IS DISTINCT FROM v_effective_expires_at THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Provider route reference does not match recorded evidence';
    END IF;

    IF v_existing.status<>'current'
      OR (v_existing.expires_at IS NOT NULL AND v_existing.expires_at<=v_now) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Provider route reference belongs to stale evidence';
    END IF;

    PERFORM private.assert_offering_route_evidence(v_existing.id);
    RETURN QUERY SELECT v_existing.id, v_existing.version, v_existing.status, v_existing.expires_at;
    RETURN;
  END IF;

  SELECT COALESCE(MAX(e.version),0)+1 INTO v_next_version
  FROM private.offering_route_evidence e
  WHERE e.offering_movement_intent_id=v_intent.id;

  UPDATE private.offering_route_evidence e
  SET status='superseded'
  WHERE e.offering_movement_intent_id=v_intent.id
    AND e.status='current';

  v_attested_at := clock_timestamp();
  IF NOT isfinite(p_generated_at) OR p_generated_at>v_attested_at
    OR p_generated_at<v_intent.created_at OR p_generated_at<v_origin.resolved_at OR p_generated_at<v_destination.resolved_at
    OR (p_expires_at IS NOT NULL AND (NOT isfinite(p_expires_at) OR p_expires_at<=v_attested_at))
    OR (v_effective_expires_at IS NOT NULL AND v_effective_expires_at<=v_attested_at) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Trusted route evidence attestation time is invalid';
  END IF;
  INSERT INTO private.offering_route_evidence(
    offering_movement_intent_id, offering_member_id,
    origin_location_reference_id, destination_location_reference_id,
    version, evidence_schema_version,
    provider_namespace, provider_product, provider_version, provider_route_reference,
    route_shape_format, route_shape, route_distance_meters, route_duration_seconds,
    generated_at, expires_at, status, created_at
  )
  VALUES(
    v_intent.id, v_intent.offering_member_id,
    v_origin.id, v_destination.id,
    v_next_version, 'offering_route_evidence_v1',
    p_provider_namespace, p_provider_product, p_provider_version, p_provider_route_reference,
    'geojson_linestring_v1', p_route_shape, p_route_distance_meters, p_route_duration_seconds,
    p_generated_at, v_effective_expires_at, 'current', v_attested_at
  )
  RETURNING id INTO v_new_id;

  PERFORM private.assert_offering_route_evidence(v_new_id);

  -- Drain pending INSERT checks while this version is still current. Otherwise
  -- a later call in this transaction could supersede it before validation.
  SET CONSTRAINTS private.offering_route_evidence_complete IMMEDIATE;
  SET CONSTRAINTS private.offering_route_evidence_complete DEFERRED;

  RETURN QUERY
  SELECT e.id,e.version,e.status,e.expires_at
  FROM private.offering_route_evidence e
  WHERE e.id=v_new_id;
END;

DECLARE
  m private.trusted_route_match_evidence%ROWTYPE;
  e private.pricing_geography_evidence%ROWTYPE;
  previous private.pricing_geography_evidence%ROWTYPE;
  deadline timestamptz;
  replay_count integer;
BEGIN
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000', MESSAGE='Pricing geography producer requires READ COMMITTED';
  END IF;
  IF p_route_match_evidence_id IS NULL OR p_expected_route_match_evidence_version IS NULL
    OR p_expected_route_evidence_id IS NULL OR p_expected_route_evidence_version IS NULL
    OR p_pricing_corridor_distance_meters IS NULL OR p_geographic_events IS NULL
    OR p_classifier_name IS NULL OR p_classifier_version IS NULL
    OR p_transport_geography_version IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='Complete normalized pricing geography result required';
  END IF;
  IF p_expected_route_match_evidence_version<1 OR p_expected_route_evidence_version<1
    OR p_pricing_corridor_distance_meters<=0
    OR p_classifier_name !~ '^[a-zA-Z0-9][a-zA-Z0-9_.-]{0,99}$'
    OR p_classifier_version !~ '^[a-zA-Z0-9][a-zA-Z0-9_.-]{0,99}$'
    OR p_transport_geography_version !~ '^[a-zA-Z0-9][a-zA-Z0-9_.-]{0,99}$' THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Invalid pricing geography result or provenance';
  END IF;
  PERFORM private.assert_pricing_geography_events(p_geographic_events,p_pricing_corridor_distance_meters);

  -- Preliminary read discovers immutable need identity only. Never lock the
  -- match before its authoritative need/endpoints/intent/route dependencies.
  SELECT x.* INTO m FROM private.trusted_route_match_evidence x WHERE x.id=p_route_match_evidence_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Exact trusted route-match evidence unavailable';
  END IF;
  PERFORM 1 FROM public.movement_needs n WHERE n.id=m.movement_need_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Pricing geography movement need unavailable';
  END IF;
  SELECT x.* INTO STRICT m FROM private.trusted_route_match_evidence x WHERE x.id=p_route_match_evidence_id;
  IF ROW(m.version,m.route_evidence_id,m.route_evidence_version)
    IS DISTINCT FROM ROW(p_expected_route_match_evidence_version,p_expected_route_evidence_id,p_expected_route_evidence_version) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Classified source identity or version mismatch';
  END IF;
  SELECT coalesce(n.latest_departure_at,n.earliest_departure_at) INTO STRICT deadline
    FROM public.movement_needs n WHERE n.id=m.movement_need_id;

  e.id:=gen_random_uuid();
  e.route_match_evidence_id:=m.id;
  e.route_match_evidence_version:=m.version;
  e.movement_need_id:=m.movement_need_id;
  e.requesting_member_id:=m.requesting_member_id;
  e.offering_member_id:=m.offering_member_id;
  e.offering_movement_intent_id:=m.offering_movement_intent_id;
  e.offering_intent_version:=m.offering_intent_version;
  e.route_evidence_id:=m.route_evidence_id;
  e.route_evidence_version:=m.route_evidence_version;
  e.state_location_reference_id:=m.requester_origin_location_reference_id;
  e.evidence_schema_version:='pricing_geography_evidence_v1';
  e.classifier_name:=p_classifier_name;
  e.classifier_version:=p_classifier_version;
  e.transport_geography_version:=p_transport_geography_version;
  e.pricing_corridor_distance_meters:=p_pricing_corridor_distance_meters;
  e.pricing_range_supported:=(p_pricing_corridor_distance_meters<=100000);
  e.geographic_events:=p_geographic_events;
  e.generated_at:=clock_timestamp();
  e.created_at:=e.generated_at;
  e.expires_at:=least(deadline,m.expires_at);
  e.status:='current';
  -- 0059 acquires/revalidates canonical context, then match SHARE. Only after
  -- that may this producer lock pricing history. No weaker matching validator.
  PERFORM private.assert_pricing_geography_context(e);
  PERFORM x.id FROM private.pricing_geography_evidence x
    WHERE x.movement_need_id=e.movement_need_id
      AND x.offering_movement_intent_id=e.offering_movement_intent_id
    ORDER BY x.version FOR UPDATE;
  -- Fresh eligibility after any pricing-history lock wait.
  PERFORM private.assert_pricing_geography_context(e);

  -- Replay identity is exact match + classifier name/version + dataset version.
  -- Scan terminal history too: an old result must never reopen after supersession.
  SELECT count(*) INTO replay_count FROM private.pricing_geography_evidence x
    WHERE x.route_match_evidence_id=m.id AND x.classifier_name=p_classifier_name
      AND x.classifier_version=p_classifier_version
      AND x.transport_geography_version=p_transport_geography_version;
  IF replay_count>1 THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Ambiguous pricing geography replay history';
  END IF;
  IF replay_count=1 THEN
    SELECT x.* INTO STRICT previous FROM private.pricing_geography_evidence x
      WHERE x.route_match_evidence_id=m.id AND x.classifier_name=p_classifier_name
        AND x.classifier_version=p_classifier_version
        AND x.transport_geography_version=p_transport_geography_version;
    IF (to_jsonb(previous)-ARRAY['id','version','generated_at','created_at','expires_at','status'])
      IS DISTINCT FROM (to_jsonb(e)-ARRAY['id','version','generated_at','created_at','expires_at','status']) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Pricing geography replay payload mismatch';
    END IF;
    -- Retain original timestamps/expiry, and fail if the evidence is terminal,
    -- expired or no longer within live dependency bounds. Never refresh a retry.
    PERFORM private.assert_pricing_geography_evidence(previous.id);
    RETURN QUERY SELECT previous.id,previous.version,previous.status,previous.expires_at;
    RETURN;
  END IF;

  SELECT coalesce(max(x.version),0)+1 INTO e.version FROM private.pricing_geography_evidence x
    WHERE x.movement_need_id=e.movement_need_id
      AND x.offering_movement_intent_id=e.offering_movement_intent_id;
  UPDATE private.pricing_geography_evidence x SET status='superseded'
    WHERE x.movement_need_id=e.movement_need_id
      AND x.offering_movement_intent_id=e.offering_movement_intent_id AND x.status='current';
  -- Generated time here means normalized evidence recording, not the future
  -- classifier's computation time. Bindings pin the classified source instead.
  e.generated_at:=clock_timestamp();
  e.created_at:=e.generated_at;
  INSERT INTO private.pricing_geography_evidence SELECT e.*;
  PERFORM private.assert_pricing_geography_evidence(e.id);
  RETURN QUERY SELECT e.id,e.version,e.status,e.expires_at;
END;

DECLARE
  e private.pricing_geography_evidence%ROWTYPE;
  q private.pricing_quotes%ROWTYPE;
  previous private.pricing_quotes%ROWTYPE;
  replay_count bigint;
  next_version bigint;
BEGIN
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000', MESSAGE='Pricing quote producer requires READ COMMITTED';
  END IF;
  IF p_pricing_geography_evidence_id IS NULL
    OR p_expected_pricing_geography_evidence_version IS NULL
    OR p_pricing_policy_version IS NULL OR p_seat_price_minor IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='Complete trusted pricing quote result required';
  END IF;
  -- Numeric input is exact: reject fractions before bigint conversion. Callers
  -- must preserve decimal precision in transport; never pass a JS float price.
  IF p_expected_pricing_geography_evidence_version < 1
    OR p_pricing_policy_version <> 'trusted_server_result_infrastructure_v1'
    OR p_seat_price_minor::text IN ('NaN','Infinity','-Infinity')
    OR p_seat_price_minor <= 0 OR p_seat_price_minor > 9223372036854775807::numeric
    OR p_seat_price_minor <> trunc(p_seat_price_minor) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Unsupported policy or invalid trusted quote input';
  END IF;

  -- Preliminary read discovers immutable bindings only; take no quote lock.
  SELECT x.* INTO e FROM private.pricing_geography_evidence x
  WHERE x.id=p_pricing_geography_evidence_id;
  IF NOT FOUND OR e.version IS DISTINCT FROM p_expected_pricing_geography_evidence_version THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Exact pricing geography evidence unavailable';
  END IF;
  q.pricing_geography_evidence_id:=e.id;
  q.pricing_geography_evidence_version:=e.version;
  q.movement_need_id:=e.movement_need_id;
  q.requesting_member_id:=e.requesting_member_id;
  q.offering_member_id:=e.offering_member_id;
  q.offering_movement_intent_id:=e.offering_movement_intent_id;
  q.offering_intent_version:=e.offering_intent_version;
  q.state_location_reference_id:=e.state_location_reference_id;
  q.pricing_policy_version:=p_pricing_policy_version;
  q.currency:='NGN';
  q.seat_price_minor:=p_seat_price_minor::bigint;
  q.status:='current';
  q.created_at:=clock_timestamp();
  q.expires_at:=e.expires_at;

  -- 0061 delegates to 0059: need UPDATE -> requester endpoints -> intent ->
  -- route -> match -> geography SHARE. The need also serializes empty history.
  PERFORM private.assert_pricing_quote_context(q);
  PERFORM x.id FROM private.pricing_quotes x
  WHERE x.movement_need_id=q.movement_need_id
    AND x.offering_movement_intent_id=q.offering_movement_intent_id
  ORDER BY x.version FOR UPDATE;
  -- Fresh lifecycle and clock checks after any history lock wait.
  PERFORM private.assert_pricing_quote_context(q);

  SELECT count(*) INTO replay_count FROM private.pricing_quotes x
  WHERE x.pricing_geography_evidence_id=e.id
    AND x.pricing_geography_evidence_version=e.version
    AND x.pricing_policy_version=p_pricing_policy_version;
  IF replay_count > 1 THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Ambiguous pricing quote replay history';
  END IF;
  IF replay_count = 1 THEN
    SELECT x.* INTO STRICT previous FROM private.pricing_quotes x
    WHERE x.pricing_geography_evidence_id=e.id
      AND x.pricing_geography_evidence_version=e.version
      AND x.pricing_policy_version=p_pricing_policy_version;
    IF (to_jsonb(previous)-ARRAY['id','version','created_at','expires_at','status'])
      IS DISTINCT FROM (to_jsonb(q)-ARRAY['id','version','created_at','expires_at','status']) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Pricing quote replay payload mismatch';
    END IF;
    PERFORM private.assert_pricing_quote(previous.id);
    RETURN QUERY SELECT previous.id,previous.version,previous.created_at,previous.expires_at;
    RETURN;
  END IF;

  SELECT coalesce(max(x.version)::bigint,0)+1 INTO next_version
  FROM private.pricing_quotes x WHERE x.movement_need_id=q.movement_need_id
    AND x.offering_movement_intent_id=q.offering_movement_intent_id;
  IF next_version > 2147483647 THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Pricing quote version exhausted';
  END IF;
  q.id:=gen_random_uuid();
  q.version:=next_version::integer;
  q.created_at:=clock_timestamp();
  PERFORM private.assert_pricing_quote_context(q);
  UPDATE private.pricing_quotes x SET status='superseded'
  WHERE x.movement_need_id=q.movement_need_id
    AND x.offering_movement_intent_id=q.offering_movement_intent_id AND x.status='current';
  INSERT INTO private.pricing_quotes SELECT q.*;
  PERFORM private.assert_pricing_quote(q.id);
  RETURN QUERY SELECT q.id,q.version,q.created_at,q.expires_at;
END;

DECLARE
  s private.movement_location_references%ROWTYPE;
  r private.movement_location_selection_receipts%ROWTYPE;
  a private.movement_location_selection_attestations%ROWTYPE;
  v_id uuid;
  v_now timestamptz;
  v_constraint text;
  v_table text;
  v_schema text;
BEGIN
  IF current_setting('transaction_isolation')<>'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000', MESSAGE='Verified selection requires READ COMMITTED';
  END IF;
  IF p_verified_member_id IS NULL OR p_selection_request_id IS NULL
    OR NOT EXISTS (SELECT 1 FROM public.members m WHERE m.id=p_verified_member_id)
    OR p_declared_label IS NULL OR p_declared_label<>btrim(p_declared_label)
    OR length(p_declared_label) NOT BETWEEN 1 AND 300 OR p_declared_label !~ '[^[:space:]]'
    OR p_provider_namespace IS NULL OR p_provider_namespace<>btrim(p_provider_namespace)
    OR length(p_provider_namespace) NOT BETWEEN 1 AND 100 OR p_provider_namespace !~ '[^[:space:]]'
    OR p_provider_place_reference IS NULL OR p_provider_place_reference<>btrim(p_provider_place_reference)
    OR length(p_provider_place_reference) NOT BETWEEN 1 AND 500 OR p_provider_place_reference !~ '[^[:space:]]'
    OR p_proof_version IS DISTINCT FROM 'selection_proof_v1'
    OR p_proof_issued_at IS NULL OR p_proof_expires_at IS NULL
    OR NOT isfinite(p_proof_issued_at) OR NOT isfinite(p_proof_expires_at)
    OR p_proof_issued_at>=p_proof_expires_at THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Verified selection input is invalid';
  END IF;
  SELECT x.* INTO r FROM private.movement_location_selection_receipts x WHERE x.request_id=p_selection_request_id;
  IF NOT FOUND THEN
    BEGIN
      v_now := clock_timestamp();
      IF p_proof_issued_at>v_now OR p_proof_expires_at<=v_now THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Selection proof is not currently valid';
      END IF;
      INSERT INTO private.movement_location_references(
        owner_member_id,declared_label,source_kind,resolution_status,provider_namespace,provider_place_reference,
        latitude,longitude,resolution_version,resolved_at,expires_at,created_at
      ) VALUES (p_verified_member_id,p_declared_label,'member_selected','unresolved',p_provider_namespace,p_provider_place_reference,
        NULL,NULL,NULL,NULL,NULL,v_now) RETURNING id INTO v_id;
      INSERT INTO private.movement_location_selection_receipts(request_id,location_reference_id,recorded_at)
      VALUES (p_selection_request_id,v_id,v_now);
      INSERT INTO private.movement_location_selection_attestations(
        selection_request_id,proof_version,proof_issued_at,proof_expires_at,verified_at
      ) VALUES (p_selection_request_id,p_proof_version,p_proof_issued_at,p_proof_expires_at,v_now);
    EXCEPTION WHEN unique_violation THEN
      -- All three attempted inserts roll back before reading a concurrent winner.
      -- Only the receipt request-key race is recoverable, never unrelated errors.
      GET STACKED DIAGNOSTICS v_constraint=CONSTRAINT_NAME,v_table=TABLE_NAME,v_schema=SCHEMA_NAME;
      IF v_constraint<>'movement_location_selection_receipts_pkey'
        OR v_table<>'movement_location_selection_receipts' OR v_schema<>'private' THEN
        RAISE;
      END IF;
      SELECT x.* INTO r FROM private.movement_location_selection_receipts x WHERE x.request_id=p_selection_request_id;
      IF NOT FOUND THEN RAISE; END IF;
    END;
  END IF;
  SELECT x.* INTO r FROM private.movement_location_selection_receipts x WHERE x.request_id=p_selection_request_id;
  s := private.require_verified_location_selection(p_verified_member_id,r.location_reference_id);
  SELECT x.* INTO STRICT a FROM private.movement_location_selection_attestations x WHERE x.selection_request_id=r.request_id;
  IF s.declared_label IS DISTINCT FROM p_declared_label OR s.provider_namespace IS DISTINCT FROM p_provider_namespace
    OR s.provider_place_reference IS DISTINCT FROM p_provider_place_reference
    OR a.proof_version IS DISTINCT FROM p_proof_version OR a.proof_issued_at IS DISTINCT FROM p_proof_issued_at
    OR a.proof_expires_at IS DISTINCT FROM p_proof_expires_at THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Verified selection replay does not match';
  END IF;
  RETURN QUERY SELECT s.id,s.declared_label;
END;

DECLARE
  v_key text;
  v_previous private.wallet_transactions%ROWTYPE;
  v_available uuid;
  v_clearing uuid;
  v_id uuid;
  v_total bigint;
  v_active bigint;
  v_matching bigint;
  v_balance numeric;
BEGIN
  -- Each statement after a waited event lock must see the committed winner.
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000', MESSAGE='Wallet top-up requires READ COMMITTED';
  END IF;
  IF p_member_id IS NULL OR p_amount_minor IS NULL OR p_currency IS NULL
     OR p_provider IS NULL OR p_provider_reference IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='Complete wallet top-up input required';
  END IF;
  IF p_amount_minor <= 0 OR p_currency <> 'NGN'
     OR length(p_provider) NOT BETWEEN 1 AND 100
     OR p_provider <> btrim(p_provider)
     OR p_provider !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]*$'
     OR length(p_provider_reference) NOT BETWEEN 1 AND 255
     OR p_provider_reference <> btrim(p_provider_reference)
     OR p_provider_reference !~ '[^[:space:]]'
     OR p_provider_reference ~ '[[:cntrl:]]' THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Invalid wallet top-up input';
  END IF;

  -- JSON array encoding avoids delimiter ambiguity. Store exact case-sensitive
  -- provenance; do not trim or normalize two distinct events into one.
  v_key := 'wallet_top_up:' || encode(sha256(convert_to(
    jsonb_build_array(p_provider, p_provider_reference)::text, 'UTF8'
  )), 'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended(v_key, 0));

  SELECT t.* INTO v_previous
  FROM private.wallet_transactions t
  WHERE t.provider = p_provider AND t.provider_reference = p_provider_reference
  FOR SHARE;
  IF FOUND AND (
    v_previous.transaction_kind IS DISTINCT FROM 'wallet_top_up'
    OR v_previous.currency IS DISTINCT FROM p_currency
    OR v_previous.alignment_id IS NOT NULL
    OR v_previous.financial_component_id IS NOT NULL
    OR v_previous.idempotency_key IS DISTINCT FROM v_key
  ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Wallet top-up replay mismatch';
  END IF;

  -- Serialize member provisioning and this writer's balance checks. 0065 takes
  -- SHARE on this same row, so its concurrent provisioning cannot cross this gate.
  PERFORM 1 FROM public.members m WHERE m.id = p_member_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23503', MESSAGE='Member unavailable';
  END IF;
  PERFORM 1 FROM private.wallet_accounts a
  WHERE a.member_id = p_member_id AND a.currency = 'NGN'
  ORDER BY a.id FOR SHARE;
  SELECT count(*), count(*) FILTER (WHERE a.status='active')
  INTO v_total, v_active
  FROM private.wallet_accounts a
  WHERE a.member_id = p_member_id AND a.currency = 'NGN';
  -- 0065 can fill missing accounts. This stricter posting boundary must refuse
  -- a pre-existing incomplete wallet instead of silently repairing it.
  IF v_total NOT IN (0, 3) OR v_total <> v_active THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Member wallet unavailable';
  END IF;
  SELECT w.available_account_id INTO STRICT v_available
  FROM public.ensure_ngn_wallet_accounts_for_server(p_member_id) w;

  INSERT INTO private.wallet_accounts(member_id, account_kind, currency)
  VALUES (NULL, 'provider_clearing', 'NGN')
  ON CONFLICT (account_kind, currency) WHERE member_id IS NULL DO NOTHING;
  SELECT a.id INTO v_clearing FROM private.wallet_accounts a
  WHERE a.member_id IS NULL AND a.account_kind = 'provider_clearing'
    AND a.currency = 'NGN' AND a.status = 'active'
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Provider clearing unavailable';
  END IF;

  IF v_previous.id IS NOT NULL THEN
    SELECT count(*), count(*) FILTER (WHERE
      p.amount_minor = p_amount_minor AND (
        (p.account_id = v_clearing AND p.direction = 'debit') OR
        (p.account_id = v_available AND p.direction = 'credit')
      ))
    INTO v_total, v_matching
    FROM private.wallet_postings p WHERE p.transaction_id = v_previous.id;
    IF v_total <> 2 OR v_matching <> 2 THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Wallet top-up replay mismatch';
    END IF;
    PERFORM private.assert_wallet_transaction_balanced(v_previous.id);
    RETURN v_previous.id;
  END IF;

  -- Never make the 0065 bigint projection overflow. Numeric accumulation also
  -- rejects an already inconsistent balance without overflow during summation.
  SELECT coalesce(sum(CASE WHEN p.direction='credit'
    THEN p.amount_minor::numeric ELSE -p.amount_minor::numeric END), 0)
  INTO v_balance FROM private.wallet_postings p WHERE p.account_id = v_available;
  IF v_balance < 0 OR v_balance + p_amount_minor > 9223372036854775807::numeric THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Member wallet unavailable';
  END IF;

  INSERT INTO private.wallet_transactions(
    transaction_kind, currency, provider, provider_reference, idempotency_key,
    alignment_id, financial_component_id
  ) VALUES ('wallet_top_up', 'NGN', p_provider, p_provider_reference, v_key, NULL, NULL)
  RETURNING id INTO v_id;
  INSERT INTO private.wallet_postings(transaction_id, account_id, direction, amount_minor)
  VALUES (v_id, v_clearing, 'debit', p_amount_minor),
         (v_id, v_available, 'credit', p_amount_minor);
  PERFORM private.assert_wallet_transaction_balanced(v_id);
  RETURN v_id;
EXCEPTION
  WHEN unique_violation THEN
    -- Includes collisions with transactions written outside this narrow RPC.
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Wallet top-up identity conflict';
END;

DECLARE
  v_member_id uuid := auth.uid();
  v_make text := btrim(p_make);
  v_model text := nullif(btrim(p_model), '');
  v_color text := btrim(p_color);
  v_vehicle_id uuid;
  v_access_id uuid;
BEGIN
  IF v_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF v_make IS NULL OR v_make = '' OR length(v_make) > 100 THEN
    RAISE EXCEPTION 'Make is required and must be 100 characters or fewer';
  END IF;
  IF length(v_model) > 100 THEN
    RAISE EXCEPTION 'Model must be 100 characters or fewer';
  END IF;
  IF v_color IS NULL OR v_color = '' OR length(v_color) > 100 THEN
    RAISE EXCEPTION 'Color is required and must be 100 characters or fewer';
  END IF;
  IF p_year IS NOT NULL AND (p_year < 1900 OR p_year > 2100) THEN
    RAISE EXCEPTION 'Year must be between 1900 and 2100';
  END IF;
  IF p_seat_capacity IS NULL OR p_seat_capacity NOT BETWEEN 1 AND 12 THEN
    RAISE EXCEPTION 'Seat capacity must be between 1 and 12';
  END IF;

  INSERT INTO public.vehicles (make, model, year, color, seat_capacity)
  VALUES (v_make, v_model, p_year, v_color, p_seat_capacity)
  RETURNING id INTO v_vehicle_id;
  INSERT INTO public.member_vehicle_access (member_id, vehicle_id, active)
  VALUES (v_member_id, v_vehicle_id, true)
  RETURNING id INTO v_access_id;
  RETURN QUERY SELECT v_vehicle_id, v_access_id;
END;

DECLARE
  v_plate text := btrim(p_plate_number);
  v_vehicle_id uuid;
  v_access_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF v_plate IS NULL OR length(v_plate) NOT BETWEEN 1 AND 32
    OR v_plate ~ '[[:cntrl:]]' THEN
    RAISE EXCEPTION 'Plate number must contain 1 to 32 characters without control characters';
  END IF;

  SELECT registered.vehicle_id, registered.access_id
  INTO v_vehicle_id, v_access_id
  FROM public.register_vehicle_with_access(
    p_make, p_model, p_year, p_color, p_seat_capacity
  ) registered;

  UPDATE public.vehicles v SET plate_number = v_plate WHERE v.id = v_vehicle_id;
  RETURN QUERY SELECT v_vehicle_id, v_access_id;
END;

DECLARE
  v_caller_member_id uuid;
  v_movement_need_id uuid;
  v_participant_record public.movement_participants%ROWTYPE;
  v_need_record public.movement_needs%ROWTYPE;
BEGIN
  v_caller_member_id := auth.uid();
  
  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  -- Step 1: Read participant WITHOUT lock to obtain movement_need_id
  SELECT *
  INTO v_participant_record
  FROM public.movement_participants mp
  WHERE mp.id = p_participant_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Participant row not found';
  END IF;
  
  v_movement_need_id := v_participant_record.movement_need_id;
  
  -- Step 2: Lock the movement need FIRST
  SELECT *
  INTO v_need_record
  FROM public.movement_needs mn
  WHERE mn.id = v_movement_need_id
  FOR UPDATE;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Movement need not found';
  END IF;
  
  -- Step 3: Verify caller owns the movement need and it is discoverable
  IF v_need_record.member_id <> v_caller_member_id THEN
    RAISE EXCEPTION 'Only the movement need owner may remove participants';
  END IF;
  
  IF v_need_record.status <> 'discoverable' THEN
    RAISE EXCEPTION 'Movement need is not discoverable; cannot remove participants';
  END IF;
  
  -- Step 4: Now lock the participant row with the locked need context
  SELECT *
  INTO v_participant_record
  FROM public.movement_participants mp
  WHERE mp.id = p_participant_id
    AND mp.movement_need_id = v_need_record.id
  FOR UPDATE;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Participant row not found or does not match movement need';
  END IF;
  
  -- Cannot remove the primary requester row itself
  IF v_participant_record.role = 'primary_requester' THEN
    RAISE EXCEPTION 'Cannot remove the primary requester';
  END IF;
  
  -- Only remove if invited or confirmed invited participant
  IF v_participant_record.status NOT IN ('invited', 'confirmed') THEN
    RAISE EXCEPTION 'Participant is in a terminal state and cannot be removed';
  END IF;
  
  -- Mark as removed (do not physically delete to preserve history)
  UPDATE public.movement_participants mp
  SET
    status = 'removed',
    updated_at = NOW()
  WHERE mp.id = p_participant_id;
  
  RETURN QUERY
  SELECT
    p_participant_id,
    v_movement_need_id,
    'removed'::text;
END;

DECLARE
  v_caller_member_id uuid;
  v_journey_record public.journeys%ROWTYPE;
  v_alignment_record public.alignments%ROWTYPE;
  v_returned_timestamp timestamptz;
BEGIN
  IF EXISTS(SELECT 1 FROM public.journeys lifecycle_journey WHERE lifecycle_journey.id=p_journey_id AND private.is_financial_alignment(lifecycle_journey.alignment_id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial coordination lifecycle unavailable'; END IF;
  v_caller_member_id := auth.uid();

  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  -- Load and lock the journey
  SELECT *
  INTO v_journey_record
  FROM public.journeys j
  WHERE j.id = p_journey_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Journey not found';
  END IF;

  -- Load and lock the alignment
  SELECT *
  INTO v_alignment_record
  FROM public.alignments a
  WHERE a.id = v_journey_record.alignment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alignment not found';
  END IF;

  -- Caller must be the offering member
  IF v_alignment_record.offering_member_id <> v_caller_member_id THEN
    RAISE EXCEPTION 'Only the offering member may request journey completion';
  END IF;

  -- Journey must be in_progress
  IF v_journey_record.status <> 'in_progress' THEN
    RAISE EXCEPTION 'Journey is not in_progress';
  END IF;

  -- Alignment must be in_progress
  IF v_alignment_record.status <> 'in_progress' THEN
    RAISE EXCEPTION 'Alignment is not in_progress';
  END IF;

  -- started_at must not be null
  IF v_journey_record.started_at IS NULL THEN
    RAISE EXCEPTION 'Journey has not been started';
  END IF;

  -- Idempotency: if completion_requested_at already exists while still in_progress, return existing
  IF v_journey_record.completion_requested_at IS NOT NULL THEN
    v_returned_timestamp := v_journey_record.completion_requested_at;
  ELSE
    -- Set completion_requested_at to now
    UPDATE public.journeys j
    SET completion_requested_at = NOW(), updated_at = NOW()
    WHERE j.id = p_journey_id
    RETURNING j.completion_requested_at
    INTO v_returned_timestamp;
  END IF;

  RETURN QUERY
  SELECT
    p_journey_id AS journey_id,
    'in_progress'::text AS journey_status,
    v_returned_timestamp AS completion_requested_at;
END;

DECLARE
  v_caller_member_id uuid;
  v_journey_record public.journeys%ROWTYPE;
  v_alignment_record public.alignments%ROWTYPE;
  v_returned_timestamp timestamptz;
BEGIN
  IF EXISTS(SELECT 1 FROM public.journeys lifecycle_journey WHERE lifecycle_journey.id=p_journey_id AND private.is_financial_alignment(lifecycle_journey.alignment_id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial coordination lifecycle unavailable'; END IF;
  v_caller_member_id := auth.uid();

  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  -- Load and lock the journey
  SELECT *
  INTO v_journey_record
  FROM public.journeys j
  WHERE j.id = p_journey_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Journey not found';
  END IF;

  -- Load and lock the alignment
  SELECT *
  INTO v_alignment_record
  FROM public.alignments a
  WHERE a.id = v_journey_record.alignment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alignment not found';
  END IF;

  -- Caller must be the offering member
  IF v_alignment_record.offering_member_id <> v_caller_member_id THEN
    RAISE EXCEPTION 'Only the offering member may request journey start';
  END IF;

  -- Alignment must be activated
  IF v_alignment_record.status <> 'activated' THEN
    RAISE EXCEPTION 'Alignment is not activated';
  END IF;

  -- Journey must be not_started
  IF v_journey_record.status <> 'not_started' THEN
    RAISE EXCEPTION 'Journey is not in not_started state';
  END IF;

  -- Journey must not be completed, cancelled, or failed
  IF v_journey_record.status IN ('completed', 'cancelled', 'failed') THEN
    RAISE EXCEPTION 'Journey is in a terminal state';
  END IF;

  -- Idempotency: if start_requested_at already exists and journey is still not_started, return existing
  IF v_journey_record.start_requested_at IS NOT NULL THEN
    v_returned_timestamp := v_journey_record.start_requested_at;
  ELSE
    -- Set start_requested_at to now
    UPDATE public.journeys j
    SET start_requested_at = NOW(), updated_at = NOW()
    WHERE j.id = p_journey_id
    RETURNING j.start_requested_at
    INTO v_returned_timestamp;
  END IF;

  RETURN QUERY
  SELECT
    p_journey_id AS journey_id,
    'not_started'::text AS journey_status,
    v_returned_timestamp AS start_requested_at;
END;

DECLARE
  v_caller_member_id uuid;
  v_journey_record public.journeys%ROWTYPE;
  v_alignment_record public.alignments%ROWTYPE;
  v_offering_member_id uuid;
  v_requester_member_id uuid;
  v_end_status text;
  v_requested_by_me boolean;
  v_waiting_for_other_member boolean;
BEGIN
  IF EXISTS(SELECT 1 FROM public.journeys lifecycle_journey WHERE lifecycle_journey.id=p_journey_id AND private.is_financial_alignment(lifecycle_journey.alignment_id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial coordination lifecycle unavailable'; END IF;
  v_caller_member_id := auth.uid();

  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  -- Load and lock the journey
  SELECT *
  INTO v_journey_record
  FROM public.journeys j
  WHERE j.id = p_journey_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Journey not found';
  END IF;

  -- Load and lock the alignment
  SELECT *
  INTO v_alignment_record
  FROM public.alignments a
  WHERE a.id = v_journey_record.alignment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alignment not found';
  END IF;

  v_offering_member_id := v_alignment_record.offering_member_id;
  v_requester_member_id := v_alignment_record.member_needing_movement_id;

  -- Caller must be one of the two principal members
  IF v_caller_member_id <> v_offering_member_id AND v_caller_member_id <> v_requester_member_id THEN
    RAISE EXCEPTION 'Only principal movement members may end the movement';
  END IF;

  -- Terminal retries cannot create another consent or settlement.
  IF v_journey_record.status='cancelled' AND v_alignment_record.status='cancelled'
    AND EXISTS (SELECT 1 FROM private.mutual_no_travel_closures c WHERE c.journey_id=p_journey_id) THEN
    RETURN QUERY SELECT p_journey_id, 'cancelled'::text, 'cancelled'::text, 'mutual_no_travel'::text, false::boolean, false::boolean, NULL::timestamptz;
    RETURN;
  END IF;
  -- Allow ending only in valid states
  -- A: activated + not_started
  -- B: in_progress + in_progress
  -- C: already completed (idempotent)

  IF v_alignment_record.status = 'completed' AND v_journey_record.status = 'completed' THEN
    -- Already completed, return idempotently
    RETURN QUERY
    SELECT
      p_journey_id,
      v_journey_record.status,
      v_alignment_record.status,
      'completed'::text,
      false::boolean,
      false::boolean,
      v_journey_record.completed_at;
    RETURN;
  END IF;

  -- Reject if not in a valid ending state
  IF NOT (
    (v_alignment_record.status = 'activated' AND v_journey_record.status = 'not_started')
    OR
    (v_alignment_record.status = 'in_progress' AND v_journey_record.status = 'in_progress')
  ) THEN
    RAISE EXCEPTION 'Movement is not in a state that allows mutual ending';
  END IF;

  -- Check if an end request already exists
  IF v_journey_record.end_requested_by_member_id IS NOT NULL THEN
    -- End request already pending
    IF v_journey_record.end_requested_by_member_id = v_caller_member_id THEN
      -- Same member requesting again: idempotent
      v_end_status := 'awaiting_other_member';
      v_requested_by_me := true;
      v_waiting_for_other_member := true;
    ELSE
      -- OTHER principal member is now also requesting end: mutual agreement!
      -- Both rows are locked in journey-then-alignment order. A request is not a start.
      IF v_alignment_record.status='activated' AND v_journey_record.status='not_started' THEN
        PERFORM private.close_mutual_no_travel(p_journey_id);
        RETURN QUERY SELECT p_journey_id, 'cancelled'::text, 'cancelled'::text, 'mutual_no_travel'::text, false::boolean, false::boolean, NULL::timestamptz;
        RETURN;
      END IF;
      -- Complete the movement
      UPDATE public.journeys j
      SET
        end_confirmed_by_member_id = v_caller_member_id,
        end_confirmed_at = NOW(),
        status = 'completed',
        completed_at = COALESCE(j.completed_at, NOW()),
        end_method = 'mutual_user_end',
        updated_at = NOW()
      WHERE j.id = p_journey_id;

      UPDATE public.alignments a
      SET
        status = 'completed',
        updated_at = NOW()
      WHERE a.id = v_alignment_record.id;

      -- Create settlement entitlement
      INSERT INTO private.movement_settlements (
        alignment_id,
        journey_id,
        beneficiary_member_id,
        status,
        created_at
      )
      VALUES (
        v_alignment_record.id,
        p_journey_id,
        v_offering_member_id,
        'pending_amount',
        NOW()
      )
      ON CONFLICT (alignment_id) DO NOTHING;

      v_end_status := 'completed';
      v_requested_by_me := false;
      v_waiting_for_other_member := false;

      -- Reload both records for accurate return
      SELECT *
      INTO v_journey_record
      FROM public.journeys j
      WHERE j.id = p_journey_id;

      SELECT *
      INTO v_alignment_record
      FROM public.alignments a
      WHERE a.id = v_alignment_record.id;
    END IF;
  ELSE
    -- No end request exists yet: create one
    -- Defensive: also clear any stale confirmation fields
    UPDATE public.journeys j
    SET
      end_requested_by_member_id = v_caller_member_id,
      end_requested_at = NOW(),
      end_confirmed_by_member_id = NULL,
      end_confirmed_at = NULL,
      end_reason = NULLIF(trim(p_reason), ''),
      updated_at = NOW()
    WHERE j.id = p_journey_id;

    v_end_status := 'awaiting_other_member';
    v_requested_by_me := true;
    v_waiting_for_other_member := true;
  END IF;

  RETURN QUERY
  SELECT
    p_journey_id,
    v_journey_record.status,
    v_alignment_record.status,
    v_end_status,
    v_requested_by_me,
    v_waiting_for_other_member,
    v_journey_record.completed_at;
END;

DECLARE a public.alignments%ROWTYPE; j public.journeys%ROWTYPE; g uuid; stamp timestamptz;
BEGIN
 a:=private.funded_coordination_alignment(p_movement_need_id);
 IF auth.uid() IS DISTINCT FROM a.offering_member_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact offerer required'; END IF;
 PERFORM x.id FROM public.journeys x WHERE x.alignment_id=a.id FOR UPDATE;
 j:=private.assert_funded_coordination_entry(a.id);
 IF EXISTS(SELECT 1 FROM private.funded_movement_completion_requests WHERE alignment_id=a.id) THEN
  RETURN QUERY SELECT * FROM public.get_my_funded_movement_completion_status(p_movement_need_id); RETURN;
 END IF;
 IF a.status<>'in_progress' OR j.status<>'in_progress' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Confirmed financial start required'; END IF;
 SELECT financial_agreement_id INTO STRICT g FROM private.funded_movement_activations WHERE alignment_id=a.id;
 -- Observe the request only after both principal construction gates.
 PERFORM m.id FROM public.members m WHERE m.id IN(a.offering_member_id,a.member_needing_movement_id) ORDER BY m.id FOR UPDATE;
 stamp:=clock_timestamp();
 BEGIN
  -- One statement completes both sides before any immediate constraint trigger
  -- fires. RETURNING is the dependency between writes; caller modes are untouched.
  WITH evidence AS (
   INSERT INTO private.funded_movement_completion_requests VALUES(a.id,g,j.id,stamp)
   RETURNING journey_id,requested_at
  )
  UPDATE public.journeys x SET completion_requested_at=e.requested_at,updated_at=e.requested_at
   FROM evidence e WHERE x.id=e.journey_id;
  PERFORM private.assert_funded_coordination_entry(a.id);
 EXCEPTION WHEN OTHERS THEN RAISE;
 END;
 RETURN QUERY SELECT * FROM public.get_my_funded_movement_completion_status(p_movement_need_id);
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING ERRCODE=SQLSTATE,MESSAGE='Movement completion unavailable';
END;

DECLARE a public.alignments%ROWTYPE; j public.journeys%ROWTYPE; mp private.journey_meeting_points%ROWTYPE; stamp timestamptz;
BEGIN
 a:=private.funded_coordination_alignment(p_movement_need_id);
 IF auth.uid() IS DISTINCT FROM a.offering_member_id THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact offerer required'; END IF;
 PERFORM x.id FROM public.journeys x WHERE x.alignment_id=a.id FOR UPDATE;
 j:=private.assert_funded_coordination_entry(a.id);
 -- Historical exact replay performs no operational or evidence writes.
 IF EXISTS(SELECT 1 FROM private.funded_movement_start_requests WHERE alignment_id=a.id) THEN
  RETURN QUERY SELECT * FROM public.get_my_movement_start_status(p_movement_need_id); RETURN;
 END IF;
 IF a.status<>'activated' OR j.status<>'not_started' OR j.started_at IS NOT NULL THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact pre-start coordination required'; END IF;
 SELECT x.* INTO mp FROM private.journey_meeting_points x WHERE x.journey_id=j.id FOR SHARE;
 IF mp.journey_id IS NULL OR mp.place_text<>btrim(mp.place_text) OR length(mp.place_text) NOT BETWEEN 1 AND 200 OR mp.place_text !~ '[^[:space:]]' THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Valid meeting point required'; END IF;
 -- All graph/journey/meeting-point waits and revalidation precede this instant.
 stamp:=clock_timestamp();
 BEGIN
  SET CONSTRAINTS private.funded_start_request_complete,private.funded_start_complete,public.funded_start_journey_complete,public.funded_start_alignment_complete DEFERRED;
  INSERT INTO private.funded_movement_start_requests VALUES(a.id,j.id,stamp,mp.revision);
  UPDATE public.journeys x SET start_requested_at=stamp,updated_at=stamp WHERE x.id=j.id;
  PERFORM private.assert_funded_coordination_entry(a.id);
  SET CONSTRAINTS private.funded_start_request_complete,private.funded_start_complete,public.funded_start_journey_complete,public.funded_start_alignment_complete IMMEDIATE;
 EXCEPTION WHEN OTHERS THEN RAISE;
 END;
 RETURN QUERY SELECT * FROM public.get_my_movement_start_status(p_movement_need_id);
END;

DECLARE selected uuid;
BEGIN
 IF EXISTS(SELECT 1 FROM public.alignments x WHERE x.movement_need_id=p_movement_need_id AND private.is_financial_alignment(x.id)) THEN
  PERFORM private.mutate_funded_no_travel(p_movement_need_id,'request',NULLIF(btrim(p_reason),''));
 ELSE
  selected:=private.movement_end_context(p_movement_need_id);
  IF EXISTS(SELECT 1 FROM public.get_my_movement_end_status(selected) s WHERE s.action_required_from_me) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Explicit confirmation required'; END IF;
  PERFORM * FROM public.request_movement_end(selected,p_reason);
 END IF;
 RETURN QUERY SELECT * FROM public.get_my_movement_end_status_by_need(p_movement_need_id);
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Movement end unavailable';
END;

DECLARE c record;
BEGIN
  IF EXISTS(SELECT 1 FROM public.alignments lifecycle_candidate WHERE lifecycle_candidate.movement_need_id=p_movement_need_id AND private.is_financial_alignment(lifecycle_candidate.id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial coordination lifecycle unavailable'; END IF;
  SELECT * INTO c FROM private.movement_coordination_context(p_movement_need_id,true);
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Coordination unavailable'; END IF;
  IF auth.uid()<>c.offering_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Coordination unavailable'; END IF;
  IF NOT EXISTS (SELECT 1 FROM private.journey_meeting_points mp WHERE mp.journey_id=c.journey_id AND mp.place_text=btrim(mp.place_text) AND length(mp.place_text) BETWEEN 1 AND 200 AND mp.place_text ~ '[^[:space:]]') THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Meeting point required';
  END IF;

  PERFORM * FROM public.request_journey_start(c.journey_id);
  RETURN QUERY SELECT * FROM public.get_my_movement_coordination_status(p_movement_need_id);
END;

DECLARE
  v_caller_member_id uuid;
  v_movement_need_id uuid;
  v_participant_record public.movement_participants%ROWTYPE;
  v_need_record public.movement_needs%ROWTYPE;
  v_new_status text;
  v_responded_at timestamptz;
  v_confirmed_count integer;
BEGIN
  v_caller_member_id := auth.uid();
  
  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  IF p_accept IS NULL THEN
    RAISE EXCEPTION 'Invitation response is required';
  END IF;
  
  -- Step 1: Read participant WITHOUT lock to obtain movement_need_id
  SELECT *
  INTO v_participant_record
  FROM public.movement_participants mp
  WHERE mp.id = p_participant_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Participant row not found';
  END IF;
  
  v_movement_need_id := v_participant_record.movement_need_id;
  
  -- Step 2: Lock the movement need FIRST to prevent state transitions
  SELECT *
  INTO v_need_record
  FROM public.movement_needs mn
  WHERE mn.id = v_movement_need_id
  FOR UPDATE;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Movement need not found';
  END IF;
  
  -- Step 3: Verify movement need is still discoverable
  IF v_need_record.status <> 'discoverable' THEN
    RAISE EXCEPTION 'Movement need is no longer discoverable; invitation can no longer be changed';
  END IF;
  
  -- Step 4: Now load and lock the participant row with the locked need context
  SELECT *
  INTO v_participant_record
  FROM public.movement_participants mp
  WHERE mp.id = p_participant_id
    AND mp.movement_need_id = v_need_record.id
  FOR UPDATE;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Participant row not found or does not match movement need';
  END IF;
  
  -- Caller must be the participant
  IF v_participant_record.member_id <> v_caller_member_id THEN
    RAISE EXCEPTION 'Only the invited member may respond to their own invitation';
  END IF;
  
  -- Participant must have role 'invited_participant'
  IF v_participant_record.role <> 'invited_participant' THEN
    RAISE EXCEPTION 'Only invited participants may respond to invitations';
  END IF;
  
  -- Current status must be 'invited'
  IF v_participant_record.status = 'confirmed' THEN
    RAISE EXCEPTION 'This invitation has already been accepted';
  END IF;
  
  IF v_participant_record.status = 'declined' THEN
    RAISE EXCEPTION 'This invitation has already been declined';
  END IF;
  
  IF v_participant_record.status = 'removed' THEN
    RAISE EXCEPTION 'This invitation has been removed';
  END IF;
  
  IF v_participant_record.status <> 'invited' THEN
    RAISE EXCEPTION 'Participant is not in invited state';
  END IF;
  
  -- If accepting, check group capacity
  IF p_accept THEN
    -- Count currently confirmed participants (not including this one, which is still invited)
    SELECT COUNT(*)
    INTO v_confirmed_count
    FROM public.movement_participants mp
    WHERE mp.movement_need_id = v_need_record.id
      AND mp.status = 'confirmed';
    
    -- If confirmed count is already at people_count, reject
    IF v_confirmed_count >= v_need_record.people_count THEN
      RAISE EXCEPTION 'Movement group is already full';
    END IF;
    
    v_new_status := 'confirmed';
  ELSE
    v_new_status := 'declined';
  END IF;
  
  -- Update the participant row
  UPDATE public.movement_participants mp
  SET
    status = v_new_status,
    responded_at = NOW(),
    updated_at = NOW()
  WHERE mp.id = p_participant_id
  RETURNING mp.responded_at
  INTO v_responded_at;
  
  RETURN QUERY
  SELECT
    p_participant_id,
    v_movement_need_id,
    v_new_status,
    v_responded_at;
END;

BEGIN
  PERFORM 1 FROM public.members WHERE id=p_member_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Member not found'; END IF;
  UPDATE public.member_media SET verified=false,is_current=false WHERE member_id=p_member_id AND media_type='photo' AND is_current;
  UPDATE public.members SET profile_media_verified=false WHERE id=p_member_id;
  UPDATE private.alignment_face_verifications SET status='superseded' WHERE member_id=p_member_id AND status='pending';
  DELETE FROM private.post_activation_photo_tokens WHERE subject_member_id=p_member_id;
END;

DECLARE
  v_caller_member_id uuid;
  v_share_record private.member_profile_shares%ROWTYPE;
BEGIN
  v_caller_member_id := auth.uid();
  
  IF v_caller_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  -- Validate share token input
  IF p_share_token IS NULL OR trim(p_share_token) = '' THEN
    RAISE EXCEPTION 'Share token is required';
  END IF;
  
  -- Find the share token (lock for update to prevent concurrent revocations)
  SELECT *
  INTO v_share_record
  FROM private.member_profile_shares mps
  WHERE mps.share_token = p_share_token
  FOR UPDATE;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Share token not found';
  END IF;
  
  -- Token must belong to the caller
  IF v_share_record.member_id <> v_caller_member_id THEN
    RAISE EXCEPTION 'You may only revoke your own share tokens';
  END IF;
  
  -- Token must currently be active
  IF v_share_record.status <> 'active' THEN
    RAISE EXCEPTION 'Share token is not active';
  END IF;
  
  -- Mark as revoked
  UPDATE private.member_profile_shares mps
  SET
    status = 'revoked',
    revoked_at = NOW()
  WHERE mps.id = v_share_record.id;
  
  RETURN QUERY
  SELECT true::boolean;
END;

DECLARE c record; current_revision bigint;
BEGIN
  SELECT * INTO c FROM private.movement_coordination_context(p_movement_need_id,true);
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Coordination unavailable'; END IF;
  IF auth.uid() NOT IN (c.offering_id,c.requester_id) OR c.journey_status<>'not_started' OR c.requested_at IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Coordination unavailable';
  END IF;
  IF p_place_text IS NULL OR length(btrim(p_place_text)) NOT BETWEEN 1 AND 200 OR p_place_text !~ '[^[:space:]]' THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid meeting point';
  END IF;
  SELECT mp.revision INTO current_revision FROM private.journey_meeting_points mp WHERE mp.journey_id=c.journey_id;
  -- NULL expected revision means "no row yet"; never silently overwrite.
  IF p_expected_revision IS DISTINCT FROM current_revision THEN
    RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Meeting point changed; refresh and retry';
  END IF;
  IF current_revision IS NULL THEN
    INSERT INTO private.journey_meeting_points(journey_id,place_text,revision) VALUES(c.journey_id,btrim(p_place_text),1);
  ELSE
    UPDATE private.journey_meeting_points mp SET place_text=btrim(p_place_text),revision=mp.revision+1,updated_at=now() WHERE mp.journey_id=c.journey_id;
  END IF;
  RETURN QUERY SELECT * FROM public.get_my_movement_coordination_status(p_movement_need_id);
END;

BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;

DECLARE v_media uuid; v_id uuid; v_now timestamptz;
BEGIN
  PERFORM 1 FROM public.alignments WHERE id=p_alignment_id AND status='awaiting_activation_payment' FOR UPDATE;
  IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM private.required_face_members(p_alignment_id) r WHERE r.member_id=p_member_id) THEN
    RAISE EXCEPTION 'Face verification unavailable';
  END IF;
  PERFORM 1 FROM public.members WHERE id=p_member_id FOR UPDATE;
  -- Only prepare_profile_photo_submission_for_server establishes this binding.
  -- Successful live checks leave the submission ready, allowing later reuse.
  SELECT mm.id INTO v_media FROM public.member_media mm
    JOIN private.profile_photo_submissions ps ON ps.media_id=mm.id AND ps.member_id=mm.member_id
      AND ps.status='ready' AND ps.processed_at IS NOT NULL
    WHERE mm.member_id=p_member_id AND mm.media_type='photo' AND mm.is_current
    FOR SHARE OF ps;
  IF v_media IS NULL THEN RAISE EXCEPTION 'Prepared current face photo required'; END IF;
  UPDATE private.alignment_face_verifications SET status='superseded'
    WHERE alignment_id=p_alignment_id AND member_id=p_member_id AND status='pending';
  v_now:=clock_timestamp();
  INSERT INTO private.alignment_face_verifications(alignment_id,member_id,media_id,provider,provider_reference,started_at,expires_at,attempt_ordinal)
  VALUES (p_alignment_id,p_member_id,v_media,p_provider,p_provider_reference,v_now,v_now+interval '10 minutes',nextval('private.alignment_face_attempt_ordinal_seq'::regclass)) RETURNING id INTO v_id;
  RETURN v_id;
END;

DECLARE v_alignment uuid; v_session uuid;
BEGIN
  SELECT a.id INTO v_alignment FROM public.alignments a
  WHERE a.movement_need_id=p_movement_need_id AND a.status='awaiting_activation_payment'
    AND EXISTS (SELECT 1 FROM private.required_face_members(a.id) r WHERE r.member_id=p_member_id);
  IF v_alignment IS NULL OR (SELECT count(*) FROM public.alignments a
    WHERE a.movement_need_id=p_movement_need_id AND a.status='awaiting_activation_payment')<>1 THEN
    RAISE EXCEPTION 'Verification unavailable';
  END IF;
  -- Installed 0016 rechecks state, participant eligibility and ready provenance
  -- under its alignment/member locks and binds the exact current media.
  v_session:=public.start_alignment_face_verification_for_server(
    v_alignment,p_member_id,p_provider,p_provider_reference);
  RETURN QUERY SELECT f.id,f.media_id,mm.storage_path,f.expires_at
    FROM private.alignment_face_verifications f JOIN public.member_media mm ON mm.id=f.media_id
    WHERE f.id=v_session;
END;

DECLARE
  v_member_id uuid;
  v_trimmed_first_name text;
BEGIN
  v_member_id := auth.uid();

  IF v_member_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  v_trimmed_first_name := trim(p_first_name);

  IF v_trimmed_first_name IS NULL OR v_trimmed_first_name = '' THEN
    RAISE EXCEPTION 'First name is required';
  END IF;

  IF length(v_trimmed_first_name) > 100 THEN
    RAISE EXCEPTION 'First name must be 100 characters or fewer';
  END IF;

  IF p_date_of_birth IS NOT NULL AND p_date_of_birth > CURRENT_DATE THEN
    RAISE EXCEPTION 'Date of birth cannot be in the future';
  END IF;

  UPDATE public.members
  SET
    first_name = v_trimmed_first_name,
    date_of_birth = p_date_of_birth
  WHERE public.members.id = v_member_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Member record not found for the authenticated user';
  END IF;

  RETURN QUERY
  SELECT
    m.id,
    m.first_name,
    m.date_of_birth,
    m.identity_verified,
    m.profile_media_verified,
    m.common_movement_area,
    m.completed_movements,
    m.rating,
    m.created_at,
    m.updated_at
  FROM public.members AS m
  WHERE m.id = v_member_id;
END;

DECLARE
  v_member_id uuid := auth.uid();
  i private.requester_movement_interests%ROWTYPE;
BEGIN
  IF current_setting('transaction_isolation')<>'read committed' THEN
    RAISE EXCEPTION USING ERRCODE='25000', MESSAGE='Interest withdrawal requires READ COMMITTED';
  END IF;
  IF v_member_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Authenticated member required';
  END IF;
  IF p_interest_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='Interest is required';
  END IF;
  SELECT x.* INTO i FROM private.requester_movement_interests x
    WHERE x.id=p_interest_id AND x.requesting_member_id=v_member_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Requester interest unavailable';
  END IF;
  IF i.status='expired' THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Expired interest cannot change';
  END IF;
  IF i.status='active' THEN
    UPDATE private.requester_movement_interests x SET status='withdrawn'
    WHERE x.id=i.id RETURNING * INTO i;
  END IF;
  RETURN QUERY SELECT i.id,i.status,i.created_at;
END;
